  videos = '[{"kind":"featured","title":"Big Bill Broonzy - Key To the Highway (1941)","youtube_id":"psqnMEP3aL4","channel":"Tube Radio","note":"Recorded May 2, 1941 for Okeh — one of the most-covered blues songs of the century."},{"kind":"more","title":"Big Bill Broonzy: Black, Brown and White","youtube_id":"k0c1c0ZsTLA","channel":"HaloedG"},{"kind":"more","title":"Big Bill Broonzy plays \"Hey Hey\"","youtube_id":"_2Npu8KFsIY","channel":"GtrWorkShp","note":"Filmed by Pete Seeger, July 6, 1957."}]',
