  formative_i18n = '{"en":["1922: Mother remarried William Moore, who taught Hooker his signature droning, one-chord style. (Kilde: Wikipedia)","1943: Moved to Detroit, worked for Ford Motor Company, and frequented Hastings Street blues clubs. (Kilde: Wikipedia)","1948: \"Boogie Chillen''\" released on Modern Records while he was working as a steel-mill janitor — became the best-selling race record of 1949. (Kilde: Wikipedia)","1950s: Recorded under numerous pseudonyms (John Lee Booker, Texas Slim, Delta John, and others) due to conflicting non-exclusive contracts. (Kilde: Wikipedia)","1989: \"The Healer,\" with Carlos Santana and Bonnie Raitt, relaunched his career and won a Grammy. (Kilde: Wikipedia)"],"no":["1922: Moren giftet seg på nytt med William Moore, som lærte Hooker hans signatur dorrende énakkords-stil. (Kilde: Wikipedia)","1943: Flyttet til Detroit, jobbet for Ford Motor Company, og oppholdt seg mye på bluesklubbene på Hastings Street. (Kilde: Wikipedia)","1948: «Boogie Chillen''» utgitt på Modern Records mens han jobbet som vaktmester på en stålfabrikk — ble den best-selgende «race record»-en i 1949. (Kilde: Wikipedia)","1950-tallet: Spilte inn under tallrike pseudonymer (John Lee Booker, Texas Slim, Delta John, med flere) på grunn av motstridende, ikke-eksklusive kontrakter. (Kilde: Wikipedia)","1989: «The Healer», med Carlos Santana og Bonnie Raitt, relanserte karrieren hans og vant en Grammy. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Electric guitar (droning one-chord style)","note":"His entire sound was built on a hypnotic, single-chord droning technique taught to him by his stepfather William Moore.","source":"Wikipedia"},{"category":"Annet","name":"Foot-stomp percussion","note":"Kept time by stamping his foot on the floor, an audible and essential part of his signature groove.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Elektrisk gitar (dorrende énakkords-stil)","note":"Hele lyden hans var bygget på en hypnotisk, énakkords dorreteknikk lært av stefaren William Moore.","source":"Wikipedia"},{"category":"Annet","name":"Fotstamp-perkusjon","note":"Holdt takten ved å stampe foten i gulvet, en hørbar og essensiell del av signaturgrooven hans.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Recorded under a rotating cast of pseudonyms — including Texas Slim, Delta John and \"Birmingham Sam and His Magic Guitar\" — to get around conflicting non-exclusive record contracts in the 1950s. (Kilde: Wikipedia)","Was working as a janitor in a Detroit steel mill at the exact moment \"Boogie Chillen''\" became the best-selling race record of 1949. (Kilde: Wikipedia)","He owned five houses by the end of his life, a striking contrast to his beginnings as a Mississippi sharecropper''s son. (Kilde: Wikipedia)"],"no":["Spilte inn under en roterende rekke pseudonymer — deriblant Texas Slim, Delta John og «Birmingham Sam and His Magic Guitar» — for å omgå motstridende, ikke-eksklusive platekontrakter på 1950-tallet. (Kilde: Wikipedia)","Jobbet som vaktmester på en Detroit-stålfabrikk akkurat i det øyeblikket «Boogie Chillen''» ble den best-selgende «race record»-en i 1949. (Kilde: Wikipedia)","Han eide fem hus ved slutten av livet, en slående kontrast til opphavet som sønn av en forpakter i Mississippi. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"William Moore","note":"Stepfather and blues singer who directly taught him his signature droning guitar style.","source":"Wikipedia"},{"name":"Tony Hollins","note":"Local musician who gave the young Hooker his first guitar.","source":"Wikipedia"},{"name":"Carlos Santana & Bonnie Raitt","note":"Featured on his 1989 comeback album \"The Healer,\" which won a Grammy.","source":"Wikipedia"},{"name":"Van Morrison","note":"Collaborated on \"Don''t Look Back\" (1997), winning Hooker two more Grammys.","source":"Wikipedia"}],"no":[{"name":"William Moore","note":"Stefar og bluessanger som lærte ham direkte hans signatur dorrende gitarstil.","source":"Wikipedia"},{"name":"Tony Hollins","note":"Lokal musiker som ga den unge Hooker hans første gitar.","source":"Wikipedia"},{"name":"Carlos Santana & Bonnie Raitt","note":"Medvirket på comeback-albumet «The Healer» fra 1989, som vant en Grammy.","source":"Wikipedia"},{"name":"Van Morrison","note":"Samarbeidet på «Don''t Look Back» (1997), som ga Hooker to Grammy-priser til.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1948,"title":"\"Boogie Chillen''\" (debut)","producer":"Modern Records","label":"Modern","notes":"Recorded/released 1948, hit #1 R&B in 1949 — the best-selling race record of the year.","musicians":[],"youtube_id":"P3vJiDRaMxc"},{"year":1951,"title":"Chess / Chance Records era (as \"John Lee Booker\")","producer":"Chess / Chance","label":"Chess / Chance","notes":"1951–1952, recorded under pseudonym to bypass contract restrictions.","musicians":[],"youtube_id":""},{"year":1953,"title":"De Luxe Records era (as \"Johnny Lee\")","producer":"De Luxe Records","label":"De Luxe","notes":"1953–1954.","musicians":[],"youtube_id":""},{"year":1956,"title":"Vee-Jay Records era, Chicago","producer":"Vee-Jay Records","label":"Vee-Jay","notes":"Includes \"Dimples\" (1956) and \"Boom Boom\" (recorded Oct 1961, released on \"Burnin''\" 1962).","musicians":[],"youtube_id":"jZv04xAejrc"},{"year":1966,"title":"Chess / ABC-Bluesway era","producer":"Various","label":"Chess / ABC-Bluesway","notes":"Includes \"One Bourbon, One Scotch, One Beer\" (1966), released on \"The Real Folk Blues.\"","musicians":[],"youtube_id":"q-fSZRYeBWk"},{"year":1971,"title":"Various labels, with rock collaborators","producer":"Various","label":"Various","notes":"1970s recordings/tours with Canned Heat, the Groundhogs, Steve Miller and Elvin Bishop.","musicians":[],"youtube_id":""},{"year":1989,"title":"The Healer","producer":"Chameleon / Pointblank","label":"Chameleon","notes":"Comeback album featuring Carlos Santana and Bonnie Raitt; won a Grammy for Best Traditional Blues Recording.","musicians":[{"name":"Carlos Santana","instrument":"Guitar"},{"name":"Bonnie Raitt","instrument":"Vocals"}],"youtube_id":""},{"year":1991,"title":"Mr. Lucky","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Follow-up to The Healer.","musicians":[],"youtube_id":""},{"year":1995,"title":"Chill Out","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Won the Grammy for Best Traditional Blues Album.","musicians":[],"youtube_id":""},{"year":1997,"title":"Don''t Look Back","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Won two Grammys, including Best Pop Collaboration with Vocals for the title track with Van Morrison.","musicians":[{"name":"Van Morrison","instrument":"Vocals"}],"youtube_id":""}],"no":[{"year":1948,"title":"«Boogie Chillen''» (debut)","producer":"Modern Records","label":"Modern","notes":"Spilt inn/utgitt 1948, ble nr. 1 på R&B-listen i 1949 — årets best-selgende «race record».","musicians":[],"youtube_id":"P3vJiDRaMxc"},{"year":1951,"title":"Chess / Chance Records-æra (som «John Lee Booker»)","producer":"Chess / Chance","label":"Chess / Chance","notes":"1951–1952, spilt inn under pseudonym for å omgå kontraktbegrensninger.","musicians":[],"youtube_id":""},{"year":1953,"title":"De Luxe Records-æra (som «Johnny Lee»)","producer":"De Luxe Records","label":"De Luxe","notes":"1953–1954.","musicians":[],"youtube_id":""},{"year":1956,"title":"Vee-Jay Records-æra, Chicago","producer":"Vee-Jay Records","label":"Vee-Jay","notes":"Inkluderer «Dimples» (1956) og «Boom Boom» (spilt inn okt. 1961, utgitt på «Burnin''» 1962).","musicians":[],"youtube_id":"jZv04xAejrc"},{"year":1966,"title":"Chess / ABC-Bluesway-æra","producer":"Diverse","label":"Chess / ABC-Bluesway","notes":"Inkluderer «One Bourbon, One Scotch, One Beer» (1966), utgitt på «The Real Folk Blues».","musicians":[],"youtube_id":"q-fSZRYeBWk"},{"year":1971,"title":"Diverse plateselskap, med rock-samarbeidspartnere","producer":"Diverse","label":"Diverse","notes":"1970-talls innspillinger/turneer med Canned Heat, Groundhogs, Steve Miller og Elvin Bishop.","musicians":[],"youtube_id":""},{"year":1989,"title":"The Healer","producer":"Chameleon / Pointblank","label":"Chameleon","notes":"Comeback-album med Carlos Santana og Bonnie Raitt; vant en Grammy for beste tradisjonelle bluesinnspilling.","musicians":[{"name":"Carlos Santana","instrument":"Gitar"},{"name":"Bonnie Raitt","instrument":"Vokal"}],"youtube_id":""},{"year":1991,"title":"Mr. Lucky","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Oppfølger til The Healer.","musicians":[],"youtube_id":""},{"year":1995,"title":"Chill Out","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Vant Grammy for beste tradisjonelle blues-album.","musicians":[],"youtube_id":""},{"year":1997,"title":"Don''t Look Back","producer":"Pointblank/Virgin","label":"Pointblank","notes":"Vant to Grammyer, deriblant beste popsamarbeid med vokal for tittelsporet med Van Morrison.","musicians":[{"name":"Van Morrison","instrument":"Vokal"}],"youtube_id":""}]}',
