  family_i18n = '{"en":[{"relation":"Grandmother","name":"Della Grant","note":"Raised him after his mother''s death; gave him the nickname \"Muddy\" for playing in the mud along Deer Creek.","source":"Wikipedia"},{"relation":"Wife (1st)","name":"Mabel Berry","note":"Married early 1930s.","source":"Wikipedia"},{"relation":"Wife (2nd)","name":"Geneva Wade","note":"Married in the 1940s; died of cancer March 15, 1973.","source":"Wikipedia"},{"relation":"Wife (3rd)","name":"Marva Jean Brooks (\"Sunshine\")","note":"Married 1979; Eric Clapton served as best man.","source":"Wikipedia"},{"relation":"Sons","name":"Larry \"Mud\" Morganfield, Big Bill Morganfield, Joseph \"Mojo\" Morganfield","note":"Among at least six children; several became blues musicians themselves.","source":"Wikipedia"}],"no":[{"relation":"Bestemor","name":"Della Grant","note":"Oppdro ham etter morens død; ga ham kallenavnet «Muddy» for å ha lekt i gjørmen langs Deer Creek.","source":"Wikipedia"},{"relation":"Kone (1.)","name":"Mabel Berry","note":"Giftet seg tidlig på 1930-tallet.","source":"Wikipedia"},{"relation":"Kone (2.)","name":"Geneva Wade","note":"Giftet seg på 1940-tallet; døde av kreft 15. mars 1973.","source":"Wikipedia"},{"relation":"Kone (3.)","name":"Marva Jean Brooks («Sunshine»)","note":"Giftet seg i 1979; Eric Clapton var forlover.","source":"Wikipedia"},{"relation":"Sønner","name":"Larry «Mud» Morganfield, Big Bill Morganfield, Joseph «Mojo» Morganfield","note":"Blant minst seks barn; flere ble selv bluesmusikere.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1941–1942: Recorded by Alan Lomax for the Library of Congress at Stovall Plantation. (Kilde: Wikipedia)","1943: Moved to Chicago — \"the single most momentous event\" of his life, in his own words. (Kilde: Wikipedia)","1948: \"I Can''t Be Satisfied\" became his breakthrough hit on the newly renamed Chess Records. (Kilde: Wikipedia)","1954–1955: Recorded the Willie Dixon-written songs that would define his identity — \"Hoochie Coochie Man,\" \"I''m Ready,\" \"Mannish Boy.\" (Kilde: Wikipedia)","1958: Electric UK tour scandalized folk-purist audiences and directly seeded the British blues boom. (Kilde: Wikipedia)"],"no":["1941–1942: Spilt inn av Alan Lomax for Kongressbiblioteket på Stovall Plantation. (Kilde: Wikipedia)","1943: Flyttet til Chicago — «den enkeltstående mest skjebnesvangre hendelsen» i livet hans, i hans egne ord. (Kilde: Wikipedia)","1948: «I Can''t Be Satisfied» ble gjennombruddshiten hans på det nylig omdøpte Chess Records. (Kilde: Wikipedia)","1954–1955: Spilte inn Willie Dixon-skrevne sanger som skulle definere identiteten hans — «Hoochie Coochie Man», «I''m Ready», «Mannish Boy». (Kilde: Wikipedia)","1958: Elektrisk Storbritannia-turné skandaliserte folkemusikk-purister og sådde direkte frøet til den britiske bluesbølgen. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Stella acoustic guitar (early years)","years":"c. 1930–1943","note":"His first guitar, bought with money from selling the family horse.","source":"Wikipedia"},{"category":"Gitar","name":"Electric slide guitar (Chicago era)","years":"1943–1983","note":"Rebuilt Delta slide technique for the electric guitar, becoming the foundational sound of postwar Chicago blues.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Stella akustisk gitar (tidlige år)","years":"ca. 1930–1943","note":"Hans første gitar, kjøpt med penger fra salget av familiehesten.","source":"Wikipedia"},{"category":"Gitar","name":"Elektrisk slidegitar (Chicago-æra)","years":"1943–1983","note":"Bygde om Delta-slideteknikken for elektrisk gitar, og ble det grunnleggende lydbildet for etterkrigstidens Chicago-blues.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Hearing his own voice played back by Alan Lomax in 1941 was, by his own account, the moment he decided to pursue music as a career. (Kilde: Wikipedia)","His 1958 UK tour drew a newspaper headline reading \"Screaming Guitar and Howling Piano\" — considered scandalous at the time, it''s now viewed as the spark for the entire British blues boom. (Kilde: Wikipedia)","He publicly disowned his own 1968 psychedelic-soul album \"Electric Mud\" despite its eventual cult status. (Kilde: Wikipedia)","In 2016, the International Astronomical Union named a crater on the planet Mercury after him. (Kilde: Wikipedia)"],"no":["Å høre sin egen stemme avspilt av Alan Lomax i 1941 var, ifølge hans egen beretning, øyeblikket han bestemte seg for å satse på musikk som karriere. (Kilde: Wikipedia)","Storbritannia-turneen hans i 1958 fikk en avisoverskrift som lød «Skrikende gitar og hylende piano» — ansett som skandaløst på den tiden, ses det nå på som gnisten til hele den britiske bluesbølgen. (Kilde: Wikipedia)","Han tok offentlig avstand fra sitt eget psykedeliske soul-album «Electric Mud» fra 1968, til tross for at det senere fikk kultstatus. (Kilde: Wikipedia)","I 2016 oppkalte Den internasjonale astronomiske union et krater på planeten Merkur etter ham. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Little Walter Jacobs","note":"Harmonica player in his classic 1950s Chess band.","source":"Wikipedia"},{"name":"Willie Dixon","note":"Bassist and songwriter who wrote \"Hoochie Coochie Man,\" \"I''m Ready\" and other songs central to Waters''s identity.","source":"Wikipedia"},{"name":"Otis Spann","note":"Pianist in his classic band for over two decades.","source":"Wikipedia"},{"name":"Jimmy Rogers","note":"Guitarist in his classic 1950s Chess band.","source":"Wikipedia"},{"name":"Johnny Winter","note":"Guitarist who produced his celebrated late-career Blue Sky Records comeback albums, 1977–1981.","source":"Wikipedia"}],"no":[{"name":"Little Walter Jacobs","note":"Munnspillspiller i det klassiske Chess-bandet hans på 1950-tallet.","source":"Wikipedia"},{"name":"Willie Dixon","note":"Bassist og låtskriver som skrev «Hoochie Coochie Man», «I''m Ready» og andre sanger sentrale for Waters'' identitet.","source":"Wikipedia"},{"name":"Otis Spann","note":"Pianist i det klassiske bandet hans i over to tiår.","source":"Wikipedia"},{"name":"Jimmy Rogers","note":"Gitarist i det klassiske Chess-bandet hans på 1950-tallet.","source":"Wikipedia"},{"name":"Johnny Winter","note":"Gitarist som produserte de hyllede sen-karriere-comeback-albumene hans for Blue Sky Records, 1977–1981.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1946,"title":"Aristocrat Records era, Chicago","producer":"Leonard & Phil Chess","label":"Aristocrat","notes":"Early sessions; label soon renamed Chess Records.","musicians":[],"youtube_id":""},{"year":1948,"title":"\"I Can''t Be Satisfied\" / \"I Feel Like Going Home\"","producer":"Leonard Chess","label":"Chess","notes":"His breakthrough hit, Chess Records'' first genuine blues star.","musicians":[],"youtube_id":""},{"year":1950,"title":"\"Rollin'' Stone\"","producer":"Leonard Chess","label":"Chess","notes":"Reworking of \"Catfish Blues\"; later lent its name to both a rock band and a magazine.","musicians":[],"youtube_id":"sVmEMv8rcCA"},{"year":1954,"title":"Classic Chess band sessions","producer":"Leonard Chess","label":"Chess","notes":"\"Hoochie Coochie Man\" (Jan 7), \"I Just Want to Make Love to You,\" \"I''m Ready\" — all written by Willie Dixon.","musicians":[{"name":"Little Walter Jacobs","instrument":"Harmonica"},{"name":"Otis Spann","instrument":"Piano"},{"name":"Willie Dixon","instrument":"Bass"}],"youtube_id":"TIxFr2HMx6Y"},{"year":1955,"title":"\"Mannish Boy\"","producer":"Leonard Chess","label":"Chess","notes":"Recorded May 24, 1955 — answer song to Bo Diddley''s \"I''m a Man.\"","musicians":[],"youtube_id":"Wl0xvB-U6vU"},{"year":1960,"title":"Muddy Waters Sings \"Big Bill\"","producer":"Chess","label":"Chess","notes":"Tribute to Big Bill Broonzy.","musicians":[],"youtube_id":""},{"year":1964,"title":"Folk Singer","producer":"Chess","label":"Chess","notes":"Deliberately acoustic album, featuring a young Buddy Guy on guitar.","musicians":[{"name":"Buddy Guy","instrument":"Guitar"}],"youtube_id":""},{"year":1968,"title":"Electric Mud","producer":"Marshall Chess","label":"Cadet Concept","notes":"Psychedelic-soul-leaning album that Waters later publicly disowned.","musicians":[],"youtube_id":""},{"year":1969,"title":"Fathers and Sons","producer":"Chess","label":"Chess","notes":"Celebrated collaboration with Michael Blo