  family_i18n = '{"en":[{"relation":"Mother","name":"Leola Brooks","note":"A field hand, aged fifteen at the time of Elmore''s birth.","source":"Wikipedia"},{"relation":"Father (likely)","name":"Joe Willie \"Frost\" James","note":"Gave young Elmore the surname James.","source":"Wikipedia"},{"relation":"Cousin","name":"Homesick James","note":"Fellow bluesman; Elmore died at his Chicago home in 1963.","source":"Wikipedia"}],"no":[{"relation":"Mor","name":"Leola Brooks","note":"Markarbeider, femten år gammel da Elmore ble født.","source":"Wikipedia"},{"relation":"Far (trolig)","name":"Joe Willie «Frost» James","note":"Ga den unge Elmore etternavnet James.","source":"Wikipedia"},{"relation":"Fetter","name":"Homesick James","note":"Medbluesmusiker; Elmore døde hjemme hos ham i Chicago i 1963.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["Age 12: Began playing on a homemade one-string instrument. (Kilde: Wikipedia)","WWII: Served in the U.S. Navy, promoted to coxswain, took part in the invasion of Guam. (Kilde: Wikipedia)","August 1951: Recorded \"Dust My Broom\" as his debut session-leader single. (Kilde: Wikipedia)","November 1959: Wrote and recorded \"The Sky Is Crying,\" reportedly inspired by rain outside the studio. (Kilde: Wikipedia)","May 24, 1963: Died of a heart attack in Chicago at 45. (Kilde: Wikipedia)"],"no":["12 år: Begynte å spille på et hjemmelaget énstrengsinstrument. (Kilde: Wikipedia)","2. verdenskrig: Tjenestegjorde i den amerikanske marinen, forfremmet til styrmann, deltok i invasjonen av Guam. (Kilde: Wikipedia)","August 1951: Spilte inn «Dust My Broom» som sin debutsingel som øktleder. (Kilde: Wikipedia)","November 1959: Skrev og spilte inn «The Sky Is Crying», angivelig inspirert av regn utenfor studioet. (Kilde: Wikipedia)","24. mai 1963: Døde av hjerteinfarkt i Chicago, 45 år gammel. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Amplified slide guitar","note":"Known for playing at unusually loud volumes even by electric Chicago blues standards, earning him the nickname \"King of the Slide Guitar.\"","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Forsterket slidegitar","note":"Kjent for å spille i uvanlig høyt volum selv etter standardene til elektrisk Chicago-blues, noe som ga ham kallenavnet «King of the Slide Guitar».","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["\"The Sky Is Crying\" was reportedly written on the spot during the recording session, inspired by rain falling outside the studio. (Kilde: Wikipedia)","His backing band took its name, the Broomdusters, directly from his signature hit \"Dust My Broom.\" (Kilde: Wikipedia)","George Harrison referenced him by name in the Beatles song \"For You Blue.\" (Kilde: Wikipedia)"],"no":["«The Sky Is Crying» ble angivelig skrevet på stedet under innspillingsøkten, inspirert av regn som falt utenfor studioet. (Kilde: Wikipedia)","Backingbandet hans tok navnet sitt, Broomdusters, direkte fra signaturhiten hans «Dust My Broom». (Kilde: Wikipedia)","George Harrison nevnte ham ved navn i Beatles-sangen «For You Blue». (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"\"Little\" Johnny Jones","note":"Pianist in his backing band, the Broomdusters; formerly with Tampa Red.","source":"Wikipedia"},{"name":"Odie Payne","note":"Drummer in the Broomdusters; formerly with Tampa Red.","source":"Wikipedia"},{"name":"Ike Turner","note":"Talent scout who brought him to the Bihari brothers'' labels in the mid-1950s.","source":"Wikipedia"}],"no":[{"name":"«Little» Johnny Jones","note":"Pianist i backingbandet hans, Broomdusters; tidligere med Tampa Red.","source":"Wikipedia"},{"name":"Odie Payne","note":"Trommeslager i Broomdusters; tidligere med Tampa Red.","source":"Wikipedia"},{"name":"Ike Turner","note":"Talentspeider som tok ham med til Bihari-brødrenes plateselskap midt på 1950-tallet.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1951,"title":"Trumpet Records era, Jackson, Mississippi","producer":"Lillian McMurry","label":"Trumpet","notes":"Debut as sideman, then as session leader with \"Dust My Broom\" (August 1951), a Robert Johnson composition that became a surprise hit in 1952.","musicians":[],"youtube_id":"SOhQP5wHNHQ"},{"year":1953,"title":"Flair / Meteor / Modern Records era, via Ike Turner","producer":"Bihari brothers","label":"Flair / Meteor / Modern","notes":"Includes \"I Believe.\"","musicians":[],"youtube_id":""},{"year":1955,"title":"Chess Records sessions","producer":"Chess","label":"Chess","notes":"Additional mid-1950s sides.","musicians":[],"youtube_id":""},{"year":1957,"title":"Chief Records era, Chicago","producer":"Mel London","label":"Chief","notes":"Includes his version of \"It Hurts Me Too.\"","musicians":[],"youtube_id":"fzr1Rfn-P4Y"},{"year":1959,"title":"Fire Records era, Chicago","producer":"Bobby Robinson","label":"Fire","notes":"\"The Sky Is Crying\" (recorded Nov 3–4 1959, released March 1960), \"Shake Your Moneymaker\" and \"Look on Yonder Wall\" (both 1961) — most enduring performances of his career.","musicians":[{"name":"\"Little\" Johnny Jones","instrument":"Piano"},{"name":"Odie Payne","instrument":"Drums"}],"youtube_id":"u7ZC-kv8THk"},{"year":1965,"title":"\"One Way Out\" (posthumous release)","producer":"Fire / Enjoy","label":"Fire / Enjoy","notes":"Released after his 1963 death.","musicians":[],"youtube_id":""}],"no":[{"year":1951,"title":"Trumpet Records-æra, Jackson, Mississippi","producer":"Lillian McMurry","label":"Trumpet","notes":"Debut som studiomusiker, deretter som øktleder med «Dust My Broom» (august 1951), en Robert Johnson-komposisjon som ble en overraskende hit i 1952.","musicians":[],"youtube_id":"SOhQP5wHNHQ"},{"year":1953,"title":"Flair / Meteor / Modern Records-æra, via Ike Turner","producer":"Bihari-brødrene","label":"Flair / Meteor / Modern","notes":"Inkluderer «I Believe».","musicians":[],"youtube_