  family_i18n = '{"en":[{"relation":"Parents","name":"Albert & Nora Ella King","note":"Sharecroppers; separated when Riley was four.","source":"Wikipedia"},{"relation":"Grandmother","name":"Elnora Farr","note":"Raised him in Kilmichael and Lexington, Mississippi after his parents separated.","source":"Wikipedia"},{"relation":"Cousin","name":"Bukka White","note":"Bluesman; King stayed with him after moving to Memphis in 1946.","source":"Wikipedia"}],"no":[{"relation":"Foreldre","name":"Albert & Nora Ella King","note":"Forpaktere; separerte da Riley var fire år gammel.","source":"Wikipedia"},{"relation":"Bestemor","name":"Elnora Farr","note":"Oppdro ham i Kilmichael og Lexington, Mississippi etter at foreldrene separerte.","source":"Wikipedia"},{"relation":"Fetter","name":"Bukka White","note":"Bluesmann; King bodde hos ham etter flyttingen til Memphis i 1946.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1946: Moved to Memphis, staying with cousin Bukka White. (Kilde: Wikipedia)","1948: Got his own radio slot on WDIA, earning the nickname \"Beale Street Blues Boy\" — shortened to \"B.B.\" (Kilde: Wikipedia)","1949: Ran back into a burning club in Twist, Arkansas to save his guitar, later naming it \"Lucille.\" (Kilde: Wikipedia)","February 1952: \"3 O''Clock Blues\" became his first #1 R&B hit. (Kilde: Wikipedia)","November 1964: Recorded \"Live at the Regal\" in Chicago. (Kilde: Wikipedia)","December 2006: Awarded the Presidential Medal of Freedom. (Kilde: Wikipedia)"],"no":["1946: Flyttet til Memphis, bodde hos fetteren Bukka White. (Kilde: Wikipedia)","1948: Fikk sin egen radiosending på WDIA, og fikk kallenavnet «Beale Street Blues Boy» — forkortet til «B.B.». (Kilde: Wikipedia)","1949: Løp tilbake inn i en brennende klubb i Twist, Arkansas for å redde gitaren sin, og oppkalte den senere «Lucille». (Kilde: Wikipedia)","Februar 1952: «3 O''Clock Blues» ble hans første #1 R&B-hit. (Kilde: Wikipedia)","November 1964: Spilte inn «Live at the Regal» i Chicago. (Kilde: Wikipedia)","Desember 2006: Tildelt Presidential Medal of Freedom. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Gibson ES-355 \"Lucille\"","note":"Named after a woman two men fought over, sparking a nightclub fire King nearly died retrieving his guitar from in 1949.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Gibson ES-355 «Lucille»","note":"Oppkalt etter en kvinne to menn sloss om, noe som utløste en nattklubbrann King nesten omkom i mens han hentet gitaren sin i 1949.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Named his guitar \"Lucille\" after nearly dying retrieving it from a burning club in Twist, Arkansas — the fire started when two men fought over a woman by that name. (Kilde: Wikipedia)","Played an average of over 200 shows a year well into his seventies, and completed 342 concerts in 1956 alone. (Kilde: Wikipedia)","His funeral procession traveled down Beale Street in Memphis accompanied by a brass band playing \"When the Saints Go Marching In,\" watched by thousands. (Kilde: Wikipedia)"],"no":["Oppkalte gitaren sin «Lucille» etter å ha vært nær ved å dø mens han hentet den fra en brennende klubb i Twist, Arkansas — brannen startet da to menn sloss om en kvinne med det navnet. (Kilde: Wikipedia)","Spilte i gjennomsnitt over 200 show i året godt inn i syttiårene, og fullførte 342 konserter i 1956 alene. (Kilde: Wikipedia)","Begravelsesprosesjonen hans kjørte nedover Beale Street i Memphis akkompagnert av et messingblåseband som spilte «When the Saints Go Marching In», sett av tusenvis. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Bukka White","note":"Cousin and bluesman who hosted King in Memphis in 1946.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Collaborated on the 2000 Grammy-winning album \"Riding with the King.\"","source":"Wikipedia"},{"name":"U2","note":"Guest appearance on \"When Love Comes to Town,\" from \"Rattle and Hum\" (1988).","source":"Wikipedia"},{"name":"Sam Phillips","note":"Produced some of his earliest RPM sessions before founding Sun Records.","source":"Wikipedia"}],"no":[{"name":"Bukka White","note":"Fetter og bluesmann som var vertskap for King i Memphis i 1946.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Samarbeidet på det Grammy-vinnende albumet «Riding with the King» fra 2000.","source":"Wikipedia"},{"name":"U2","note":"Gjesteopptreden på «When Love Comes to Town», fra «Rattle and Hum» (1988).","source":"Wikipedia"},{"name":"Sam Phillips","note":"Produserte noen av hans tidligste RPM-økter før han grunnla Sun Records.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1949,"title":"Bullet / RPM Records debut","producer":"Sam Phillips","label":"Bullet / RPM","notes":"Debut single \"Miss Martha King\" on Bullet; signed to RPM (Modern Records subsidiary), some early sessions produced by Sam Phillips.","musicians":[],"youtube_id":""},{"year":1952,"title":"\"3 O''Clock Blues\"","producer":"RPM Records","label":"RPM","notes":"His first #1 R&B hit, released February 1952.","musicians":[],"youtube_id":"tX67JL78ICM"},{"year":1956,"title":"\"Sweet Little Angel\"","producer":"RPM/Kent","label":"RPM / Kent","notes":"Later re-recorded live for \"Live at the Regal.\"","musicians":[],"youtube_id":"AxDryOXIXWY"},{"year":1958,"title":"Crown Records era","producer":"Crown Records","label":"Crown","notes":"Album releases through the late 1950s.","musicians":[],"youtube_id":""},{"year":1962,"title":"ABC-Paramount Records era begins","producer":"ABC-Paramount","label":"ABC-Paramount","notes":"Moved labels; stayed with ABC''s successors for the rest of his career.","musicians":[],"youtube_id":""},{"year":1964,"title":"Live at the Regal","producer":"ABC-Paramount","label":"ABC-Paramount","notes":"Recorded November 1964 at Chicago''s Regal Theater — widely considered one of the greatest live blues albums ever made.","musicians":[],"youtube_id":""},{"year":1969,"title":"Completely Well (\"The Thrill Is Gone\")","producer":"Bill Szymczyk","label":"ABC/BluesWay","notes":"Released December 1969; his biggest crossover hit, won a Grammy.","musicians":[],"youtube_id":"oica5jG7FpU"},{"year":2000,"title":"Riding with the King","producer":"Simon Climie","label":"Reprise / Duck","notes":"Collaboration album with Eric Clapton; won the Grammy for Best Traditional Blues Album.","musicians":[{"name":"Eric Clapton","instrument":"Guitar/Vocals"}],"youtube_id":""},{"year":2008,"title":"One Kind Favor","producer":"T Bone Burnett","label":"Geffen","notes":"Final studio album; won a Grammy.","musicians":[],"youtube_id":""}],"no":[{"year":1949,"title":"Bullet / RPM Records-debut","producer":"Sam Phillips","label":"Bullet / RPM","notes":"Debutsingelen «Miss Martha King» på Bullet; signerte med RPM (Modern Records-datterselskap), noen tidlige økter produsert av Sam Phillips.","musicians":[],"youtube_id":""},{"year":1952,"title":"«3 O''Clock Blues»","producer":"RPM Records","label":"RPM","notes":"Hans første #1 R&B-hit, utgitt februar 1952.","musicians":[],"youtube_id":"tX67JL78ICM"},{"year":1956,"title":"«Sweet Little Angel»","producer":"RPM/Kent","label":"RPM / Kent","notes":"Senere spilt inn på nytt live for «Live at the Regal».","musicians":[],"youtube_id":"AxDryOXIXWY"},{"year":1958,"title":"Crown Records-æra","producer":"Crown Records","label":"Crown","notes":"Albumutgivelser gjennom sent 1950-tall.","musicians":[],"youtube_id":""},{"year":1962,"title":"ABC-Paramount Records-æra begynner","producer":"ABC-Paramount","label":"ABC-Paramount","notes":"Byttet plateselskap; forble hos ABCs etterfølgere resten av karrieren.","musicians":[],"youtube_id":""},{"year":1964,"title":"Live at the Regal","producer":"ABC-Paramount","label":"ABC-Paramount","notes":"Spilt inn november 1964 på Chicagos Regal Theater — bredt ansett som et av de beste live-bluesalbumene noensinne laget.","musicians":[],"youtube_id":""},{"year":1969,"title":"Completely Well («The Thrill Is Gone»)","producer":"Bill Szymczyk","label":"ABC/BluesWay","notes":"Utgitt desember 1969; hans største krysningshit, vant en Grammy.","musicians":[],"youtube_id":"oica5jG7FpU"},{"year":2000,"title":"Riding with the King","producer":"Simon Climie","label":"Reprise / Duck","notes":"Samarbeidsalbum med Eric Clapton; vant Grammy for beste tradisjonelle bluesalbum.","musicians":[{"name":"Eric Clapton","instrument":"Gitar/Vokal"}],"youtube_id":""},{"year":2008,"title":"One Kind Favor","producer":"T Bone Burnett","label":"Geffen","notes":"Siste studioalbum; vant en Grammy.","musicians":[],"youtube_id":""}]}',
