  family_i18n = '{"en":[{"relation":"Parents","name":"Ella Mae King & J.T. Christian","note":"His mother and an uncle taught him guitar starting at age six.","source":"Wikipedia"},{"relation":"Wife","name":"Jessie Burnett","note":"Married 1952; the couple had seven children.","source":"Wikipedia"}],"no":[{"relation":"Foreldre","name":"Ella Mae King & J.T. Christian","note":"Moren og en onkel lærte ham gitar fra sekstre års alder.","source":"Wikipedia"},{"relation":"Kone","name":"Jessie Burnett","note":"Giftet seg i 1952; paret fikk sju barn.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1949: Family moved to Chicago''s South Side. (Kilde: Wikipedia)","1956: First record, \"Country Boy,\" on El-Bee Records. (Kilde: Wikipedia)","1960: Signed to Federal Records under producer Sonny Thompson. (Kilde: Wikipedia)","1961: \"Hide Away\" reached #5 R&B — became his signature song. (Kilde: Wikipedia)","1971: Recorded \"Getting Ready...\" at Chess Studios for Shelter Records. (Kilde: Wikipedia)"],"no":["1949: Familien flyttet til Chicagos sørside. (Kilde: Wikipedia)","1956: Første plate, «Country Boy», på El-Bee Records. (Kilde: Wikipedia)","1960: Signerte med Federal Records under produsent Sonny Thompson. (Kilde: Wikipedia)","1961: «Hide Away» nådde #5 på R&B-listen — ble hans signatursang. (Kilde: Wikipedia)","1971: Spilte inn «Getting Ready...» i Chess Studios for Shelter Records. (Kilde: Wikipedia)"]}',
  anecdotes_i18n = '{"en":["Eric Clapton said hearing King''s playing sent him \"into a complete kind of ecstasy\" while also scaring him. (Kilde: Wikipedia)","\"Hide Away\" was King''s own reworking of a theme he credited to fellow guitarist Hound Dog Taylor, blended with pieces of other tunes. (Kilde: Wikipedia)","Texas Governor Ann Richards proclaimed September 3, 1993 — his birthday — Freddie King Day. (Kilde: Wikipedia)"],"no":["Eric Clapton sa at det å høre Kings spill sendte ham «inn i en fullstendig form for ekstase» mens det samtidig skremte ham. (Kilde: Wikipedia)","«Hide Away» var Kings egen bearbeidelse av et tema han krediterte medgitarist Hound Dog Taylor, blandet med biter av andre låter. (Kilde: Wikipedia)","Texas-guvernør Ann Richards erklærte 3. september 1993 — bursdagen hans — som Freddie King-dagen. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Sonny Thompson","note":"Producer who signed him to Federal Records in 1960.","source":"Wikipedia"},{"name":"Leon Russell","note":"Producer and pianist on \"Getting Ready...\" (1971) for Shelter Records.","source":"Wikipedia"},{"name":"King Curtis","note":"Produced his two Cotillion/Atlantic albums, 1968–1970.","source":"Wikipedia"},{"name":"Hound Dog Taylor","note":"Fellow guitarist whose theme King reworked into \"Hide Away.\"","source":"Wikipedia"}],"no":[{"name":"Sonny Thompson","note":"Produsent som signerte ham med Federal Records i 1960.","source":"Wikipedia"},{"name":"Leon Russell","note":"Produsent og pianist på «Getting Ready...» (1971) for Shelter Records.","source":"Wikipedia"},{"name":"King Curtis","note":"Produserte hans to Cotillion/Atlantic-album, 1968–1970.","source":"Wikipedia"},{"name":"Hound Dog Taylor","note":"Medgitarist hvis tema King bearbeidet til «Hide Away».","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1956,"title":"\"Country Boy\" (debut single)","producer":"El-Bee Records","label":"El-Bee","notes":"Duet with Margaret Whitfield.","musicians":[{"name":"Margaret Whitfield","instrument":"Vocals"}],"youtube_id":""},{"year":1961,"title":"Let''s Hide Away and Dance Away with Freddy King","producer":"Sonny Thompson","label":"Federal / King","notes":"Includes \"Hide Away\" (#5 R&B) and \"San-Ho-Zay\" (#4 R&B).","musicians":[],"youtube_id":"-6JOEx44ZvI"},{"year":1961,"title":"Freddy King Sings","producer":"Sonny Thompson","label":"King Records","notes":"Includes \"Have You Ever Loved a Woman\" — later famously covered by Derek and the Dominos.","musicians":[],"youtube_id":""},{"year":1968,"title":"Cotillion/Atlantic era","producer":"King Curtis","label":"Cotillion / Atlantic","notes":"Two albums, 1968–1970.","musicians":[],"youtube_id":""},{"year":1971,"title":"Getting Ready...","producer":"Leon Russell","label":"Shelter Records","notes":"Recorded at Chess Studios, Chicago; includes \"Going Down\" (Don Nix cover).","musicians":[{"name":"Leon Russell","instrument":"Piano"},{"name":"Duck Dunn","instrument":"Bass"},{"name":"Chuck Blackwell","instrument":"Drums"}],"youtube_id":"htxrJ7-F2uE"},{"year":1974,"title":"Burglar","producer":"RSO Records","label":"RSO","notes":"","musicians":[],"youtube_id":""},{"year":1975,"title":"Larger Than Life","producer":"RSO Records","label":"RSO","notes":"One of his final studio albums.","musicians":[],"youtube_id":""}],"no":[{"year":1956,"title":"«Country Boy» (debutsingel)","producer":"El-Bee Records","label":"El-Bee","notes":"Duett med Margaret Whitfield.","musicians":[{"name":"Margaret Whitfield","instrument":"Vokal"}],"youtube_id":""},{"year":1961,"title":"Let''s Hide Away and Dance Away with Freddy King","producer":"Sonny Thompson","label":"Federal / King","notes":"Inkluderer «Hide Away» (#5 R&B) og «San-Ho-Zay» (#4 R&B).","musicians":[],"youtube_id":"-6JOEx44ZvI"},{"year":1961,"title":"Freddy King Sings","producer":"Sonny Thompson","label":"King Records","notes":"Inkluderer «Have You Ever Loved a Woman» — senere berømt coveret av Derek and the Dominos.","musicians":[],"youtube_id":""},{"year":1968,"title":"Cotillion/Atlantic-æra","producer":"King Curtis","label":"Cotillion / Atlantic","notes":"To album, 1968–1970.","musicians":[],"youtube_id":""},{"year":1971,"title":"Getting Ready...","producer":"Leon Russell","label":"Shelter Records","notes":"Spilt inn i Chess Studios, Chicago; inkluderer «Going Down» (Don Nix-cover).","musicians":[{"name":"Leon Russell","instrument":"Piano"},{"name":"Duck Dunn","instrument":"Bass"},{"name":"Chuck Blackwell","instrument":"Trommer"}],"youtube_id":"htxrJ7-F2uE"},{"year":1974,"title":"Burglar","producer":"RSO Records","label":"RSO","notes":"","musicians":[],"youtube_id":""},{"year":1975,"title":"Larger Than Life","producer":"RSO Records","label":"RSO","notes":"Ett av hans siste studioalbum.","musicians":[],"youtube_id":""}]}',
  videos = '[{"kind":"featured","title":"Freddie King - Hide Away (1961)","youtube_id":"-6JOEx44ZvI","channel":"Classic Mood Experience","note":"His signature instrumental, reaching #5 R&B and #29 pop in 1961."},{"kind":"more","title":"Freddie King - San-Ho-Zay (1961)","youtube_id":"D2pey9TfvWw","channel":"Classic Mood Experience"},{"kind":"more","title":"Freddie King / Getting Ready... - Going Down","youtube_id":"htxrJ7-F2uE","channel":"YvdorianThe1st"},{"kind":"more","title":"Freddie King - Have You Ever Loved A Woman","youtube_id":"mE9H1bW-zQ4","channel":"mick7575"}]',
