  formative_i18n = '{"en":["1949: Moved to Chicago at age 14. (Kilde: Wikipedia)","1956: Recorded \"I Can''t Quit You Baby\" with Willie Dixon — his breakthrough hit. (Kilde: Wikipedia)","1969: Released his first full studio album, \"Mourning in the Morning,\" on Cotillion. (Kilde: Wikipedia)","1998: Won the Grammy Award for \"Any Place I''m Going.\" (Kilde: Wikipedia)","2003: A stroke ended his touring and performing career. (Kilde: Wikipedia)"],"no":["1949: Flyttet til Chicago som fjortenåring. (Kilde: Wikipedia)","1956: Spilte inn «I Can''t Quit You Baby» med Willie Dixon — gjennombruddshiten hans. (Kilde: Wikipedia)","1969: Ga ut sitt første fullstendige studioalbum, «Mourning in the Morning», på Cotillion. (Kilde: Wikipedia)","1998: Vant Grammy-prisen for «Any Place I''m Going». (Kilde: Wikipedia)","2003: Et hjerneslag avsluttet turné- og opptredenkarrieren hans. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Left-handed guitar, strung upside-down","note":"Low E string kept at the bottom rather than flipped to the top; often anchored his picking-hand pinky under the low string for leverage — a genuinely idiosyncratic setup.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Venstrehendt gitar, strengsatt opp-ned","note":"Lav E-streng holdt nederst fremfor snudd til toppen; forankret ofte lillefingeren på plukkehånden under den lave strengen for grep — en genuint særegen oppsett.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Reportedly turned down or missed opportunities to record with the Rolling Stones, Johnny Winter and Carlos Santana over the course of his career. (Kilde: Wikipedia)","Went 16 years between studio albums, from the late 1970s until 1994''s \"Ain''t Enough Comin'' In.\" (Kilde: Wikipedia)","Chicago mayor Rahm Emanuel declared June 12, 2016 \"Otis Rush Day\" in his honor. (Kilde: Wikipedia)"],"no":["Skal ha avslått eller gått glipp av muligheter til å spille inn med Rolling Stones, Johnny Winter og Carlos Santana i løpet av karrieren. (Kilde: Wikipedia)","Hadde 16 år mellom studioalbum, fra sent på 1970-tallet til «Ain''t Enough Comin'' In» i 1994. (Kilde: Wikipedia)","Chicagos borgermester Rahm Emanuel erklærte 12. juni 2016 «Otis Rush-dagen» til hans ære. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Willie Dixon","note":"Produced his breakthrough Cobra Records sessions, 1956–1958.","source":"Wikipedia"},{"name":"Buddy Guy","note":"Fellow pioneer of the West Side Chicago blues sound.","source":"Wikipedia"},{"name":"Magic Sam","note":"Fellow pioneer of the West Side Chicago blues sound.","source":"Wikipedia"},{"name":"Ike Turner","note":"Played guitar on the \"Double Trouble\" session.","source":"Wikipedia"}],"no":[{"name":"Willie Dixon","note":"Produserte hans gjennombrudds-Cobra Records-økter, 1956–1958.","source":"Wikipedia"},{"name":"Buddy Guy","note":"Medpioner innen West Side Chicago-bluesen.","source":"Wikipedia"},{"name":"Magic Sam","note":"Medpioner innen West Side Chicago-bluesen.","source":"Wikipedia"},{"name":"Ike Turner","note":"Spilte gitar på «Double Trouble»-økten.","source":"Wikipedia"}]}',
