  formative_i18n = '{"en":["1956: Moved to Chicago at 19. (Kilde: Wikipedia)","1957: Debut single \"All Your Love\" on Cobra Records. (Kilde: Wikipedia)","Early 1960s: Drafted into the U.S. Army, deserted, served 6 months in prison and was dishonorably discharged. (Kilde: Wikipedia)","1967–1968: Recorded \"West Side Soul\" for Delmark, released April 1968. (Kilde: Wikipedia)","1969: A triumphant performance at the Ann Arbor Blues Festival opened up national and international bookings — just months before his death. (Kilde: Wikipedia)"],"no":["1956: Flyttet til Chicago som nittenåring. (Kilde: Wikipedia)","1957: Debutsingelen «All Your Love» på Cobra Records. (Kilde: Wikipedia)","Tidlig 1960-tall: Innkalt til den amerikanske hæren, deserterte, sonet 6 måneder i fengsel og ble vanærende avskjediget. (Kilde: Wikipedia)","1967–1968: Spilte inn «West Side Soul» for Delmark, utgitt april 1968. (Kilde: Wikipedia)","1969: En triumferende opptreden på Ann Arbor Blues Festival åpnet nasjonale og internasjonale bookinger — bare måneder før hans død. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Electric guitar (signature tremolo tone)","note":"Known for a distinctive, heavily tremolo-inflected guitar sound combined with unusually sophisticated chord harmonies for the genre.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Elektrisk gitar (signatur-tremolotone)","note":"Kjent for en særegen, kraftig tremolo-preget gitarlyd kombinert med uvanlig sofistikerte akkordharmonier for sjangeren.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["His stage name was invented on the spot by bassist Mack Thompson during his first Cobra session, because his old nickname \"Good Rocking Sam\" was already taken. (Kilde: Wikipedia)","Deserted the U.S. Army and served six months in prison before receiving a dishonorable discharge. (Kilde: Wikipedia)","His triumphant 1969 Ann Arbor Blues Festival set opened the door to international touring — he died less than three months later. (Kilde: Wikipedia)","John Belushi dedicated a performance to \"the late great Magic Sam\" in the 1980 film \"The Blues Brothers.\" (Kilde: Wikipedia)"],"no":["Scenenavnet hans ble funnet opp på stedet av bassisten Mack Thompson under hans første Cobra-økt, fordi det gamle kallenavnet hans «Good Rocking Sam» allerede var opptatt. (Kilde: Wikipedia)","Desertere fra den amerikanske hæren og sonet seks måneder i fengsel før han ble vanærende avskjediget. (Kilde: Wikipedia)","Den triumferende opptredenen hans på Ann Arbor Blues Festival i 1969 åpnet døren til internasjonal turnering — han døde mindre enn tre måneder senere. (Kilde: Wikipedia)","John Belushi tilegnet en opptreden til «avdøde, store Magic Sam» i filmen «The Blues Brothers» fra 1980. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Mack Thompson","note":"Bass player and childhood friend who coined his stage name.","source":"Wikipedia"},{"name":"Otis Rush & Buddy Guy","note":"Fellow Cobra Records artists and co-pioneers of the West Side sound.","source":"Wikipedia"},{"name":"Willie Dixon","note":"Composed material for his Cobra recordings.","source":"Wikipedia"},{"name":"Shakey Jake Harris","note":"Uncle and harmonica player; performed and toured with him.","source":"Wikipedia"}],"no":[{"name":"Mack Thompson","note":"Bassist og barndomsvenn som fant opp scenenavnet hans.","source":"Wikipedia"},{"name":"Otis Rush & Buddy Guy","note":"Medartister hos Cobra Records og medpionerer bak West Side-lyden.","source":"Wikipedia"},{"name":"Willie Dixon","note":"Komponerte materiale for hans Cobra-innspillinger.","source":"Wikipedia"},{"name":"Shakey Jake Harris","note":"Onkel og munnspillspiller; opptrådte og turnerte med ham.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1957,"title":"Cobra Records era, Chicago","producer":"Cobra Records","label":"Cobra","notes":"1957–1959; debut single \"All Your Love,\" plus \"Easy Baby\" and Willie Dixon-composed material.","musicians":[],"youtube_id":"O2Cq9x7WSTE"},{"year":1960,"title":"Chief Records era","producer":"Chief Records","label":"Chief","notes":"1960–1961; includes \"Mr. Charlie.\"","musicians":[],"youtube_id":""},{"year":1963,"title":"\"Feelin'' Good (We''re Gonna Boogie)\"","producer":"—","label":"—","notes":"His first single to reach national attention.","musicians":[],"youtube_id":""},{"year":1966,"title":"Crash Records era","producer":"Crash Records","label":"Crash","notes":"Includes \"Out of Bad Luck.\"","musicians":[],"youtube_id":""},{"year":1968,"title":"West Side Soul","producer":"Delmark Records","label":"Delmark","notes":"Recorded July/October 1967, released April 1968; includes his celebrated version of \"Sweet Home Chicago.\"","musicians":[],"youtube_id":"xt9v1KZ56Ok"},{"year":1969,"title":"Black Magic","producer":"Delmark Records","label":"Delmark","notes":"Both this and \"West Side Soul\" are individually inducted into the Blues Hall of Fame''s Classics of Blues Recording category.","musicians":[],"youtube_id":""}],"no":[{"year":1957,"title":"Cobra Records-æra, Chicago","producer":"Cobra Records","label":"Cobra","notes":"1957–1959; debutsingelen «All Your Love», pluss «Easy Baby» og Willie Dixon-komponert materiale.","musicians":[],"youtube_id":"O2Cq9x7WSTE"},{"year":1960,"title":"Chief Records-æra","producer":"Chief Records","label":"Chief","notes":"1960–1961; inkluderer «Mr. Charlie».","musicians":[],"youtube_id":""},{"year":1963,"title":"«Feelin'' Good (We''re Gonna Boogie)»","producer":"—","label":"—","notes":"Hans første singel til å nå nasjonal oppmerksomhet.","musicians":[],"youtube_id":""},{"year":1966,"title":"Crash Records-æra","producer":"Crash Records","label":"Crash","notes":"Inkluderer «Out of Bad Luck».","musicians":[