  family_i18n = '{"en":[{"relation":"Cousin","name":"Junior Parker","note":"Taught him harmonica as a small child.","source":"Wikipedia"}],"no":[{"relation":"Fetter","name":"Junior Parker","note":"Lærte ham munnspill da han var liten gutt.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["Learned harmonica from cousin Junior Parker and Sonny Boy Williamson II, proficient by age 7. (Kilde: Wikipedia)","1948: Moved to Chicago with his mother. (Kilde: Wikipedia)","1952: Sat in on Muddy Waters''s Chess sessions as a direct replacement for Little Walter. (Kilde: Wikipedia)","1960: \"Little by Little\" reaches #23 on the Billboard R&B chart; records \"Messin'' with the Kid,\" his signature song. (Kilde: Wikipedia)","November 1965: Releases \"Hoodoo Man Blues\" on Delmark with Buddy Guy on guitar. (Kilde: Wikipedia)"],"no":["Lærte munnspill av fetteren Junior Parker og Sonny Boy Williamson II, dyktig allerede som syvåring. (Kilde: Wikipedia)","1948: Flyttet til Chicago med moren sin. (Kilde: Wikipedia)","1952: Satt inn på Muddy Waters'' Chess-økter som direkte erstatning for Little Walter. (Kilde: Wikipedia)","1960: «Little by Little» når nummer 23 på Billboards R&B-liste; spiller inn «Messin'' with the Kid», signatursangen hans. (Kilde: Wikipedia)","November 1965: Gir ut «Hoodoo Man Blues» på Delmark med Buddy Guy på gitar. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Munnspill","name":"Amplified harmonica","note":"Style directly influenced by Little Walter; became one of the defining amplified-harmonica voices of Chicago blues.","source":"Wikipedia"}],"no":[{"category":"Munnspill","name":"Forsterket munnspill","note":"Stil direkte påvirket av Little Walter; ble en av de definerende stemmene for forsterket munnspill i Chicago-blues.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["As a child he stole a harmonica from a pawnshop because he had to have one; the judge, impressed by his playing, dismissed the case and ordered restitution instead. (Kilde: Wikipedia)","Buddy Guy was credited pseudonymously as \"Friendly Chap\" on \"Hoodoo Man Blues\" for contractual reasons. (Kilde: Wikipedia)","\"Blues is blues no matter where it''s at — it''s not Chicago blues or Memphis blues.\" (Kilde: Wikipedia)","Appeared in \"Blues Brothers 2000,\" released the same year he died. (Kilde: Wikipedia)"],"no":["Som barn stjal han et munnspill fra en pantelånerbutikk fordi han måtte ha ett; dommeren, imponert over spillet hans, henla saken og påla erstatning i stedet. (Kilde: Wikipedia)","Buddy Guy ble kreditert under pseudonymet «Friendly Chap» på «Hoodoo Man Blues» av kontraktsmessige årsaker. (Kilde: Wikipedia)","«Blues er blues uansett hvor den er — det er ikke Chicago-blues eller Memphis-blues.» (Kilde: Wikipedia)","Opptrådte i «Blues Brothers 2000», utgitt samme år som han døde. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Buddy Guy","note":"Most frequent and defining musical partner from the 1960s onward.","source":"Wikipedia"},{"name":"Muddy Waters","note":"Sat in on his Chess sessions in 1952 as a replacement for Little Walter.","source":"Wikipedia"},{"name":"The Aces (Dave & Louis Myers, Fred Below)","note":"Backing band through the 1950s.","source":"Wikipedia"},{"name":"The Rolling Stones","note":"Touring and recording collaborations through the 1970s.","source":"Wikipedia"}],"no":[{"name":"Buddy Guy","note":"Hyppigste og mest definerende musikalske partner fra 1960-tallet og utover.","source":"Wikipedia"},{"name":"Muddy Waters","note":"Satt inn på Chess-øktene hans i 1952 som erstatning for Little Walter.","source":"Wikipedia"},{"name":"The Aces (Dave & Louis Myers, Fred Below)","note":"Backingband gjennom 1950-tallet.","source":"Wikipedia"},{"name":"The Rolling Stones","note":"Turné- og innspillingssamarbeid gjennom 1970-tallet.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1953,"title":"States Records era","producer":"States Records","label":"States","notes":"First recordings as a bandleader.","musicians":[],"youtube_id":""},{"year":1957,"title":"Chief / Profile Records era","producer":"Chief / Profile Records","label":"Chief / Profile","notes":"Late 1950s–early 1960s recordings.","musicians":[],"youtube_id":""},{"year":1960,"title":"\"Little by Little\" / \"Messin'' with the Kid\"","producer":"—","label":"USA Records","notes":"\"Little by Little\" reached #23 Billboard R&B; \"Messin'' with the Kid\" became his signature song.","musicians":[],"youtube_id":"cFNyJzCvF1U"},{"year":1965,"title":"Hoodoo Man Blues","producer":"Delmark Records","label":"Delmark","notes":"With Buddy Guy on guitar (credited as \"Friendly Chap\"). Delmark''s best-selling album; Grammy Hall of Fame inductee.","musicians":[{"name":"Buddy Guy","instrument":"Guitar"},{"name":"Jack Myers","instrument":"Bass"},{"name":"Billy Warren","instrument":"Drums"}],"youtube_id":"b0IbaQ5GIJs"},{"year":1971,"title":"South Side Blues Jam","producer":"Delmark Records","label":"Delmark","notes":"1970s Delmark release.","musicians":[],"youtube_id":""},{"year":1975,"title":"On Tap","producer":"Delmark Records","label":"Delmark","notes":"1970s Delmark release.","musicians":[],"youtube_id":""},{"year":1996,"title":"Come On in This House","producer":"Telarc / Blind Pig","label":"Telarc / Blind Pig","notes":"Featuring Alvin Youngblood Hart and Derek Trucks.","musicians":[{"name":"Alvin Youngblood Hart","instrument":"Guitar"},{"name":"Derek Trucks","instrument":"Guitar"}],"youtube_id":""}],"no":[{"year":1953,"title":"States Records-æra","producer":"States Records","label":"States","notes":"Første innspillinger som bandleder.","musicians":[],"youtube_id":""},{"year":1957,"title":"Chief / Profile Records-æra","producer":"Chief / Profile Records","label":"Chief / Profile","notes":"Innspillinger fra sent 1950-tall til tidlig 1960-tall.","musicians":[],"youtube_id":""},{"year":1960,"title":"«Little by Little» / «Messin'' with the Kid»","producer":"—","label":"USA Records","notes":"«Little by Little» nådde nummer 23 på Billboard R&B; «Messin'' with the Kid» ble signatursangen hans.","musicians":[],"youtube_id":"cFNyJzCvF1U"},{"year":1965,"title":"Hoodoo Man Blues","producer":"Delmark Records","label":"Delmark","notes":"Med Buddy Guy på gitar (kreditert som «Friendly Chap»). Delmarks bestselgende album; innlemmet i Grammy Hall of Fame.","musicians":[{"name":"Buddy Guy","instrument":"Gitar"},{"name":"Jack Myers","instrument":"Bass"},{"name":"Billy Warren","instrument":"Trommer"}],"youtube_id":"b0IbaQ5GIJs"},{"year":1971,"title":"South Side Blues Jam","producer":"Delmark Records","label":"Delmark","notes":"Delmark-utgivelse fra 1970-tallet.","musicians":[],"youtube_id":""},{"year":1975,"title":"On Tap","producer":"Delmark Records","label":"Delmark","notes":"Delmark-utgivelse fra 1970-tallet.","musicians":[],"youtube_id":""},{"year":1996,"title":"Come On in This House","producer":"Telarc / Blind Pig","label":"Telarc / Blind Pig","notes":"Med Alvin Youngblood Hart og Derek Trucks.","musicians":[{"name":"Alvin Youngblood Hart","instrument":"Gitar"},{"name":"Derek Trucks","instrument":"Gitar"}],"youtube_id":""}]}',
