  family_i18n = '{"en":[{"relation":"Father","name":"Sam Guy","note":"Sharecropper in Lettsworth, Louisiana.","source":"Wikipedia"},{"relation":"Mother","name":"Isabel Guy","note":"The polka-dot motif on his signature guitars honors her.","source":"Wikipedia"},{"relation":"Brother","name":"Phil Guy","note":"Blues musician; frequent recording and touring partner.","source":"Wikipedia"},{"relation":"First wife","name":"Joan Guy","note":"Married 1959; six children together.","source":"Wikipedia"},{"relation":"Second wife","name":"Jennifer Guy","note":"Married 1975–2002; two children, including Rashawnna (rapper Shawnna).","source":"Wikipedia"}],"no":[{"relation":"Far","name":"Sam Guy","note":"Festeoppsitter i Lettsworth, Louisiana.","source":"Wikipedia"},{"relation":"Mor","name":"Isabel Guy","note":"Polkaprikk-motivet på signaturgitarene hans hyller henne.","source":"Wikipedia"},{"relation":"Bror","name":"Phil Guy","note":"Bluesmusiker; hyppig innspillings- og turnépartner.","source":"Wikipedia"},{"relation":"Første kone","name":"Joan Guy","note":"Gift i 1959; seks barn sammen.","source":"Wikipedia"},{"relation":"Andre kone","name":"Jennifer Guy","note":"Gift 1975–2002; to barn, inkludert Rashawnna (rapperen Shawnna).","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1957: Moves to Chicago on September 25. (Kilde: Wikipedia)","1958: A cutting contest against Magic Sam and Otis Rush lands his first record deal. (Kilde: Wikipedia)","1959: Signs to Chess Records as a session guitarist. (Kilde: Wikipedia)","1965: Begins his decades-long partnership with Junior Wells on \"Hoodoo Man Blues.\" (Kilde: Wikipedia)","1991: \"Damn Right, I''ve Got the Blues\" becomes his mainstream breakthrough at age 54. (Kilde: Wikipedia)","2005: Inducted into the Rock and Roll Hall of Fame by Eric Clapton and B.B. King. (Kilde: Wikipedia)"],"no":["1957: Flytter til Chicago 25. september. (Kilde: Wikipedia)","1958: En «cutting contest» mot Magic Sam og Otis Rush gir ham hans første plateavtale. (Kilde: Wikipedia)","1959: Signerer med Chess Records som studiogitarist. (Kilde: Wikipedia)","1965: Begynner sitt flere tiår lange samarbeid med Junior Wells på «Hoodoo Man Blues». (Kilde: Wikipedia)","1991: «Damn Right, I''ve Got the Blues» blir hans mainstream-gjennombrudd som 54-åring. (Kilde: Wikipedia)","2005: Innlemmet i Rock and Roll Hall of Fame av Eric Clapton og B.B. King. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Fender Stratocaster (polka-dot)","note":"His signature instrument since the mid-1990s; the polka-dot pattern honors his late mother.","source":"Wikipedia"},{"category":"Gitar","name":"Harmony acoustic guitar","note":"His first real guitar as a child; now held by the Rock and Roll Hall of Fame.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Fender Stratocaster (polkaprikk)","note":"Hans signaturinstrument siden midten av 1990-tallet; polkaprikkmønsteret hyller hans avdøde mor.","source":"Wikipedia"},{"category":"Gitar","name":"Harmony akustisk gitar","note":"Hans første ekte gitar som barn; eies nå av Rock and Roll Hall of Fame.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Built his first instrument himself as a child — a homemade two-string diddley bow. (Kilde: Wikipedia)","Contractual obligations forced him to be credited as \"Friendly Chap\" on his early recordings with Junior Wells. (Kilde: Wikipedia)","Eric Clapton has said Jimi Hendrix''s teeth-and-behind-the-head guitar showmanship was directly inspired by watching Guy perform at London''s Marquee Club in 1965. (Kilde: Wikipedia)","In February 2012 he performed at the White House and got President Barack Obama to sing part of \"Sweet Home Chicago\" on camera. (Kilde: Wikipedia)","Explained in a 2022 interview that his polka-dot guitar honors a lie he once told his mother — that he had driven to Louisiana in a polka-dot Cadillac. (Kilde: Wikipedia)","Retired from touring in 2024 with the \"Damn Right Farewell Tour,\" but maintained he was \"not done\" with music. (Kilde: Wikipedia)"],"no":["Bygde sitt første instrument selv som barn — en hjemmelaget tostrengs diddley bow. (Kilde: Wikipedia)","Kontraktsforpliktelser tvang ham til å bli kreditert som «Friendly Chap» på sine tidlige innspillinger med Junior Wells. (Kilde: Wikipedia)","Eric Clapton har sagt at Jimi Hendrix'' gitarshow med tenner og bak hodet var direkte inspirert av å se Guy opptre på Londons Marquee Club i 1965. (Kilde: Wikipedia)","I februar 2012 opptrådte han i Det hvite hus og fikk president Barack Obama til å synge deler av «Sweet Home Chicago» på kamera. (Kilde: Wikipedia)","Forklarte i et intervju fra 2022 at polkaprikk-gitaren hans hyller en løgn han en gang fortalte moren sin — at han hadde kjørt til Louisiana i en polkaprikk-Cadillac. (Kilde: Wikipedia)","Trakk seg tilbake fra turnering i 2024 med «Damn Right Farewell Tour», men fastholdt at han «ikke var ferdig» med musikken. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Junior Wells","note":"Harmonica player and his defining musical partner for three decades, beginning 1965.","source":"Wikipedia"},{"name":"Muddy Waters, Howlin'' Wolf, Little Walter","note":"Backed all three as a Chess Records session guitarist.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Idolized him from the 1960s; invited him to the \"24 Nights\" Royal Albert Hall series that sparked his comeback; inducted him into the Rock and Roll Hall of Fame.","source":"Wikipedia"},{"name":"Phil Guy","note":"Brother and frequent recording/touring partner.","source":"Wikipedia"}],"no":[{"name":"Junior Wells","note":"Munnspillspiller og hans definerende musikalske partner i tre tiår, fra 1965.","source":"Wikipedia"},{"name":"Muddy Waters, Howlin'' Wolf, Little Walter","note":"Backet alle tre som studiogitarist for Chess Records.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Tilba ham fra 1960-tallet; inviterte ham til «24 Nights»-serien i Royal Albert Hall som utløste comebacket hans; innlemmet ham i Rock and Roll Hall of Fame.","source":"Wikipedia"},{"name":"Phil Guy","note":"Bror og hyppig innspillings-/turnépartner.","source":"Wikipedia"}]}',
