  family_i18n = '{"en":[{"relation":"Father","name":"Jimmie Lee Vaughan","note":"1921–1986; Stevie was named after him.","source":"Wikipedia"},{"relation":"Mother","name":"Martha Jean Cook","note":"1928–2009.","source":"Wikipedia"},{"relation":"Brother","name":"Jimmie Vaughan","note":"Guitarist, three years older; introduced Stevie to guitar.","source":"Wikipedia"},{"relation":"Wife","name":"Lenora \"Lenny\" Bailey","note":"Married 1979, divorced 1988; the instrumental \"Lenny\" was written for her.","source":"Wikipedia"}],"no":[{"relation":"Far","name":"Jimmie Lee Vaughan","note":"1921–1986; Stevie ble oppkalt etter ham.","source":"Wikipedia"},{"relation":"Mor","name":"Martha Jean Cook","note":"1928–2009.","source":"Wikipedia"},{"relation":"Bror","name":"Jimmie Vaughan","note":"Gitarist, tre år eldre; introduserte Stevie for gitar.","source":"Wikipedia"},{"relation":"Kone","name":"Lenora «Lenny» Bailey","note":"Gift 1979, skilt 1988; instrumentalstykket «Lenny» ble skrevet for henne.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1961: Receives a toy Sears guitar for his seventh birthday. (Kilde: Wikipedia)","1972: Drops out of high school and moves to Austin, Texas. (Kilde: Wikipedia)","1978: Forms Double Trouble with Tommy Shannon and Chris Layton. (Kilde: Wikipedia)","1982: Montreux Jazz Festival performance leads David Bowie to hire him for \"Let''s Dance.\" (Kilde: Wikipedia)","1983: \"Texas Flood\" released June 13, proving there was still an audience for traditional electric blues. (Kilde: Wikipedia)","1986: Enters treatment at Peachford Hospital, Atlanta, after a near-fatal collapse; gets sober. (Kilde: Wikipedia)"],"no":["1961: Får en leke-Sears-gitar til sin sjuende bursdag. (Kilde: Wikipedia)","1972: Dropper ut av videregående og flytter til Austin, Texas. (Kilde: Wikipedia)","1978: Danner Double Trouble med Tommy Shannon og Chris Layton. (Kilde: Wikipedia)","1982: Opptreden på Montreux Jazz Festival fører til at David Bowie hyrer ham til «Let''s Dance». (Kilde: Wikipedia)","1983: «Texas Flood» utgitt 13. juni, beviste at det fortsatt fantes et publikum for tradisjonell elektrisk blues. (Kilde: Wikipedia)","1986: Blir tatt inn til behandling ved Peachford Hospital i Atlanta etter et nesten dødelig kollaps; blir edru. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Fender Stratocaster (\"Number One\")","note":"His primary, heavily modified 1963/1962-composite Stratocaster used throughout his career.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Fender Stratocaster («Number One»)","note":"Hans primære, kraftig modifiserte 1963/1962-komposittstratocaster brukt gjennom hele karrieren.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Began stealing sips of his father''s drinks at age six — the start of a lifelong struggle with alcoholism. (Kilde: Wikipedia)","His 1982 Montreux performance was initially booed by parts of the jazz-festival crowd before David Bowie sought him out afterward. (Kilde: Wikipedia)","Wrote the instrumental \"Lenny\" as a tribute to his first wife, Lenora Bailey. (Kilde: Wikipedia)","Described feeling \"in step with life, in step with myself, in step with my music\" for the first time while recording \"In Step\" after achieving sobriety. (Kilde: Wikipedia)","Died alongside four others, including Eric Clapton''s bodyguard, when their helicopter crashed in fog shortly after leaving an Alpine Valley concert bill they had shared. (Kilde: Wikipedia)","His grave marker in Dallas reads: \"Thank you ... for all the love you passed our way.\" (Kilde: Wikipedia)"],"no":["Begynte å stjele slurker av farens drinker som seksåring — starten på en livslang kamp med alkoholisme. (Kilde: Wikipedia)","Opptredenen hans på Montreux i 1982 ble først buet av deler av jazzfestival-publikummet før David Bowie oppsøkte ham etterpå. (Kilde: Wikipedia)","Skrev instrumentalstykket «Lenny» som en hyllest til sin første kone, Lenora Bailey. (Kilde: Wikipedia)","Beskrev å føle seg «i takt med livet, i takt med meg selv, i takt med musikken min» for første gang mens han spilte inn «In Step» etter å ha blitt edru. (Kilde: Wikipedia)","Døde sammen med fire andre, inkludert Eric Claptons livvakt, da helikopteret deres krasjet i tåke kort tid etter å ha forlatt en Alpine Valley-konsert de hadde delt. (Kilde: Wikipedia)","Gravsteinen hans i Dallas har teksten: «Thank you ... for all the love you passed our way.» (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Double Trouble (Tommy Shannon, Chris Layton)","note":"His backing band from 1978 onward; inducted with him into the Rock and Roll Hall of Fame in 2015.","source":"Wikipedia"},{"name":"David Bowie","note":"Hired him to play lead guitar on \"Let''s Dance\" (1983) after seeing him at Montreux.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Shared the bill at Alpine Valley Music Theatre the night of the fatal helicopter crash.","source":"Wikipedia"},{"name":"Jimmie Vaughan","note":"His older brother, guitarist, and earliest musical influence.","source":"Wikipedia"}],"no":[{"name":"Double Trouble (Tommy Shannon, Chris Layton)","note":"Backingbandet hans fra 1978 og utover; innlemmet sammen med ham i Rock and Roll Hall of Fame i 2015.","source":"Wikipedia"},{"name":"David Bowie","note":"Hyret ham til å spille sologitar på «Let''s Dance» (1983) etter å ha sett ham på Montreux.","source":"Wikipedia"},{"name":"Eric Clapton","note":"Delte plakat på Alpine Valley Music Theatre kvelden for den dødelige helikopterulykken.","source":"Wikipedia"},{"name":"Jimmie Vaughan","note":"Storebroren hans, gitarist, og tidligste musikalske innflytelse.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1983,"title":"Texas Flood","producer":"John Hammond, Richard Mullen","label":"Epic Records","notes":"Debut album, recorded essentially live; proved the mainstream audience for traditional electric blues.","musicians":[{"name":"Tommy Shannon","instrument":"Bass"},{"name":"Chris Layton","instrument":"Drums"}],"youtube_id":"evjMjpd4PNM"},{"year":1984,"title":"Couldn''t Stand the Weather","producer":"Richard Mullen, Stevie Ray Vaughan","label":"Epic Records","notes":"—","musicians":[],"youtube_id":""},{"year":1985,"title":"Soul to Soul","producer":"Richard Mullen, Stevie Ray Vaughan and Double Trouble","label":"Epic Records","notes":"—","musicians":[],"youtube_id":""},{"year":1986,"title":"Live Alive","producer":"Stevie Ray Vaughan and Double Trouble","label":"Epic Records","notes":"The only official live album released during his lifetime.","musicians":[],"youtube_id":""},{"year":1989,"title":"In Step","producer":"Jim Gaines","label":"Epic Records","notes":"Recorded after he achieved sobriety; includes his only #1 hit, \"Crossfire.\"","musicians":[],"youtube_id":""}],"no":[{"year":1983,"title":"Texas Flood","producer":"John Hammond, Richard Mullen","label":"Epic Records","notes":"Debutalbum, spilt inn nærmest live; beviste mainstream-publikummet for tradisjonell elektrisk blues.","musicians":[{"name":"Tommy Shannon","instrument":"Bass"},{"name":"Chris Layton","instrument":"Trommer"}],"youtube_id":"evjMjpd4PNM"},{"year":1984,"title":"Couldn''t Stand the Weather","producer":"Richard Mullen, Stevie Ray Vaughan","label":"Epic Records","notes":"—","musicians":[],"youtube_id":""},{"year":1985,"title":"Soul to Soul","producer":"Richard Mullen, Stevie Ray Vaughan and Double Trouble","label":"Epic Records","notes":"—","musicians":[],"youtube_id":""},{"year":1986,"title":"Live Alive","producer":"Stevie Ray Vaughan and Double Trouble","label":"Epic Records","notes":"Det eneste offisielle liveealbumet utgitt i løpet av hans levetid.","musicians":[],"youtube_id":""},{"year":1989,"title":"In Step","producer":"Jim Gaines","label":"Epic Records","notes":"Spilt inn etter at han ble edru; inkluderer hans eneste nummer-én-hit, «Crossfire».","musicians":[],"youtube_id":""}]}',
  videos = '[{"kind":"featured","title":"Stevie Ray Vaughan & Double Trouble - Texas Flood (Live From Austin, TX)","youtube_id":"evjMjpd4PNM","channel":"stevierayvaughnVEVO","note":"The title track that launched his career, cut essentially live in the studio."},{"kind":"more","title":"Stevie Ray Vaughan & Double Trouble - Pride And Joy (Live at Montreux 1982)","youtube_id":"kfjXp4KTTY8","channel":"stevierayvaughnVEVO"},{"kind":"more","title":"Stevie Ray Vaughan ~Voodoo Child ~ Live From Austin TX","youtube_id":"cFwTbsKkqxE","channel":"Patricia Ni_Sol"}]',
