  family_i18n = '{"en":[{"relation":"Sisters","name":"Rebecca Lovell & Megan Lovell","note":"Core duo of Larkin Poe; born 1991 and 1989 respectively.","source":"Wikipedia"},{"relation":"Older sister","name":"Jessica Lovell","note":"Third member of their earlier bluegrass trio, the Lovell Sisters; left in 2009 to start a family.","source":"Wikipedia"},{"relation":"Namesake ancestor","name":"Larkin Poe","note":"Great-great-great-great-grandfather, a first cousin of Edgar Allan Poe; the band is named for him.","source":"Wikipedia"}],"no":[{"relation":"Søstre","name":"Rebecca Lovell & Megan Lovell","note":"Kjerneduoen i Larkin Poe; født henholdsvis 1991 og 1989.","source":"Wikipedia"},{"relation":"Storesøster","name":"Jessica Lovell","note":"Tredje medlem av deres tidligere bluegrass-trio, the Lovell Sisters; sluttet i 2009 for å starte familie.","source":"Wikipedia"},{"relation":"Navnegivende forfar","name":"Larkin Poe","note":"Tipp-tipp-tippoldefar, en fetter av Edgar Allan Poe; bandet er oppkalt etter ham.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["2005: Rebecca and Megan form the acoustic bluegrass trio the Lovell Sisters with older sister Jessica. (Kilde: Wikipedia)","December 2009: The Lovell Sisters disband. (Kilde: Wikipedia)","January 2010: Rebecca and Megan regroup as Larkin Poe, moving toward blues and roots-rock. (Kilde: Wikipedia)","2014: Debut album \"Kin\" released; plays Glastonbury Festival, named \"Best Discovery of Glastonbury 2014\" by The Observer. (Kilde: Wikipedia)","2024: \"Blood Harmony\" wins the Grammy Award for Best Contemporary Blues Album. (Kilde: Wikipedia)"],"no":["2005: Rebecca og Megan danner den akustiske bluegrass-trioen the Lovell Sisters med storesøsteren Jessica. (Kilde: Wikipedia)","Desember 2009: The Lovell Sisters oppløses. (Kilde: Wikipedia)","Januar 2010: Rebecca og Megan samler seg som Larkin Poe, og beveger seg mot blues og roots-rock. (Kilde: Wikipedia)","2014: Debutalbumet «Kin» utgitt; spiller på Glastonbury Festival, kåret til «Best Discovery of Glastonbury 2014» av The Observer. (Kilde: Wikipedia)","2024: «Blood Harmony» vinner Grammy-prisen for beste samtidsbluesalbum. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Lap-steel guitar (Megan)","note":"Central to the band''s identity rather than a decorative accent; one of the most distinctive lap-steel voices in modern blues.","source":"Wikipedia"},{"category":"Gitar","name":"Electric guitar & voice (Rebecca)","note":"Handles lead vocals and electric guitar.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Lap-steel-gitar (Megan)","note":"Sentral for bandets identitet snarere enn en dekorativ detalj; en av de mest særpregede lap-steel-stemmene i moderne blues.","source":"Wikipedia"},{"category":"Gitar","name":"Elektrisk gitar & vokal (Rebecca)","note":"Håndterer hovedvokal og elektrisk gitar.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["The band''s name honors their great-great-great-great-grandfather Larkin Poe, a first cousin of Edgar Allan Poe. (Kilde: Wikipedia)","Started as a classically trained bluegrass trio, the Lovell Sisters, with their older sister Jessica before reforming as a duo. (Kilde: Wikipedia)","Built their early audience through a stream of blues and rock cover videos posted online. (Kilde: Wikipedia)","Named \"Best Discovery of Glastonbury 2014\" by The Observer after their festival debut. (Kilde: Wikipedia)","Contributed to producer T Bone Burnett''s \"Lost on the River: The New Basement Tapes,\" setting newly discovered Bob Dylan lyrics to music alongside Elvis Costello and Marcus Mumford. (Kilde: Wikipedia)"],"no":["Bandnavnet hyller deres tipp-tipp-tippoldefar Larkin Poe, en fetter av Edgar Allan Poe. (Kilde: Wikipedia)","Startet som en klassisk skolert bluegrass-trio, the Lovell Sisters, med storesøsteren Jessica før de omdannet seg til en duo. (Kilde: Wikipedia)","Bygde sitt tidlige publikum gjennom en strøm av blues- og rockecover-videoer lagt ut på nett. (Kilde: Wikipedia)","Kåret til «Best Discovery of Glastonbury 2014» av The Observer etter festivaldebuten deres. (Kilde: Wikipedia)","Bidro til produsent T Bone Burnetts «Lost on the River: The New Basement Tapes», hvor de satte nyoppdagede Bob Dylan-tekster til musikk sammen med Elvis Costello og Marcus Mumford. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Jessica Lovell","note":"Older sister; third member of the earlier bluegrass trio the Lovell Sisters.","source":"Wikipedia"},{"name":"T Bone Burnett","note":"Producer of \"Lost on the River: The New Basement Tapes\" (2014), which they contributed to.","source":"Wikipedia"},{"name":"Elvis Costello, Marcus Mumford","note":"Fellow contributors on \"Lost on the River: The New Basement Tapes.\"","source":"Wikipedia"}],"no":[{"name":"Jessica Lovell","note":"Storesøster; tredje medlem av den tidligere bluegrass-trioen the Lovell Sisters.","source":"Wikipedia"},{"name":"T Bone Burnett","note":"Produsent av «Lost on the River: The New Basement Tapes» (2014), som de bidro til.","source":"Wikipedia"},{"name":"Elvis Costello, Marcus Mumford","note":"Medbidragsytere på «Lost on the River: The New Basement Tapes».","source":"Wikipedia"}]}',
