  anecdotes_i18n = '{"en":["Got his stage name directly from Ronnie Hawkins, who named him after the radio show \"King Biscuit Time.\" (Kilde: Wikipedia)","Became the first Canadian blues artist ever to chart on the Billboard Hot 100. (Kilde: Wikipedia)","Recorded his 1974 self-titled album in New Orleans backed by Allen Toussaint''s studio band, the Meters. (Kilde: Wikipedia)","Critic Robert Christgau praised his \"virtuoso harmonica\" playing. (Kilde: Wikipedia)","Friends established the annual \"Blues with a Feeling\" benefit concert and a music scholarship at Mohawk College in his memory after his 2003 death. (Kilde: Wikipedia)"],"no":["Fikk scenenavnet sitt direkte fra Ronnie Hawkins, som oppkalte ham etter radioprogrammet «King Biscuit Time». (Kilde: Wikipedia)","Ble den første kanadiske bluesartisten noensinne til å nå Billboard Hot 100. (Kilde: Wikipedia)","Spilte inn sitt selvtitulerte album fra 1974 i New Orleans, backet av Allen Toussaints studioband, the Meters. (Kilde: Wikipedia)","Kritiker Robert Christgau roste hans «virtuose munnspill»-spilling. (Kilde: Wikipedia)","Venner etablerte den årlige veldedighetskonserten «Blues with a Feeling» og et musikkstipend ved Mohawk College til hans minne etter hans død i 2003. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Ronnie Hawkins","note":"Gave him his stage name and bandleader role in \"And Many Others\" (1969).","source":"Wikipedia"},{"name":"Crowbar","note":"Band formed by Hawkins''s ex-backing musicians; he played with them intermittently throughout his career.","source":"Wikipedia"},{"name":"Allen Toussaint & the Meters","note":"Backed him on his 1974 self-titled album, recorded in New Orleans.","source":"Wikipedia"},{"name":"Sonny Del-Rio","note":"Fellow Crowbar veteran and lifelong friend; recorded \"Two Hound Blues\" together, released posthumously in 2003.","source":"Wikipedia"}],"no":[{"name":"Ronnie Hawkins","note":"Ga ham scenenavnet hans og en bandlederrolle i «And Many Others» (1969).","source":"Wikipedia"},{"name":"Crowbar","note":"Band dannet av Hawkins'' tidligere backingmusikere; han spilte med jevne mellomrom med dem gjennom karrieren.","source":"Wikipedia"},{"name":"Allen Toussaint & the Meters","note":"Backet ham på hans selvtitulerte album fra 1974, spilt inn i New Orleans.","source":"Wikipedia"},{"name":"Sonny Del-Rio","note":"Crowbar-veteran og livslang venn; spilte inn «Two Hound Blues» sammen, utgitt posthumt i 2003.","source":"Wikipedia"}]}',
