  family_i18n = '{"en":[{"relation":"Wife","name":"Heather","note":"Married 1989.","source":"Wikipedia"},{"relation":"Grandfather","name":"—","note":"Serbian heritage.","source":"Wikipedia"}],"no":[{"relation":"Kone","name":"Heather","note":"Gift i 1989.","source":"Wikipedia"},{"relation":"Bestefar","name":"—","note":"Serbisk avstamning.","source":"Wikipedia"}]}',
  formative_i18n = '{"en":["1983: Unexpectedly opens for Stevie Ray Vaughan in Regina; becomes a permanent tour opener. (Kilde: Wikipedia)","1988: Self-titled debut album released. (Kilde: Wikipedia)","1990: \"Just Came Back (to Say Goodbye)\" wins the Juno Award for Single of the Year. (Kilde: Wikipedia)","1993: \"Colin James and the Little Big Band\" pivots into swing revival. (Kilde: Wikipedia)","1997: \"National Steel\" — widely considered his purest blues record. (Kilde: Wikipedia)"],"no":["1983: Forspiller uventet for Stevie Ray Vaughan i Regina; blir et fast forband på turné. (Kilde: Wikipedia)","1988: Det selvtitulerte debutalbumet gis ut. (Kilde: Wikipedia)","1990: «Just Came Back (to Say Goodbye)» vinner Juno-prisen for årets singel. (Kilde: Wikipedia)","1993: «Colin James and the Little Big Band» svinger inn i swing-vekkelse. (Kilde: Wikipedia)","1997: «National Steel» — bredt ansett som hans reneste blueplate. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Electric & National Steel guitar","note":"Moves between blues-rock electric guitar and stripped-down resonator/steel guitar work.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Elektrisk & National Steel-gitar","note":"Beveger seg mellom bluesrock elektrisk gitar og nedstrippet resonator-/stålgitararbeid.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Got his break entirely by chance: the scheduled opener for a 1983 Stevie Ray Vaughan show never arrived, and he filled in with only hours'' notice. (Kilde: Wikipedia)","His stage name is reportedly Vaughan''s own suggestion, since \"Munn\" sounded too much like \"Mud\" through arena PA systems. (Kilde: Wikipedia)","Performed a command performance for Queen Elizabeth II in Saskatchewan in 2005. (Kilde: Wikipedia)","Appointed to the Order of British Columbia in 2024. (Kilde: Wikipedia)"],"no":["Fikk gjennombruddet sitt helt tilfeldig: det planlagte forbandet til en Stevie Ray Vaughan-konsert i 1983 dukket aldri opp, og han steppet inn med bare noen timers varsel. (Kilde: Wikipedia)","Scenenavnet hans er visstnok Vaughans eget forslag, siden «Munn» hørtes for mye ut som «Mud» gjennom arena-PA-anlegg. (Kilde: Wikipedia)","Holdt en gallaopptreden for dronning Elizabeth II i Saskatchewan i 2005. (Kilde: Wikipedia)","Utnevnt til Order of British Columbia i 2024. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Stevie Ray Vaughan","note":"Discovered him by chance in 1983 and made him a permanent tour opener.","source":"Wikipedia"},{"name":"Bonnie Raitt","note":"Recording and performing collaborator.","source":"Wikipedia"},{"name":"The Chieftains","note":"Recording collaborator.","source":"Wikipedia"}],"no":[{"name":"Stevie Ray Vaughan","note":"Oppdaget ham tilfeldig i 1983 og gjorde ham til et fast forband på turné.","source":"Wikipedia"},{"name":"Bonnie Raitt","note":"Innspillings- og opptredenssamarbeidspartner.","source":"Wikipedia"},{"name":"The Chieftains","note":"Innspillingssamarbeidspartner.","source":"Wikipedia"}]}',
