  formative_i18n = '{"en":["Starts on electric guitar, switches to banjo after hearing bluegrass band Gone At Last. (Kilde: Store norske leksikon)","Hears Robert Johnson and reorients completely toward acoustic blues, buying a 12-string National Steel resonator guitar. (Kilde: Rockipedia)","1994: Recording debut on \"Berge/Flaaten\" with Jan Flåten. (Kilde: Rockipedia)","1996: Begins solo career after the Flåten partnership ends. (Kilde: Rockipedia)","2001 & 2002: Wins the Spellemannpris for \"Stringmachine\" and \"Illustrated Man.\" (Kilde: Rockipedia)"],"no":["Starter på elektrisk gitar, bytter til banjo etter å ha hørt bluegrassbandet Gone At Last. (Kilde: Store norske leksikon)","Hører Robert Johnson og vender seg fullstendig mot akustisk blues, og kjøper en 12-strengs National Steel-resonatorgitar. (Kilde: Rockipedia)","1994: Innspillingsdebut på «Berge/Flaaten» med Jan Flåten. (Kilde: Rockipedia)","1996: Begynner solokarriere etter at Flåten-samarbeidet tar slutt. (Kilde: Rockipedia)","2001 og 2002: Vinner Spellemannprisen for «Stringmachine» og «Illustrated Man». (Kilde: Rockipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"12-string National Steel resonator guitar","note":"His signature instrument since abandoning electric guitar and banjo after discovering Robert Johnson.","source":"Rockipedia"},{"category":"Annet","name":"Stomp box","note":"Foot-operated percussion box; central to his \"one-man band\" technique of playing rhythm, melody and percussion simultaneously.","source":"Rockipedia"}],"no":[{"category":"Gitar","name":"12-strengs National Steel-resonatorgitar","note":"Hans signaturinstrument etter at han forlot elektrisk gitar og banjo etter å ha oppdaget Robert Johnson.","source":"Rockipedia"},{"category":"Annet","name":"Stompboks","note":"Fotbetjent perkusjonsboks; sentral for hans «enmannsorkester»-teknikk med å spille rytme, melodi og perkusjon samtidig.","source":"Rockipedia"}]}',
  anecdotes_i18n = '{"en":["Started on electric guitar and briefly switched to banjo before hearing Robert Johnson, which sent him permanently toward acoustic Delta blues. (Kilde: Store norske leksikon)","Norway''s national encyclopedia credits him with developing \"a distinctive expression within a music style often regarded as stagnant.\" (Kilde: Store norske leksikon)","His acoustic, slide-driven cover of Motörhead''s \"Ace of Spades\" became his best-known live showpiece, performed everywhere from Trondheim to Paris''s New Morning club. (Kilde: Rockipedia)","Served as guitarist for Norwegian folk-rock band Vamp from 2014 to 2019, replacing Torbjørn Økland. (Kilde: Store norske leksikon)"],"no":["Startet på elektrisk gitar og byttet kort til banjo før han hørte Robert Johnson, som sendte ham permanent mot akustisk deltablues. (Kilde: Store norske leksikon)","Store norske leksikon krediterer ham for å ha utviklet «et eget uttrykk innenfor en musikkstil som ofte betraktes som stagnert». (Kilde: Store norske leksikon)","Hans akustiske, slide-drevne cover av Motörheads «Ace of Spades» ble hans mest kjente scenestykke, fremført overalt fra Trondheim til New Morning-klubben i Paris. (Kilde: Rockipedia)","Fungerte som gitarist for det norske folk-rock-bandet Vamp fra 2014 til 2019, og erstattet Torbjørn Økland. (Kilde: Store norske leksikon)"]}',
  collaborators_i18n = '{"en":[{"name":"Jan Flåten","note":"Vocalist and harmonica player; recording partner on his 1994 debut \"Berge/Flaaten.\"","source":"Rockipedia"},{"name":"Vamp","note":"Norwegian folk-rock band; served as guitarist/dobro player 2014–2019.","source":"Store norske leksikon"},{"name":"Odin Staveland","note":"Vamp bandmate; released a duo album with him in 2023.","source":"Store norske leksikon"}],"no":[{"name":"Jan Flåten","note":"Vokalist og munnspillspiller; innspillingspartner på debuten «Berge/Flaaten» fra 1994.","source":"Rockipedia"},{"name":"Vamp","note":"Norsk folk-rock-band; fungerte som gitarist/dobro-spiller 2014–2019.","source":"Store norske leksikon"},{"name":"Odin Staveland","note":"Vamp-bandmedlem; ga ut et duoalbum med ham i 2023.","source":"Store norske leksikon"}]}',
  discography_i18n = '{"en":[{"year":1994,"title":"Berge/Flaaten","producer":"—","label":"—","notes":"Recording debut, with Jan Flåten on vocals and harmonica.","musicians":[{"name":"Jan Flåten","instrument":"Vocals, harmonica"}],"youtube_id":""},{"year":1997,"title":"Bjørn Berge","producer":"—","label":"—","notes":"First solo album.","musicians":[],"youtube_id":""},{"year":2000,"title":"Bag of Nails","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2001,"title":"Stringmachine","producer":"—","label":"—","notes":"Won the Spellemannpris (Blues category).","musicians":[],"youtube_id":"CwjVlEgvEuc"},{"year":2002,"title":"Illustrated Man","producer":"—","label":"—","notes":"Won the Spellemannpris (Blues category).","musicians":[],"youtube_id":""},{"year":2004,"title":"St. Slide","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2006,"title":"We''re Gonna Groove","producer":"—","label":"—","notes":"Played all instruments except drums.","musicians":[],"youtube_id":""},{"year":2007,"title":"I''m the Antipop","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2009,"title":"Fretwork","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2011,"title":"Blackwood","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2013,"title":"Mad Fingers Ball","producer":"—","label":"—","notes":"Spellemannpris-nominated.","musicians":[],"youtube_id":""},{"year":2019,"title":"Who Else?","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2024,"title":"Introducing SteelFinger Slim","producer":"—","label":"Blue Mood Records","notes":"His thirteenth studio album.","musicians":[],"youtube_id":""}],"no":[{"year":1994,"title":"Berge/Flaaten","producer":"—","label":"—","notes":"Innspillingsdebut, med Jan Flåten på vokal og munnspill.","musicians":[{"name":"Jan Flåten","instrument":"Vokal, munnspill"}],"youtube_id":""},{"year":1997,"title":"Bjørn Berge","producer":"—","label":"—","notes":"Første soloalbum.","musicians":[],"youtube_id":""},{"year":2000,"title":"Bag of Nails","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2001,"title":"Stringmachine","producer":"—","label":"—","notes":"Vant Spellemannprisen (Blues-kategorien).","musicians":[],"youtube_id":"CwjVlEgvEuc"},{"year":2002,"title":"Illustrated Man","producer":"—","label":"—","notes":"Vant Spellemannprisen (Blues-kategorien).","musicians":[],"youtube_id":""},{"year":2004,"title":"St. Slide","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2006,"title":"We''re Gonna Groove","producer":"—","label":"—","notes":"Spilte alle instrumenter unntatt trommer.","musicians":[],"youtube_id":""},{"year":2007,"title":"I''m the Antipop","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2009,"title":"Fretwork","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2011,"title":"Blackwood","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2013,"title":"Mad Fingers Ball","producer":"—","label":"—","notes":"Spellemannpris-nominert.","musicians":[],"youtube_id":""},{"year":2019,"title":"Who Else?","producer":"—","label":"—","notes":"—","musicians":[],"youtube_id":""},{"year":2024,"title":"Introducing SteelFinger Slim","producer":"—","label":"Blue Mood Records","notes":"Hans trettende studioalbum.","musicians":[],"youtube_id":""}]}',
  videos = '[{"kind":"featured","title":"Bjørn Berge - Ace of Spades - New Morning PARIS - 22.11.2021","youtube_id":"M3C99xA8_p0","channel":"Gnac17","note":"His acoustic, slide-driven reworking of the Motörhead classic — his best-known live showpiece."},{"kind":"more","title":"Bjørn Berge \"Stringmachine\"","youtube_id":"CwjVlEgvEuc","channel":"livedtap"},{"kind":"more","title":"Bjørn Berge - Ace of Spades Live in Trondheim 17''th of september 2014","youtube_id":"Rq8oAbfCMk8","channel":"bluesplumber"}]',
