":[{"name":"Mike Brignardello","instrument":"Bass"},{"name":"Wes Little","instrument":"Trommer, perkusjon"},{"name":"Jimmy Nichols","instrument":"Piano, Wurlitzer, Hammond-orgel"},{"name":"Chris Leuzinger","instrument":"Gitar"},{"name":"Joe Wilkins","instrument":"Gitar"}],"youtube_id":"7fAS-RjrO1c"},{"year":2020,"title":"Ain''t Nothing But","producer":"Richard Stockley (miks/master)","label":"Outlaw Music","notes":"Live-/nedstrippet album. Nominert, UK Blues Awards Blues Album of the Year 2021.","musicians":[{"name":"Joe Wilkins","instrument":"Gitar, bakgrunnsvokal"},{"name":"Phil King","instrument":"Gitar, bakgrunnsvokal"},{"name":"Joe James","instrument":"Kontrabass, bakgrunnsvokal"}],"youtube_id":""},{"year":2022,"title":"Shining in the Half Light","producer":"Dan Weller","label":"Outlaw Music","notes":"Spilt inn ved Middle Farm Studios og Sound Emporium, Nashville, under koronanedstengingen mens Bailey var gravid; hun gjennomgikk de siste miksene fra en sykehusseng. Nådde nummer 42 på UK Albums Chart.","musicians":[{"name":"Matthew Jones","instrument":"Trommer, perkusjon"},{"name":"Joe Wilkins","instrument":"Gitar"},{"name":"Kris Donegan","instrument":"Gitar"},{"name":"Jonny Henderson","instrument":"Piano, Wurlitzer, Hammond-orgel"}],"youtube_id":""},{"year":2024,"title":"Beneath the Neon Glow","producer":"Dan Weller","label":"Cooking Vinyl","notes":"Spilt inn ved Middle Farm Studios og 13 Sound Studios. Nådde nummer 12 på UK Albums Chart, nummer 1 på UK Blues Chart. Feide innom UK Blues Awards 2025 (Vocalist, Broadcaster, Album of the Year).","musicians":[{"name":"Matthew Waer","instrument":"Bass"},{"name":"Jonny Henderson","instrument":"Clavinet, Wurlitzer, piano, Hammond-orgel"},{"name":"Matthew Jones","instrument":"Trommer, perkusjon"},{"name":"Joe Wilkins","instrument":"Gitar"},{"name":"Pete Fraser","instrument":"Saksofon"},{"name":"Cormac Neeson","instrument":"Munnspill"},{"name":"Holly Carter","instrument":"Pedal steel-gitar"}],"youtube_id":"WzrFkwLYtYQ"},{"year":2025,"title":"Beneath the Neon Glow (Reimagined)","producer":"Dan Weller","label":"Cooking Vinyl","notes":"Nedstrippet vokal-og-piano-følgesvennutgivelse med to ekstra spor.","musicians":[],"youtube_id":""},{"year":2026,"title":"Can''t Take My Story Away","producer":"—","label":"Cooking Vinyl","notes":"Kommende studioalbum.","musicians":[],"youtube_id":""}]}',
