  formative_i18n = '{"en":["Trains at Copenhagen''s Rytmisk Musikkonservatorium. (Kilde: dansk Wikipedia)","2002: Founds the septet Thorbjørn Risager Blue7. (Kilde: dansk Wikipedia)","2004: Releases live debut \"Live 2004.\" (Kilde: dansk Wikipedia)","2005: Named \"Årets danske blues navn\" (Denmark''s Blues Name of the Year). (Kilde: dansk Wikipedia)","2014: The expanded lineup begins performing as Thorbjørn Risager & The Black Tornado with \"Too Many Roads.\" (Kilde: dansk Wikipedia)","2017: Wins Best Blues Band at the European Blues Awards. (Kilde: dansk Wikipedia)"],"no":["Trener ved Rytmisk Musikkonservatorium i København. (Kilde: dansk Wikipedia)","2002: Grunnlegger septetten Thorbjørn Risager Blue7. (Kilde: dansk Wikipedia)","2004: Gir ut livedebuten «Live 2004». (Kilde: dansk Wikipedia)","2005: Kåret til «Årets danske blues navn». (Kilde: dansk Wikipedia)","2014: Den utvidede besetningen begynner å opptre som Thorbjørn Risager & The Black Tornado med «Too Many Roads». (Kilde: dansk Wikipedia)","2017: Vinner Best Blues Band på European Blues Awards. (Kilde: dansk Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Vokal","name":"Vocals, guitars, Dobro (Risager)","note":"Lead vocalist, guitarist and primary songwriter for the band since its founding.","source":"dansk Wikipedia"},{"category":"Annet","name":"Eight-piece horn-and-strings ensemble","note":"Full band includes saxophones, clarinet, trumpet, flugelhorn, trombone and sousaphone alongside guitars, keys, bass and drums.","source":"dansk Wikipedia"}],"no":[{"category":"Vokal","name":"Vokal, gitarer, dobro (Risager)","note":"Hovedvokalist, gitarist og primær låtskriver for bandet siden grunnleggelsen.","source":"dansk Wikipedia"},{"category":"Annet","name":"Åttemanns messingblås-og-stryker-ensemble","note":"Fullt band inkluderer saksofoner, klarinett, trompet, flygelhorn, trombone og sousafon sammen med gitarer, keyboard, bass og trommer.","source":"dansk Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Founded the band as a septet, Thorbjørn Risager Blue7, in 2002, before it grew into the eight-piece Black Tornado. (Kilde: dansk Wikipedia)","Named Denmark''s Blues Name of the Year in 2005, just three years after founding the band. (Kilde: dansk Wikipedia)","The Black Tornado''s horn section alone includes saxophones, clarinet, trumpet, flugelhorn, trombone and sousaphone — an unusually large arsenal for a touring blues band. (Kilde: dansk Wikipedia)","Won Best Blues Band at the 2017 European Blues Awards, cementing the band''s status as Denmark''s leading international blues export. (Kilde: dansk Wikipedia)"],"no":["Grunnla bandet som en septett, Thorbjørn Risager Blue7, i 2002, før det vokste til den åttemanns Black Tornado. (Kilde: dansk Wikipedia)","Kåret til Danmarks bluesnavn for året i 2005, bare tre år etter at bandet ble grunnlagt. (Kilde: dansk Wikipedia)","Black Tornados blåserseksjon alene inkluderer saksofoner, klarinett, trompet, flygelhorn, trombone og sousafon — et uvanlig stort arsenal for et turnerende blueband. (Kilde: dansk Wikipedia)","Vant Best Blues Band på European Blues Awards i 2017, og sementerte bandets status som Danmarks fremste internasjonale blueseksport. (Kilde: dansk Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Emil Balsgaard","note":"Piano, organ, Rhodes.","source":"dansk Wikipedia"},{"name":"Joachim Svensmark","note":"Guitars.","source":"dansk Wikipedia"},{"name":"Kasper Wagner & Hans Nybo","note":"Saxophones, clarinet.","source":"dansk Wikipedia"},{"name":"Søren Bøjgaard","note":"Bass; produced \"Navigation Blues.\"","source":"dansk Wikipedia"}],"no":[{"name":"Emil Balsgaard","note":"Piano, orgel, Rhodes.","source":"dansk Wikipedia"},{"name":"Joachim Svensmark","note":"Gitarer.","source":"dansk Wikipedia"},{"name":"Kasper Wagner & Hans Nybo","note":"Saksofoner, klarinett.","source":"dansk Wikipedia"},{"name":"Søren Bøjgaard","note":"Bass; produserte «Navigation Blues».","source":"dansk Wikipedia"}]}',
