  discography_i18n = '{"en":[{"year":1926,"title":"First Paramount sessions, Marsh Laboratories, Chicago","producer":"Paramount Records (Mayo Williams)","label":"Paramount Records","notes":"December 1925/January 1926 debut, credited as \"Deacon L. J. Bates\"; further sessions through the year at Marsh Laboratories in Chicago produced the breakout secular hit \"Long Lonesome Blues.\" Solo — voice and guitar only, as on almost all his recordings.","musicians":[],"youtube_id":""},{"year":1927,"title":"Chicago sessions with pianist George Perkins","producer":"Paramount Records (Mayo Williams)","label":"Paramount Records","notes":"May–June 1927 sessions were among the very few of his career to feature a second musician rather than solo guitar.","musicians":[{"name":"George Perkins","instrument":"Piano"}],"youtube_id":""},{"year":1927,"title":"Okeh Records session, Atlanta","producer":"Okeh Records","label":"Okeh Records","notes":"One-off session away from Paramount, March 14–15, 1927; recorded \"Black Snake Moan\" and \"Matchbox Blues\" in a single sitting. Solo.","musicians":[],"youtube_id":"o_J9xMfpTVY"},{"year":1927,"title":"\"See That My Grave Is Kept Clean\" (original), Chicago","producer":"Paramount Records","label":"Paramount Records","notes":"October 1927 original recording, credited as \"Deacon L. J. Bates.\" Solo.","musicians":[],"youtube_id":""},{"year":1928,"title":"\"See That My Grave Is Kept Clean\" (re-recording), Chicago","producer":"Paramount Records","label":"Paramount Records","notes":"Re-recorded in February 1928 after the October 1927 original sold well. Solo.","musicians":[],"youtube_id":"7zSH_jpVXQk"},{"year":1929,"title":"Gennett Studios session, Richmond, Indiana","producer":"Gennett Records","label":"Gennett Records (Paramount lease)","notes":"September 24, 1929; recorded at the same Richmond, Indiana studio Charley Patton used the same year. Solo.","musicians":[],"youtube_id":""},{"year":1929,"title":"Final Chicago ensemble session","producer":