  discography_i18n = '{"en":[{"year":1923,"title":"First Columbia session, New York","producer":"Frank Walker","label":"Columbia Records","notes":"February 15, 1923, engineered by Dan Hornsby — produced breakout hit \"Downhearted Blues,\" which sold roughly 750,000 copies in six months. Accompanied by pianist Clarence Williams, who arranged many of her earliest sides.","musicians":[{"name":"Clarence Williams","instrument":"Piano"}],"youtube_id":"5TzylwYt-YM"},{"year":1925,"title":"\"St. Louis Blues\" session, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Recorded January 14, 1925, with Louis Armstrong on cornet and Fred Longshaw on pump organ — her first electrical-era session.","musicians":[{"name":"Louis Armstrong","instrument":"Cornet"},{"name":"Fred Longshaw","instrument":"Pump organ"}],"youtube_id":"hpu14BRmvGA"},{"year":1925,"title":"\"Cake Walking Babies (From Home)\" session, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Recorded May 5, 1925, her first fully electrical recording; backed by Fletcher Henderson''s orchestra with Joe Smith on cornet.","musicians":[{"name":"Fletcher Henderson","instrument":"Piano, bandleader"},{"name":"Joe Smith","instrument":"Cornet"}],"youtube_id":""},{"year":1927,"title":"\"Backwater Blues\" session, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Recorded February 17, 1927, accompanied by stride pianist James P. Johnson; released just before the Great Mississippi Flood, giving the song an eerily prophetic resonance.","musicians":[{"name":"James P. Johnson","instrument":"Piano"}],"youtube_id":""},{"year":1929,"title":"\"Nobody Knows You When You''re Down and Out\" session, New York","producer":"Columbia Records","label":"Columbia Records","notes":"Recorded May 15, 1929; released September 13, 1929, days before the Wall Street Crash — its lyrics proved eerily prophetic.","musicians":[],"youtube_id":"e3AwfORXYpQ"},{"year":1933,"title":"Final session, New York","producer":"John Hammond","label":"Okeh Records","notes":"November 24, 1933, produced by a 22-year-old John Hammond for Okeh; her last recordings, featuring a young Benny Goodman on clarinet.","musicians":[{"name":"Benny Goodman","instrument":"Clarinet"},{"name":"Jack Teagarden","instrument":"Trombone"}],"youtube_id":""}],"no":[{"year":1923,"title":"Første Columbia-økt, New York","producer":"Frank Walker","label":"Columbia Records","notes":"15. februar 1923, med lydtekniker Dan Hornsby — produserte gjennombruddshiten «Downhearted Blues», som solgte rundt 750 000 eksemplarer på seks måneder. Akkompagnert av pianist Clarence Williams, som arrangerte mange av hennes tidligste spor.","musicians":[{"name":"Clarence Williams","instrument":"Piano"}],"youtube_id":"5TzylwYt-YM"},{"year":1925,"title":"«St. Louis Blues»-økt, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Spilt inn 14. januar 1925, med Louis Armstrong på kornett og Fred Longshaw på pumpeorgel — hennes første elektriske-æra-økt.","musicians":[{"name":"Louis Armstrong","instrument":"Kornett"},{"name":"Fred Longshaw","instrument":"Pumpeorgel"}],"youtube_id":"hpu14BRmvGA"},{"year":1925,"title":"«Cake Walking Babies (From Home)»-økt, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Spilt inn 5. mai 1925, hennes første helelektriske innspilling; backet av Fletcher Hendersons orkester med Joe Smith på kornett.","musicians":[{"name":"Fletcher Henderson","instrument":"Piano, bandleder"},{"name":"Joe Smith","instrument":"Kornett"}],"youtube_id":""},{"year":1927,"title":"«Backwater Blues»-økt, New York","producer":"Frank Walker","label":"Columbia Records","notes":"Spilt inn 17. februar 1927, akkompagnert av stride-pianisten James P. Johnson; utgitt rett før Den store Missisipi-flommen, noe som ga sangen en uhyggelig profetisk klang.","musicians":[{"name":"James P. Johnson","instrument":"Piano"}],"youtube_id":""},{"year":1929,"title":"«Nobody Knows You When You''re Down and Out»-økt, New York","producer":"Columbia Records","label":"Columbia Records","notes":"Spilt inn 15. mai 1929; utgitt 13. september 1929, dager før børskrakket på Wall Street — tekstene viste seg å være uhyggelig profetiske.","musicians":[],"youtube_id":"e3AwfORXYpQ"},{"year":1933,"title":"Siste økt, New York","producer":"John Hammond","label":"Okeh Records","notes":"24. november 1933, produsert av en 22 år gammel John Hammond for Okeh; hennes siste innspillinger, med en ung Benny Goodman på klarinett.","musicians":[{"name":"Benny Goodman","instrument":"Klarinett"},{"name":"Jack Teagarden","instrument":"Trombone"}],"youtube_id":""}]}'
