  discography_i18n = '{"en":[{"year":1929,"title":"Columbia debut session, New York","producer":"Columbia Records","label":"Columbia","notes":"June 18, 1929 — debut single \"Frisco Town,\" billed as Kansas Joe and Memphis Minnie.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":""},{"year":1930,"title":"Vocalion sessions, Memphis & Chicago","producer":"Vocalion Records","label":"Vocalion","notes":"Four sessions across the year, including \"Bumble Bee\" and \"When the Levee Breaks,\" a response to the 1927 Mississippi flood.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":"oz9TTTt3joY"},{"year":1931,"title":"Vocalion sessions, Chicago","producer":"Vocalion Records","label":"Vocalion","notes":"Two sessions, including \"Lay My Money Down\" and \"Soo Cow Soo,\" recorded with musical and recording partner Kansas Joe McCoy.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":""},{"year":1932,"title":"Vocalion / Banner / Melotone / Perfect session","producer":"Vocalion Records","label":"Vocalion (multi-imprint)","notes":"February 1932 session issued across several sister labels, including \"Fishin'' Blues,\" with Kansas Joe McCoy.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":""},{"year":1933,"title":"Okeh session","producer":"Okeh Records","label":"Okeh","notes":"October–November 1933 — \"My Butcher Man\" and \"Too Late,\" with Kansas Joe McCoy.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":""},{"year":1934,"title":"Vocalion & Decca sessions","producer":"Decca / Vocalion","label":"Decca / Vocalion","notes":"Marked the end of her recording partnership with Kansas Joe McCoy.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Guitar"}],"youtube_id":""},{"year":1935,"title":"Decca, Vocalion & Bluebird sessions","producer":"Various","label":"Decca / Vocalion / Bluebird","notes":"Five sessions across the year; the October Bluebird date featured steel guitarist Casey Bill Weldon. Included \"Joe Louis Strut.\"","musicians":[{"name":"Casey Bill Weldon","instrument":"Steel guitar"}],"youtube_id":""},{"year":1936,"title":"Vocalion sessions, Chicago","producer":"Vocalion Records","label":"Vocalion","notes":"Three sessions producing \"Hoodoo Lady\" and \"Black Cat Blues.\"","musicians":[],"youtube_id":""},{"year":1937,"title":"Vocalion sessions","producer":"Vocalion Records","label":"Vocalion","notes":"Three sessions, including \"Down in the Alley\" and \"Keep on Sailing.\"","musicians":[],"youtube_id":""},{"year":1938,"title":"Vocalion session","producer":"Vocalion Records","label":"Vocalion","notes":"June 1938 — \"Good Biscuits\" and \"Long as I Can See You Smile,\" around the time of her marriage to guitarist Ernest \"Little Son Joe\" Lawlars.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1939,"title":"Vocalion / Conqueror session, Chicago","producer":"Vocalion Records","label":"Vocalion / Conqueror","notes":"February 1939 session, including \"Black Widow Stinger,\" with Little Son Joe.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1941,"title":"Columbia/Okeh/Conqueror sessions, Chicago","producer":"Columbia / Okeh","label":"Columbia / Okeh / Conqueror","notes":"May and December 1941 — \"Me and My Chauffeur Blues\" (her biggest hit; added to the U.S. National Recording Registry, 2019) and \"In My Girlish Days.\" First sessions on electric guitar.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":"rD2GUKwqliU"},{"year":1944,"title":"Columbia/Okeh session","producer":"Columbia Records","label":"Columbia / Okeh","notes":"December 1944 — \"Love Come and Go,\" with Little Son Joe.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1946,"title":"Columbia sessions, Chicago","producer":"Columbia Records","label":"Columbia","notes":"Two sessions across the year, including \"Killer Diller\" and \"Western Union Blues,\" with Little Son Joe.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1947,"title":"Columbia session","producer":"Columbia Records","label":"Columbia","notes":"December 1947 — \"Million Dollar Blues\" and \"Shout Boogie,\" with Little Son Joe.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1949,"title":"Final Columbia session","producer":"Columbia Records","label":"Columbia","notes":"May 1949 — \"Jump Little Rabbit,\" among her last commercial recordings before retiring c. 1953, with Little Son Joe.","musicians":[{"name":"Ernest \"Little Son Joe\" Lawlars","instrument":"Guitar"}],"youtube_id":""},{"year":1991,"title":"Hoodoo Lady 1933–1937 (compilation)","producer":"—","label":"Chess/MCA","notes":"Posthumous compilation gathering key 1930s sides.","musicians":[],"youtube_id":""},{"year":1994,"title":"Complete Recorded Works, Vols. 1–7 (compilation series)","producer":"—","label":"Document Records","notes":"Posthumous chronological reissue series covering her full 1929–1953 recorded output.","musicians":[],"youtube_id":""}],"no":[{"year":1929,"title":"Columbia-debutøkt, New York","producer":"Columbia Records","label":"Columbia","notes":"18. juni 1929 — debutsingelen «Frisco Town», annonsert som Kansas Joe og Memphis Minnie.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Gitar"}],"youtube_id":""},{"year":1930,"title":"Vocalion-økter, Memphis og Chicago","producer":"Vocalion Records","label":"Vocalion","notes":"Fire økter gjennom året, inkludert «Bumble Bee» og «When the Levee Breaks», et svar på Missisipi-flommen i 1927.","musicians":[{"name":"Kansas Joe McCoy","instrument":"Gitar"}],"youtube_id":"oz9TTTt3joY"},{"year":1931,"title":"Vocalion-økter, Chicago","producer":"Vocalion Records","label":"Vocalion","n