UPDATE artists SET
  discography_i18n = '{"en":[{"year":1930,"title":"First Paramount session, Grafton, Wisconsin","producer":"Paramount Records","label":"Paramount Records","notes":"August 1930 — nine songs recorded, eight released, including \"Preachin'' the Blues\" and \"My Black Mama.\" Commercial failure amid the Great Depression.","musicians":[],"youtube_id":"wBDasv8oYZU"},{"year":1941,"title":"Library of Congress session, Clack Store, Lake Cormorant, Mississippi","producer":"Alan Lomax","label":"Library of Congress","notes":"August 1941 — first Lomax field session, recorded at a country store with electricity to power the equipment; songs included \"Levee Camp Blues,\" \"Government Fleet Blues,\" \"Walking Blues\" and \"Shetland Pony Blues,\" with railway noise audible on some takes. Recorded alongside his regular playing partner Willie Brown.","musicians":[{"name":"Willie Brown","instrument":"Guitar"},{"name":"Fiddlin'' Joe Martin","instrument":"Mandolin"},{"name":"Leroy Williams","instrument":"Harmonica"}],"youtube_id":""},{"year":1942,"title":"Library of Congress session, Robinsonville, Mississippi","producer":"Alan Lomax","label":"Library of Congress","notes":"Second Lomax field session, July 17, 1942, yielding \"Special Rider Blues\" and \"Depot Blues.\"","musicians":[],"youtube_id":""},{"year":1965,"title":"Father of Folk Blues","producer":"John Hammond","label":"Columbia Records","notes":"Rediscovery-era sessions; engineered with help from 22-year-old blues scholar Alan Wilson (later of Canned Heat).","musicians":[],"youtube_id":"NdgrQoZHnNY"}],"no":[{"year":1930,"title":"Første Paramount-økt, Grafton, Wisconsin","producer":"Paramount Records","label":"Paramount Records","notes":"August 1930 — ni sanger spilt inn, åtte utgitt, deriblant «Preachin'' the Blues» og «My Black Mama». Kommersiell fiasko midt i den store depresjonen.","musicians":[],"youtube_id":"wBDasv8oYZU"},{"year":1941,"title":"Kongressbibliotek-økt, Clack Store, Lake Cormorant, Mississippi","producer":"Alan Lomax","label":"Library of Congress","notes":"August 1941 — første Lomax-feltøkt, spilt inn i en landhandel med strøm til utstyret; sangene inkluderte «Levee Camp Blues», «Government Fleet Blues», «Walking Blues» og «Shetland Pony Blues», med hørbar togstøy på enkelte opptak. Spilt inn sammen med hans faste spillepartner Willie Brown.","musicians":[{"name":"Willie Brown","instrument":"Gitar"},{"name":"Fiddlin'' Joe Martin","instrument":"Mandolin"},{"name":"Leroy Williams","instrument":"Munnspill"}],"youtube_id":""},{"year":1942,"title":"Kongressbibliotek-økt, Robinsonville, Mississippi","producer":"Alan Lomax","label":"Library of Congress","notes":"Andre Lomax-feltøkt, 17. juli 1942, som ga «Special Rider Blues» og «Depot Blues».","musicians":[],"youtube_id":""},{"year":1965,"title":"Father of Folk Blues","producer":"John Hammond","label":"Columbia Records","notes":"Gjenoppdagelsesøktene; produsert med hjelp fra 22 år gamle blueshistorikeren Alan Wilson (senere i Canned Heat).","musicians":[],"youtube_id":"NdgrQoZHnNY"}]}'
