UPDATE artists SET
  discography_i18n = '{"en":[{"year":1927,"title":"Paramount debut","producer":"Paramount Records","label":"Paramount","notes":"First release, \"House Rent Stomp\" b/w \"Big Bill Blues.\"","musicians":[],"youtube_id":""},{"year":1930,"title":"Paramount / Champion / Gennett / ARC era, Chicago","producer":"Various","label":"Paramount / Champion / Gennett / Melotone / Perfect","notes":"Prolific run of sessions through the early-to-mid 1930s; part of 224 songs recorded by 1942, among the most of any prewar blues artist. Included the 1931 \"Alabama Scratch\" session in Grafton, Wisconsin as one third of the trio the Harum Scarums.","musicians":[{"name":"Thomas \"Georgia Tom\" Dorsey","instrument":"Piano"},{"name":"Mozelle Alderson","instrument":"Vocals"}],"youtube_id":""},{"year":1934,"title":"Bluebird Records era, Chicago","producer":"RCA Victor / Bluebird","label":"Bluebird","notes":"Moved to RCA Victor''s Bluebird subsidiary, where his sound began evolving toward a fuller, more urban R&B feel accompanied by the pianist known as \"Black Bob.\"","musicians":[{"name":"Black Bob","instrument":"Piano"}],"youtube_id":""},{"year":1937,"title":"Small-combo sessions with Joshua Altheimer, Chicago","producer":"Various","label":"Vocalion / Bluebird","notes":"Began working with pianist Joshua Altheimer in a small instrumental group featuring drums, double bass and one or more melody instruments, moving his sound further from solo country blues toward a Chicago combo style.","musicians":[{"name":"Joshua Altheimer","instrument":"Piano"}],"youtube_id":""},{"year":1938,"title":"Vocalion / Okeh era, Chicago","producer":"Vocalion / Okeh","label":"Vocalion / Okeh","notes":"Included the May 1941 recording of \"Key to the Highway\" with Jazz Gillum (harmonica) and Washboard Sam (washboard). Broonzy also reportedly played guitar on most of Washboard Sam''s own recordings during this period.","musicians":[{"name":"Jazz Gillum","instrument":"Harmonica"},{"name":"Washboard Sam","instrument":"Washboard"}],"youtube_id":"psqnMEP3aL4"},{"year":1945,"title":"\"Where the Blues Began\" / \"Martha Blues\" sessions, Chicago","producer":"Various","label":"Various","notes":"\"Where the Blues Began\" recorded with pianist Big Maceo Merriweather and saxophonist Buster Bennett; \"Martha Blues\" recorded with pianist Memphis Slim.","musicians":[{"name":"Big Maceo Merriweather","instrument":"Piano"},{"name":"Buster Bennett","instrument":"Saxophone"},{"name":"Memphis Slim","instrument":"Piano"}],"youtube_id":""},{"year":1947,"title":"\"Black, Brown and White\" recorded","producer":"—","label":"—","notes":"Written and recorded 1947 but withheld from release by the label until 1951 as too provocative.","musicians":[],"youtube_id":"k0c1c0ZsTLA"},{"year":1948,"title":"Mercury Records era, Chicago","producer":"Mercury Records","label":"Mercury","notes":"Signed after the AFM recording ban ended; includes \"Hey Hey\" (1951/52).","musicians":[],"youtube_id":"_2Npu8KFsIY"},{"year":1951,"title":"European tour recordings","producer":"Various","label":"Various European labels","notes":"Live and studio material from his first, sensationally received European tour.","musicians":[],"youtube_id":""},{"year":1955,"title":"Folkways Records era","producer":"Folkways Records","label":"Folkways","notes":"Acoustic folk-blues recordings through the mid-to-late 1950s, coinciding with his autobiography \"Big Bill Blues\" (1955, with Yannick Bruynoghe).","musicians":[],"youtube_id":""}],"no":[{"year":1927,"title":"Paramount-debut","producer":"Paramount Records","label":"Paramount","notes":"Første utgivelse, «House Rent Stomp» med «Big Bill Blues» på B-siden.","musicians":[],"youtube_id":""},{"year":1930,"title":"Paramount / Champion / Gennett / ARC-æra, Chicago","producer":"Diverse","label":"Paramount / Champion / Gennett / Melotone / Perfect","notes":"Produktiv rekke av økter gjennom tidlig-til-midt-1930-tallet; del av 224 sanger spilt inn innen 1942, blant de fleste av noen førkrigstids-bluesartist. Inkluderte 1931-økten «Alabama Scratch» i Grafton, Wisconsin, som en tredjedel av trioen Harum Scarums.","musicians":[{"name":"Thomas «Georgia Tom» Dorsey","instrument":"Piano"},{"name":"Mozelle Alderson","instrument":"Vokal"}],"youtube_id":""},{"year":1934,"title":"Bluebird Records-æra, Chicago","producer":"RCA Victor / Bluebird","label":"Bluebird","notes":"Byttet til RCA Victors Bluebird-underselskap, hvor lyden hans begynte å utvikle seg mot en fyldigere, mer urban R&B-følelse akkompagnert av pianisten kjent som «Black Bob».","musicians":[{"name":"Black Bob","instrument":"Piano"}],"youtube_id":""},{"year":1937,"title":"Småkombo-økter med Joshua Altheimer, Chicago","producer":"Diverse","label":"Vocalion / Bluebird","notes":"Begynte å spille med pianisten Joshua Altheimer i en liten instrumentalgruppe med trommer, kontrabass og ett eller flere melodiinstrumenter, noe som flyttet lyden hans lenger bort fra solo countryblues mot en Chicago-kombostil.","musicians":[{"name":"Joshua Altheimer","instrument":"Piano"}],"youtube_id":""},{"year":1938,"title":"Vocalion / Okeh-æra, Chicago","producer":"Vocalion / Okeh","label":"Vocalion / Okeh","notes":"Inkluderte mai 1941-innspillingen av «Key to the Highway» med Jazz Gillum (munnspill) og Washboard Sam (vaskebrett). Broonzy skal også ha spilt gitar på de fleste av Washboard Sams egne innspillinger i denne perioden.","musicians":[{"name":"Jazz Gillum","instrument":"Munnspill"},{"name":"Washboard Sam","instrument":"Vaskebrett"}],"youtube_id":"psqnMEP3aL4"},{"year":1945,"title":"«Where the Blues Began» / «Martha Blues»-øktene, Chicago","producer":"Diverse","label":"Diverse","notes":"«Where the Blues Began» spilt inn med pianist Big Maceo Merriweather og saksofonist Buster Bennett; «Martha Blues» spilt inn med pianist Memphis Slim.","musicians":[{"name":"Big Maceo Merriweather","instrument":"Piano"},{"name":"Buster Bennett","instrument":"Saksofon"},{"name":"Memphis Slim","instrument":"Piano"}],"youtube_id":""},{"year":1947,"title":"«Black, Brown and White» spilt inn","producer":"—","label":"—","notes":"Skrevet og spilt inn i 1947, men holdt tilbake fra utgivelse av selskapet til 1951 som for provoserende.","musicians":[],"youtube_id":"k0c1c0ZsTLA"},{"year":1948,"title":"Mercury Records-æra, Chicago","producer":"Mercury Records","label":"Mercury","notes":"Signerte etter at AFM-innspillingsforbudet opphørte; inkluderer «Hey Hey» (1951/52).","musicians":[],"youtube_id":"_2Npu8KFsIY"},{"year":1951,"title":"Europaturné-innspillinger","producer":"Diverse","label":"Diverse europeiske selskap","notes":"Live- og studiomateriale fra hans første, sensasjonelt mottatte Europa-turné.","musicians":[],"youtube_id":""},{"year":1955,"title":"Folkways Records-æra","producer":"Folkways Records","label":"Folkways","notes":"Akustiske folk-blues-innspillinger gjennom midten til slutten av 1950-tallet, sammenfallende med selvbiografien «Big Bill Blues» (1955, med Yannick Bruynoghe).","musicians":[],"youtube_id":""}]}'
