UPDATE artists SET
  discography_i18n = '{"en":[{"year":1951,"title":"\"Moanin'' at Midnight\" / \"How Many More Years\" (debut single)","producer":"Sam Phillips","label":"Chess","notes":"Discovered by talent scout Ike Turner; recorded at Sam Phillips''s Memphis Recording Service.","musicians":[{"name":"Willie Johnson","instrument":"Guitar"},{"name":"Pat Hare","instrument":"Guitar"},{"name":"Junior Parker","instrument":"Harmonica"}],"youtube_id":""},{"year":1956,"title":"\"Smokestack Lightning\"","producer":"Chess","label":"Chess","notes":"Recorded with Hubert Sumlin on guitar.","musicians":[{"name":"Hubert Sumlin","instrument":"Guitar"}],"youtube_id":"RZS5OoKFdME"},{"year":1959,"title":"Moanin'' in the Moonlight","producer":"Chess","label":"Chess","notes":"His debut album, compiling earlier singles.","musicians":[{"name":"Hubert Sumlin","instrument":"Guitar"},{"name":"Willie Dixon","instrument":"Bass, songwriter"}],"youtube_id":""},{"year":1960,"title":"\"Spoonful\"","producer":"Chess","label":"Chess","notes":"Written by Willie Dixon, recorded June 1960.","musicians":[{"name":"Hubert Sumlin","instrument":"Guitar"},{"name":"Willie Dixon","instrument":"Bass, songwriter"}],"youtube_id":"8ClGzbkI1gY"},{"year":1962,"title":"Howlin'' Wolf (self-titled, the \"rocking chair album\")","producer":"Chess","label":"Chess","notes":"Includes \"Little Red Rooster\" and \"Back Door Man.\"","musicians":[{"name":"Hubert Sumlin","instrument":"Guitar"},{"name":"Willie Dixon","instrument":"Bass, songwriter"}],"youtube_id":""},{"year":1964,"title":"\"Killing Floor\"","producer":"Chess","label":"Chess","notes":"Recorded Chicago, August 1964 — now regarded as a defining Chicago electric blues classic.","musicians":[{"name":"Hubert Sumlin","instrument":"Guitar"}],"youtube_id":"N6VtX0r3Rwo"},{"year":1966,"title":"The Real Folk Blues","producer":"Chess","label":"Chess","notes":"Compilation album.","musicians":[],"youtube_id":""},{"year":1968,"title":"The Super Super Blues Band","producer":"Chess","label":"Chec