  discography_i18n = '{"en":[{"year":1951,"title":"Trumpet Records era, Jackson, Mississippi","producer":"Lillian McMurry","label":"Trumpet","notes":"Debut as sideman, then as session leader with \"Dust My Broom\" (August 1951), a Robert Johnson composition that became a surprise hit in 1952.","musicians":[],"youtube_id":"SOhQP5wHNHQ"},{"year":1953,"title":"Flair / Meteor / Modern Records era, via Ike Turner","producer":"Bihari brothers","label":"Flair / Meteor / Modern","notes":"Includes \"I Believe.\" Ike Turner played guitar and piano on some of these Bihari-brothers sessions.","musicians":[{"name":"\"Little\" Johnny Jones","instrument":"Piano"},{"name":"Odie Payne","instrument":"Drums"},{"name":"Ike Turner","instrument":"Guitar, piano"}],"youtube_id":""},{"year":1955,"title":"Chess Records sessions","producer":"Chess","label":"Chess","notes":"Additional mid-1950s sides.","musicians":[{"name":"\"Little\" Johnny Jones","instrument":"Piano"},{"name":"Odie Payne","instrument":"Drums"}],"youtube_id":""},{"year":1957,"title":"Chief Records era, Chicago","producer":"Mel London","label":"Chief","notes":"Includes his version of \"It Hurts Me Too.\" The Broomdusters, both inherited from Tampa Red''s band, remained his core backing unit into the Chief Records era.","musicians":[{"name":"\"Little\" Johnny Jones","instrument":"Piano"},{"name":"Odie Payne","instrument":"Drums"}],"youtube_id":"fzr1Rfn-P4Y"},{"year":1959,"title":"Fire Records era, Chicago","producer":"Bobby Robinson","label":"Fire","notes":"\"The Sky Is Crying\" (recorded Nov 3–4 1959, released March 1960), \"Shake Your Moneymaker\" and \"Look on Yonder Wall\" (both 1961) — most enduring performances of his career.","musicians":[{"name":"\"Little\" Johnny Jones","instrument":"Piano"},{"name":"Odie Payne","instrument":"Drums"}],"youtube_id":"u7ZC-kv8THk"},{"year":1965,"title":"\"One Way Out\" (posthumous release)","producer":"Fire / Enjoy","label":"Fire / Enjoy","notes":"Released after his 1963 death.","musician