  formative_i18n = '{"en":["1949: Korner meets harmonica player Cyril Davies while both are playing in Chris Barber''s Jazz Band. (Kilde: Wikipedia)","1955: The two open the London Blues and Barrelhouse Club above the Roundhouse pub in Soho. (Kilde: Wikipedia)","17 March 1962: Launch of the \"Rhythm and Blues Night\" at the Ealing Jazz Club — Britain''s first regular electric blues residency. (Kilde: Wikipedia)","3 May 1962: Thursday-night residency begins at the Marquee Club, London. (Kilde: Wikipedia)","Late 1962: Cyril Davies departs to form his own harder-edged R&B group; organist Graham Bond joins. (Kilde: Wikipedia)","2024: Alexis Korner is posthumously inducted into the Rock and Roll Hall of Fame in the Musical Influence category. (Kilde: Rock and Roll Hall of Fame)"],"no":["1949: Korner møter munnspillspiller Cyril Davies mens begge spiller i Chris Barbers jazzband. (Kilde: Wikipedia)","1955: De to åpner London Blues and Barrelhouse Club over Roundhouse-puben i Soho. (Kilde: Wikipedia)","17. mars 1962: Lansering av «Rhythm and Blues Night» på Ealing Jazz Club — Storbritannias første faste elektriske bluesresidens. (Kilde: Wikipedia)","3. mai 1962: Torsdagskveldsresidens starter på Marquee Club, London. (Kilde: Wikipedia)","Sent 1962: Cyril Davies forlater bandet for å danne sin egen, hardere R&B-gruppe; organisten Graham Bond blir med. (Kilde: Wikipedia)","2024: Alexis Korner innlemmes posthumt i Rock and Roll Hall of Fame i kategorien Musical Influence. (Kilde: Rock and Roll Hall of Fame)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Acoustic & electric guitar","note":"Korner''s core instrument from the late 1940s onward; his first guitar was handmade by a friend.","source":"Wikipedia"},{"category":"Annet","name":"Amplified harmonica","note":"Cyril Davies pioneered the amplified, distorted harmonica sound in Britain that became a signature of the band.","source":"Wikipedia"},{"category":"Vokal","name":"Vocals","note":"Korner sang lead on later recordings; Long John Baldry and others fronted the band in its early years.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Akustisk og elektrisk gitar","note":"Korners kjerneinstrument fra slutten av 1940-tallet; hans første gitar var håndlaget av en venn.","source":"Wikipedia"},{"category":"Annet","name":"Forsterket munnspill","note":"Cyril Davies var pioner for den forsterkede, forvrengte munnspilllyden i Storbritannia som ble et kjennetegn for bandet.","source":"Wikipedia"},{"category":"Vokal","name":"Vokal","note":"Korner sang lead på senere innspillinger; Long John Baldry og andre frontet bandet i de tidlige årene.","source":"Wikipedia"}]}',
  collaborators_i18n = '{"en":[{"name":"Cyril Davies","note":"Co-founder; pioneering amplified-harmonica player, left in late 1962 to form his own group.","source":"Wikipedia"},{"name":"Charlie Watts","note":"Early drummer, later of the Rolling Stones.","source":"Wikipedia"},{"name":"Jack Bruce","note":"Early bassist, later of Cream.","source":"Wikipedia"},{"name":"Ginger Baker","note":"Drummer, replaced Watts; later of Cream.","source":"Wikipedia"},{"name":"Long John Baldry","note":"Lead vocalist on the debut album \"R&B from the Marquee.\"","source":"Wikipedia"},{"name":"Dick Heckstall-Smith","note":"Saxophonist across much of the band''s run.","source":"Wikipedia"},{"name":"Graham Bond","note":"Organist, replaced Davies from late 1962.","source":"Wikipedia"}],"no":[{"name":"Cyril Davies","note":"Medgrunnlegger; banebrytende forsterket munnspillspiller, forlot bandet sent i 1962 for å danne sin egen gruppe.","source":"Wikipedia"},{"name":"Charlie Watts","note":"Tidlig trommeslager, senere i Rolling Stones.","source":"Wikipedia"},{"name":"Jack Bruce","note":"Tidlig bassist, senere i Cream.","source":"Wikipedia"},{"name":"Ginger Baker","note":"Trommeslager, erstattet Watts; senere i Cream.","source":"Wikipedia"},{"name":"Long John Baldry","note":"Lead vokalist på debutalbumet «R&B from the Marquee».","source":"Wikipedia"},{"name":"Dick Heckstall-Smith","note":"Saksofonist gjennom store deler av bandets levetid.","source":"Wikipedia"},{"name":"Graham Bond","note":"Organist, erstattet Davies fra sent 1962.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1962,"title":"R&B from the Marquee","producer":"—","label":"Decca","notes":"Recorded live-in-studio with Long John Baldry on lead vocals; widely regarded as the first British blues album ever released.","musicians":[{"name":"Long John Baldry","instrument":"Vocals"},{"name":"Cyril Davies","instrument":"Harmonica"},{"name":"Charlie Watts","instrument":"Drums"},{"name":"Dick Heckstall-Smith","instrument":"Saxophone"}],"youtube_id":"STjn0ZM5JiI"},{"year":1964,"title":"Red Hot from Alex","producer":"—","label":"Transatlantic","notes":"Recorded during the post-Davies, horn-driven phase of the band.","musicians":[{"name":"Graham Bond","instrument":"Organ"},{"name":"Ginger Baker","instrument":"Drums"},{"name":"Dick Heckstall-Smith","instrument":"Saxophone"}],"youtube_id":""},{"year":1964,"title":"At the Cavern","producer":"—","label":"Oriole","notes":"Live album recorded at the Cavern Club, Liverpool.","musicians":[{"name":"Graham Bond","instrument":"Organ"},{"name":"Ginger Baker","instrument":"Drums"}],"youtube_id":""},{"year":1965,"title":"Alexis Korner''s Blues Incorporated","producer":"—","label":"Fontana","notes":"Self-titled album from the mid-1960s configuration of the band.","musicians":[],"youtube_id":""},{"year":1966,"title":"Sky High","producer":"—","label":"Spot","notes":"Final Blues Incorporated album before Korner moved on to other projects.","musicians":[],"youtube_id":""}],"no":[{"year":1962,"title":"R&B from the Marquee","producer":"—","label":"Decca","notes":"Spilt inn live-i-studio med Long John Baldry på lead vokal; regnes generelt som det aller første britiske bluesalbumet som ble utgitt.","musicians":[{"name":"Long John Baldry","instrument":"Vokal"},{"name":"Cyril Davies","instrument":"Munnspill"},{"name":"Charlie Watts","instrument":"Trommer"},{"name":"Dick Heckstall-Smith","instrument":"Saksofon"}],"youtube_id":"STjn0ZM5JiI"},{"year":1964,"title":"Red Hot from Alex","producer":"—","label":"Transatlantic","notes":"Spilt inn under den blåserdrevne fasen etter Davies'' avgang.","musicians":[{"name":"Graham Bond","instrument":"Orgel"},{"name":"Ginger Baker","instrument":"Trommer"},{"name":"Dick Heckstall-Smith","instrument":"Saksofon"}],"youtube_id":""},{"year":1964,"title":"At the Cavern","producer":"—","label":"Oriole","notes":"Livealbum spilt inn ved Cavern Club, Liverpool.","musicians":[{"name":"Graham Bond","instrument":"Orgel"},{"name":"Ginger Baker","instrument":"Trommer"}],"youtube_id":""},{"year":1965,"title":"Alexis Korner''s Blues Incorporated","producer":"—","label":"Fontana","notes":"Selvtitulert album fra midten av 1960-tallets bandkonstellasjon.","musicians":[],"youtube_id":""},{"year":1966,"title":"Sky High","producer":"—","label":"Spot","notes":"Siste Blues Incorporated-album før Korner gikk videre til andre prosjekter.","musicians":[],"youtube_id":""}]}',
