  influences_i18n = '{"en":["Lead Belly","Albert Ammons","Chicago electric blues"],"no":["Lead Belly","Albert Ammons","Chicago-elektrisk blues"]}',
  styles = '["British Blues Boom","Electric Blues"]',
  article_references = '[{"title":"John Mayall — Wikipedia","url":"https://en.wikipedia.org/wiki/John_Mayall"},{"title":"Blues Breakers with Eric Clapton — Wikipedia","url":"https://en.wikipedia.org/wiki/Blues_Breakers_with_Eric_Clapton"},{"title":"John Mayall — Blues Hall of Fame","url":"https://blues.org/blues_hof_inductee/john-mayall/"},{"title":"John Mayall With Eric Clapton – Blues Breakers — Discogs","url":"https://www.discogs.com/release/7025814"}]',
  external_links = '[{"label":"YouTube Music","url":"https://music.youtube.com/search?q=John+Mayall+Bluesbreakers"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Mayall"},{"label":"Blues Hall of Fame","url":"https://blues.org/blues_hof_inductee/john-mayall/"}]',
