  article_references = '[{"title":"The Yardbirds — Wikipedia","url":"https://en.wikipedia.org/wiki/The_Yardbirds"},{"title":"The Yardbirds — Rock and Roll Hall of Fame","url":"https://rockhall.com/inductees/the-yardbirds/"},{"title":"The Yardbirds — Little Games — Discogs","url":"https://www.discogs.com/release/1016956"}]',
