  external_links = '[{"label":"YouTube Music","url":"https://music.youtube.com/search?q=Savoy+Brown+Kim+Simmonds"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Savoy_Brown"}]',
