  styles = '["British Blues Boom","Blues Rock","Hard Rock"]',
  article_references = '[{"title":"Free (band) — Wikipedia","url":"https://en.wikipedia.org/wiki/Free_(band)"},{"title":"Paul Kossoff — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_Kossoff"}]',
