  article_references = '[{"title":"Kent Erik Thorvaldsen — Discogs artist page","url":"https://www.discogs.com/artist/17888541-Kent-Erik-Thorvaldsen"},{"title":"SUGG. — Discogs release","url":"https://www.discogs.com/release/37666977-Kent-Erik-Thorvaldsen-SUGG"},{"title":"Jelly Roll Shuffle — Discogs release","url":"https://www.discogs.com/release/10526658-The-Jelly-Roll-Men-Jelly-Roll-Shuffle"},{"title":"Svalbard Blues — Dark Season Blues Festival artist biography","url":"https://www.svalbardblues.com/en/dsb/artists/kent-erik-thorvaldsen-en/"},{"title":"Telen — \"Blues på totning: Migstulk og sægabel blir god blues, det\"","url":"https://www.telen.no/blues-pa-totning-migstulk-og-sagabel-blir-god-blues-det/s/5-75-776887"},{"title":"Viberate — Kent Erik Thorvaldsen artist profile","url":"https://www.viberate.com/artist/kent-erik-thorvaldsen/"},{"title":"No Border Blues Episode Seven: The Jelly Roll Men — Chicago Blues Network","url":"https://www.youtube.com/watch?v=OqJ3WZs8tos"}]',
