UPDATE artists SET
  img = '/images/johnny-augland.jpg',
  image_credit = 'Photo: Svein Teigen',
  discography_i18n = '{"en":[{"year":1988,"title":"\"Davy Crockett\" / \"Come On\" (with Good Time Charlie)","producer":"—","label":"—","notes":"Good Time Charlie''s debut single (the band itself formed in 1982). Lineup: Arle Hjelmeland (vocals, harmonica), Johnny Augland (guitar, piano), Øivind Lunde (bass), Jarle Olsen (drums).","musicians":[{"name":"Arle Hjelmeland","instrument":"Vocals, harmonica"},{"name":"Øivind Lunde","instrument":"Bass"},{"name":"Jarle Olsen","instrument":"Drums"}],"youtube_id":""},{"year":1995,"title":"Comin'' Down With the Blues (with Good Time Charlie)","producer":"—","label":"—","notes":"Landmark Norwegian blues album per Bluesnews. Augland co-wrote \"Why Don''t You Stop Babe,\" played piano on \"Broke and Lonely,\" and guitar on \"I Ain''t Gonna Be Your Monkey Man.\"","musicians":[{"name":"Arle Hjelmeland","instrument":"Vocals"},{"name":"Per Fredriksen","instrument":"Bass"},{"name":"Leif \"Dixon\" Korsnes","instrument":"Drums"}],"youtube_id":""},{"year":1997,"title":"Stompin'' Our Feet With Joy (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"—","notes":"Vidar Busk''s debut album, recorded at Cross Studio, Kristiansand. Augland produced and played piano and guitar.","musicians":[{"name":"Vidar Busk","instrument":"Vocals, guitar"}],"youtube_id":""},{"year":1998,"title":"I Came Here To Rock (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"WEA / Blue Mood Records","notes":"Won Spellemannsprisen for Artist of the Year. Augland produced, arranged horns, played piano, guitar, bass and slide guitar, sang backing vocals, and co-wrote several songs. Producer/arranger/vocal credits independently confirmed on Discogs.","musicians":[{"name":"Vidar Busk","instrument":"Vocals, guitar, co-producer"}],"youtube_id":""},{"year":1999,"title":"Atomic Swing (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"—","notes":"Received a Spellemannspris nomination in rock. Augland played piano and organ and co-wrote several tracks; a Puls review noted his piano-\"hammering\" on the title track.","musicians":[{"name":"Vidar Busk","instrument":"Vocals, guitar"}],"youtube_id":""},{"year":1999,"title":"Oochie-Coochie! (with Good Time Charlie)","producer":"—","label":"Blue Mood Records / Amigo","notes":"Fourteen-track album; per Rockipedia, Augland contributed as composer and lyricist alongside his instrumental role in the band.","musicians":[],"youtube_id":""},{"year":2005,"title":"My Kind of Blues","producer":"Johnny Augland","label":"Ponca Jazz Records","notes":"Released 12 August 2005. Augland wrote the music and lyrics and played vocals, guitar, organ, piano, bass and drums. Kid Andersen guests. Ten original tracks: \"A Hundred Years...,\" \"Colorblind,\" \"One Hell of a Man,\" \"The Power of the Cigarette,\" \"Taxicab,\" \"Same Old Boogie,\" \"The Grocery Store,\" \"Braggin'',\" \"Chainsaw Blues,\" \"The Last T-Bone.\"","musicians":[{"name":"Kid Andersen","instrument":"Guitar (guest)"},{"name":"Bernhard Seland","instrument":"Saxophone"},{"name":"Trond Augland","instrument":"Percussion"}],"youtube_id":""},{"year":2013,"title":"In Sugartown (with Good Time Charlie)","producer":"—","label":"Grappa","notes":"Career-spanning compilation drawing on \"Comin'' Down With the Blues\" and \"Oochie-Coochie!\" Augland credited on Discogs for piano and guitar.","musicians":[],"youtube_id":""},{"year":2021,"title":"Refleksjoner","producer":"Johnny Augland","label":"Egen utgivelse (self-released)","notes":"Eight songs blending blues and R&B traditions with social commentary and humor: \"Stilling Ledig,\" \"H2O2 Hydrogenperoksid,\" \"Friends,\" \"Fastsjaman,\" \"Refleksjoner,\" \"Svart Hav,\" \"Egg og Bacon,\" \"Liten Flyktning.\" Reviewed by Øyvind Pharo in Bluesnews (BN119, April 2021), who highlighted \"Liten flyktning\" (a protest blues benefiting refugee organizations on Lesvos, with Gatemouth Brown-influenced guitar), \"Stilling ledig\" (a boogie critique of corporate culture with vocal harmonies from Endre Kirkesola) and \"Friends\" (an English-language duet with Lene Tønnesen). Guest musicians include saxophonist Trygve Rypestøl and guitarist Øyvind Nypan.","musicians":[{"name":"Lene Tønnesen","instrument":"Duet vocals on \"Friends\""},{"name":"Endre Kirkesola","instrument":"Vocal harmonies on \"Stilling ledig\""},{"name":"Trygve Rypestøl","instrument":"Saxophone"},{"name":"Øyvind Nypan","instrument":"Guitar"}],"youtube_id":"p-n5OdaLqrY"},{"year":2023,"title":"Christmas Here (The Paradiso Session)","producer":"Johnny Augland","label":"Blue Mood Records / Grappa","notes":"Released 1 December 2023, featuring vocalist Adam Douglas. Addresses the commercialization of Christmas.","musicians":[{"name":"Adam Douglas","instrument":"Vocals"}],"youtube_id":""}],"no":[{"year":1988,"title":"«Davy Crockett» / «Come On» (med Good Time Charlie)","producer":"—","label":"—","notes":"Good Time Charlies debutsingel (bandet selv ble dannet i 1982). Besetning: Arle Hjelmeland (vokal, munnspill), Johnny Augland (gitar, piano), Øivind Lunde (bass), Jarle Olsen (trommer).","musicians":[{"name":"Arle Hjelmeland","instrument":"Vokal, munnspill"},{"name":"Øivind Lunde","instrument":"Bass"},{"name":"Jarle Olsen","instrument":"Trommer"}],"youtube_id":""},{"year":1995,"title":"Comin'' Down With the Blues (med Good Time Charlie)","producer":"—","label":"—","notes":"Landemerke-album i norsk blues ifølge Bluesnews. Augland medforfattet «Why Don''t You Stop Babe», spilte piano på «Broke and Lonely», og gitar på «I Ain''t Gonna Be Your Monkey Man».","musicians":[{"name":"Arle Hjelmeland","instrument":"Vokal"},{"name":"Per Fredriksen","instrument":"Bass"},{"name":"Leif «Dixon» Korsnes","instrument":"Trommer"}],"youtube_id":""},{"year":1997,"title":"Stompin'' Our Feet With Joy (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"—","notes":"Vidar Busks debutalbum, spilt inn ved Cross Studio, Kristiansand. Augland produserte og spilte piano og gitar.","musicians":[{"name":"Vidar Busk","instrument":"Vokal, gitar"}],"youtube_id":""},{"year":1998,"title":"I Came Here To Rock (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"WEA / Blue Mood Records","notes":"Vant Spellemannsprisen for årets artist. Augland produserte, arrangerte blåserne, spilte piano, gitar, bass og slidegitar, sang bakgrunnsvokal, og medforfattet flere sanger. Produsent-/arrangør-/vokalkreditering uavhengig bekreftet på Discogs.","musicians":[{"name":"Vidar Busk","instrument":"Vokal, gitar, medprodusent"}],"youtube_id":""},{"year":1999,"title":"Atomic Swing (Vidar Busk & His True Believers)","producer":"Johnny Augland","label":"—","notes":"Fikk en Spellemannspris-nominasjon i rock. Augland spilte piano og orgel og medforfattet flere spor; en Puls-anmeldelse bemerket hans piano-«hamring» på tittelsporet.","musicians":[{"name":"Vidar Busk","instrument":"Vokal, gitar"}],"youtube_id":""},{"year":1999,"title":"Oochie-Coochie! (med Good Time Charlie)","producer":"—","label":"Blue Mood Records / Amigo","notes":"Fjorten-spors album; ifølge Rockipedia bidro Augland som komponist og tekstforfatter i tillegg til sin instrumentale rolle i bandet.","musicians":[],"youtube_id":""},{"year":2005,"title":"My Kind of Blues","producer":"Johnny Augland","label":"Ponca Jazz Records","notes":"Utgitt 12. august 2005. Augland skrev musikk og tekst og spilte vokal, gitar, orgel, piano, bass og trommer. Kid Andersen gjester. Ti originalspor: «A Hundred Years...», «Colorblind», «One Hell of a Man», «The Power of the Cigarette», «Taxicab», «Same Old Boogie», «The Grocery Store», «Braggin''», «Chainsaw Blues», «The Last T-Bone».","musicians":[{"name":"Kid Andersen","instrument":"Gitar (gjest)"},{"name":"Bernhard Seland","instrument":"Saksofon"},{"name":"Trond Augland","instrument":"Perkusjon"}],"youtube_id":""},{"year":2013,"title":"In Sugartown (med Good Time Charlie)","producer":"—","label":"Grappa","notes":"Karriereoppsummerende samlealbum som trekker på «Comin'' Down With the Blues» og «Oochie-Coochie!». Augland kreditert på Discogs for piano og gitar.","musicians":[],"youtube_id":""},{"year":2021,"title":"Refleksjoner","producer":"Johnny Augland","label":"Egen utgivelse","notes":"Åtte sanger som blander blues- og R&B-tradisjoner med samfunnskommentar og humor: «Stilling Ledig», «H2O2 Hydrogenperoksid», «Friends», «Fastsjaman», «Refleksjoner», «Svart Hav», «Egg og Bacon», «Liten Flyktning». Anmeldt av Øyvind Pharo i Bluesnews (BN119, april 2021), som trakk frem «Liten flyktning» (en protestblues til inntekt for flyktningorganisasjoner på Lesvos, med Gatemouth Brown-inspirert gitar), «Stilling ledig» (en boogie-kritikk av bedriftskultur med vokalharmonier fra Endre Kirkesola) og «Friends» (en engelskspråklig duett med Lene Tønnesen). Gjestemusikere inkluderer saksofonisten Trygve Rypestøl og gitaristen Øyvind Nypan.","musicians":[{"name":"Lene Tønnesen","instrument":"Duettvokal på «Friends»"},{"name":"Endre Kirkesola","instrument":"Vokalharmonier på «Stilling ledig»"},{"name":"Trygve Rypestøl","instrument":"Saksofon"},{"name":"Øyvind Nypan","instrument":"Gitar"}],"youtube_id":"p-n5OdaLqrY"},{"year":2023,"title":"Christmas Here (The Paradiso Session)","producer":"Johnny Augland","label":"Blue Mood Records / Grappa","notes":"Utgitt 1. desember 2023, med vokalisten Adam Douglas. Tar for seg kommersialiseringen av julen.","musicians":[{"name":"Adam Douglas","instrument":"Vokal"}],"youtube_id":""}]}',
  press_quotes_i18n = '{"en":[{"quote":"Johnny er Blues-Norges kronjuvel!","author":"Arle Hjelmeland","role":"Good Time Charlie bandleader","source_title":"Bluesnews","source_url":"https://bluesnews.no/"},{"quote":"Er det en utøver man kan si har hatt stor betydning for bluesmusikkens fremvekst i Norge, så er det komponist, produsent og multiinstrumentalist Johnny Augland.","author":"Oslo Bluesklubb","role":"Concert announcement","source_title":"Oslo Bluesklubb","source_url":"https://osloblues.com/konsert/johnny-augland-med-johnnys-etat"}],"no":[{"quote":"Johnny er Blues-Norges kronjuvel!","author":"Arle Hjelmeland","role":"Good Time Charlie-bandleder","source_title":"Bluesnews","source_url":"https://bluesnews.no/"},{"quote":"Er det en utøver man kan si har hatt stor betydning for bluesmusikkens fremvekst i Norge, så er det komponist, produsent og multiinstrumentalist Johnny Augland.","author":"Oslo Bluesklubb","role":"Konsertomtale","source_title":"Oslo Bluesklubb","source_url":"https://osloblues.com/konsert/johnny-augland-med-johnnys-etat"}]}',
  collaborators_i18n = '{"en":[{"name":"Arle Hjelmeland","note":"Good Time Charlie bandleader; co-wrote \"Why Don''t You Stop Babe\" with Augland.","source":"Bluesnews"},{"name":"Vidar Busk","note":"Augland produced his first three key albums, 1997-1999.","source":"Discogs"},{"name":"Kid Andersen","note":"Guested on Augland''s \"My Kind of Blues\" (2005); later reunited with him at Greaseland studio, California.","source":"Grappa"},{"name":"Charlie Musselwhite","note":"Played alongside Augland and Kid Andersen at Greaseland studio.","source":"Grappa"},{"name":"Tor Einar \"Daumann\" Jacobsen","note":"Fellow Kristiansand blues pioneer; co-member of the Blue Masters All Star Band, 2025.","source":"Buen Kulturhus"},{"name":"Ronnie Jacobsen","note":"2018 Spellemannspris-winning bluesman; performed together in various combinations, including a joint concert in 2019 ahead of the Royal Albert Hall show, and in the Blue Masters All Star Band.","source":"Buen Kulturhus; Blå Kors Kristiansand"},{"name":"Per Fredriksen","note":"Bassist; fellow member of the Blue Masters All Star Band.","source":"Buen Kulturhus"},{"name":"Adam Douglas","note":"Featured vocalist on \"Christmas Here (The Paradiso Session),\" 2023.","source":"Grappa"},{"name":"Johnnys Etat","note":"Current band: Kenneth Silden (organ/piano), Kristoffer Tokle (drums), Morten Martens (bass), Trygve Rypestøl (saxophone), with Ole Jørgen Bardal and Eivind Kristensen on saxophone as needed.","source":"Oslo Bluesklubb"}],"no":[{"name":"Arle Hjelmeland","note":"Good Time Charlie-bandleder; medforfattet «Why Don''t You Stop Babe» med Augland.","source":"Bluesnews"},{"name":"Vidar Busk","note":"Augland produserte hans tre første nøkkelalbum, 1997–1999.","source":"Discogs"},{"name":"Kid Andersen","note":"Gjestet på Auglands «My Kind of Blues» (2005); gjenforentes senere med ham ved Greaseland-studio, California.","source":"Grappa"},{"name":"Charlie Musselwhite","note":"Spilte sammen med Augland og Kid Andersen ved Greaseland-studio.","source":"Grappa"},{"name":"Tor Einar «Daumann» Jacobsen","note":"Medbluespioner fra Kristiansand; medmedlem av Blue Masters All Star Band, 2025.","source":"Buen Kulturhus"},{"name":"Ronnie Jacobsen","note":"Spellemannspris-vinnende bluesmusiker fra 2018; opptrådte sammen i ulike konstellasjoner, inkludert en felles konsert i 2019 før Royal Albert Hall-showet, og i Blue Masters All Star Band.","source":"Buen Kulturhus; Blå Kors Kristiansand"},{"name":"Per Fredriksen","note":"Bassist; medmedlem av Blue Masters All Star Band.","source":"Buen Kulturhus"},{"name":"Adam Douglas","note":"Gjestevokalist på «Christmas Here (The Paradiso Session)», 2023.","source":"Grappa"},{"name":"Johnnys Etat","note":"Nåværende band: Kenneth Silden (orgel/piano), Kristoffer Tokle (trommer), Morten Martens (bass), Trygve Rypestøl (saksofon), med Ole Jørgen Bardal og Eivind Kristensen på saksofon ved behov.","source":"Oslo Bluesklubb"}]}',
  videos = '[{"kind":"more","title":"Stilling ledig — Johnny Augland","youtube_id":"p-n5OdaLqrY","channel":"torgeir langeid","note":"Fra albumet «Refleksjoner» (2021)."}]',
  article_references = '[{"title":"Oslo Bluesklubb — Johnny Augland med Johnnys Etat","url":"https://osloblues.com/konsert/johnny-augland-med-johnnys-etat"},{"title":"Rockipedia — Johnny Augland","url":"https://www.rockipedia.no/artister/johnny_augland-61472/"},{"title":"Bluesnews BN119 (april 2021) — «Har mye på hjertet»","url":"https://bluesnews.no/musikkanmeldelser/bn119-april-2021/har-mye-paa-hjertet"},{"title":"Bluesnews — Comin'' Down With the Blues","url":"https://bluesnews.no/"},{"title":"Grappa — Good Time Charlie / Johnny Augland","url":"https://grappa.no/"},{"title":"Johnny Augland — My Kind Of Blues — Discogs","url":"https://www.discogs.com/release/12443461"},{"title":"Vidar Busk & His True Believers — I Came Here To Rock — Discogs","url":"https://www.discogs.com/release/1844357"},{"title":"Good Time Charlie — In Sugartown — Discogs","url":"https://www.discogs.com/release/10801847"},{"title":"Notodden Blues Festival","url":"https://bluesfest.no/"}]'
WHERE slug = 'johnny-guitar-augland';

INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'peps-persson', 'Peps Persson', 'Per-Åke Tommy Persson', 'Classic', 'Classic Era', '1962–2021', 'Helsingborg, Sweden', 'Tjörnarp, Scania, Sweden', 'Sweden', 'Nordic', 400, 'The voice that translated Muddy Waters and Elmore James into Scanian dialect — Sweden''s most beloved blues institution, from Peps Blodsband''s 1970s heyday to a 2015 Swedish Music Hall of Fame induction.', 'Stemmen som oversatte Muddy Waters og Elmore James til skånsk dialekt — Sveriges mest elskede bluesinstitusjon, fra Peps Blodsbands storhetstid på 1970-tallet til innlemmelse i Swedish Music Hall of Fame i 2015.');

UPDATE artists SET
  short_sv = 'Rösten som översatte Muddy Waters och Elmore James till skånska — Sveriges mest älskade bluesinstitution, från Peps Blodsbands storhetstid på 1970-talet till invalet i Swedish Music Hall of Fame 2015.', short_de = 'Die Stimme, die Muddy Waters und Elmore James in schonischen Dialekt übersetzte — Schwedens beliebteste Blues-Institution, von Peps Blodsbands Blütezeit in den 1970ern bis zur Aufnahme in die Swedish Music Hall of Fame 2015.', short_pl = 'Głos, który przetłumaczył Muddy''ego Watersa i Elmore''a Jamesa na dialekt skański — najbardziej uwielbiana szwedzka instytucja bluesowa, od lat świetności Peps Blodsband w latach 70. po wprowadzenie do Szwedzkiej Galerii Sław Muzyki w 2015 roku.',
  biography_en = 'Peps Persson didn''t just sing the blues in Sweden — he translated it, giving Muddy Waters and Elmore James songs new life in his own thick Scanian dialect, and in doing so became one of the most beloved and instantly recognizable voices in Swedish popular music. Born Per-Åke Tommy Persson on 20 December 1946 in Helsingborg and raised in Tjörnarp, Scania, he started his first band, Pop Penders, in 1962, before teaming up with Blues Quality to form Peps Blues Quality in the late 1960s, playing straight electric blues covers (Kilde: Wikipedia; Svensk Musik).

His most enduring vehicle was Peps Perssons Blodsband, formed in 1974, which released nine studio albums between 1974 and 2005 and became the definitive Swedish blues-rock outfit of its era — built on Persson''s dialect-sung, horn-driven arrangements of blues and R&B standards. After 1975 his songwriting increasingly turned toward reggae rhythms and the socially conscious lyrics associated with Sweden''s progg movement, without ever abandoning the blues feeling underneath. His single "Falsk matematik" spent 15 weeks atop Svensktoppen, the Swedish national chart show, and remains one of the most-loved singles in Swedish pop history (Kilde: Wikipedia; Sveriges Radio).

Persson''s late-career albums continued to chart strongly — "Röster från Södern" reached No. 1 in 1994, and the retrospective "Oh Boy! – Det bästa med Peps Persson" reached No. 2 in 2006 — cementing his status as a genuine national institution. He received an honorary Grammis award in 2007 and was inducted into the Swedish Music Hall of Fame in 2015, recognition of a career that had, by then, spanned more than four decades of turning American blues into something unmistakably his own (Kilde: Grammis; Swedish Music Hall of Fame).

Persson died on 27 June 2021 at his home in Vittsjö, Sweden, at the age of 74. He remains a towering reference point for every Swedish blues artist who followed — proof that the blues could be sung in a regional Swedish dialect and still hit exactly as hard as the Chicago and Delta originals he loved (Kilde: Wikipedia; Sveriges Radio, obituary coverage).', biography_no = 'Peps Persson sang ikke bare blues i Sverige — han oversatte den, og ga Muddy Waters- og Elmore James-sanger nytt liv på sin egen tykke skånske dialekt, og ble dermed en av de mest elskede og umiddelbart gjenkjennelige stemmene i svensk populærmusikk. Født Per-Åke Tommy Persson 20. desember 1946 i Helsingborg og oppvokst i Tjörnarp, Skåne, startet han sitt første band, Pop Penders, i 1962, før han gikk sammen med Blues Quality for å danne Peps Blues Quality på slutten av 1960-tallet, hvor de spilte rene elektriske bluesdekninger (Kilde: Wikipedia; Svensk Musik).

Hans mest varige prosjekt var Peps Perssons Blodsband, dannet i 1974, som ga ut ni studioalbum mellom 1974 og 2005 og ble den definitive svenske bluesrock-gruppen i sin epoke — bygget på Perssons dialektsungede, blåserdrevne arrangementer av blues- og R&B-standarder. Etter 1975 vendte låtskrivingen hans seg i økende grad mot reggae-rytmer og de samfunnskritiske tekstene knyttet til Sveriges progg-bevegelse, uten noen gang å forlate bluesfølelsen under. Singelen «Falsk matematik» lå 15 uker på topp av Svensktoppen, den svenske nasjonale hitlisteshowet, og er fortsatt en av de mest elskede singlene i svensk poparv (Kilde: Wikipedia; Sveriges Radio).

Perssons sene album fortsatte å ligge høyt på listene — «Röster från Södern» nådde førsteplass i 1994, og retrospektivet «Oh Boy! – Det bästa med Peps Persson» nådde andreplass i 2006 — og befestet hans status som en genuin nasjonal institusjon. Han mottok en æres-Grammis i 2007 og ble innlemmet i Swedish Music Hall of Fame i 2015, en anerkjennelse av en karriere som da hadde spent over mer enn fire tiår med å gjøre amerikansk blues til noe umiskjennelig sitt eget (Kilde: Grammis; Swedish Music Hall of Fame).

Persson døde 27. juni 2021 hjemme i Vittsjö, Sverige, 74 år gammel. Han forblir et enormt referansepunkt for enhver svensk bluesartist som fulgte etter — et bevis på at bluesen kunne synges på en regional svensk dialekt og likevel treffe like hardt som Chicago- og Delta-originalene han elsket (Kilde: Wikipedia; Sveriges Radio, minneomtaler).', biography_sv = 'Peps Persson sjöng inte bara blues i Sverige — han översatte den, och gav Muddy Waters- och Elmore James-låtar nytt liv på sin egen tjocka skånska dialekt, och blev därmed en av de mest älskade och omedelbart igenkännbara rösterna i svensk populärmusik. Född Per-Åke Tommy Persson den 20 december 1946 i Helsingborg och uppvuxen i Tjörnarp, Skåne, startade han sitt första band, Pop Penders, 1962, innan han gick samman med Blues Quality för att bilda Peps Blues Quality i slutet av 1960-talet, där de spelade rena elektriska bluescovers (Källa: Wikipedia; Svensk Musik).

Hans mest bestående projekt var Peps Perssons Blodsband, bildat 1974, som gav ut nio studioalbum mellan 1974 och 2005 och blev den definitiva svenska bluesrockgruppen under sin era — byggd på Perssons dialektsjungna, blåsardrivna arrangemang av blues- och R&B-standarder. Efter 1975 vände sig hans låtskrivande alltmer mot reggae-rytmer och de samhällskritiska texter som förknippades med Sveriges proggrörelse, utan att någonsin överge bluesskänslan därunder. Singeln "Falsk matematik" låg 15 veckor på toppen av Svensktoppen, det svenska nationella listprogrammet, och är fortfarande en av de mest älskade singlarna i svensk poparv (Källa: Wikipedia; Sveriges Radio).

Perssons sena album fortsatte att ligga högt på listorna — "Röster från Södern" nådde förstaplatsen 1994, och retrospektivet "Oh Boy! – Det bästa med Peps Persson" nådde andraplatsen 2006 — och befäste hans status som en genuin nationell institution. Han fick en heders-Grammis 2007 och invaldes i Swedish Music Hall of Fame 2015, ett erkännande av en karriär som då hade spänt över mer än fyra decennier av att göra amerikansk blues till något omisskännligt eget (Källa: Grammis; Swedish Music Hall of Fame).

Persson dog den 27 juni 2021 i sitt hem i Vittsjö, Sverige, 74 år gammal. Han förblir en enorm referenspunkt för varje svensk bluesartist som följde efter — ett bevis på att bluesen kunde sjungas på en regional svensk dialekt och ändå träffa lika hårt som Chicago- och Deltaoriginalen han älskade (Källa: Wikipedia; Sveriges Radio, minnesbevakning).', biography_de = 'Peps Persson sang den Blues in Schweden nicht nur — er übersetzte ihn, verlieh Songs von Muddy Waters und Elmore James neues Leben in seinem eigenen breiten schonischen Dialekt und wurde dadurch zu einer der beliebtesten und sofort erkennbaren Stimmen der schwedischen Popmusik. Geboren als Per-Åke Tommy Persson am 20. Dezember 1946 in Helsingborg und aufgewachsen in Tjörnarp, Schonen, gründete er 1962 seine erste Band, Pop Penders, bevor er sich Ende der 1960er-Jahre mit Blues Quality zu Peps Blues Quality zusammenschloss, die reine elektrische Blues-Coverversionen spielten (Quelle: Wikipedia; Svensk Musik).

Sein dauerhaftestes Projekt war Peps Perssons Blodsband, 1974 gegründet, die zwischen 1974 und 2005 neun Studioalben veröffentlichten und zur maßgeblichen schwedischen Bluesrock-Formation ihrer Ära wurden — aufgebaut auf Perssons im Dialekt gesungenen, bläsergetriebenen Arrangements von Blues- und R&B-Standards. Nach 1975 wandte sich sein Songwriting zunehmend Reggae-Rhythmen und den gesellschaftskritischen Texten zu, die mit Schwedens Progg-Bewegung verbunden waren, ohne je das darunterliegende Blues-Gefühl aufzugeben. Seine Single "Falsk matematik" stand 15 Wochen an der Spitze von Svensktoppen, der schwedischen nationalen Hitparaden-Sendung, und bleibt eine der beliebtesten Singles der schwedischen Popgeschichte (Quelle: Wikipedia; Sveriges Radio).

Perssons Alben aus späteren Karrierejahren blieben weiterhin stark in den Charts — "Röster från Södern" erreichte 1994 Platz 1, und die Retrospektive "Oh Boy! – Det bästa med Peps Persson" erreichte 2006 Platz 2 — und festigten seinen Status als echte nationale Institution. Er erhielt 2007 einen Ehren-Grammis und wurde 2015 in die Swedish Music Hall of Fame aufgenommen, eine Anerkennung einer Karriere, die zu diesem Zeitpunkt bereits mehr als vier Jahrzehnte umfasste, in denen er amerikanischen Blues in etwas unverkennbar Eigenes verwandelte (Quelle: Grammis; Swedish Music Hall of Fame).

Persson starb am 27. Juni 2021 im Alter von 74 Jahren in seinem Zuhause in Vittsjö, Schweden. Er bleibt ein überragender Bezugspunkt für jeden schwedischen Bluesmusiker, der ihm folgte — ein Beweis dafür, dass der Blues in einem regionalen schwedischen Dialekt gesungen werden konnte und dennoch genauso hart traf wie die Chicago- und Delta-Originale, die er liebte (Quelle: Wikipedia; Sveriges Radio, Nachrufberichterstattung).', biography_pl = 'Peps Persson nie tylko śpiewał bluesa w Szwecji — tłumaczył go, nadając piosenkom Muddy''ego Watersa i Elmore''a Jamesa nowe życie we własnym, gęstym dialekcie skańskim, stając się tym samym jednym z najbardziej uwielbianych i natychmiast rozpoznawalnych głosów szwedzkiej muzyki popularnej. Urodzony jako Per-Åke Tommy Persson 20 grudnia 1946 roku w Helsingborgu i wychowany w Tjörnarp w Skanii, założył swój pierwszy zespół, Pop Penders, w 1962 roku, zanim połączył siły z Blues Quality, tworząc Peps Blues Quality pod koniec lat 60., grając czyste, elektryczne covery bluesowe (Źródło: Wikipedia; Svensk Musik).

Jego najtrwalszym projektem był Peps Perssons Blodsband, założony w 1974 roku, który wydał dziewięć albumów studyjnych w latach 1974–2005 i stał się definitywnym szwedzkim zespołem blues-rockowym swojej epoki — zbudowanym na śpiewanych w dialekcie, napędzanych sekcją dętą aranżacjach standardów bluesa i R&B. Po 1975 roku jego twórczość coraz bardziej zwracała się ku rytmom reggae i społecznie zaangażowanym tekstom kojarzonym ze szwedzkim ruchem progg, nigdy jednak nie porzucając leżącego u podstaw uczucia bluesa. Jego singiel "Falsk matematik" spędził 15 tygodni na szczycie Svensktoppen, szwedzkiej narodowej listy przebojów, i pozostaje jednym z najbardziej ukochanych singli w historii szwedzkiego popu (Źródło: Wikipedia; Sveriges Radio).

Późniejsze albumy Perssona nadal osiągały wysokie pozycje na listach — "Röster från Södern" dotarł na 1. miejsce w 1994 roku, a retrospektywny "Oh Boy! – Det bästa med Peps Persson" dotarł na 2. miejsce w 2006 roku — utrwalając jego status prawdziwej instytucji narodowej. Otrzymał honorową nagrodę Grammis w 2007 roku i został wprowadzony do Szwedzkiej Galerii Sław Muzyki w 2015 roku, uznanie kariery, która do tego czasu obejmowała już ponad cztery dekady przekształcania amerykańskiego bluesa w coś niepowtarzalnie własnego (Źródło: Grammis; Szwedzka Galeria Sław Muzyki).

Persson zmarł 27 czerwca 2021 roku w swoim domu w Vittsjö w Szwecji, w wieku 74 lat. Pozostaje olbrzymim punktem odniesienia dla każdego szwedzkiego artysty bluesowego, który przyszedł po nim — dowodem na to, że blues można było śpiewać w regionalnym szwedzkim dialekcie i wciąż uderzał tak mocno, jak oryginały z Chicago i Delty, które kochał (Źródło: Wikipedia; Sveriges Radio, relacje pośmiertne).',
  influence_en = 'By singing American blues in his own regional dialect, Persson proved the genre could be fully naturalized without losing its power — a template every subsequent Swedish blues artist has had to reckon with. (Kilde: Wikipedia; Swedish Music Hall of Fame)', influence_no = 'Ved å synge amerikansk blues på sin egen regionale dialekt beviste Persson at sjangeren kunne bli fullstendig naturalisert uten å miste sin kraft — en mal enhver senere svensk bluesartist har måttet forholde seg til. (Kilde: Wikipedia; Swedish Music Hall of Fame)', influence_sv = 'Genom att sjunga amerikansk blues på sin egen regionala dialekt bevisade Persson att genren kunde naturaliseras helt utan att förlora sin kraft — en mall varje senare svensk bluesartist har fått förhålla sig till. (Källa: Wikipedia; Swedish Music Hall of Fame)', influence_de = 'Indem er amerikanischen Blues in seinem eigenen regionalen Dialekt sang, bewies Persson, dass das Genre vollständig eingebürgert werden konnte, ohne seine Kraft zu verlieren — eine Vorlage, mit der sich jeder nachfolgende schwedische Bluesmusiker auseinandersetzen musste. (Quelle: Wikipedia; Swedish Music Hall of Fame)', influence_pl = 'Śpiewając amerykańskiego bluesa we własnym dialekcie regionalnym, Persson udowodnił, że gatunek ten można w pełni zaadaptować bez utraty jego siły — wzorzec, z którym musiał się zmierzyć każdy późniejszy szwedzki artysta bluesowy. (Źródło: Wikipedia; Szwedzka Galeria Sław Muzyki)',
  formative_i18n = '{"en":["1962: Forms his first band, Pop Penders. (Kilde: Wikipedia)","Late 1960s: Forms Peps Blues Quality with Blues Quality, playing electric blues covers. (Kilde: Wikipedia)","1974: Forms Peps Perssons Blodsband, his most enduring and influential band. (Kilde: Wikipedia)","1975: \"Falsk matematik\" tops Svensktoppen for 15 weeks. (Kilde: Sveriges Radio)","1994: \"Röster från Södern\" reaches No. 1 on the Swedish albums chart. (Kilde: Wikipedia)","2007: Receives an honorary Grammis award. (Kilde: Grammis)","2015: Inducted into the Swedish Music Hall of Fame. (Kilde: Swedish Music Hall of Fame)","2021: Dies on 27 June in Vittsjö, Sweden, aged 74. (Kilde: Wikipedia)"],"no":["1962: Danner sitt første band, Pop Penders. (Kilde: Wikipedia)","Sent 1960-tall: Danner Peps Blues Quality med Blues Quality, og spiller elektriske bluesdekninger. (Kilde: Wikipedia)","1974: Danner Peps Perssons Blodsband, hans mest varige og innflytelsesrike band. (Kilde: Wikipedia)","1975: «Falsk matematik» topper Svensktoppen i 15 uker. (Kilde: Sveriges Radio)","1994: «Röster från Södern» når førsteplass på den svenske albumlisten. (Kilde: Wikipedia)","2007: Mottar en æres-Grammis. (Kilde: Grammis)","2015: Innlemmes i Swedish Music Hall of Fame. (Kilde: Swedish Music Hall of Fame)","2021: Dør 27. juni i Vittsjö, Sverige, 74 år gammel. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Vokal","name":"Vocals","note":"His dialect-sung interpretations of American blues songs are his defining artistic signature.","source":"Wikipedia"},{"category":"Gitar","name":"Guitar","note":"Rhythm and lead guitar across his career, especially in the Blues Quality and early Blodsband years.","source":"Wikipedia"}],"no":[{"category":"Vokal","name":"Vokal","note":"Hans dialektsungede tolkninger av amerikanske bluessanger er hans definerende kunstneriske signatur.","source":"Wikipedia"},{"category":"Gitar","name":"Gitar","note":"Rytme- og leadgitar gjennom karrieren, spesielt i Blues Quality- og tidlige Blodsband-år.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["\"Falsk matematik\" spent 15 consecutive weeks at No. 1 on Svensktoppen, an almost unheard-of run that turned Persson into a household name far beyond blues circles. (Kilde: Sveriges Radio)","Persson''s decision to sing blues classics in his native Scanian dialect rather than English or standard Swedish was, at the time, a genuinely radical artistic choice — one that Swedish critics later credited with giving the blues real cultural roots in Sweden. (Kilde: Wikipedia)","Even after his songwriting turned toward reggae and political themes in the late 1970s, Peps Blodsband kept touring and recording together for another three decades, releasing albums as late as 2005. (Kilde: Wikipedia)"],"no":["«Falsk matematik» lå 15 sammenhengende uker på førsteplass på Svensktoppen, en nesten uhørt bragd som gjorde Persson til et husstandsnavn langt utenfor bluesmiljøet. (Kilde: Sveriges Radio)","Perssons beslutning om å synge blueslassikere på sin egen skånske dialekt fremfor engelsk eller standardsvensk var, på den tiden, et genuint radikalt kunstnerisk valg — et valg svenske kritikere senere krediterte med å gi bluesen ekte kulturelle røtter i Sverige. (Kilde: Wikipedia)","Selv etter at låtskrivingen hans vendte seg mot reggae og politiske temaer på slutten av 1970-tallet, fortsatte Peps Blodsband å turnere og spille inn sammen i ytterligere tre tiår, med album helt frem til 2005. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Blues Quality","note":"Backing band for Peps Blues Quality in the late 1960s.","source":"Wikipedia"},{"name":"Peps Perssons Blodsband","note":"His main band from 1974 to 2005; nine studio albums.","source":"Wikipedia"},{"name":"Pelle Perssons Kapell","note":"Collaborative project alongside his main output.","source":"Wikipedia"}],"no":[{"name":"Blues Quality","note":"Backingband for Peps Blues Quality på slutten av 1960-tallet.","source":"Wikipedia"},{"name":"Peps Perssons Blodsband","note":"Hans hovedband fra 1974 til 2005; ni studioalbum.","source":"Wikipedia"},{"name":"Pelle Perssons Kapell","note":"Samarbeidsprosjekt ved siden av hans hovedvirke.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1974,"title":"Blodsband","producer":"—","label":"—","notes":"Debut album of Peps Perssons Blodsband, launching his signature dialect-sung blues sound.","musicians":[],"youtube_id":""},{"year":1975,"title":"Hög Standard","producer":"—","label":"—","notes":"Contains \"Falsk matematik,\" which topped Svensktoppen for 15 weeks.","musicians":[],"youtube_id":"qcnTW2s1kKo"},{"year":1988,"title":"Fram Med Pengarna!","producer":"—","label":"—","notes":"Late-period Blodsband album.","musicians":[],"youtube_id":"H3nqKzAjBnI"},{"year":1994,"title":"Röster från Södern","producer":"—","label":"—","notes":"Reached No. 1 on the Swedish albums chart.","musicians":[],"youtube_id":""},{"year":2006,"title":"Oh Boy! – Det bästa med Peps Persson","producer":"—","label":"—","notes":"Career-spanning retrospective; reached No. 2 on the Swedish albums chart.","musicians":[],"youtube_id":""}],"no":[{"year":1974,"title":"Blodsband","producer":"—","label":"—","notes":"Debutalbum til Peps Perssons Blodsband, som lanserte hans signatur dialektsungede bluessound.","musicians":[],"youtube_id":""},{"year":1975,"title":"Hög Standard","producer":"—","label":"—","notes":"Inneholder «Falsk matematik», som toppet Svensktoppen i 15 uker.","musicians":[],"youtube_id":"qcnTW2s1kKo"},{"year":1988,"title":"Fram Med Pengarna!","producer":"—","label":"—","notes":"Sent Blodsband-album.","musicians":[],"youtube_id":"H3nqKzAjBnI"},{"year":1994,"title":"Röster från Södern","producer":"—","label":"—","notes":"Nådde førsteplass på den svenske albumlisten.","musicians":[],"youtube_id":""},{"year":2006,"title":"Oh Boy! – Det bästa med Peps Persson","producer":"—","label":"—","notes":"Karriereoppsummerende retrospektiv; nådde andreplass på den svenske albumlisten.","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["Falsk matematik","Lived på lanned","Fram med pengarna"],"no":["Falsk matematik","Lived på lanned","Fram med pengarna"]}',
  influences_i18n = '{"en":["Muddy Waters","Elmore James","Chicago blues"],"no":["Muddy Waters","Elmore James","Chicago-blues"]}',
  styles = '["Nordic Blues","Blues Rock","Reggae"]',
  videos = '[{"kind":"featured","title":"Peps Blodsband — Falsk matematik","youtube_id":"qcnTW2s1kKo","channel":"Peps Blodsband - Topic"},{"kind":"more","title":"Peps Blodsband — Lived på lanned","youtube_id":"H3nqKzAjBnI","channel":"Peps Blodsband - Topic"},{"kind":"more","title":"Peps Blodsband — Lived po lanned (live)","youtube_id":"YYaxMG87qXU","channel":"Apollon Bild & Film"}]',
  article_references = '[{"title":"Peps Persson — Wikipedia","url":"https://en.wikipedia.org/wiki/Peps_Persson"},{"title":"Svensk Musik / Sveriges Radio — Peps Persson","url":"https://sverigesradio.se/"},{"title":"Grammis — Hedersgrammis","url":"https://grammis.se/"},{"title":"Swedish Music Hall of Fame","url":"https://swedishmusichalloffame.se/"}]'
WHERE slug = 'peps-persson';
INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'eric-bibb', 'Eric Bibb', NULL, 'Modern', 'Modern Era', '1972–present', 'New York City, USA', 'Stockholm, Sweden (resident)', 'Sweden', 'Nordic', 500, 'American folk royalty (father Leon Bibb, godfather Paul Robeson) who settled in Stockholm and became one of the world''s most Grammy-nominated acoustic blues artists, spanning 50+ albums from "Good Stuff" (1997) to "Ridin''" (2023).', 'Amerikansk folkemusikk-adel (far Leon Bibb, gudfar Paul Robeson) som slo seg ned i Stockholm og ble en av verdens mest Grammy-nominerte akustiske bluesartister, med over 50 album fra «Good Stuff» (1997) til «Ridin''» (2023).');

UPDATE artists SET
  short_sv = 'Amerikansk folkmusikadel (far Leon Bibb, gudfar Paul Robeson) som bosatte sig i Stockholm och blev en av världens mest Grammy-nominerade akustiska bluesartister, med över 50 album från "Good Stuff" (1997) till "Ridin''" (2023).', short_de = 'Amerikanischer Folk-Adel (Vater Leon Bibb, Patenonkel Paul Robeson), der sich in Stockholm niederließ und einer der weltweit meist Grammy-nominierten Akustik-Bluesmusiker wurde, mit über 50 Alben von "Good Stuff" (1997) bis "Ridin''" (2023).', short_pl = 'Amerykańska arystokracja folku (ojciec Leon Bibb, ojciec chrzestny Paul Robeson), który osiadł w Sztokholmie i stał się jednym z najczęściej nominowanych do Grammy akustycznych artystów bluesowych na świecie, z ponad 50 albumami od "Good Stuff" (1997) po "Ridin''" (2023).',
  biography_en = 'Eric Bibb was born into American folk royalty on 16 August 1951 in New York City — his father Leon Bibb was a prominent musical-theatre singer on the 1960s New York folk scene, his uncle was Modern Jazz Quartet pianist John Lewis, and his godfather was Paul Robeson. Pete Seeger was a family friend. Bibb got his first steel-string guitar at eight, met a young Bob Dylan as a child (who told him to "keep it simple, forget all that fancy stuff"), and by 16 was playing guitar in the house band of his father''s television talent show (Kilde: Wikipedia).

After briefly studying psychology and Russian at Columbia University, Bibb moved to Paris at 19, where guitarist Mickey Baker introduced him to blues guitar technique. He eventually settled in Stockholm, immersing himself in pre-war acoustic blues and world music traditions — a move that would define the rest of his career and, decades later, earn him a place on this site as one of Sweden''s most important resident blues artists, even though his roots remain unmistakably American (Kilde: Wikipedia).

His Stockholm-based recordings began with "Good Stuff" (1997, Opus 3/Earthbeat) and "Me to You" (Code Blue), the latter featuring Pops and Mavis Staples and Taj Mahal. Through his own Manhaton Records he released "Home to Me" (1999), "Roadworks" (2000) and "Painting Signs" (2001), and in 2002 recorded "A Family Affair" with his father. His years on Telarc International (2004–2011) produced some of his most acclaimed work: "Friends" (2004), "A Ship Called Love" (2005), "Diamond Days" (2007), "Spirit I Am" (2008), and "Booker''s Guitar" (2010), a tribute to Delta bluesman Bukka White (Kilde: Wikipedia).

Bibb signed to Stony Plain Records in 2011 and to Provogue Records in 2021, releasing "Dear America" (2021, featuring Eric Gales and Ron Carter) and "Ridin''" (2023), which reached the Top 10 of the blues charts. His album "One Mississippi" is slated for release on Repute Records in 2026. Across more than 50 albums, Bibb has earned three Grammy nominations — for "Shakin'' a Tailfeather" (1997), "Migration Blues" (2017) and "Ridin''" (2023) — and Blues Music Awards for Acoustic Artist of the Year (2012, 2013) and Acoustic Album of the Year for "The Happiest Man in the World" (2017), his collaboration with British bassist Danny Thompson. His long list of collaborators includes Taj Mahal, Odetta, Charlie Musselwhite, Guy Davis and Mamadou Diabaté (Kilde: Wikipedia; Blues Music Awards).', biography_no = 'Eric Bibb ble født inn i amerikansk folkemusikk-adel 16. august 1951 i New York City — faren Leon Bibb var en fremtredende musikkteatersanger i New Yorks folkemusikkmiljø på 1960-tallet, onkelen var Modern Jazz Quartet-pianisten John Lewis, og gudfaren var Paul Robeson. Pete Seeger var en familievenn. Bibb fikk sin første stålstrenget gitar som åtteåring, møtte en ung Bob Dylan som barn (som sa til ham «hold det enkelt, glem alt det fancy»), og spilte allerede som 16-åring gitar i husbandet til farens TV-talentshow (Kilde: Wikipedia).

Etter en kort periode med psykologi- og russiskstudier ved Columbia University flyttet Bibb til Paris som 19-åring, hvor gitaristen Mickey Baker introduserte ham for blues-gitarteknikk. Han slo seg til slutt ned i Stockholm, og fordypet seg i før-krigs akustisk blues og verdensmusikktradisjoner — et flytt som skulle definere resten av karrieren hans og, tiår senere, gi ham en plass på dette nettstedet som en av Sveriges viktigste bosatte bluesartister, selv om røttene hans forblir umiskjennelig amerikanske (Kilde: Wikipedia).

Hans Stockholm-baserte innspillinger startet med «Good Stuff» (1997, Opus 3/Earthbeat) og «Me to You» (Code Blue), sistnevnte med Pops og Mavis Staples og Taj Mahal. Gjennom sitt eget Manhaton Records ga han ut «Home to Me» (1999), «Roadworks» (2000) og «Painting Signs» (2001), og i 2002 spilte han inn «A Family Affair» med faren sin. Årene på Telarc International (2004–2011) ga noen av hans mest anerkjente verk: «Friends» (2004), «A Ship Called Love» (2005), «Diamond Days» (2007), «Spirit I Am» (2008), og «Booker''s Guitar» (2010), en hyllest til Delta-bluesmusikeren Bukka White (Kilde: Wikipedia).

Bibb skrev under hos Stony Plain Records i 2011 og hos Provogue Records i 2021, og ga ut «Dear America» (2021, med Eric Gales og Ron Carter) og «Ridin''» (2023), som nådde topp 10 på blueslistene. Albumet «One Mississippi» er planlagt utgitt på Repute Records i 2026. Over mer enn 50 album har Bibb fått tre Grammy-nominasjoner — for «Shakin'' a Tailfeather» (1997), «Migration Blues» (2017) og «Ridin''» (2023) — og Blues Music Awards for Acoustic Artist of the Year (2012, 2013) og Acoustic Album of the Year for «The Happiest Man in the World» (2017), samarbeidet med den britiske bassisten Danny Thompson. Hans lange liste av samarbeidspartnere inkluderer Taj Mahal, Odetta, Charlie Musselwhite, Guy Davis og Mamadou Diabaté (Kilde: Wikipedia; Blues Music Awards).', biography_sv = 'Eric Bibb föddes in i amerikansk folkmusikadel den 16 augusti 1951 i New York City — hans far Leon Bibb var en framstående musikteatersångare i New Yorks folkmusikscen på 1960-talet, hans farbror var Modern Jazz Quartet-pianisten John Lewis, och hans gudfar var Paul Robeson. Pete Seeger var en familjevän. Bibb fick sin första stålsträngade gitarr vid åtta års ålder, träffade en ung Bob Dylan som barn (som sa till honom "håll det enkelt, glöm allt det där flashiga"), och vid 16 spelade han redan gitarr i husbandet till faderns tv-talangshow (Källa: Wikipedia).

Efter att kort ha studerat psykologi och ryska vid Columbia University flyttade Bibb till Paris vid 19 års ålder, där gitarristen Mickey Baker introducerade honom för blues-gitarrteknik. Han bosatte sig så småningom i Stockholm och fördjupade sig i akustisk förkrigsblues och världsmusiktraditioner — en flytt som skulle definiera resten av hans karriär och, decennier senare, ge honom en plats på den här sajten som en av Sveriges viktigaste bosatta bluesartister, även om hans rötter förblir omisskännligt amerikanska (Källa: Wikipedia).

Hans Stockholmsbaserade inspelningar började med "Good Stuff" (1997, Opus 3/Earthbeat) och "Me to You" (Code Blue), den senare med Pops och Mavis Staples samt Taj Mahal. Genom sitt eget Manhaton Records gav han ut "Home to Me" (1999), "Roadworks" (2000) och "Painting Signs" (2001), och 2002 spelade han in "A Family Affair" med sin far. Åren på Telarc International (2004–2011) gav några av hans mest hyllade verk: "Friends" (2004), "A Ship Called Love" (2005), "Diamond Days" (2007), "Spirit I Am" (2008) och "Booker''s Guitar" (2010), en hyllning till Delta-bluesmusikern Bukka White (Källa: Wikipedia).

Bibb skrev kontrakt med Stony Plain Records 2011 och med Provogue Records 2021, och gav ut "Dear America" (2021, med Eric Gales och Ron Carter) och "Ridin''" (2023), som nådde topp 10 på blueslistorna. Albumet "One Mississippi" är planerat att släppas på Repute Records 2026. Över mer än 50 album har Bibb fått tre Grammy-nomineringar — för "Shakin'' a Tailfeather" (1997), "Migration Blues" (2017) och "Ridin''" (2023) — och Blues Music Awards för Acoustic Artist of the Year (2012, 2013) och Acoustic Album of the Year för "The Happiest Man in the World" (2017), samarbetet med den brittiske basisten Danny Thompson. Hans långa lista över samarbetspartners inkluderar Taj Mahal, Odetta, Charlie Musselwhite, Guy Davis och Mamadou Diabaté (Källa: Wikipedia; Blues Music Awards).', biography_de = 'Eric Bibb wurde am 16. August 1951 in New York City in eine Familie amerikanischer Folk-Größen hineingeboren — sein Vater Leon Bibb war ein prominenter Musiktheater-Sänger der New Yorker Folk-Szene der 1960er-Jahre, sein Onkel war der Modern-Jazz-Quartet-Pianist John Lewis, und sein Patenonkel war Paul Robeson. Pete Seeger war ein Familienfreund. Bibb bekam seine erste Stahlsaitengitarre im Alter von acht Jahren, traf als Kind einen jungen Bob Dylan (der ihm riet: "Halt es einfach, vergiss all den ausgefallenen Kram"), und spielte mit 16 Jahren bereits Gitarre in der Hausband der Fernseh-Talentshow seines Vaters (Quelle: Wikipedia).

Nach einem kurzen Psychologie- und Russisch-Studium an der Columbia University zog Bibb im Alter von 19 Jahren nach Paris, wo ihn der Gitarrist Mickey Baker in die Blues-Gitarrentechnik einführte. Schließlich ließ er sich in Stockholm nieder und vertiefte sich in akustischen Vorkriegsblues und Weltmusiktraditionen — ein Umzug, der den Rest seiner Karriere prägen und ihm Jahrzehnte später einen Platz auf dieser Seite als einer der bedeutendsten in Schweden ansässigen Bluesmusiker einbringen sollte, obwohl seine Wurzeln unverkennbar amerikanisch bleiben (Quelle: Wikipedia).

Seine in Stockholm entstandenen Aufnahmen begannen mit "Good Stuff" (1997, Opus 3/Earthbeat) und "Me to You" (Code Blue), letzteres mit Pops und Mavis Staples sowie Taj Mahal. Über sein eigenes Label Manhaton Records veröffentlichte er "Home to Me" (1999), "Roadworks" (2000) und "Painting Signs" (2001), und 2002 nahm er mit seinem Vater "A Family Affair" auf. Seine Jahre bei Telarc International (2004–2011) brachten einige seiner am meisten gefeierten Werke hervor: "Friends" (2004), "A Ship Called Love" (2005), "Diamond Days" (2007), "Spirit I Am" (2008) und "Booker''s Guitar" (2010), eine Hommage an den Delta-Bluesmusiker Bukka White (Quelle: Wikipedia).

Bibb unterschrieb 2011 bei Stony Plain Records und 2021 bei Provogue Records, wo er "Dear America" (2021, mit Eric Gales und Ron Carter) und "Ridin''" (2023) veröffentlichte, das die Top 10 der Blues-Charts erreichte. Sein Album "One Mississippi" soll 2026 bei Repute Records erscheinen. Über mehr als 50 Alben hinweg erhielt Bibb drei Grammy-Nominierungen — für "Shakin'' a Tailfeather" (1997), "Migration Blues" (2017) und "Ridin''" (2023) — sowie Blues Music Awards als Acoustic Artist of the Year (2012, 2013) und Acoustic Album of the Year für "The Happiest Man in the World" (2017), seine Zusammenarbeit mit dem britischen Bassisten Danny Thompson. Seine lange Liste an Mitwirkenden umfasst Taj Mahal, Odetta, Charlie Musselwhite, Guy Davis und Mamadou Diabaté (Quelle: Wikipedia; Blues Music Awards).', biography_pl = 'Eric Bibb urodził się w rodzinie amerykańskiej arystokracji folkowej 16 sierpnia 1951 roku w Nowym Jorku — jego ojciec Leon Bibb był znanym śpiewakiem teatru muzycznego na nowojorskiej scenie folkowej lat 60., wujek był pianistą Modern Jazz Quartet Johnem Lewisem, a ojcem chrzestnym był Paul Robeson. Pete Seeger był przyjacielem rodziny. Bibb otrzymał swoją pierwszą gitarę ze stalowymi strunami w wieku ośmiu lat, jako dziecko poznał młodego Boba Dylana (który powiedział mu, by "zachować prostotę, zapomnieć o tych wszystkich fikuśnych rzeczach"), a w wieku 16 lat grał już na gitarze w zespole domowym telewizyjnego talent show swojego ojca (Źródło: Wikipedia).

Po krótkich studiach psychologii i rusycystyki na Uniwersytecie Columbia, Bibb przeniósł się w wieku 19 lat do Paryża, gdzie gitarzysta Mickey Baker wprowadził go w technikę gry bluesowej na gitarze. Ostatecznie osiadł w Sztokholmie, zagłębiając się w akustycznego bluesa sprzed wojny i tradycje muzyki świata — przeprowadzka, która miała zdefiniować resztę jego kariery i, dekady później, zapewnić mu miejsce na tej stronie jako jednemu z najważniejszych szwedzkich artystów bluesowych osiadłych w tym kraju, mimo że jego korzenie pozostają niezaprzeczalnie amerykańskie (Źródło: Wikipedia).

Jego nagrania powstałe w Sztokholmie rozpoczęły się od "Good Stuff" (1997, Opus 3/Earthbeat) i "Me to You" (Code Blue), na którym gościnnie wystąpili Pops i Mavis Staples oraz Taj Mahal. Poprzez własną wytwórnię Manhaton Records wydał "Home to Me" (1999), "Roadworks" (2000) i "Painting Signs" (2001), a w 2002 roku nagrał "A Family Affair" ze swoim ojcem. Lata w Telarc International (2004–2011) przyniosły jedne z jego najbardziej cenionych dzieł: "Friends" (2004), "A Ship Called Love" (2005), "Diamond Days" (2007), "Spirit I Am" (2008) i "Booker''s Guitar" (2010), hołd dla bluesmana z Delty, Bukki White''a (Źródło: Wikipedia).

Bibb podpisał kontrakt ze Stony Plain Records w 2011 roku i z Provogue Records w 2021 roku, wydając "Dear America" (2021, z udziałem Erica Galesa i Rona Cartera) oraz "Ridin''" (2023), który dotarł do Top 10 list bluesowych. Jego album "One Mississippi" ma się ukazać nakładem Repute Records w 2026 roku. Na przestrzeni ponad 50 albumów Bibb otrzymał trzy nominacje do nagrody Grammy — za "Shakin'' a Tailfeather" (1997), "Migration Blues" (2017) i "Ridin''" (2023) — oraz nagrody Blues Music Awards dla Akustycznego Artysty Roku (2012, 2013) i Akustycznego Albumu Roku za "The Happiest Man in the World" (2017), jego współpracę z brytyjskim basistą Dannym Thompsonem. Jego długa lista współpracowników obejmuje Taj Mahala, Odettę, Charliego Musselwhite''a, Guya Davisa i Mamadou Diabaté (Źródło: Wikipedia; Blues Music Awards).',
  influence_en = 'Bibb''s decades in Stockholm make him a genuine bridge figure between American acoustic blues tradition and the Swedish/European blues scene — a resident ambassador whose Grammy-nominated catalog has shaped how a generation of European acoustic blues players approach the genre. (Kilde: Wikipedia)', influence_no = 'Bibbs tiår i Stockholm gjør ham til en genuin brofigur mellom amerikansk akustisk bluestradisjon og den svenske/europeiske bluesscenen — en bosatt ambassadør hvis Grammy-nominerte katalog har formet hvordan en generasjon europeiske akustiske bluesmusikere nærmer seg sjangeren. (Kilde: Wikipedia)', influence_sv = 'Bibbs decennier i Stockholm gör honom till en genuin brofigur mellan amerikansk akustisk bluestradition och den svenska/europeiska bluesscenen — en bosatt ambassadör vars Grammy-nominerade katalog har format hur en generation europeiska akustiska bluesmusiker närmar sig genren. (Källa: Wikipedia)', influence_de = 'Bibbs Jahrzehnte in Stockholm machen ihn zu einer echten Brückenfigur zwischen amerikanischer akustischer Blues-Tradition und der schwedisch-europäischen Blues-Szene — ein ansässiger Botschafter, dessen für den Grammy nominierter Katalog geprägt hat, wie eine Generation europäischer Akustik-Bluesmusiker an das Genre herangeht. (Quelle: Wikipedia)', influence_pl = 'Dekady Bibba w Sztokholmie czynią go prawdziwą postacią-pomostem między amerykańską tradycją akustycznego bluesa a szwedzką/europejską sceną bluesową — rezydującym ambasadorem, którego nominowany do Grammy katalog ukształtował podejście do gatunku całego pokolenia europejskich akustycznych muzyków bluesowych. (Źródło: Wikipedia)',
  formative_i18n = '{"en":["1959: Receives his first steel-string guitar at age eight. (Kilde: Wikipedia)","1969: Performs for the Negro Ensemble Company in New York. (Kilde: Wikipedia)","1970: Moves to Paris at 19; learns blues guitar technique from Mickey Baker. (Kilde: Wikipedia)","Relocates to Stockholm, immersing himself in pre-war acoustic blues. (Kilde: Wikipedia)","1997: Releases \"Good Stuff\" on Opus 3/Earthbeat, his Stockholm-era breakthrough. (Kilde: Wikipedia)","2004–2011: Telarc International years produce \"Friends,\" \"Diamond Days,\" \"Spirit I Am\" and \"Booker''s Guitar.\" (Kilde: Wikipedia)","2017: \"The Happiest Man in the World\" with Danny Thompson wins Blues Music Award for Acoustic Album of the Year. (Kilde: Blues Music Awards)","2023: \"Ridin''\" reaches Top 10 of the blues charts and earns a Grammy nomination. (Kilde: Wikipedia)"],"no":["1959: Får sin første stålstrenget gitar som åtteåring. (Kilde: Wikipedia)","1969: Opptrer for Negro Ensemble Company i New York. (Kilde: Wikipedia)","1970: Flytter til Paris som 19-åring; lærer bluesgitarteknikk av Mickey Baker. (Kilde: Wikipedia)","Slår seg ned i Stockholm, og fordyper seg i før-krigs akustisk blues. (Kilde: Wikipedia)","1997: Gir ut «Good Stuff» på Opus 3/Earthbeat, hans Stockholm-æras gjennombrudd. (Kilde: Wikipedia)","2004–2011: Telarc International-årene gir «Friends», «Diamond Days», «Spirit I Am» og «Booker''s Guitar». (Kilde: Wikipedia)","2017: «The Happiest Man in the World» med Danny Thompson vinner Blues Music Award for Acoustic Album of the Year. (Kilde: Blues Music Awards)","2023: «Ridin''» når topp 10 på blueslistene og får en Grammy-nominasjon. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Acoustic steel-string guitar","note":"His core instrument since age eight; central to his acoustic-blues identity.","source":"Wikipedia"},{"category":"Vokal","name":"Vocals","note":"Warm, folk-inflected vocal style rooted in his musical-theatre and folk upbringing.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Akustisk stålstrenget gitar","note":"Hans kjerneinstrument siden åtteårsalderen; sentralt i hans akustisk-blues-identitet.","source":"Wikipedia"},{"category":"Vokal","name":"Vokal","note":"Varm, folkmusikkpreget vokalstil forankret i hans musikkteater- og folkmusikkoppvekst.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["As a child, Bibb met a young Bob Dylan, who gave him career-defining advice: \"Keep it simple, forget all that fancy stuff.\" (Kilde: Wikipedia)","Bibb''s godfather was actor, singer and civil-rights activist Paul Robeson — a connection reflecting how deeply embedded his family was in mid-century Black American cultural and political life. (Kilde: Wikipedia)","Despite being American-born and raised, Bibb has spent so much of his career based in Sweden that he is now widely regarded there as a resident artist and cultural fixture of the Swedish blues scene. (Kilde: Wikipedia)"],"no":["Som barn møtte Bibb en ung Bob Dylan, som ga ham et karrieredefinerende råd: «Hold det enkelt, glem alt det fancy.» (Kilde: Wikipedia)","Bibbs gudfar var skuespilleren, sangeren og borgerrettighetsaktivisten Paul Robeson — en forbindelse som gjenspeiler hvor dypt familien hans var forankret i det svarte amerikanske kultur- og politiske livet på midten av århundret. (Kilde: Wikipedia)","Til tross for å være amerikanskfødt og -oppvokst, har Bibb tilbrakt så mye av karrieren sin basert i Sverige at han nå er allment regnet der som en bosatt artist og kulturell fast del av den svenske bluesscenen. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Taj Mahal","note":"Longtime collaborator across multiple recordings.","source":"Wikipedia"},{"name":"Mavis & Pops Staples","note":"Featured on \"Me to You\" (Code Blue).","source":"Wikipedia"},{"name":"Danny Thompson","note":"British bassist; collaborated on \"The Happiest Man in the World\" (2016), winner of a Blues Music Award.","source":"Blues Music Awards"},{"name":"Leon Bibb","note":"His father; collaborated on \"A Family Affair\" (2002).","source":"Wikipedia"},{"name":"Charlie Musselwhite","note":"Frequent collaborator.","source":"Wikipedia"},{"name":"Guy Davis","note":"Frequent collaborator.","source":"Wikipedia"}],"no":[{"name":"Taj Mahal","note":"Mangeårig samarbeidspartner på tvers av flere innspillinger.","source":"Wikipedia"},{"name":"Mavis & Pops Staples","note":"Medvirket på «Me to You» (Code Blue).","source":"Wikipedia"},{"name":"Danny Thompson","note":"Britisk bassist; samarbeidet på «The Happiest Man in the World» (2016), vinner av en Blues Music Award.","source":"Blues Music Awards"},{"name":"Leon Bibb","note":"Hans far; samarbeidet på «A Family Affair» (2002).","source":"Wikipedia"},{"name":"Charlie Musselwhite","note":"Hyppig samarbeidspartner.","source":"Wikipedia"},{"name":"Guy Davis","note":"Hyppig samarbeidspartner.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1997,"title":"Good Stuff","producer":"—","label":"Opus 3 / Earthbeat","notes":"Stockholm-era breakthrough album.","musicians":[],"youtube_id":""},{"year":2004,"title":"Friends","producer":"—","label":"Telarc International","notes":"First of the acclaimed Telarc-era albums.","musicians":[],"youtube_id":""},{"year":2008,"title":"Spirit I Am","producer":"—","label":"Telarc International","notes":"Contains \"In My Father''s House.\"","musicians":[],"youtube_id":"G2s0vrV56M8"},{"year":2010,"title":"Booker''s Guitar","producer":"—","label":"Telarc International","notes":"A tribute to Delta blues guitarist Bukka White.","musicians":[],"youtube_id":""},{"year":2017,"title":"The Happiest Man in the World","producer":"—","label":"—","notes":"Collaboration with British bassist Danny Thompson; won Blues Music Award for Acoustic Album of the Year.","musicians":[{"name":"Danny Thompson","instrument":"Double bass"}],"youtube_id":""},{"year":2021,"title":"Dear America","producer":"—","label":"Provogue Records","notes":"Features Eric Gales and Ron Carter.","musicians":[{"name":"Eric Gales","instrument":"Guitar (guest)"},{"name":"Ron Carter","instrument":"Bass (guest)"}],"youtube_id":""},{"year":2023,"title":"Ridin''","producer":"—","label":"Provogue Records","notes":"Reached Top 10 of the blues charts; Grammy-nominated.","musicians":[],"youtube_id":""}],"no":[{"year":1997,"title":"Good Stuff","producer":"—","label":"Opus 3 / Earthbeat","notes":"Stockholm-æras gjennombruddsalbum.","musicians":[],"youtube_id":""},{"year":2004,"title":"Friends","producer":"—","label":"Telarc International","notes":"Det første av de anerkjente Telarc-æra-albumene.","musicians":[],"youtube_id":""},{"year":2008,"title":"Spirit I Am","producer":"—","label":"Telarc International","notes":"Inneholder «In My Father''s House».","musicians":[],"youtube_id":"G2s0vrV56M8"},{"year":2010,"title":"Booker''s Guitar","producer":"—","label":"Telarc International","notes":"En hyllest til Delta-bluesgitaristen Bukka White.","musicians":[],"youtube_id":""},{"year":2017,"title":"The Happiest Man in the World","producer":"—","label":"—","notes":"Samarbeid med den britiske bassisten Danny Thompson; vant Blues Music Award for Acoustic Album of the Year.","musicians":[{"name":"Danny Thompson","instrument":"Kontrabass"}],"youtube_id":""},{"year":2021,"title":"Dear America","producer":"—","label":"Provogue Records","notes":"Med Eric Gales og Ron Carter.","musicians":[{"name":"Eric Gales","instrument":"Gitar (gjest)"},{"name":"Ron Carter","instrument":"Bass (gjest)"}],"youtube_id":""},{"year":2023,"title":"Ridin''","producer":"—","label":"Provogue Records","notes":"Nådde topp 10 på blueslistene; Grammy-nominert.","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["In My Father''s House","Booker''s Guitar","Ridin''"],"no":["In My Father''s House","Booker''s Guitar","Ridin''"]}',
  influences_i18n = '{"en":["Odetta","Josh White","Bukka White","Mickey Baker"],"no":["Odetta","Josh White","Bukka White","Mickey Baker"]}',
  styles = '["Acoustic Blues","Folk Blues","Delta Blues"]',
  img = 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Eric_Bibb_%282012%29.jpg',
  image_credit = 'Photo: Nicolas Esposito (CC BY 2.0)',
  videos = '[{"kind":"featured","title":"Eric Bibb & Cyndee Peters — Lead Me, Guide Me","youtube_id":"XP-UAmkUNJo","channel":"Hans van der Linden"},{"kind":"more","title":"Eric Bibb — In My Father''s House","youtube_id":"G2s0vrV56M8","channel":"rlpes"}]',
  article_references = '[{"title":"Eric Bibb — Wikipedia","url":"https://en.wikipedia.org/wiki/Eric_Bibb"},{"title":"Eric Bibb — official website","url":"https://ericbibb.com"},{"title":"Blues Music Awards","url":"https://blues.org/"}]'
WHERE slug = 'eric-bibb';
INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'roffe-wikstrom', 'Rolf "Roffe" Wikström', NULL, 'Classic', 'Classic Era', '1970–present', 'Stockholm, Sweden', 'Stockholm, Sweden', 'Sweden', 'Nordic', 400, 'Self-taught after a childhood TV glimpse of Champion Jack Dupree, Roffe Wikström fused blues structure with Swedish poetic lyricism — including sung settings of poet Nils Ferlin — across a career still active in his seventies.', 'Selvlært etter et TV-glimt av Champion Jack Dupree i barndommen, forente Roffe Wikström bluesstruktur med svensk poetisk lyrikk — inkludert sungede tonesettinger av dikteren Nils Ferlin — gjennom en karriere fortsatt aktiv i syttiårene.');

UPDATE artists SET
  short_sv = 'Självlärd efter en tv-glimt av Champion Jack Dupree i barndomen, förenade Roffe Wikström bluesstruktur med svensk poetisk lyrik — inklusive tonsatta dikter av Nils Ferlin — genom en karriär fortfarande aktiv i sjuttioårsåldern.', short_de = 'Nach einem Kindheits-Fernsehmoment mit Champion Jack Dupree brachte sich Roffe Wikström selbst das Gitarrespiel bei und verband Blues-Struktur mit poetischer schwedischer Lyrik — inklusive vertonter Gedichte von Nils Ferlin — über eine bis in seine Siebziger aktive Karriere.', short_pl = 'Samouk po dziecięcym spotkaniu z Championem Jackiem Dupree w telewizji, Roffe Wikström połączył strukturę bluesa ze szwedzką liryką poetycką — w tym śpiewanymi wersjami wierszy Nilsa Ferlina — w karierze wciąż aktywnej w jego siedemdziesiątych latach.',
  biography_en = 'Rolf "Roffe" Wikström was born on 5 April 1949 in Stockholm and grew up in modest circumstances near Hammarby IP. His path into the blues began in 1961, when he saw pianist Champion Jack Dupree on Swedish television — a moment that sent him teaching himself guitar on borrowed instruments before he could afford his own Fenton Veil and Levin 325 (Kilde: Wikipedia).

He first gained wider recognition in Slim''s Blues Gang, led by Per "Slim" Notini, in 1971, having played guitar the year before in The Underground Failures. From 1972 to 1974 he was part of Löpande bandet, a politically engaged song collective aligned with the Swedish progg movement, before forming his own backing band, Rolf Wikströms Hjärtslag, in 1976 — the vehicle for most of his solo career from that point forward. He later played in Blue Hammer from 2002 to 2006 (Kilde: Wikipedia).

Wikström''s songwriting combined blues structures with poetic Swedish lyricism, at times setting the words of poet Nils Ferlin to music. His albums "Mitt hjärta är ditt" (1989) and "...din längtans blå anemone" (1996) were both commercially successful and drew on this Ferlin connection, work that earned him the Nils Ferlin Society''s Troubadour Prize in 1989. He continued releasing new material well into his seventies, with "Ballader och bröl" appearing in 2021 (Kilde: Wikipedia).

Alongside his music career, Wikström completed a bachelor''s degree in cultural geography, economics and economic history. His body of work has been recognized with the City of Stockholm''s Bellman Prize (1995), the Cornelis Vreeswijk Scholarship (2015), and the Guitarpeoples Prize (2018) — honors that reflect his standing as one of the elder statesmen of Swedish blues-rooted songwriting (Kilde: Wikipedia).', biography_no = 'Rolf «Roffe» Wikström ble født 5. april 1949 i Stockholm og vokste opp under beskjedne kår nær Hammarby IP. Veien hans inn i bluesen begynte i 1961, da han så pianisten Champion Jack Dupree på svensk fjernsyn — et øyeblikk som fikk ham til å lære seg selv gitar på lånte instrumenter før han hadde råd til sine egne, en Fenton Veil og en Levin 325 (Kilde: Wikipedia).

Han fikk først bredere anerkjennelse i Slim''s Blues Gang, ledet av Per «Slim» Notini, i 1971, etter å ha spilt gitar året før i The Underground Failures. Fra 1972 til 1974 var han del av Löpande bandet, et politisk engasjert sangkollektiv tilknyttet den svenske progg-bevegelsen, før han dannet sitt eget backingband, Rolf Wikströms Hjärtslag, i 1976 — kjøretøyet for det meste av solokarrieren hans fra det tidspunktet. Han spilte senere i Blue Hammer fra 2002 til 2006 (Kilde: Wikipedia).

Wikströms låtskriving kombinerte bluesstrukturer med poetisk svensk lyrikk, og satte til tider dikteren Nils Ferlins ord til musikk. Albumene hans «Mitt hjärta är ditt» (1989) og «...din längtans blå anemone» (1996) var begge kommersielt vellykkede og bygde på denne Ferlin-forbindelsen, et arbeid som ga ham Nils Ferlin-sällskapets Trubadurpris i 1989. Han fortsatte å gi ut nytt materiale langt inn i syttiårene, med «Ballader och bröl» i 2021 (Kilde: Wikipedia).

Ved siden av musikkarrieren fullførte Wikström en bachelorgrad i kulturgeografi, økonomi og økonomisk historie. Verkene hans er blitt anerkjent med Stockholm bys Bellmanpris (1995), Cornelis Vreeswijk-stipendet (2015), og Guitarpeoples-prisen (2018) — hedersbevisninger som gjenspeiler hans status som en av de eldste statsmennene innen svensk bluesforankret låtskriving (Kilde: Wikipedia).', biography_sv = 'Rolf "Roffe" Wikström föddes den 5 april 1949 i Stockholm och växte upp under blygsamma förhållanden nära Hammarby IP. Hans väg in i bluesen började 1961, då han såg pianisten Champion Jack Dupree i svensk tv — ett ögonblick som fick honom att lära sig gitarr på lånade instrument innan han hade råd med egna, en Fenton Veil och en Levin 325 (Källa: Wikipedia).

Han fick först bredare erkännande i Slim''s Blues Gang, ledd av Per "Slim" Notini, 1971, efter att ha spelat gitarr året innan i The Underground Failures. Från 1972 till 1974 var han del av Löpande bandet, ett politiskt engagerat sångkollektiv kopplat till den svenska proggrörelsen, innan han bildade sitt eget backingband, Rolf Wikströms Hjärtslag, 1976 — fordonet för det mesta av hans solokarriär från den punkten. Han spelade senare i Blue Hammer från 2002 till 2006 (Källa: Wikipedia).

Wikströms låtskrivande kombinerade bluesstrukturer med poetisk svensk lyrik, och tonsatte ibland poeten Nils Ferlins ord. Hans album "Mitt hjärta är ditt" (1989) och "...din längtans blå anemone" (1996) var båda kommersiellt framgångsrika och byggde på denna Ferlin-koppling, ett arbete som gav honom Nils Ferlin-sällskapets Trubadurpris 1989. Han fortsatte att ge ut nytt material långt in i sjuttioårsåldern, med "Ballader och bröl" 2021 (Källa: Wikipedia).

Vid sidan av musikkarriären avslutade Wikström en filosofie kandidatexamen i kulturgeografi, nationalekonomi och ekonomisk historia. Hans verk har hyllats med Stockholms stads Bellmanpris (1995), Cornelis Vreeswijk-stipendiet (2015), och Guitarpeoples pris (2018) — utmärkelser som speglar hans ställning som en av de äldre statsmännen inom svenskt bluesförankrat låtskrivande (Källa: Wikipedia).', biography_de = 'Rolf "Roffe" Wikström wurde am 5. April 1949 in Stockholm geboren und wuchs unter bescheidenen Verhältnissen in der Nähe von Hammarby IP auf. Sein Weg in den Blues begann 1961, als er den Pianisten Champion Jack Dupree im schwedischen Fernsehen sah — ein Moment, der ihn dazu brachte, sich das Gitarrespiel auf geliehenen Instrumenten selbst beizubringen, bevor er sich seine eigenen leisten konnte, eine Fenton Veil und eine Levin 325 (Quelle: Wikipedia).

Breitere Anerkennung erlangte er zunächst 1971 in Slim''s Blues Gang, geleitet von Per "Slim" Notini, nachdem er im Jahr zuvor Gitarre bei The Underground Failures gespielt hatte. Von 1972 bis 1974 war er Teil von Löpande bandet, einem politisch engagierten Liederkollektiv, das mit der schwedischen Progg-Bewegung verbunden war, bevor er 1976 seine eigene Begleitband, Rolf Wikströms Hjärtslag, gründete — das Vehikel für den Großteil seiner Solokarriere ab diesem Zeitpunkt. Später spielte er von 2002 bis 2006 bei Blue Hammer (Quelle: Wikipedia).

Wikströms Songwriting verband Blues-Strukturen mit poetischer schwedischer Lyrik und vertonte gelegentlich die Worte des Dichters Nils Ferlin. Seine Alben "Mitt hjärta är ditt" (1989) und "...din längtans blå anemone" (1996) waren beide kommerziell erfolgreich und bauten auf dieser Ferlin-Verbindung auf, eine Arbeit, die ihm 1989 den Troubadour-Preis der Nils-Ferlin-Gesellschaft einbrachte. Er veröffentlichte bis weit in seine Siebziger hinein weiterhin neues Material, mit "Ballader och bröl" im Jahr 2021 (Quelle: Wikipedia).

Neben seiner Musikkarriere absolvierte Wikström einen Bachelorabschluss in Kulturgeographie, Volkswirtschaftslehre und Wirtschaftsgeschichte. Sein Werk wurde mit dem Bellman-Preis der Stadt Stockholm (1995), dem Cornelis-Vreeswijk-Stipendium (2015) und dem Guitarpeoples-Preis (2018) gewürdigt — Auszeichnungen, die seinen Status als einer der Grandseigneurs des schwedischen bluesverwurzelten Songwritings widerspiegeln (Quelle: Wikipedia).', biography_pl = 'Rolf "Roffe" Wikström urodził się 5 kwietnia 1949 roku w Sztokholmie i dorastał w skromnych warunkach w pobliżu Hammarby IP. Jego droga do bluesa rozpoczęła się w 1961 roku, gdy zobaczył pianistę Championa Jacka Dupree w szwedzkiej telewizji — moment, który skłonił go do samodzielnej nauki gry na pożyczonych instrumentach, zanim było go stać na własne, Fenton Veil i Levin 325 (Źródło: Wikipedia).

Szersze uznanie zdobył najpierw w Slim''s Blues Gang, prowadzonym przez Pera "Slima" Notiniego, w 1971 roku, po tym jak rok wcześniej grał na gitarze w The Underground Failures. Od 1972 do 1974 roku był częścią Löpande bandet, zaangażowanego politycznie kolektywu pieśniowego związanego ze szwedzkim ruchem progg, zanim w 1976 roku założył własny zespół akompaniujący, Rolf Wikströms Hjärtslag — narzędzie dla większości jego kariery solowej od tego momentu. Później grał w Blue Hammer w latach 2002–2006 (Źródło: Wikipedia).

Twórczość Wikströma łączyła struktury bluesowe z poetycką szwedzką liryką, czasami nadając muzykę słowom poety Nilsa Ferlina. Jego albumy "Mitt hjärta är ditt" (1989) i "...din längtans blå anemone" (1996) odniosły sukces komercyjny i czerpały z tego związku z Ferlinem, co przyniosło mu Nagrodę Trubadura Towarzystwa Nilsa Ferlina w 1989 roku. Nadal wydawał nowy materiał daleko w swoich siedemdziesiątych latach życia, z albumem "Ballader och bröl" w 2021 roku (Źródło: Wikipedia).

Oprócz kariery muzycznej, Wikström ukończył studia licencjackie z geografii kulturowej, ekonomii i historii gospodarczej. Jego dorobek został uhonorowany Nagrodą Bellmana miasta Sztokholm (1995), Stypendium im. Cornelisa Vreeswijka (2015) oraz Nagrodą Guitarpeoples (2018) — wyróżnieniami odzwierciedlającymi jego pozycję jednego ze starszych statystów szwedzkiej twórczości zakorzenionej w bluesie (Źródło: Wikipedia).',
  influence_en = 'Wikström is one of the few artists to fuse American blues form with the Swedish literary song tradition, giving the poetry of Nils Ferlin a bluesy musical voice and helping establish a distinctly Swedish idiom within blues-rooted songwriting. (Kilde: Wikipedia)', influence_no = 'Wikström er en av få artister som har forent amerikansk bluesform med den svenske litterære sangtradisjonen, og gitt Nils Ferlins poesi en blueset musikalsk stemme, og har bidratt til å etablere et distinkt svensk formspråk innen bluesforankret låtskriving. (Kilde: Wikipedia)', influence_sv = 'Wikström är en av få artister som har förenat amerikansk bluesform med den svenska litterära sångtraditionen, och gett Nils Ferlins poesi en blues-präglad musikalisk röst, och bidragit till att etablera ett distinkt svenskt formspråk inom bluesförankrat låtskrivande. (Källa: Wikipedia)', influence_de = 'Wikström ist einer der wenigen Künstler, die amerikanische Blues-Form mit der schwedischen literarischen Liedtradition verschmolzen haben, wodurch der Poesie von Nils Ferlin eine bluesige musikalische Stimme verliehen wurde und ein unverwechselbar schwedisches Idiom innerhalb des blues-verwurzelten Songwritings entstand. (Quelle: Wikipedia)', influence_pl = 'Wikström jest jednym z niewielu artystów, którzy połączyli amerykańską formę bluesa ze szwedzką tradycją pieśni literackiej, nadając poezji Nilsa Ferlina bluesowy głos muzyczny i pomagając ustanowić wyraźnie szwedzki idiom w twórczości zakorzenionej w bluesie. (Źródło: Wikipedia)',
  formative_i18n = '{"en":["1961: Sees pianist Champion Jack Dupree on Swedish television, sparking his interest in blues. (Kilde: Wikipedia)","1970: Plays guitar in The Underground Failures. (Kilde: Wikipedia)","1971: Gains wider recognition in Slim''s Blues Gang, led by Per \"Slim\" Notini. (Kilde: Wikipedia)","1972–1974: Member of the politically engaged Löpande bandet. (Kilde: Wikipedia)","1976: Forms his own backing band, Rolf Wikströms Hjärtslag. (Kilde: Wikipedia)","1989: \"Mitt hjärta är ditt\" is released and wins him the Nils Ferlin Society''s Troubadour Prize. (Kilde: Wikipedia)","2021: Releases \"Ballader och bröl.\" (Kilde: Wikipedia)"],"no":["1961: Ser pianisten Champion Jack Dupree på svensk fjernsyn, noe som tenner interessen for blues. (Kilde: Wikipedia)","1970: Spiller gitar i The Underground Failures. (Kilde: Wikipedia)","1971: Får bredere anerkjennelse i Slim''s Blues Gang, ledet av Per «Slim» Notini. (Kilde: Wikipedia)","1972–1974: Medlem av det politisk engasjerte Löpande bandet. (Kilde: Wikipedia)","1976: Danner sitt eget backingband, Rolf Wikströms Hjärtslag. (Kilde: Wikipedia)","1989: «Mitt hjärta är ditt» gis ut og gir ham Nils Ferlin-sällskapets Trubadurpris. (Kilde: Wikipedia)","2021: Gir ut «Ballader och bröl». (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Guitar","note":"Self-taught, initially on borrowed instruments; later owned a Fenton Veil and a Levin 325.","source":"Wikipedia"},{"category":"Vokal","name":"Vocals","note":"Distinctive Swedish-language blues vocal style, often setting poetry to music.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Gitar","note":"Selvlært, først på lånte instrumenter; eide senere en Fenton Veil og en Levin 325.","source":"Wikipedia"},{"category":"Vokal","name":"Vokal","note":"Særegen svenskspråklig bluesvokalstil, og satte ofte poesi til musikk.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Wikström''s entire path into music traces back to a single 1961 Swedish TV appearance by American blues pianist Champion Jack Dupree. (Kilde: Wikipedia)","Unable to afford his own guitar as a young man, Wikström taught himself to play on borrowed instruments before eventually acquiring a Fenton Veil and a Levin 325. (Kilde: Wikipedia)","Alongside his music career, Wikström completed a full university degree in cultural geography, economics and economic history — an unusually academic parallel path for a blues songwriter. (Kilde: Wikipedia)"],"no":["Wikströms hele vei inn i musikken kan spores tilbake til én enkelt TV-opptreden i 1961 av den amerikanske bluespianisten Champion Jack Dupree. (Kilde: Wikipedia)","Uten råd til sin egen gitar som ung mann, lærte Wikström seg selv å spille på lånte instrumenter før han til slutt fikk en Fenton Veil og en Levin 325. (Kilde: Wikipedia)","Ved siden av musikkarrieren fullførte Wikström en fullstendig universitetsgrad i kulturgeografi, økonomi og økonomisk historie — en uvanlig akademisk parallell vei for en blueslåtskriver. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Per \"Slim\" Notini","note":"Bandleader of Slim''s Blues Gang, where Wikström first gained recognition.","source":"Wikipedia"},{"name":"Rolf Wikströms Hjärtslag","note":"His own backing band, formed 1976, vehicle for most of his solo career.","source":"Wikipedia"},{"name":"Nils Ferlin (poet)","note":"Wikström set several of Ferlin''s poems to music.","source":"Wikipedia"}],"no":[{"name":"Per «Slim» Notini","note":"Bandleder for Slim''s Blues Gang, hvor Wikström først fikk anerkjennelse.","source":"Wikipedia"},{"name":"Rolf Wikströms Hjärtslag","note":"Hans eget backingband, dannet 1976, kjøretøy for det meste av solokarrieren.","source":"Wikipedia"},{"name":"Nils Ferlin (dikter)","note":"Wikström satte flere av Ferlins dikt til musikk.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1975,"title":"Sjung Svenska Folk","producer":"—","label":"—","notes":"Early solo album.","musicians":[],"youtube_id":""},{"year":1989,"title":"Mitt Hjärta Är Ditt","producer":"—","label":"MNW","notes":"Commercially successful album drawing on Nils Ferlin''s poetry; won the Nils Ferlin Society''s Troubadour Prize.","musicians":[],"youtube_id":"XX84RJ_hoRk"},{"year":1990,"title":"Himlen Är Blå","producer":"—","label":"MNW","notes":"Follow-up to \"Mitt Hjärta Är Ditt.\"","musicians":[],"youtube_id":""},{"year":1996,"title":"...din längtans blå anemone","producer":"—","label":"—","notes":"Second major Nils Ferlin-influenced album.","musicians":[],"youtube_id":""},{"year":2021,"title":"Ballader och bröl","producer":"—","label":"—","notes":"Late-career album, released when Wikström was 72.","musicians":[],"youtube_id":""}],"no":[{"year":1975,"title":"Sjung Svenska Folk","producer":"—","label":"—","notes":"Tidlig soloalbum.","musicians":[],"youtube_id":""},{"year":1989,"title":"Mitt Hjärta Är Ditt","producer":"—","label":"MNW","notes":"Kommersielt vellykket album som bygger på Nils Ferlins poesi; vant Nils Ferlin-sällskapets Trubadurpris.","musicians":[],"youtube_id":"XX84RJ_hoRk"},{"year":1990,"title":"Himlen Är Blå","producer":"—","label":"MNW","notes":"Oppfølger til «Mitt Hjärta Är Ditt».","musicians":[],"youtube_id":""},{"year":1996,"title":"...din längtans blå anemone","producer":"—","label":"—","notes":"Andre store Nils Ferlin-inspirerte album.","musicians":[],"youtube_id":""},{"year":2021,"title":"Ballader och bröl","producer":"—","label":"—","notes":"Sent karrierealbum, utgitt da Wikström var 72 år.","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["Mitt hjärta är ditt","Himlen är blå"],"no":["Mitt hjärta är ditt","Himlen är blå"]}',
  influences_i18n = '{"en":["Champion Jack Dupree","Nils Ferlin (poetry)"],"no":["Champion Jack Dupree","Nils Ferlin (poesi)"]}',
  styles = '["Nordic Blues","Blues Rock","Visa/Songwriter"]',
  img = 'https://upload.wikimedia.org/wikipedia/commons/d/dc/Roffe_Wikstrom_2004.jpg',
  image_credit = 'Photo: Sune Frack (CC BY-SA 2.0)',
  videos = '[{"kind":"featured","title":"Rolf Wikström — Mitt Hjärta Är Ditt","youtube_id":"XX84RJ_hoRk","channel":"tjavo2"}]',
  article_references = '[{"title":"Rolf Wikström — svensk Wikipedia","url":"https://sv.wikipedia.org/wiki/Roffe_Wikstr%C3%B6m"},{"title":"Nils Ferlin-sällskapet","url":"https://www.nilsferlin.se/"}]'
WHERE slug = 'roffe-wikstrom';
INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'sven-zetterberg', 'Sven Zetterberg', NULL, 'Classic', 'Classic Era', '1970s–2016', 'Skärblacka, Sweden', 'Skärblacka, Sweden', 'Sweden', 'Nordic', 400, '"The Swedish blues professor" — a Chicago Express bandleader who toured with Jimmy Rogers, Luther Allison and Eddie Boyd, and built a soul-inflected solo catalog until his death in 2016, with one final album released posthumously in 2022.', '«Den svenske bluesprofessoren» — en Chicago Express-bandleder som turnerte med Jimmy Rogers, Luther Allison og Eddie Boyd, og bygde en soulpreget solokatalog frem til sin død i 2016, med et siste album utgitt posthumt i 2022.');

UPDATE artists SET
  short_sv = '"Den svenska bluesprofessorn" — en Chicago Express-bandledare som turnerade med Jimmy Rogers, Luther Allison och Eddie Boyd, och byggde en soulpräglad solokatalog fram till sin död 2016, med ett sista album utgivet postumt 2022.', short_de = '"Der schwedische Blues-Professor" — ein Chicago-Express-Bandleader, der mit Jimmy Rogers, Luther Allison und Eddie Boyd tourte und bis zu seinem Tod 2016 einen soul-geprägten Solokatalog aufbaute, mit einem letzten, 2022 posthum veröffentlichten Album.', short_pl = '"Szwedzki profesor bluesa" — lider Chicago Express, który koncertował z Jimmym Rogersem, Lutherem Allisonem i Eddiem Boydem, budując przesiąknięty soulem katalog solowy aż do swojej śmierci w 2016 roku, z ostatnim albumem wydanym pośmiertnie w 2022 roku.',
  biography_en = 'Sven Zetterberg was born on 28 March 1952 in Skärblacka, Östergötland, and became one of Sweden''s most respected blues and soul vocalists, guitarists and songwriters across four decades of steady, unglamorous dedication to the form. His career began in bands like Telge Blues and Blues Rockers before he co-founded Blue Fire and Four Roosters, and then, from 1981 to 1996, led Chicago Express, the band most associated with his name (Kilde: Wikipedia).

Zetterberg earned genuine credibility touring alongside American blues royalty, sharing stages and billing with Jimmy Rogers, Jimmy McCracklin, Louisiana Red, Luther Allison and Eddie Boyd — direct contact with the Chicago blues tradition that shaped his own guitar and vocal phrasing. In 1989 he received the Cornelis Vreeswijk Scholarship, formal Swedish recognition of his songwriting (Kilde: Wikipedia).

As a solo artist he released a steady stream of acclaimed albums, including "Blues from Within" (1999), "Horton''s Briefcase" (2000), "Let Me Get Over It" (2001), "Moving in the Right Direction" (2004), "Southern Soul Agenda" (2006), "Hollerin'' Up a Storm" (2007) and "Swings and Roundabouts" (2008), building a catalog that moved fluidly between blues and deep soul (Kilde: Wikipedia; Discogs).

Zetterberg died on 21 December 2016 in Stockholm at the age of 64. His final album, "Rain On, The Lost Session," was released posthumously in 2022, a last testament from an artist Swedish blues fans still refer to as "the Swedish blues professor" (Kilde: Wikipedia).', biography_no = 'Sven Zetterberg ble født 28. mars 1952 i Skärblacka, Östergötland, og ble en av Sveriges mest respekterte blues- og soulvokalister, gitarister og låtskrivere gjennom fire tiår med jevn, ustrålende dedikasjon til sjangeren. Karrieren hans begynte i band som Telge Blues og Blues Rockers før han var med å danne Blue Fire og Four Roosters, og deretter, fra 1981 til 1996, ledet Chicago Express, bandet mest forbundet med navnet hans (Kilde: Wikipedia).

Zetterberg opparbeidet seg genuin troverdighet ved å turnere sammen med amerikansk blues-adel, og delte scene og plakat med Jimmy Rogers, Jimmy McCracklin, Louisiana Red, Luther Allison og Eddie Boyd — direkte kontakt med Chicago-blues-tradisjonen som formet hans egen gitar- og vokalfrasering. I 1989 mottok han Cornelis Vreeswijk-stipendet, formell svensk anerkjennelse av låtskrivingen hans (Kilde: Wikipedia).

Som soloartist ga han ut en jevn strøm av anerkjente album, inkludert «Blues from Within» (1999), «Horton''s Briefcase» (2000), «Let Me Get Over It» (2001), «Moving in the Right Direction» (2004), «Southern Soul Agenda» (2006), «Hollerin'' Up a Storm» (2007) og «Swings and Roundabouts» (2008), og bygde en katalog som beveget seg smidig mellom blues og dyp soul (Kilde: Wikipedia; Discogs).

Zetterberg døde 21. desember 2016 i Stockholm, 64 år gammel. Hans siste album, «Rain On, The Lost Session», ble utgitt posthumt i 2022, et siste testamente fra en artist svenske blueselskere fortsatt kaller «den svenske bluesprofessoren» (Kilde: Wikipedia).', biography_sv = 'Sven Zetterberg föddes den 28 mars 1952 i Skärblacka, Östergötland, och blev en av Sveriges mest respekterade blues- och soulvokalister, gitarrister och låtskrivare genom fyra decennier av jämn, oglamorös hängivenhet åt genren. Hans karriär började i band som Telge Blues och Blues Rockers innan han var med och bildade Blue Fire och Four Roosters, och sedan, från 1981 till 1996, ledde Chicago Express, bandet mest förknippat med hans namn (Källa: Wikipedia).

Zetterberg vann genuin trovärdighet genom att turnera tillsammans med amerikansk blues-adel, och delade scen och affischer med Jimmy Rogers, Jimmy McCracklin, Louisiana Red, Luther Allison och Eddie Boyd — direkt kontakt med Chicago-bluestraditionen som formade hans egen gitarr- och vokalfrasering. 1989 fick han Cornelis Vreeswijk-stipendiet, formellt svenskt erkännande av hans låtskrivande (Källa: Wikipedia).

Som soloartist gav han ut en jämn ström av hyllade album, inklusive "Blues from Within" (1999), "Horton''s Briefcase" (2000), "Let Me Get Over It" (2001), "Moving in the Right Direction" (2004), "Southern Soul Agenda" (2006), "Hollerin'' Up a Storm" (2007) och "Swings and Roundabouts" (2008), och byggde en katalog som rörde sig smidigt mellan blues och djup soul (Källa: Wikipedia; Discogs).

Zetterberg dog den 21 december 2016 i Stockholm, 64 år gammal. Hans sista album, "Rain On, The Lost Session", gavs ut postumt 2022, ett sista testamente från en artist svenska bluesälskare fortfarande kallar "den svenska bluesprofessorn" (Källa: Wikipedia).', biography_de = 'Sven Zetterberg wurde am 28. März 1952 in Skärblacka, Östergötland, geboren und wurde zu einem der angesehensten Blues- und Soul-Sänger, Gitarristen und Songwriter Schwedens, über vier Jahrzehnte stetiger, unprätentiöser Hingabe an das Genre. Seine Karriere begann in Bands wie Telge Blues und Blues Rockers, bevor er Blue Fire und Four Roosters mitbegründete und dann von 1981 bis 1996 Chicago Express leitete, die Band, die am meisten mit seinem Namen verbunden ist (Quelle: Wikipedia).

Zetterberg erwarb sich echte Glaubwürdigkeit, indem er zusammen mit amerikanischer Blues-Prominenz tourte und sich Bühne und Plakat mit Jimmy Rogers, Jimmy McCracklin, Louisiana Red, Luther Allison und Eddie Boyd teilte — direkter Kontakt zur Chicago-Blues-Tradition, die seine eigene Gitarren- und Gesangsphrasierung prägte. 1989 erhielt er das Cornelis-Vreeswijk-Stipendium, die formelle schwedische Anerkennung seines Songwritings (Quelle: Wikipedia).

Als Solokünstler veröffentlichte er einen stetigen Strom gefeierter Alben, darunter "Blues from Within" (1999), "Horton''s Briefcase" (2000), "Let Me Get Over It" (2001), "Moving in the Right Direction" (2004), "Southern Soul Agenda" (2006), "Hollerin'' Up a Storm" (2007) und "Swings and Roundabouts" (2008), und baute einen Katalog auf, der sich flüssig zwischen Blues und tiefem Soul bewegte (Quelle: Wikipedia; Discogs).

Zetterberg starb am 21. Dezember 2016 im Alter von 64 Jahren in Stockholm. Sein letztes Album, "Rain On, The Lost Session", wurde 2022 posthum veröffentlicht, ein letztes Vermächtnis eines Künstlers, den schwedische Blues-Fans noch immer "den schwedischen Blues-Professor" nennen (Quelle: Wikipedia).', biography_pl = 'Sven Zetterberg urodził się 28 marca 1952 roku w Skärblace, w regionie Östergötland, i stał się jednym z najbardziej szanowanych szwedzkich wokalistów, gitarzystów i autorów piosenek bluesowych i soulowych, przez cztery dekady niewzruszonego poświęcenia dla tego gatunku. Jego kariera rozpoczęła się w zespołach takich jak Telge Blues i Blues Rockers, zanim współzałożył Blue Fire i Four Roosters, a następnie, od 1981 do 1996 roku, prowadził Chicago Express, zespół najbardziej kojarzony z jego nazwiskiem (Źródło: Wikipedia).

Zetterberg zdobył prawdziwą wiarygodność, koncertując wraz z amerykańską arystokracją bluesa, dzieląc scenę i afisze z Jimmym Rogersem, Jimmym McCracklinem, Louisiana Redem, Lutherem Allisonem i Eddiem Boydem — bezpośredni kontakt z tradycją chicagowskiego bluesa, który ukształtował jego własną frazę gitarową i wokalną. W 1989 roku otrzymał Stypendium im. Cornelisa Vreeswijka, formalne szwedzkie uznanie dla jego twórczości (Źródło: Wikipedia).

Jako artysta solowy wydał stały strumień cenionych albumów, w tym "Blues from Within" (1999), "Horton''s Briefcase" (2000), "Let Me Get Over It" (2001), "Moving in the Right Direction" (2004), "Southern Soul Agenda" (2006), "Hollerin'' Up a Storm" (2007) i "Swings and Roundabouts" (2008), budując katalog płynnie poruszający się między bluesem a głębokim soulem (Źródło: Wikipedia; Discogs).

Zetterberg zmarł 21 grudnia 2016 roku w Sztokholmie w wieku 64 lat. Jego ostatni album, "Rain On, The Lost Session", został wydany pośmiertnie w 2022 roku, ostatni testament artysty, którego szwedzcy fani bluesa nadal nazywają "szwedzkim profesorem bluesa" (Źródło: Wikipedia).',
  influence_en = 'Zetterberg''s decades of direct touring experience alongside first-generation Chicago blues musicians gave his own Swedish blues and soul recordings an authenticity that made him a reference point for the country''s blues scene until his death. (Kilde: Wikipedia)', influence_no = 'Zetterbergs tiår med direkte turneerfaring sammen med første generasjons Chicago-bluesmusikere ga hans egne svenske blues- og soulinnspillinger en autentisitet som gjorde ham til et referansepunkt for landets bluesscene frem til hans død. (Kilde: Wikipedia)', influence_sv = 'Zetterbergs decennier av direkt turnéerfarenhet tillsammans med första generationens Chicago-bluesmusiker gav hans egna svenska blues- och soulinspelningar en autenticitet som gjorde honom till en referenspunkt för landets bluesscen fram till hans död. (Källa: Wikipedia)', influence_de = 'Zetterbergs jahrzehntelange direkte Tourerfahrung an der Seite von Chicago-Bluesmusikern der ersten Generation verlieh seinen eigenen schwedischen Blues- und Soul-Aufnahmen eine Authentizität, die ihn bis zu seinem Tod zu einem Bezugspunkt für die Blues-Szene des Landes machte. (Quelle: Wikipedia)', influence_pl = 'Dekady bezpośredniego doświadczenia koncertowego Zetterberga u boku muzyków chicagowskiego bluesa pierwszej generacji nadały jego własnym szwedzkim nagraniom bluesowym i soulowym autentyczność, która uczyniła go punktem odniesienia dla krajowej sceny bluesowej aż do jego śmierci. (Źródło: Wikipedia)',
  formative_i18n = '{"en":["Early career in Telge Blues and Blues Rockers. (Kilde: Wikipedia)","Co-founds Blue Fire and Four Roosters. (Kilde: Wikipedia)","1981–1996: Leads Chicago Express, his best-known band. (Kilde: Wikipedia)","1989: Receives the Cornelis Vreeswijk Scholarship. (Kilde: Wikipedia)","1999: Releases solo album \"Blues from Within.\" (Kilde: Wikipedia)","2016: Dies on 21 December in Stockholm, aged 64. (Kilde: Wikipedia)","2022: \"Rain On, The Lost Session\" released posthumously. (Kilde: Wikipedia)"],"no":["Tidlig karriere i Telge Blues og Blues Rockers. (Kilde: Wikipedia)","Er med å danne Blue Fire og Four Roosters. (Kilde: Wikipedia)","1981–1996: Leder Chicago Express, hans mest kjente band. (Kilde: Wikipedia)","1989: Mottar Cornelis Vreeswijk-stipendet. (Kilde: Wikipedia)","1999: Gir ut soloalbumet «Blues from Within». (Kilde: Wikipedia)","2016: Dør 21. desember i Stockholm, 64 år gammel. (Kilde: Wikipedia)","2022: «Rain On, The Lost Session» utgis posthumt. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Vokal","name":"Vocals","note":"Central instrument; soul-inflected blues vocal style.","source":"Wikipedia"},{"category":"Gitar","name":"Guitar","note":"Core instrument across all his bands and solo work.","source":"Wikipedia"}],"no":[{"category":"Vokal","name":"Vokal","note":"Sentralt instrument; soulpreget bluesvokalstil.","source":"Wikipedia"},{"category":"Gitar","name":"Gitar","note":"Kjerneinstrument gjennom alle hans band og soloarbeid.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Zetterberg toured and shared bills directly with Chicago blues legends Jimmy Rogers (Muddy Waters'' former guitarist) and Eddie Boyd, giving him a rare direct lineage to the genre''s first generation. (Kilde: Wikipedia)","Swedish blues fans nicknamed him \"the Swedish blues professor,\" a title reflecting both his musical authority and his decades of consistent, unshowy dedication to the genre. (Kilde: Wikipedia)","His final album, \"Rain On, The Lost Session,\" was assembled and released six years after his death, from recordings made before he passed. (Kilde: Wikipedia)"],"no":["Zetterberg turnerte og delte plakat direkte med Chicago-bluselegendene Jimmy Rogers (Muddy Waters'' tidligere gitarist) og Eddie Boyd, noe som ga ham en sjelden direkte linje til sjangerens første generasjon. (Kilde: Wikipedia)","Svenske blueselskere ga ham kallenavnet «den svenske bluesprofessoren», en tittel som gjenspeiler både hans musikalske autoritet og hans tiår med jevn, ustrålende dedikasjon til sjangeren. (Kilde: Wikipedia)","Hans siste album, «Rain On, The Lost Session», ble satt sammen og utgitt seks år etter hans død, fra opptak gjort før han gikk bort. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Jimmy Rogers","note":"Toured together; Rogers was Muddy Waters'' longtime guitarist.","source":"Wikipedia"},{"name":"Luther Allison","note":"Toured together.","source":"Wikipedia"},{"name":"Eddie Boyd","note":"Toured together.","source":"Wikipedia"},{"name":"Chicago Express","note":"His main band, 1981–1996.","source":"Wikipedia"}],"no":[{"name":"Jimmy Rogers","note":"Turnerte sammen; Rogers var Muddy Waters'' mangeårige gitarist.","source":"Wikipedia"},{"name":"Luther Allison","note":"Turnerte sammen.","source":"Wikipedia"},{"name":"Eddie Boyd","note":"Turnerte sammen.","source":"Wikipedia"},{"name":"Chicago Express","note":"Hans hovedband, 1981–1996.","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1983,"title":"Bluesmeeting In Chicago","producer":"—","label":"—","notes":"Recorded with Chicago blues musicians.","musicians":[],"youtube_id":""},{"year":1999,"title":"Blues From Within","producer":"—","label":"—","notes":"Solo album.","musicians":[],"youtube_id":""},{"year":2004,"title":"Moving In The Right Direction","producer":"—","label":"Last Buzz Record Co","notes":"Solo album.","musicians":[],"youtube_id":""},{"year":2006,"title":"Southern Soul Agenda","producer":"—","label":"Borderline Records","notes":"Deep-soul-leaning solo album.","musicians":[],"youtube_id":""},{"year":2022,"title":"Rain On, The Lost Session","producer":"—","label":"—","notes":"Posthumous release, six years after his death.","musicians":[],"youtube_id":""}],"no":[{"year":1983,"title":"Bluesmeeting In Chicago","producer":"—","label":"—","notes":"Spilt inn med Chicago-bluesmusikere.","musicians":[],"youtube_id":""},{"year":1999,"title":"Blues From Within","producer":"—","label":"—","notes":"Soloalbum.","musicians":[],"youtube_id":""},{"year":2004,"title":"Moving In The Right Direction","producer":"—","label":"Last Buzz Record Co","notes":"Soloalbum.","musicians":[],"youtube_id":""},{"year":2006,"title":"Southern Soul Agenda","producer":"—","label":"Borderline Records","notes":"Dyp-soul-preget soloalbum.","musicians":[],"youtube_id":""},{"year":2022,"title":"Rain On, The Lost Session","producer":"—","label":"—","notes":"Posthum utgivelse, seks år etter hans død.","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["Blues From Within","Southern Soul Agenda"],"no":["Blues From Within","Southern Soul Agenda"]}',
  influences_i18n = '{"en":["Jimmy Rogers","Eddie Boyd","Chicago blues"],"no":["Jimmy Rogers","Eddie Boyd","Chicago-blues"]}',
  styles = '["Nordic Blues","Soul","Chicago Blues"]',
  img = 'https://upload.wikimedia.org/wikipedia/commons/1/1e/Sven_Zetterberg_2012.jpg',
  image_credit = 'Photo: Bengt Nyman (CC BY-SA 3.0)',
  videos = '[{"kind":"featured","title":"Sven Zetterberg Blues Band","youtube_id":"VzCj5qerrhA","channel":"Apassi AV"},{"kind":"more","title":"Sven Zetterberg — minneomtale (1952–2016)","youtube_id":"e4c5Qukprsc","channel":"MaBeL \"AllILike\""},{"kind":"more","title":"Sven Zetterberg live at pub Kuntze, Malmö (2015)","youtube_id":"Yq35F3aKYNY","channel":"fluand5910"}]',
  article_references = '[{"title":"Sven Zetterberg — svensk Wikipedia","url":"https://sv.wikipedia.org/wiki/Sven_Zetterberg"},{"title":"Discogs — Sven Zetterberg","url":"https://www.discogs.com/artist/894928-Sven-Zetterberg"}]'
WHERE slug = 'sven-zetterberg';
INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'trickbag', 'Trickbag', NULL, 'Modern', 'Modern Era', '1990s–present', 'Sweden', 'Sweden', 'Sweden', 'Nordic', 700, '"Sweden''s largest blues export" — over 30 years of raw, swinging Delta-rooted houserockin'' rhythm & blues, from 1999''s "Just Passing Through" to the 30th-anniversary "The Collection" (2024).', '«Sveriges største blueseksport» — over 30 år med rå, svingende Delta-forankret houserockin'' rhythm & blues, fra 1999s «Just Passing Through» til 30-årsjubileumsalbumet «The Collection» (2024).');

UPDATE artists SET
  short_sv = '"Sveriges största blues-export" — över 30 år av rå, swingig Delta-förankrad houserockin'' rhythm & blues, från 1999 års "Just Passing Through" till 30-årsjubileumsalbumet "The Collection" (2024).', short_de = '"Schwedens größter Blues-Export" — über 30 Jahre roher, swingender, im Delta verwurzelter Houserockin'' Rhythm & Blues, von "Just Passing Through" (1999) bis zum 30-jährigen Jubiläumsalbum "The Collection" (2024).', short_pl = '"Największy szwedzki eksport bluesa" — ponad 30 lat surowego, swingującego rhythm & bluesa zakorzenionego w Delcie, od "Just Passing Through" z 1999 roku po album z okazji 30-lecia "The Collection" (2024).',
  biography_en = 'Formed in the early 1990s, Trickbag has spent over thirty years earning its reputation as one of Sweden''s most active blues bands — and, by most accounts, Sweden''s largest blues export. Rather than a studio-focused project, Trickbag has built its name on the road, playing what critics describe as raw, swinging blues rooted in Mississippi Delta tradition, spiked with R&B and rock and roll energy, and delivered, as one description put it, "with maximal energy already in the first song" (Kilde: band promotional materials; Discogs).

The band''s recorded catalog runs from "Just Passing Through" (1999, Concrete Records) through "Afternoon Mint" (2004), "Goin'' Downtown" (2011), "Candyville" (2015) and the anniversary-marking "The Collection" (2024), released to celebrate three decades together. Along the way Trickbag has also released two "Trickbag With Friends" collaborative volumes (2013 and 2016) and a career retrospective, "25 Years Of Houserockin'' Rhythm''N''Blues!" (2019) (Kilde: Discogs).

The band''s current lineup centers on vocalist Tommy Moberg, harmonica player Steve "West" Weston — regarded as one of Europe''s finest blues harp players — and guitarist Tomi Leino, known for his heavy, aggressive playing style. Their reputation as a top touring act has carried them across the European blues festival circuit for three decades, appearances documented on Discogs through track credits on blues festival compilations from Toronto to Lucerne, Switzerland (Kilde: Discogs; band promotional materials).

In 2024, Trickbag marked their 30th anniversary with a dedicated tour and "The Collection," a career-spanning release that captured a band still known, after three decades, for going all-out on stage from the very first note (Kilde: band promotional materials).', biography_no = 'Dannet på begynnelsen av 1990-tallet, har Trickbag brukt over tretti år på å opparbeide seg et rykte som et av Sveriges mest aktive bluesband — og, ifølge de fleste kilder, Sveriges største blueseksport. Fremfor å være et studiofokusert prosjekt, har Trickbag bygget navnet sitt på veien, og spiller det kritikere beskriver som rå, svingende blues forankret i Mississippi Delta-tradisjon, krydret med R&B- og rock and roll-energi, og levert, som én beskrivelse formulerte det, «med maksimal energi allerede i den første sangen» (Kilde: bandets promoteringsmateriell; Discogs).

Bandets innspilte katalog strekker seg fra «Just Passing Through» (1999, Concrete Records) via «Afternoon Mint» (2004), «Goin'' Downtown» (2011), «Candyville» (2015) og jubileumsalbumet «The Collection» (2024), utgitt for å feire tre tiår sammen. Underveis har Trickbag også gitt ut to «Trickbag With Friends»-samarbeidsvolumer (2013 og 2016) og et karriereretrospektiv, «25 Years Of Houserockin'' Rhythm''N''Blues!» (2019) (Kilde: Discogs).

Bandets nåværende besetning er sentrert rundt vokalist Tommy Moberg, munnspilleren Steve «West» Weston — regnet som en av Europas fremste bluesmunnspillere — og gitaristen Tomi Leino, kjent for sin tunge, aggressive spillestil. Deres rykte som et toppturnerende akt har ført dem over det europeiske bluesfestivalkretsløpet i tre tiår, opptredener dokumentert på Discogs gjennom sporkrediteringer på bluesfestivalsamlinger fra Toronto til Luzern, Sveits (Kilde: Discogs; bandets promoteringsmateriell).

I 2024 markerte Trickbag sitt 30-årsjubileum med en dedikert turné og «The Collection», en karriereoppsummerende utgivelse som fanget et band fortsatt kjent, etter tre tiår, for å gå all-in på scenen fra den aller første tonen (Kilde: bandets promoteringsmateriell).', biography_sv = 'Bildat i början av 1990-talet har Trickbag ägnat över trettio år åt att bygga sitt rykte som ett av Sveriges mest aktiva bluesband — och, enligt de flesta källor, Sveriges största blues-export. Snarare än ett studiofokuserat projekt har Trickbag byggt sitt namn på vägen, och spelar vad kritiker beskriver som rå, swingig blues förankrad i Mississippi Delta-tradition, kryddad med R&B- och rock and roll-energi, och levererad, som en beskrivning uttryckte det, "med maximal energi redan i den första låten" (Källa: bandets promotionsmaterial; Discogs).

Bandets inspelade katalog sträcker sig från "Just Passing Through" (1999, Concrete Records) via "Afternoon Mint" (2004), "Goin'' Downtown" (2011), "Candyville" (2015) och jubileumsalbumet "The Collection" (2024), utgivet för att fira tre decennier tillsammans. Under tiden har Trickbag också gett ut två "Trickbag With Friends"-samarbetsvolymer (2013 och 2016) och en karriärretrospektiv, "25 Years Of Houserockin'' Rhythm''N''Blues!" (2019) (Källa: Discogs).

Bandets nuvarande sättning centreras kring sångaren Tommy Moberg, munspelaren Steve "West" Weston — betraktad som en av Europas främsta bluesmunspelare — och gitarristen Tomi Leino, känd för sin tunga, aggressiva spelstil. Deras rykte som ett toppturnerande akt har fört dem över den europeiska bluesfestivalkretsen i tre decennier, framträdanden dokumenterade på Discogs genom spårkrediteringar på bluesfestivalsamlingar från Toronto till Luzern, Schweiz (Källa: Discogs; bandets promotionsmaterial).

2024 firade Trickbag sitt 30-årsjubileum med en dedikerad turné och "The Collection", en karriärspännande utgåva som fångade ett band fortfarande känt, efter tre decennier, för att gå all-in på scenen redan från den första tonen (Källa: bandets promotionsmaterial).', biography_de = 'Trickbag wurde Anfang der 1990er-Jahre gegründet und hat sich über dreißig Jahre hinweg den Ruf als eine der aktivsten Bluesbands Schwedens erarbeitet — und, den meisten Quellen zufolge, als Schwedens größten Blues-Export. Anstatt ein studiofokussiertes Projekt zu sein, hat sich Trickbag seinen Namen auf der Straße gemacht und spielt, was Kritiker als rohen, swingenden Blues beschreiben, verwurzelt in der Mississippi-Delta-Tradition, angereichert mit R&B- und Rock''n''Roll-Energie, und, wie eine Beschreibung es formulierte, "mit maximaler Energie bereits im ersten Song" dargeboten (Quelle: Promotionmaterial der Band; Discogs).

Der aufgenommene Katalog der Band reicht von "Just Passing Through" (1999, Concrete Records) über "Afternoon Mint" (2004), "Goin'' Downtown" (2011), "Candyville" (2015) bis zum Jubiläumsalbum "The Collection" (2024), veröffentlicht zur Feier von drei gemeinsamen Jahrzehnten. Nebenbei veröffentlichte Trickbag auch zwei "Trickbag With Friends"-Kollaborationsalben (2013 und 2016) und eine Karriere-Retrospektive, "25 Years Of Houserockin'' Rhythm''N''Blues!" (2019) (Quelle: Discogs).

Die aktuelle Besetzung der Band konzentriert sich auf Sänger Tommy Moberg, Mundharmonika-Spieler Steve "West" Weston — der als einer der besten Blues-Harp-Spieler Europas gilt — und Gitarrist Tomi Leino, bekannt für seinen schweren, aggressiven Spielstil. Ihr Ruf als Top-Touring-Act hat sie drei Jahrzehnte lang über den europäischen Blues-Festivalzirkus geführt, Auftritte, die auf Discogs durch Track-Credits auf Blues-Festival-Kompilationen von Toronto bis Luzern, Schweiz, dokumentiert sind (Quelle: Discogs; Promotionmaterial der Band).

2024 feierte Trickbag ihr 30-jähriges Bestehen mit einer eigenen Tour und "The Collection", einer karriereumspannenden Veröffentlichung, die eine Band einfing, die auch nach drei Jahrzehnten noch dafür bekannt ist, auf der Bühne vom ersten Ton an alles zu geben (Quelle: Promotionmaterial der Band).', biography_pl = 'Założony na początku lat 90., Trickbag przez ponad trzydzieści lat budował swoją reputację jako jeden z najbardziej aktywnych szwedzkich zespołów bluesowych — i, według większości źródeł, największy szwedzki eksport bluesa. Zamiast być projektem skoncentrowanym na studiu, Trickbag zbudował swoją nazwę na trasie koncertowej, grając to, co krytycy opisują jako surowy, swingujący blues zakorzeniony w tradycji Delty Missisipi, przyprawiony energią R&B i rock and rolla, dostarczany, jak ujęto to w jednym z opisów, "z maksymalną energią już od pierwszej piosenki" (Źródło: materiały promocyjne zespołu; Discogs).

Katalog nagrań zespołu obejmuje "Just Passing Through" (1999, Concrete Records), poprzez "Afternoon Mint" (2004), "Goin'' Downtown" (2011), "Candyville" (2015) oraz jubileuszowy album "The Collection" (2024), wydany z okazji trzech dekad wspólnej działalności. Po drodze Trickbag wydał również dwa wspólne albumy "Trickbag With Friends" (2013 i 2016) oraz retrospektywę kariery "25 Years Of Houserockin'' Rhythm''N''Blues!" (2019) (Źródło: Discogs).

Obecny skład zespołu skupia się wokół wokalisty Tommy''ego Moberga, harmonijkarza Steve''a "Westa" Westona — uważanego za jednego z najlepszych europejskich harmonijkarzy bluesowych — oraz gitarzysty Tomiego Leino, znanego z ciężkiego, agresywnego stylu gry. Ich reputacja jako czołowego zespołu koncertowego prowadziła ich przez europejską trasę festiwali bluesowych przez trzy dekady, występy udokumentowane na Discogs poprzez kredyty utworów na kompilacjach z festiwali bluesowych od Toronto po Lucernę w Szwajcarii (Źródło: Discogs; materiały promocyjne zespołu).

W 2024 roku Trickbag uczcił swoją 30. rocznicę dedykowaną trasą koncertową i albumem "The Collection", wydawnictwem obejmującym całą karierę, które uchwyciło zespół nadal znany, po trzech dekadach, z dawania z siebie wszystkiego na scenie już od pierwszej nuty (Źródło: materiały promocyjne zespołu).',
  influence_en = 'Trickbag''s three decades of relentless touring have made them one of the most visible ambassadors of Swedish blues on the European festival circuit, a live-first model that has outlasted most of their studio-focused peers. (Kilde: Discogs; band promotional materials)', influence_no = 'Trickbags tre tiår med utrettelig turnering har gjort dem til en av de mest synlige ambassadørene for svensk blues på det europeiske festivalkretsløpet, en live-først-modell som har overlevd de fleste av deres studiofokuserte samtidige. (Kilde: Discogs; bandets promoteringsmateriell)', influence_sv = 'Trickbags tre decennier av oförtröttlig turnering har gjort dem till en av de mest synliga ambassadörerna för svensk blues på den europeiska festivalkretsen, en live-först-modell som har överlevt de flesta av deras studiofokuserade samtida. (Källa: Discogs; bandets promotionsmaterial)', influence_de = 'Trickbags drei Jahrzehnte unermüdlichen Tourens haben sie zu einem der sichtbarsten Botschafter des schwedischen Blues auf dem europäischen Festivalzirkus gemacht, ein Live-first-Modell, das die meisten ihrer studiofokussierten Zeitgenossen überdauert hat. (Quelle: Discogs; Promotionmaterial der Band)', influence_pl = 'Trzy dekady nieustannych tras koncertowych Trickbag uczyniły ich jednym z najbardziej widocznych ambasadorów szwedzkiego bluesa na europejskiej trasie festiwalowej, model oparty na koncertach na żywo, który przetrwał większość ich rówieśników skupionych na studiu. (Źródło: Discogs; materiały promocyjne zespołu)',
  formative_i18n = '{"en":["Early 1990s: Trickbag forms in Sweden. (Kilde: band promotional materials)","1999: Releases debut album \"Just Passing Through\" on Concrete Records. (Kilde: Discogs)","2011: Releases \"Goin'' Downtown.\" (Kilde: Discogs)","2019: Career retrospective \"25 Years Of Houserockin'' Rhythm''N''Blues!\" released. (Kilde: Discogs)","2024: Marks 30th anniversary with \"The Collection\" and an anniversary tour. (Kilde: Discogs; band promotional materials)"],"no":["Tidlig 1990-tall: Trickbag dannes i Sverige. (Kilde: bandets promoteringsmateriell)","1999: Gir ut debutalbumet «Just Passing Through» på Concrete Records. (Kilde: Discogs)","2011: Gir ut «Goin'' Downtown». (Kilde: Discogs)","2019: Karriereretrospektivet «25 Years Of Houserockin'' Rhythm''N''Blues!» utgis. (Kilde: Discogs)","2024: Markerer 30-årsjubileum med «The Collection» og en jubileumsturné. (Kilde: Discogs; bandets promoteringsmateriell)"]}',
  instruments_i18n = '{"en":[{"category":"Vokal","name":"Vocals","note":"Tommy Moberg, current lead vocalist.","source":"Band promotional materials"},{"category":"Munnspill","name":"Harmonica","note":"Steve \"West\" Weston, regarded as one of Europe''s finest blues harp players.","source":"Band promotional materials"},{"category":"Gitar","name":"Guitar","note":"Tomi Leino, known for heavy, aggressive playing.","source":"Band promotional materials"}],"no":[{"category":"Vokal","name":"Vokal","note":"Tommy Moberg, nåværende hovedvokalist.","source":"Bandets promoteringsmateriell"},{"category":"Munnspill","name":"Munnspill","note":"Steve «West» Weston, regnet som en av Europas fremste bluesmunnspillere.","source":"Bandets promoteringsmateriell"},{"category":"Gitar","name":"Gitar","note":"Tomi Leino, kjent for tung, aggressiv spilling.","source":"Bandets promoteringsmateriell"}]}',
  anecdotes_i18n = '{"en":["Trickbag is widely described in Swedish blues circles as \"Sweden''s largest blues export,\" a reputation built almost entirely through relentless live touring rather than hit records. (Kilde: band promotional materials)","The band''s 2024 30th-anniversary release, \"The Collection,\" arrived exactly three decades after their formation, marking one of the longest continuously active runs of any Swedish blues band. (Kilde: Discogs)","Discogs credits Trickbag with track appearances on blues festival compilations spanning from Toronto and Lucerne, Switzerland, to New Orleans — evidence of a touring footprint far beyond Scandinavia. (Kilde: Discogs)"],"no":["Trickbag beskrives ofte i svenske bluesmiljøer som «Sveriges største blueseksport», et rykte bygget nesten utelukkende gjennom utrettelig live-turnering fremfor hitplater. (Kilde: bandets promoteringsmateriell)","Bandets 30-årsjubileumsutgivelse fra 2024, «The Collection», kom nøyaktig tre tiår etter dannelsen, og markerer en av de lengste kontinuerlig aktive periodene for et svensk bluesband. (Kilde: Discogs)","Discogs krediterer Trickbag med sporopptredener på bluesfestivalsamlinger som strekker seg fra Toronto og Luzern, Sveits, til New Orleans — bevis på et turnéfotavtrykk langt utenfor Skandinavia. (Kilde: Discogs)"]}',
  collaborators_i18n = '{"en":[{"name":"Tommy Moberg","note":"Vocalist.","source":"Band promotional materials"},{"name":"Steve \"West\" Weston","note":"Harmonica.","source":"Band promotional materials"},{"name":"Tomi Leino","note":"Guitar.","source":"Band promotional materials"}],"no":[{"name":"Tommy Moberg","note":"Vokalist.","source":"Bandets promoteringsmateriell"},{"name":"Steve «West» Weston","note":"Munnspill.","source":"Bandets promoteringsmateriell"},{"name":"Tomi Leino","note":"Gitar.","source":"Bandets promoteringsmateriell"}]}',
  discography_i18n = '{"en":[{"year":1999,"title":"Just Passing Through","producer":"—","label":"Concrete Records","notes":"Debut album.","musicians":[],"youtube_id":""},{"year":2004,"title":"Afternoon Mint","producer":"—","label":"Concrete Records","notes":"—","musicians":[],"youtube_id":""},{"year":2011,"title":"Goin'' Downtown","producer":"—","label":"Magic Production","notes":"—","musicians":[],"youtube_id":""},{"year":2015,"title":"Candyville","producer":"—","label":"Magic Production","notes":"—","musicians":[],"youtube_id":"XKEX2mruOIc"},{"year":2019,"title":"25 Years Of Houserockin'' Rhythm''N''Blues!","producer":"—","label":"Magic Production","notes":"Career retrospective marking 25 years together.","musicians":[],"youtube_id":""},{"year":2024,"title":"The Collection","producer":"—","label":"—","notes":"Released to mark the band''s 30th anniversary.","musicians":[],"youtube_id":""}],"no":[{"year":1999,"title":"Just Passing Through","producer":"—","label":"Concrete Records","notes":"Debutalbum.","musicians":[],"youtube_id":""},{"year":2004,"title":"Afternoon Mint","producer":"—","label":"Concrete Records","notes":"—","musicians":[],"youtube_id":""},{"year":2011,"title":"Goin'' Downtown","producer":"—","label":"Magic Production","notes":"—","musicians":[],"youtube_id":""},{"year":2015,"title":"Candyville","producer":"—","label":"Magic Production","notes":"—","musicians":[],"youtube_id":"XKEX2mruOIc"},{"year":2019,"title":"25 Years Of Houserockin'' Rhythm''N''Blues!","producer":"—","label":"Magic Production","notes":"Karriereretrospektiv som markerer 25 år sammen.","musicians":[],"youtube_id":""},{"year":2024,"title":"The Collection","producer":"—","label":"—","notes":"Utgitt for å markere bandets 30-årsjubileum.","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["Candyville","House Party"],"no":["Candyville","House Party"]}',
