  videos = '[{"kind":"featured","title":"Trickbag — \"thirty years of houserockin'' rhythm n''blues, live\" (Akkurat, Stockholm 2024)","youtube_id":"BQgVo1bkyOs","channel":"Davve Davve"},{"kind":"more","title":"Trickbag — House Party (live in Tampere 2024)","youtube_id":"rKT0yAG4L2E","channel":"Mr Blues"},{"kind":"more","title":"Trickbag — Candyville (live at Öbacka Jazz & Blues, Härnösand 2020)","youtube_id":"OqWw3YcFsko","channel":"EA One Channel Studios"},{"kind":"more","title":"Trickbag — Candyville (studio)","youtube_id":"XKEX2mruOIc","channel":"Trickbag - Topic"}]',
