WHERE slug = 'trickbag';
INSERT INTO artists (id, slug, name, alt_name, tag, era, active_years, birth_place, origin, country, region, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'mats-ronander', 'Mats Ronander', 'Malla', 'Classic', 'Classic Era', '1970s–present', 'Sundsvall, Sweden', 'Örebro, Sweden', 'Sweden', 'Nordic', 400, 'From Peps Persson''s stand-in guitarist to ABBA''s touring backing band — Mats "Malla" Ronander has spent five decades moving between blues, rock and pop, always anchored by his Elmore James-titled blues album "Himlen gråter för Elmore James."', 'Fra Peps Perssons vikargitarist til ABBAs turnerende backingband — Mats «Malla» Ronander har brukt fem tiår på å bevege seg mellom blues, rock og pop, alltid forankret av hans Elmore James-oppkalte bluesalbum «Himlen gråter för Elmore James».');

UPDATE artists SET
  short_sv = 'Från Peps Perssons vikarierande gitarrist till ABBAs turnerande backingband — Mats "Malla" Ronander har ägnat fem decennier åt att röra sig mellan blues, rock och pop, alltid förankrad av sitt Elmore James-uppkallade bluesalbum "Himlen gråter för Elmore James".', short_de = 'Vom Vertretungsgitarristen für Peps Persson zur Tour-Begleitband von ABBA — Mats "Malla" Ronander bewegte sich fünf Jahrzehnte lang zwischen Blues, Rock und Pop, stets verankert durch sein nach Elmore James benanntes Bluesalbum "Himlen gråter för Elmore James".', short_pl = 'Od zastępczego gitarzysty Pepsa Perssona po koncertowy zespół akompaniujący ABBIE — Mats "Malla" Ronander przez pięć dekad poruszał się między bluesem, rockiem i popem, zawsze zakotwiczony przez swój album bluesowy zatytułowany na cześć Elmore''a Jamesa, "Himlen gråter för Elmore James".',
  biography_en = 'Mats Sture Ronander, born 1 April 1954 in Sundsvall and raised in Örebro, has spent over five decades moving fluidly between blues, rock and Swedish pop — always anchored, at his core, by a deep love of electric blues guitar. At just 15 he joined the Örebro band Crossway Blues, and in the early 1970s occasionally substituted for Peps Persson in Peps & Blues Quality, before that band reformed as Nature with Ronander as lead vocalist and harmonica player (Kilde: Wikipedia).

Nature toured extensively and collaborated closely with singer-songwriter Ulf Lundell, with Ronander appearing on three of Lundell''s studio albums and touring as guitarist in his backing band. After Nature, he formed Wellander & Ronander with guitarist Lasse Wellander. His profile grew further through work as a touring backing musician for ABBA across Europe, North America and Japan, and through membership in the Low Budget Blues Band as singer and guitarist across three albums (Kilde: Wikipedia).

Ronander''s biggest commercial moment came in 1992 with the duet "Gör mig lycklig nu," featuring Danish singer Kim Larsen, released alongside his blues-specific album "Himlen gråter för Elmore James" — a title that makes his deepest musical loyalty explicit. He also worked behind the scenes as a producer, most notably on Py Bäckman''s breakthrough "Sista föreställningen" (1983), and contributed guitar to Kikki Danielsson''s "Första dagen på resten av mitt liv" (2011) (Kilde: Wikipedia).

Across a long solo catalog running from "God bok" (1982) to "Malla Motell" (2020) — using his nickname "Malla" — plus later projects including Grymlings (2004–2005, replacing Pugh Rogefeldt) and Ravaillacz (co-founded with Tommy Körberg, Claes Malmberg and Johan Rabaeus for Melodifestivalen 2013), Ronander has remained one of Swedish rock and blues music''s most versatile working musicians (Kilde: Wikipedia).', biography_no = 'Mats Sture Ronander, født 1. april 1954 i Sundsvall og oppvokst i Örebro, har brukt over fem tiår på å bevege seg smidig mellom blues, rock og svensk pop — alltid forankret, i kjernen, av en dyp kjærlighet til elektrisk bluesgitar. Allerede som 15-åring ble han med i Örebro-bandet Crossway Blues, og på begynnelsen av 1970-tallet vikarierte han av og til for Peps Persson i Peps & Blues Quality, før det bandet ble omdannet til Nature med Ronander som hovedvokalist og munnspiller (Kilde: Wikipedia).

Nature turnerte mye og samarbeidet tett med låtskriveren Ulf Lundell, med Ronander medvirkende på tre av Lundells studioalbum og turnerte som gitarist i backingbandet hans. Etter Nature dannet han Wellander & Ronander med gitaristen Lasse Wellander. Profilen hans vokste ytterligere gjennom arbeid som turnerende backingmusiker for ABBA over Europa, Nord-Amerika og Japan, og gjennom medlemskap i Low Budget Blues Band som vokalist og gitarist på tre album (Kilde: Wikipedia).

Ronanders største kommersielle øyeblikk kom i 1992 med duetten «Gör mig lycklig nu», med den danske sangeren Kim Larsen, utgitt sammen med hans bluesspesifikke album «Himlen gråter för Elmore James» — en tittel som gjør hans dypeste musikalske lojalitet eksplisitt. Han jobbet også bak kulissene som produsent, mest bemerkelsesverdig på Py Bäckmans gjennombrudd «Sista föreställningen» (1983), og bidro med gitar på Kikki Danielssons «Första dagen på resten av mitt liv» (2011) (Kilde: Wikipedia).

Gjennom en lang solokatalog som strekker seg fra «God bok» (1982) til «Malla Motell» (2020) — under kallenavnet «Malla» — pluss senere prosjekter inkludert Grymlings (2004–2005, som erstattet Pugh Rogefeldt) og Ravaillacz (medstiftet med Tommy Körberg, Claes Malmberg og Johan Rabaeus for Melodifestivalen 2013), har Ronander forblitt en av svensk rock- og bluesmusikks mest allsidige aktive musikere (Kilde: Wikipedia).', biography_sv = 'Mats Sture Ronander, född 1 april 1954 i Sundsvall och uppvuxen i Örebro, har ägnat över fem decennier åt att röra sig smidigt mellan blues, rock och svensk pop — alltid förankrad, i kärnan, av en djup kärlek till elektrisk bluesgitarr. Redan vid 15 års ålder gick han med i Örebro-bandet Crossway Blues, och i början av 1970-talet vikarierade han ibland för Peps Persson i Peps & Blues Quality, innan det bandet omvandlades till Nature med Ronander som huvudsångare och munspelare (Källa: Wikipedia).

Nature turnerade flitigt och samarbetade nära med låtskrivaren Ulf Lundell, med Ronander medverkande på tre av Lundells studioalbum och turnerade som gitarrist i hans backingband. Efter Nature bildade han Wellander & Ronander med gitarristen Lasse Wellander. Hans profil växte ytterligare genom arbete som turnerande backingmusiker för ABBA över Europa, Nordamerika och Japan, och genom medlemskap i Low Budget Blues Band som sångare och gitarrist på tre album (Källa: Wikipedia).

Ronanders största kommersiella ögonblick kom 1992 med duetten "Gör mig lycklig nu", med den danske sångaren Kim Larsen, utgiven tillsammans med hans bluesspecifika album "Himlen gråter för Elmore James" — en titel som gör hans djupaste musikaliska lojalitet explicit. Han arbetade också bakom kulisserna som producent, mest anmärkningsvärt på Py Bäckmans genombrott "Sista föreställningen" (1983), och bidrog med gitarr på Kikki Danielssons "Första dagen på resten av mitt liv" (2011) (Källa: Wikipedia).

Genom en lång solokatalog som sträcker sig från "God bok" (1982) till "Malla Motell" (2020) — under smeknamnet "Malla" — plus senare projekt inklusive Grymlings (2004–2005, där han ersatte Pugh Rogefeldt) och Ravaillacz (medgrundat med Tommy Körberg, Claes Malmberg och Johan Rabaeus för Melodifestivalen 2013), har Ronander förblivit en av svensk rock- och bluesmusiks mest mångsidiga arbetande musiker (Källa: Wikipedia).', biography_de = 'Mats Sture Ronander, geboren am 1. April 1954 in Sundsvall und aufgewachsen in Örebro, hat über fünf Jahrzehnte damit verbracht, sich fließend zwischen Blues, Rock und schwedischem Pop zu bewegen — stets im Kern verankert durch eine tiefe Liebe zur elektrischen Bluesgitarre. Bereits mit 15 Jahren schloss er sich der Örebro-Band Crossway Blues an, und Anfang der 1970er-Jahre vertrat er gelegentlich Peps Persson bei Peps & Blues Quality, bevor sich diese Band zu Nature umformte, mit Ronander als Leadsänger und Mundharmonikaspieler (Quelle: Wikipedia).

Nature tourte ausgiebig und arbeitete eng mit dem Liedermacher Ulf Lundell zusammen, wobei Ronander auf drei von Lundells Studioalben mitwirkte und als Gitarrist in dessen Begleitband tourte. Nach Nature gründete er Wellander & Ronander mit dem Gitarristen Lasse Wellander. Sein Profil wuchs weiter durch die Arbeit als tourender Begleitmusiker für ABBA in Europa, Nordamerika und Japan, sowie durch seine Mitgliedschaft in der Low Budget Blues Band als Sänger und Gitarrist auf drei Alben (Quelle: Wikipedia).

Ronanders größter kommerzieller Moment kam 1992 mit dem Duett "Gör mig lycklig nu" mit dem dänischen Sänger Kim Larsen, veröffentlicht zusammen mit seinem bluesspezifischen Album "Himlen gråter för Elmore James" — ein Titel, der seine tiefste musikalische Loyalität explizit macht. Er arbeitete auch hinter den Kulissen als Produzent, am bemerkenswertesten bei Py Bäckmans Durchbruchsalbum "Sista föreställningen" (1983), und steuerte Gitarre zu Kikki Danielssons "Första dagen på resten av mitt liv" (2011) bei (Quelle: Wikipedia).

Über einen langen Solokatalog, der von "God bok" (1982) bis "Malla Motell" (2020) reicht — unter seinem Spitznamen "Malla" — plus spätere Projekte einschließlich Grymlings (2004–2005, als Ersatz für Pugh Rogefeldt) und Ravaillacz (mitbegründet mit Tommy Körberg, Claes Malmberg und Johan Rabaeus für den Melodifestivalen 2013), ist Ronander einer der vielseitigsten aktiven Musiker der schwedischen Rock- und Bluesmusik geblieben (Quelle: Wikipedia).', biography_pl = 'Mats Sture Ronander, urodzony 1 kwietnia 1954 roku w Sundsvall i wychowany w Örebro, przez ponad pięć dekad płynnie poruszał się między bluesem, rockiem a szwedzkim popem — zawsze zakotwiczony, u podstaw, w głębokiej miłości do elektrycznej gitary bluesowej. Już w wieku 15 lat dołączył do zespołu Crossway Blues z Örebro, a na początku lat 70. okazjonalnie zastępował Pepsa Perssona w Peps & Blues Quality, zanim ten zespół przekształcił się w Nature, z Ronanderem jako głównym wokalistą i harmonijkarzem (Źródło: Wikipedia).

Nature intensywnie koncertował i ściśle współpracował z autorem piosenek Ulfem Lundellem, a Ronander występował na trzech albumach studyjnych Lundella i koncertował jako gitarzysta w jego zespole akompaniującym. Po Nature założył Wellander & Ronander z gitarzystą Lasse Wellanderem. Jego pozycja rosła dalej dzięki pracy jako koncertujący muzyk akompaniujący dla ABBY w Europie, Ameryce Północnej i Japonii, oraz dzięki członkostwu w Low Budget Blues Band jako wokalista i gitarzysta na trzech albumach (Źródło: Wikipedia).

Największy komercyjny moment Ronandera nastąpił w 1992 roku wraz z duetem "Gör mig lycklig nu" z udziałem duńskiego piosenkarza Kima Larsena, wydanym razem z jego stricte bluesowym albumem "Himlen gråter för Elmore James" — tytułem, który wprost wyraża jego najgłębszą muzyczną lojalność. Pracował także za kulisami jako producent, najbardziej godny uwagi przy przełomowym albumie Py Bäckman "Sista föreställningen" (1983), oraz dołożył gitarę do albumu Kikki Danielsson "Första dagen på resten av mitt liv" (2011) (Źródło: Wikipedia).

Poprzez długi katalog solowy, rozciągający się od "God bok" (1982) do "Malla Motell" (2020) — pod pseudonimem "Malla" — oraz późniejsze projekty, w tym Grymlings (2004–2005, zastępując Pugh Rogefeldta) i Ravaillacz (współzałożony z Tommym Körbergiem, Claesem Malmbergiem i Johanem Rabaeusem na Melodifestivalen 2013), Ronander pozostał jednym z najbardziej wszechstronnych czynnych muzyków szwedzkiej sceny rockowej i bluesowej (Źródło: Wikipedia).',
  influence_en = 'Ronander''s career-long willingness to move between pure blues, rock and mainstream Swedish pop — including a stint touring with ABBA — makes him a useful case study in how deeply blues guitar technique fed into Swedish popular music more broadly. (Kilde: Wikipedia)', influence_no = 'Ronanders karrierelange vilje til å bevege seg mellom ren blues, rock og mainstream svensk pop — inkludert en periode med å turnere med ABBA — gjør ham til et nyttig case-studie i hvor dypt bluesgitarteknikk matet inn i svensk populærmusikk mer generelt. (Kilde: Wikipedia)', influence_sv = 'Ronanders karriärlånga vilja att röra sig mellan ren blues, rock och mainstream svensk pop — inklusive en period av att turnera med ABBA — gör honom till ett användbart fallstudium i hur djupt bluesgitarrteknik matade in i svensk populärmusik mer generellt. (Källa: Wikipedia)', influence_de = 'Ronanders karrierelange Bereitschaft, sich zwischen reinem Blues, Rock und schwedischem Mainstream-Pop zu bewegen — einschließlich einer Tour mit ABBA — macht ihn zu einem aufschlussreichen Fallbeispiel dafür, wie tief Blues-Gitarrentechnik in die schwedische Popmusik im weiteren Sinne einfloss. (Quelle: Wikipedia)', influence_pl = 'Trwająca przez całą karierę gotowość Ronandera do poruszania się między czystym bluesem, rockiem i głównym nurtem szwedzkiego popu — w tym okres koncertowania z ABBĄ — czyni go użytecznym studium przypadku pokazującym, jak głęboko technika gitary bluesowej przenikała do szerzej pojętej szwedzkiej muzyki popularnej. (Źródło: Wikipedia)',
  formative_i18n = '{"en":["Age 15: Joins Örebro band Crossway Blues. (Kilde: Wikipedia)","Early 1970s: Substitutes for Peps Persson in Peps & Blues Quality; band reforms as Nature. (Kilde: Wikipedia)","Tours and records with Ulf Lundell across three studio albums. (Kilde: Wikipedia)","Tours internationally as a backing musician for ABBA. (Kilde: Wikipedia)","1983: Produces Py Bäckman''s breakthrough album \"Sista föreställningen.\" (Kilde: Wikipedia)","1992: Duet \"Gör mig lycklig nu\" with Kim Larsen and blues album \"Himlen gråter för Elmore James.\" (Kilde: Wikipedia)","2013: Co-founds Ravaillacz for Melodifestivalen with Tommy Körberg, Claes Malmberg and Johan Rabaeus. (Kilde: Wikipedia)","2020: Releases solo album \"Malla Motell.\" (Kilde: Wikipedia)"],"no":["15 år gammel: Blir med i Örebro-bandet Crossway Blues. (Kilde: Wikipedia)","Tidlig 1970-tall: Vikarierer for Peps Persson i Peps & Blues Quality; bandet omdannes til Nature. (Kilde: Wikipedia)","Turnerer og spiller inn med Ulf Lundell på tre studioalbum. (Kilde: Wikipedia)","Turnerer internasjonalt som backingmusiker for ABBA. (Kilde: Wikipedia)","1983: Produserer Py Bäckmans gjennombruddsalbum «Sista föreställningen». (Kilde: Wikipedia)","1992: Duetten «Gör mig lycklig nu» med Kim Larsen og bluesalbumet «Himlen gråter för Elmore James». (Kilde: Wikipedia)","2013: Er med å danne Ravaillacz for Melodifestivalen med Tommy Körberg, Claes Malmberg og Johan Rabaeus. (Kilde: Wikipedia)","2020: Gir ut soloalbumet «Malla Motell». (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Electric guitar","note":"Core instrument across his entire career, from Crossway Blues to ABBA touring band.","source":"Wikipedia"},{"category":"Munnspill","name":"Harmonica","note":"Played harmonica as lead vocalist/harpist in Nature.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Elektrisk gitar","note":"Kjerneinstrument gjennom hele karrieren, fra Crossway Blues til ABBAs turnéband.","source":"Wikipedia"},{"category":"Munnspill","name":"Munnspill","note":"Spilte munnspill som hovedvokalist/munnspiller i Nature.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Ronander occasionally filled in on guitar for Peps Persson in the early 1970s — a direct link between two artists on this site who each, in their own way, kept the blues alive in Swedish popular music. (Kilde: Wikipedia)","His 1992 album title, \"Himlen gråter för Elmore James\" (\"The Sky Weeps for Elmore James\"), is a direct tribute to the American slide guitarist, making his blues loyalties explicit even in the middle of a mainstream pop career. (Kilde: Wikipedia)","Beyond music, Ronander appeared on screen in the 1984 film adaptation of Ulf Lundell''s novel \"Sömnen,\" playing the character \"Tommy Cosmo.\" (Kilde: Wikipedia)"],"no":["Ronander vikarierte av og til på gitar for Peps Persson på begynnelsen av 1970-tallet — en direkte forbindelse mellom to artister på dette nettstedet som hver på sin måte holdt bluesen i live i svensk populærmusikk. (Kilde: Wikipedia)","Albumtittelen hans fra 1992, «Himlen gråter för Elmore James», er en direkte hyllest til den amerikanske slidegitaristen, og gjør bluesslojaliteten hans eksplisitt selv midt i en mainstream popkarriere. (Kilde: Wikipedia)","Utenom musikken opptrådte Ronander på lerretet i 1984-filmatiseringen av Ulf Lundells roman «Sömnen», hvor han spilte karakteren «Tommy Cosmo». (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Peps Persson","note":"Occasionally substituted for him in Peps & Blues Quality.","source":"Wikipedia"},{"name":"Ulf Lundell","note":"Toured and recorded on three of his studio albums.","source":"Wikipedia"},{"name":"Lasse Wellander","note":"Formed Wellander & Ronander together.","source":"Wikipedia"},{"name":"ABBA","note":"Toured as a backing musician across Europe, North America and Japan.","source":"Wikipedia"},{"name":"Kim Larsen","note":"Duet partner on \"Gör mig lycklig nu\" (1992).","source":"Wikipedia"}],"no":[{"name":"Peps Persson","note":"Vikarierte av og til for ham i Peps & Blues Quality.","source":"Wikipedia"},{"name":"Ulf Lundell","note":"Turnerte og spilte inn på tre av hans studioalbum.","source":"Wikipedia"},{"name":"Lasse Wellander","note":"Dannet Wellander & Ronander sammen.","source":"Wikipedia"},{"name":"ABBA","note":"Turnerte som backingmusiker over Europa, Nord-Amerika og Japan.","source":"Wikipedia"},{"name":"Kim Larsen","note":"Duettpartner på «Gör mig lycklig nu» (1992).","source":"Wikipedia"}]}',
  discography_i18n = '{"en":[{"year":1978,"title":"Wellander & Ronander","producer":"—","label":"Polar","notes":"Duo album with guitarist Lasse Wellander.","musicians":[{"name":"Lasse Wellander","instrument":"Guitar"}],"youtube_id":""},{"year":1982,"title":"God bok","producer":"—","label":"—","notes":"Early solo album.","musicians":[],"youtube_id":""},{"year":1984,"title":"50/50","producer":"—","label":"Polar","notes":"Solo album; contains \"En hederlig man.\"","musicians":[],"youtube_id":"Ux_nJ4CdIns"},{"year":1985,"title":"Kött & Blod","producer":"—","label":"Polar","notes":"Solo album.","musicians":[],"youtube_id":"uX9tVIzYF-s"},{"year":1992,"title":"Himlen gråter för Elmore James","producer":"—","label":"—","notes":"Blues-focused album, title a direct tribute to Elmore James; released alongside the hit duet \"Gör mig lycklig nu\" with Kim Larsen.","musicians":[{"name":"Kim Larsen","instrument":"Duet vocals"}],"youtube_id":""},{"year":2020,"title":"Malla Motell","producer":"—","label":"—","notes":"Recent solo album, released under his nickname \"Malla.\"","musicians":[],"youtube_id":""}],"no":[{"year":1978,"title":"Wellander & Ronander","producer":"—","label":"Polar","notes":"Duoalbum med gitaristen Lasse Wellander.","musicians":[{"name":"Lasse Wellander","instrument":"Gitar"}],"youtube_id":""},{"year":1982,"title":"God bok","producer":"—","label":"—","notes":"Tidlig soloalbum.","musicians":[],"youtube_id":""},{"year":1984,"title":"50/50","producer":"—","label":"Polar","notes":"Soloalbum; inneholder «En hederlig man».","musicians":[],"youtube_id":"Ux_nJ4CdIns"},{"year":1985,"title":"Kött & Blod","producer":"—","label":"Polar","notes":"Soloalbum.","musicians":[],"youtube_id":"uX9tVIzYF-s"},{"year":1992,"title":"Himlen gråter för Elmore James","producer":"—","label":"—","notes":"Bluesfokusert album, tittelen en direkte hyllest til Elmore James; utgitt sammen med hitduetten «Gör mig lycklig nu» med Kim Larsen.","musicians":[{"name":"Kim Larsen","instrument":"Duettvokal"}],"youtube_id":""},{"year":2020,"title":"Malla Motell","producer":"—","label":"—","notes":"Nylig soloalbum, utgitt under kallenavnet «Malla».","musicians":[],"youtube_id":""}]}',
  signature_songs_i18n = '{"en":["Himlen gråter för Elmore James","Gör mig lycklig nu"],"no":["Himlen gråter för Elmore James","Gör mig lycklig nu"]}',
