}],"pl":[{"year":2018,"title":"Bluesanovas","label":"Timezone Records","notes":"Źródło: thebluesanovas.de."},{"year":2019,"title":"Emergency Call For The Blues","label":"Timezone Records","notes":"Źródło: thebluesanovas.de.","chart":"Winner, German Blues Challenge 2019; German Rock & Pop Prize, Best Blues Album 2019"},{"year":2020,"title":"Blues''n''Roll","label":"Timezone Records","notes":"EP. Źródło: thebluesanovas.de."},{"year":2022,"title":"The Moonshine Record","label":"Timezone Records","notes":"Recorded at Moonshine Studio, Munich. Źródło: thebluesanovas.de.","chart":"German Blues Award, Best Band + Best Album + Best Piano (2021)"},{"year":2023,"title":"Big Love","label":"Timezone Records","notes":"Źródło: thebluesanovas.de.","chart":"German album charts 2023; German Blues Award, Best Band + Best Album + Best Piano (2023); Preis der Deutschen Schallplattenkritik (2024)"}]}', '{"no":[{"year":2019,"title":"German Blues Challenge","category":"Vinner"},{"year":2019,"title":"German Rock & Pop Prize","category":"Beste bluesalbum"},{"year":2020,"title":"German Blues Award","category":"Beste band + Beste album"},{"year":2020,"title":"International Blues Challenge (Memphis)","category":"Semifinalist"},{"year":2021,"title":"German Blues Award","category":"Beste band + Beste album + Beste piano"},{"year":2023,"title":"German Blues Award","category":"Beste band + Beste album + Beste piano"},{"year":2024,"title":"Preis der Deutschen Schallplattenkritik","category":null}],"en":[{"year":2019,"title":"German Blues Challenge","category":"Winner"},{"year":2019,"title":"German Rock & Pop Prize","category":"Best Blues Album"},{"year":2020,"title":"German Blues Award","category":"Best Band + Best Album"},{"year":2020,"title":"International Blues Challenge (Memphis)","category":"Semi-finalist"},{"year":2021,"title":"German Blues Award","category":"Best Band + Best Album + Best Piano"},{"year":2023,"title":"German Blues Award","category":"Best Band + Best Album + Best Piano"},{"year":2024,"title":"Preis der Deutschen Schallplattenkritik","category":null}],"sv":[{"year":2019,"title":"German Blues Challenge","category":"Vinnare"},{"year":2019,"title":"German Rock & Pop Prize","category":"Bästa bluesalbum"},{"year":2020,"title":"German Blues Award","category":"Bästa band + Bästa album"},{"year":2020,"title":"International Blues Challenge (Memphis)","category":"Semifinalist"},{"year":2021,"title":"German Blues Award","category":"Bästa band + Bästa album + Bästa piano"},{"year":2023,"title":"German Blues Award","category":"Bästa band + Bästa album + Bästa piano"},{"year":2024,"title":"Preis der Deutschen Schallplattenkritik","category":null}],"de":[{"year":2019,"title":"German Blues Challenge","category":"Sieger"},{"year":2019,"title":"German Rock & Pop Prize","category":"Bestes Bluesalbum"},{"year":2020,"title":"German Blues Award","category":"Beste Band + Bestes Album"},{"year":2020,"title":"International Blues Challenge (Memphis)","category":"Halbfinalist"},{"year":2021,"title":"German Blues Award","category":"Beste Band + Bestes Album + Bestes Piano"},{"year":2023,"title":"German Blues Award","category":"Beste Band + Bestes Album + Bestes Piano"},{"year":2024,"title":"Preis der Deutschen Schallplattenkritik","category":null}],"pl":[{"year":2019,"title":"German Blues Challenge","category":"Zwycięzca"},{"year":2019,"title":"German Rock & Pop Prize","category":"Najlepszy album bluesowy"},{"year":2020,"title":"German Blues Award","category":"Najlepszy zespół + Najlepszy album"},{"year":2020,"title":"International Blues Challenge (Memphis)","category":"Półfinalista"},{"year":2021,"title":"German Blues Award","category":"Najlepszy zespół + Najlepszy album + Najlepsze fortepian"},{"year":2023,"title":"German Blues Award","category":"Najlepszy zespół + Najlepszy album + Najlepsze fortepian"},{"year":2024,"title":"Preis der Deutschen Schallplattenkritik","category":null}]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[{"label":"Official website","url":"https://thebluesanovas.de/en"},{"label":"Baltic Blues e.V.","url":"https://www.baltic-blues.de/the-bluesanovas/"},{"label":"YouTube","url":"https://www.youtube.com/channel/UC2Tyq-zgvNBd2OLGwkmryNA"}]', '[{"title":"Official website — The Bluesanovas","url":"https://thebluesanovas.de/en"},{"title":"The Band — The Bluesanovas","url":"https://thebluesanovas.de/en/pages/the-band"},{"title":"Baltic Blues e.V. — The Bluesanovas","url":"https://www.baltic-blues.de/the-bluesanovas/"},{"title":"Bear Family Records — The Moonshine Record","url":"https://www.bear-family.de/bluesanovas-the-the-moonshine-record-lp-10inch-cd.html"}]', '{}', 'https://thebluesanovas.de/en', NULL, '{"booking_agency":null,"agent_name":"Nico Dreier (Management & Booking)","booking_email":"booking@nicodreier.de","booking_phone":"+49 (0) 152 28799085","booking_url":"https://thebluesanovas.de/en/pages/contact","source_url":"https://thebluesanovas.de/en/pages/contact","note":null}', 0);
INSERT INTO artists (id, slug, name, alt_name, tag, era, region, country, img, og_image, image_credit, gallery_images, youtube_video_ids, short_no, short_en, short_sv, short_de, short_pl, biography_no, biography_en, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_no, influence_en, influence_sv, influence_de, influence_pl, signature_songs_i18n, labels, instruments_simple, styles, categories, search_terms, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, awards_i18n, press_quotes_i18n, external_links, article_references, social_links, website_url, facebook_url, booking_info, sort_order) VALUES ('5c074233-6869-4712-892b-b48d950bdf1e', 'abi-wallenstein', 'Abi Wallenstein', NULL, 'Classic', 'Modern Era', 'Europe', 'Germany', 'https://www.abiwallenstein.de/media/489/abiwallenstein_foto_ellencoenders_02.jpg', 'https://www.abiwallenstein.de/media/513/abiwallenstein_foto_kay_winter.jpg', 'Foto: Ellen Coenders / Kay Winter (waschecht.hamburg) (Kilde: abiwallenstein.de/pressefotos-download)', '[]', '["wnKf3KwkLIM","zyN-JwAl99U","6ho5-0pL6ak"]', '«Far til Hamburgs bluesscene» — bluestolker siden 1966, ni ganger vinner av German Blues Award i solo/duo.', 'The "father of the Hamburg blues scene" — a blues interpreter since 1966, nine-time German Blues Award winner in Solo/Duo.', '"Hamburgs bluesscens far" — bluestolkare sedan 1966, nio gånger vinnare av German Blues Award i Solo/Duo.', 'Der "Vater der Hamburger Bluesszene" — Blues-Interpret seit 1966, neunfacher German-Blues-Award-Gewinner in Solo/Duo.', '"Ojciec hamburskiej sceny bluesowej" — interpretator bluesa od 1966 roku, dziewięciokrotny zdobywca German Blues Award w kategorii Solo/Duet.', 'Abi Wallenstein ble født 8. desember 1945 i Jerusalem, som sønn av tyske jøder som hadde flyktet under naziregimet — familien flyttet tilbake til Tyskland i 1960, først til Nordrhein-Westfalen (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein). Siden midten av 1960-tallet har han hatt base i Hamburg, og fra 1966 har han stått på scenen som bluestolker — en karriere som i dag spenner over nesten 60 år og rundt 120 konserter i året (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Hans signaturlyd kommer fra en åttestrengs gitar stemt i åpen G, inspirert av Big Joe Williams, der han kombinerer Piedmont-plukking med Delta-stil slidegitar — bass, rytme og melodi spilt samtidig (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Han omtales gjerne som «far til Hamburgs bluesscene» og en «levende bluesikon», og har spilt sammen med Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber og Gottfried Böttger, samt vært forband for Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford og George Thorogood (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Diskografien starter med Bad News Reunion-albumene på slutten av 1970- og 80-tallet, og fortsetter gjennom en rekke duo- og samarbeidsplater med musikere som Henry Heggen, Steve Baker og Joja Wendt, prosjektet BluesCulture (fra 2007, med Steve Baker og Martin Röttger), Boogielicious (2020) og trioen med Ludwig Seuss (2025) (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein). Han har vunnet den tyske Blues-prisen (German Blues Award) i kategorien solo/duo ni ganger mellom 2011 og 2021, i tillegg til prisen for beste mannlige vokal i 2012 og 2014, Blues-Louis-prisen på Lahnstein-bluesfestivalen i 2015, og i 2022 vant albumet «Spirit Of The Blues» prisen for beste nasjonale album (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Han har også mottatt Preis der Deutschen Schallplattenkritik for albumene «Step in Time» og «BluesCulture» (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein). Klaus «Mojo» Kilian i German Blues Circle har skrevet at «fingrene og stemmen hans, raffinert gjennom år med gatemusikk, plasserer Abi blant Europas mest uttrykksfulle bluesmusikere», mens den østerrikske kritikeren Dieter Hoscher i CONCERTO har kalt ham «så autentisk som man kan bli» (Kilde: abiwallenstein.de). I 2024 spilte han inn liveplaten «Gimme The Blues» sammen med Martin Röttger, Kalle Reuter og Matthias Schlechter (Kilde: schlechter-pianist.de; abiwallenstein.de).', 'Abi Wallenstein was born on 8 December 1945 in Jerusalem, the son of German Jews who had fled during the Nazi era — the family moved back to Germany in 1960, first to North Rhine-Westphalia (Source: de.wikipedia.org/wiki/Abi_Wallenstein). Since the mid-1960s he has been based in Hamburg, and from 1966 he has stood on stage as a blues interpreter — a career that today spans nearly 60 years and roughly 120 concerts a year (Source: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). His signature sound comes from an eight-string guitar tuned in open G, inspired by Big Joe Williams, blending Piedmont picking with Delta-style slide guitar — bass, rhythm and melody played simultaneously (Source: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). He is often called the "father of the Hamburg blues scene" and a "living blues legend," and has played alongside Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber and Gottfried Böttger, as well as opening for Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford and George Thorogood (Source: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). His discography begins with the Bad News Reunion albums of the late 1970s and 1980s and continues through a string of duo and collaborative records with musicians such as Henry Heggen, Steve Baker and Joja Wendt, the BluesCulture project (from 2007, with Steve Baker and Martin Röttger), Boogielicious (2020) and the trio with Ludwig Seuss (2025) (Source: de.wikipedia.org/wiki/Abi_Wallenstein). He has won the German Blues Award in the Solo/Duo category nine times between 2011 and 2021, plus the award for Best Male Vocals in 2012 and 2014, the Blues Louis Prize at the Lahnstein blues festival in 2015, and in 2022 his album "Spirit Of The Blues" won Best National Album (Source: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). He has also received the Preis der Deutschen Schallplattenkritik for the albums "Step in Time" and "BluesCulture" (Source: de.wikipedia.org/wiki/Abi_Wallenstein). Klaus "Mojo" Kilian of the German Blues Circle has written that "his fingers and voice, refined through years of street music, place Abi among Europe''s most expressive blues musicians," while Austrian critic Dieter Hoscher of CONCERTO called him "as authentic as one can be" (Source: abiwallenstein.de). In 2024 he recorded the live album "Gimme The Blues" together with Martin Röttger, Kalle Reuter and Matthias Schlechter (Source: schlechter-pianist.de; abiwallenstein.de).', 'Abi Wallenstein föddes den 8 december 1945 i Jerusalem, son till tyska judar som flytt under nazitiden — familjen flyttade tillbaka till Tyskland 1960, först till Nordrhein-Westfalen (Källa: de.wikipedia.org/wiki/Abi_Wallenstein). Sedan mitten av 1960-talet har han varit baserad i Hamburg, och från 1966 har han stått på scen som bluestolkare — en karriär som idag spänner över nästan 60 år och omkring 120 konserter om året (Källa: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Hans signaturljud kommer från en åttasträngad gitarr stämd i öppen G, inspirerad av Big Joe Williams, där han kombinerar Piedmont-plockning med Delta-stil slidegitarr — bas, rytm och melodi spelade samtidigt (Källa: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Han kallas ofta "far till Hamburgs bluesscen" och en "levande blueslegend", och har spelat tillsammans med Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber och Gottfried Böttger, samt varit förband åt Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford och George Thorogood (Källa: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Diskografin börjar med Bad News Reunion-albumen från slutet av 1970- och 80-talet och fortsätter genom en rad duo- och samarbetsskivor med musiker som Henry Heggen, Steve Baker och Joja Wendt, projektet BluesCulture (från 2007, med Steve Baker och Martin Röttger), Boogielicious (2020) och trion med Ludwig Seuss (2025) (Källa: de.wikipedia.org/wiki/Abi_Wallenstein). Han har vunnit German Blues Award i kategorin Solo/Duo nio gånger mellan 2011 och 2021, samt priset för bästa manliga sång 2012 och 2014, Blues Louis-priset vid Lahnstein-bluesfestivalen 2015, och 2022 vann albumet "Spirit Of The Blues" priset för bästa nationella album (Källa: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Han har även mottagit Preis der Deutschen Schallplattenkritik för albumen "Step in Time" och "BluesCulture" (Källa: de.wikipedia.org/wiki/Abi_Wallenstein). Klaus "Mojo" Kilian på German Blues Circle har skrivit att "hans fingrar och röst, förfinade genom år av gatumusik, placerar Abi bland Europas mest uttrycksfulla bluesmusiker", medan den österrikiska kritikern Dieter Hoscher på CONCERTO kallade honom "så autentisk man kan bli" (Källa: abiwallenstein.de). År 2024 spelade han in liveskivan "Gimme The Blues" tillsammans med Martin Röttger, Kalle Reuter och Matthias Schlechter (Källa: schlechter-pianist.de; abiwallenstein.de).', 'Abi Wallenstein wurde am 8. Dezember 1945 in Jerusalem geboren, als Sohn deutscher Juden, die während der NS-Zeit geflohen waren — die Familie kehrte 1960 nach Deutschland zurück, zunächst nach Nordrhein-Westfalen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein). Seit Mitte der 1960er-Jahre lebt er in Hamburg, und seit 1966 steht er als Blues-Interpret auf der Bühne — eine Karriere, die heute fast 60 Jahre umfasst und rund 120 Konzerte pro Jahr (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Sein charakteristischer Sound stammt von einer achtsaitigen Gitarre, gestimmt in offenem G, inspiriert von Big Joe Williams, bei der er Piedmont-Picking mit Slide-Gitarre im Delta-Stil kombiniert — Bass, Rhythmus und Melodie gleichzeitig gespielt (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Er wird oft als "Vater der Hamburger Bluesszene" und "lebende Blueslegende" bezeichnet und hat mit Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber und Gottfried Böttger gespielt sowie als Vorgruppe für Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford und George Thorogood (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Seine Diskografie beginnt mit den Bad-News-Reunion-Alben der späten 1970er- und 1980er-Jahre und setzt sich fort über zahlreiche Duo- und Kooperationsalben mit Musikern wie Henry Heggen, Steve Baker und Joja Wendt, das Projekt BluesCulture (ab 2007, mit Steve Baker und Martin Röttger), Boogielicious (2020) und das Trio mit Ludwig Seuss (2025) (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein). Er hat den German Blues Award in der Kategorie Solo/Duo neunmal zwischen 2011 und 2021 gewonnen, dazu den Preis für besten männlichen Gesang 2012 und 2014, den Blues-Louis-Preis beim Lahnsteiner Bluesfestival 2015, und 2022 gewann das Album "Spirit Of The Blues" den Preis für bestes nationales Album (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Zudem erhielt er den Preis der Deutschen Schallplattenkritik für die Alben "Step in Time" und "BluesCulture" (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein). Klaus "Mojo" Kilian vom German Blues Circle schrieb, dass "seine Finger und seine Stimme, verfeinert durch Jahre der Straßenmusik, Abi zu einem der ausdrucksstärksten Bluesmusiker Europas machen", während der österreichische Kritiker Dieter Hoscher von CONCERTO ihn als "so authentisch, wie man nur sein kann" bezeichnete (Quelle: abiwallenstein.de). 2024 nahm er das Livealbum "Gimme The Blues" zusammen mit Martin Röttger, Kalle Reuter und Matthias Schlechter auf (Quelle: schlechter-pianist.de; abiwallenstein.de).', 'Abi Wallenstein urodził się 8 grudnia 1945 roku w Jerozolimie, jako syn niemieckich Żydów, którzy uciekli w czasach nazistowskich — rodzina wróciła do Niemiec w 1960 roku, najpierw do Nadrenii Północnej-Westfalii (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein). Od połowy lat 60. mieszka w Hamburgu, a od 1966 roku występuje na scenie jako interpretator bluesa — kariera ta obejmuje dziś niemal 60 lat i około 120 koncertów rocznie (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Jego charakterystyczne brzmienie pochodzi z ośmiostrunowej gitary strojonej w otwartym G, inspirowanej Big Joe Williamsem, łącząc technikę Piedmont z gitarą slide w stylu Delty — bas, rytm i melodia grane jednocześnie (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Często nazywany "ojcem hamburskiej sceny bluesowej" i "żyjącą legendą bluesa", grał razem z Joją Wendtem, Ingą Rumpf, Axelem Zwingenbergerem, Tomem Shaką, Vincem Weberem i Gottfriedem Böttgerem, a także supportował Joego Cockera, Erica Burdona, Johnny''ego Wintera, Fatsa Domino, Robbena Forda i George''a Thorogooda (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Jego dyskografia zaczyna się od albumów Bad News Reunion z końca lat 70. i 80., a następnie obejmuje szereg albumów duetowych i wspólnych z muzykami takimi jak Henry Heggen, Steve Baker i Joja Wendt, projekt BluesCulture (od 2007, ze Steve''em Bakerem i Martinem Röttgerem), Boogielicious (2020) oraz trio z Ludwigiem Seussem (2025) (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein). Dziewięciokrotnie zdobył German Blues Award w kategorii Solo/Duet w latach 2011–2021, a także nagrodę za najlepszy męski wokal w 2012 i 2014 roku, nagrodę Blues Louis na festiwalu bluesowym w Lahnstein w 2015 roku, a w 2022 roku album "Spirit Of The Blues" zdobył nagrodę za najlepszy album krajowy (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de). Otrzymał również Preis der Deutschen Schallplattenkritik za albumy "Step in Time" i "BluesCulture" (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein). Klaus "Mojo" Kilian z German Blues Circle napisał, że "jego palce i głos, dopracowane przez lata gry ulicznej, sytuują Abiego wśród najbardziej ekspresyjnych muzyków bluesowych Europy", podczas gdy austriacki krytyk Dieter Hoscher z CONCERTO nazwał go "tak autentycznym, jak to tylko możliwe" (Źródło: abiwallenstein.de). W 2024 roku nagrał album koncertowy "Gimme The Blues" razem z Martinem Röttgerem, Kalle Reuterem i Matthiasem Schlechterem (Źródło: schlechter-pianist.de; abiwallenstein.de).', '1945-12-08', NULL, NULL, 'Jerusalem', 'Hamburg, Germany', '1966–present', 'Med nesten seks tiår på scenen har Abi Wallenstein blitt selve grunnmuren i Hamburgs bluesmiljø — kalt «far til Hamburgs bluesscene» av kritikere, og en fast referanse for tyske musikere som selv har spilt gitar med bass, rytme og melodi samtidig etter hans forbilde (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein). Ni seire i solo/duo-kategorien ved German Blues Award mellom 2011 og 2021 er en rekord uten sidestykke i tysk blues, og viser en konsistens over tid som få samtidige artister matcher (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein). Gjennom BluesCulture og en lang rekke samarbeid — med Steve Baker, Henry Heggen, Joja Wendt, Martin Röttger og flere — har han også fungert som en brobygger som har løftet fram yngre musikere i sitt eget nettverk (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de).', 'With nearly six decades on stage, Abi Wallenstein has become the very bedrock of Hamburg''s blues scene — called "the father of the Hamburg blues scene" by critics, and a constant reference point for German musicians who have themselves picked up the guitar playing bass, rhythm and melody simultaneously after his example (Source: de.wikipedia.org/wiki/Abi_Wallenstein). Nine wins in the Solo/Duo category at the German Blues Award between 2011 and 2021 is an unmatched record in German blues, showing a consistency over time that few contemporary artists can rival (Source: de.wikipedia.org/wiki/Abi_Wallenstein). Through BluesCulture and a long string of collaborations — with Steve Baker, Henry Heggen, Joja Wendt, Martin Röttger and others — he has also acted as a bridge-builder who has lifted up younger musicians within his own network (Source: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de).', 'Med nästan sex decennier på scenen har Abi Wallenstein blivit själva grundstenen i Hamburgs bluesscen — kallad "Hamburgs bluesscens far" av kritiker, och en ständig referenspunkt för tyska musiker som själva plockat upp gitarren och spelat bas, rytm och melodi samtidigt efter hans förebild (Källa: de.wikipedia.org/wiki/Abi_Wallenstein). Nio segrar i kategorin Solo/Duo vid German Blues Award mellan 2011 och 2021 är ett rekord utan motstycke inom tysk blues, och visar en konsekvens över tid som få samtida artister matchar (Källa: de.wikipedia.org/wiki/Abi_Wallenstein). Genom BluesCulture och en lång rad samarbeten — med Steve Baker, Henry Heggen, Joja Wendt, Martin Röttger med flera — har han också fungerat som en brobyggare som lyft fram yngre musiker i sitt eget nätverk (Källa: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de).', 'Mit fast sechs Jahrzehnten auf der Bühne ist Abi Wallenstein zum Fundament der Hamburger Bluesszene geworden — von Kritikern als "Vater der Hamburger Bluesszene" bezeichnet und ein ständiger Bezugspunkt für deutsche Musiker, die selbst nach seinem Vorbild Bass, Rhythmus und Melodie gleichzeitig auf der Gitarre spielen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein). Neun Siege in der Kategorie Solo/Duo beim German Blues Award zwischen 2011 und 2021 sind ein Rekord ohne Beispiel im deutschen Blues und zeigen eine Konstanz über die Zeit, die nur wenige zeitgenössische Künstler erreichen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein). Durch BluesCulture und eine lange Reihe von Kollaborationen — mit Steve Baker, Henry Heggen, Joja Wendt, Martin Röttger und anderen — hat er zudem als Brückenbauer gewirkt, der jüngere Musiker in seinem eigenen Netzwerk gefördert hat (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de).', 'Z niemal sześcioma dekadami na scenie Abi Wallenstein stał się fundamentem hamburskiej sceny bluesowej — nazywany przez krytyków "ojcem hamburskiej sceny bluesowej" i stałym punktem odniesienia dla niemieckich muzyków, którzy sami zaczęli grać na gitarze bas, rytm i melodię jednocześnie na jego wzór (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein). Dziewięć zwycięstw w kategorii Solo/Duet na German Blues Award w latach 2011–2021 to rekord niemający odpowiednika w niemieckim bluesie, pokazujący konsekwencję w czasie, której dorównuje niewielu współczesnych artystów (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein). Poprzez BluesCulture i długi szereg współprac — ze Steve''em Bakerem, Henrym Heggenem, Joją Wendtem, Martinem Röttgerem i innymi — pełnił także rolę budowniczego mostów, wspierając młodszych muzyków w swojej sieci (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de).', '{"no":["Mein Stil & Sound — AUF DEM ROTEN STUHL (Kilde: YouTube, mediagroove.de)"],"en":["Mein Stil & Sound — AUF DEM ROTEN STUHL (Source: YouTube, mediagroove.de)"],"sv":["Mein Stil & Sound — AUF DEM ROTEN STUHL (Källa: YouTube, mediagroove.de)"],"de":["Mein Stil & Sound — AUF DEM ROTEN STUHL (Quelle: YouTube, mediagroove.de)"],"pl":["Mein Stil & Sound — AUF DEM ROTEN STUHL (Źródło: YouTube, mediagroove.de)"]}', '[]', '["Vocals","Eight-string guitar","Slide guitar"]', '["Piedmont Blues","Delta Blues","Slide Guitar Blues"]', '["Classic","Germany"]', '["Abi Wallenstein","Hamburg blues","BluesCulture","German blues"]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":["1945: Født 8. desember i Jerusalem, sønn av tyske jøder som flyktet under naziregimet (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein).","1960: Familien flytter tilbake til Tyskland, først til Nordrhein-Westfalen (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein).","Midten av 1960-tallet: Flytter til Hamburg, som forblir hans base (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein).","1966: Debuterer som bluestolker på scenen (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein)."],"en":["1945: Born 8 December in Jerusalem, son of German Jews who fled during the Nazi era (Source: de.wikipedia.org/wiki/Abi_Wallenstein).","1960: The family moves back to Germany, first to North Rhine-Westphalia (Source: de.wikipedia.org/wiki/Abi_Wallenstein).","Mid-1960s: Moves to Hamburg, which remains his base (Source: de.wikipedia.org/wiki/Abi_Wallenstein).","1966: Debuts on stage as a blues interpreter (Source: de.wikipedia.org/wiki/Abi_Wallenstein)."],"sv":["1945: Född 8 december i Jerusalem, son till tyska judar som flydde under nazitiden (Källa: de.wikipedia.org/wiki/Abi_Wallenstein).","1960: Familjen flyttar tillbaka till Tyskland, först till Nordrhein-Westfalen (Källa: de.wikipedia.org/wiki/Abi_Wallenstein).","Mitten av 1960-talet: Flyttar till Hamburg, som förblir hans bas (Källa: de.wikipedia.org/wiki/Abi_Wallenstein).","1966: Debuterar på scen som bluestolkare (Källa: de.wikipedia.org/wiki/Abi_Wallenstein)."],"de":["1945: Geboren am 8. Dezember in Jerusalem, Sohn deutscher Juden, die während der NS-Zeit flohen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein).","1960: Die Familie kehrt nach Deutschland zurück, zunächst nach Nordrhein-Westfalen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein).","Mitte der 1960er: Umzug nach Hamburg, das seine Basis bleibt (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein).","1966: Bühnendebüt als Blues-Interpret (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein)."],"pl":["1945: Urodzony 8 grudnia w Jerozolimie, syn niemieckich Żydów, którzy uciekli w czasach nazistowskich (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein).","1960: Rodzina wraca do Niemiec, najpierw do Nadrenii Północnej-Westfalii (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein).","Połowa lat 60.: Przeprowadzka do Hamburga, który pozostaje jego bazą (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein).","1966: Debiut sceniczny jako interpretator bluesa (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein)."]}', '{"no":[{"category":"Gitar","name":"Åttestrengs gitar, stemt i åpen G","note":"Inspirert av Big Joe Williams; lar Wallenstein spille bass, rytme og melodi samtidig (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein).","years":"1966–i dag"}],"en":[{"category":"Gitar","name":"Eight-string guitar, tuned in open G","note":"Inspired by Big Joe Williams; lets Wallenstein play bass, rhythm and melody simultaneously (Source: de.wikipedia.org/wiki/Abi_Wallenstein).","years":"1966–present"}],"sv":[{"category":"Gitar","name":"Åttasträngad gitarr, stämd i öppen G","note":"Inspirerad av Big Joe Williams; låter Wallenstein spela bas, rytm och melodi samtidigt (Källa: de.wikipedia.org/wiki/Abi_Wallenstein).","years":"1966–idag"}],"de":[{"category":"Gitar","name":"Achtsaitige Gitarre, in offenem G gestimmt","note":"Inspiriert von Big Joe Williams; ermöglicht Wallenstein, Bass, Rhythmus und Melodie gleichzeitig zu spielen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein).","years":"1966–heute"}],"pl":[{"category":"Gitar","name":"Ośmiostrunowa gitara, strojona w otwartym G","note":"Zainspirowana Big Joe Williamsem; pozwala Wallensteinowi grać bas, rytm i melodię jednocześnie (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein).","years":"1966–obecnie"}]}', '{"no":["I 2001 spilte han en veldedighetskonsert for hjemløse uten honorar (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein).","Han bor sammen med scenekunstner og regissør Maryn Stucken (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein)."],"en":["In 2001 he played a benefit concert for homeless people without payment (Source: de.wikipedia.org/wiki/Abi_Wallenstein).","He lives with stage author and director Maryn Stucken (Source: de.wikipedia.org/wiki/Abi_Wallenstein)."],"sv":["2001 spelade han en välgörenhetskonsert för hemlösa utan arvode (Källa: de.wikipedia.org/wiki/Abi_Wallenstein).","Han bor tillsammans med scenförfattaren och regissören Maryn Stucken (Källa: de.wikipedia.org/wiki/Abi_Wallenstein)."],"de":["2001 spielte er ohne Honorar ein Benefizkonzert für Obdachlose (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein).","Er lebt mit der Bühnenautorin und Regisseurin Maryn Stucken zusammen (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein)."],"pl":["W 2001 roku zagrał charytatywny koncert dla bezdomnych bez wynagrodzenia (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein).","Mieszka z autorką sceniczną i reżyserką Maryn Stucken (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein)."]}', '{"no":[{"name":"Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber, Gottfried Böttger","note":"Hamburgske blues- og boogiemusikere Wallenstein har opptrådt sammen med gjentatte ganger (Kilde: de.wikipedia.org/wiki/Abi_Wallenstein)."},{"name":"Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford, George Thorogood","note":"Internasjonale artister Wallenstein har vært forband for (Kilde: abiwallenstein.de)."}],"en":[{"name":"Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber, Gottfried Böttger","note":"Hamburg blues and boogie musicians Wallenstein has repeatedly performed with (Source: de.wikipedia.org/wiki/Abi_Wallenstein)."},{"name":"Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford, George Thorogood","note":"International artists Wallenstein has opened for (Source: abiwallenstein.de)."}],"sv":[{"name":"Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber, Gottfried Böttger","note":"Hamburgska blues- och boogiemusiker Wallenstein upprepade gånger uppträtt med (Källa: de.wikipedia.org/wiki/Abi_Wallenstein)."},{"name":"Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford, George Thorogood","note":"Internationella artister Wallenstein varit förband åt (Källa: abiwallenstein.de)."}],"de":[{"name":"Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber, Gottfried Böttger","note":"Hamburger Blues- und Boogie-Musiker, mit denen Wallenstein wiederholt aufgetreten ist (Quelle: de.wikipedia.org/wiki/Abi_Wallenstein)."},{"name":"Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford, George Thorogood","note":"Internationale Künstler, für die Wallenstein als Vorgruppe spielte (Quelle: abiwallenstein.de)."}],"pl":[{"name":"Joja Wendt, Inga Rumpf, Axel Zwingenberger, Tom Shaka, Vince Weber, Gottfried Böttger","note":"Hamburscy muzycy bluesowi i boogie, z którymi Wallenstein wielokrotnie występował (Źródło: de.wikipedia.org/wiki/Abi_Wallenstein)."},{"name":"Joe Cocker, Eric Burdon, Johnny Winter, Fats Domino, Robben Ford, George Thorogood","note":"Artyści międzynarodowi, dla których Wallenstein grał jako support (Źródło: abiwallenstein.de)."}]}', '[{"kind":"featured","title":"AUF DEM ROTEN STUHL - Abi Wallenstein - Mein Stil & Sound","youtube_id":"wnKf3KwkLIM","channel":"mediagroove.de"},{"kind":"more","title":"AUF DEM ROTEN STUHL - Abi Wallenstein spielt den Blues","youtube_id":"zyN-JwAl99U","channel":"mediagroove.de"},{"kind":"more","title":"ABI WALLENSTEIN und Freunde im Zwick 2019","youtube_id":"6ho5-0pL6ak","channel":"YouTube"}]', '{"no":[{"year":1978,"title":"Live im Logo (Bad News Reunion)","label":"LP","notes":"Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de."},{"year":1980,"title":"The Easiest Way (Bad News Reunion)","label":"LP","notes":"Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de."},{"year":1981,"title":"Two Steps Forward (Bad News Reunion)","label":"LP","notes":"Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de."},{"year":1982,"title":"Last Orders Please (Bad News Reunion)","label":"LP","notes":"Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de."},{"year":1989,"title":"Just One Night (Bad News Reunion)","label":"LP","notes":"Kilde: de.wikipedia.org/wiki/Abi_Wallenstein; abiwallenstein.de."},{"year":1989,"title":"Rockin'' Shoes (Abi Wallenstein mit Uli Kringler, Christoph Buse, Stefan Gade)","label":"LP","