INSERT INTO artists (id, slug, name, alt_name, tag, era, region, country, img, og_image, image_credit, gallery_images, youtube_video_ids, short_no, short_en, short_sv, short_de, short_pl, biography_no, biography_en, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_no, influence_en, influence_sv, influence_de, influence_pl, signature_songs_i18n, labels, instruments_simple, styles, categories, search_terms, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, awards_i18n, press_quotes_i18n, external_links, article_references, social_links, website_url, facebook_url, booking_info, sort_order) VALUES ('f4444bf1-f855-43a9-bea6-8f49fc1cccc6', 'bb-and-the-blues-shacks', 'B.B. & The Blues Shacks', 'The Blues Shacks', 'Classic', 'Modern Era', 'Europe', 'Germany', 'https://bluesshacks.de/images/jdownloads/screenshots/BB-Promo2025_thumb0.png', 'https://bluesshacks.de/images/jdownloads/screenshots/bluesshacks_2021_01www.jpg', 'Foto: Clemens Heidrich (2025) / Felix Engel, diefotofabrik.de (Kilde: bluesshacks.de/de/download.html)', '[]', '["9oIdnNORPF4","d5lymr-lvw8","KMo-mRNvMk0","OA97TDmpLGw"]', 'Bluesband fra Hildesheim (1989–), over 3000 konserter på fem kontinenter, tre ganger vinner av Trophée France Blues.', 'Blues band from Hildesheim (1989–), over 3,000 concerts on five continents, three-time Trophée France Blues winner.', 'Bluesband från Hildesheim (1989–), över 3000 konserter på fem kontinenter, tre gånger vinnare av Trophée France Blues.', 'Bluesband aus Hildesheim (1989–), über 3000 Konzerte auf fünf Kontinenten, dreifacher Gewinner der Trophée France Blues.', 'Zespół bluesowy z Hildesheim (1989–), ponad 3000 koncertów na pięciu kontynentach, trzykrotny zdobywca Trophée France Blues.', 'B.B. & The Blues Shacks ble dannet i august 1989 i Lamspringe utenfor Hildesheim, av gitarist Andreas Arlt, trommeslager Andreas Bock og bassist Martin Schlockwerder — alle tidligere medlemmer av bandet Boogie Bock and die Beinharten. Samme måned kom Andreas'' bror Michael Arlt inn som vokalist og munnspillspiller (Kilde: de.wikipedia.org/wiki/B._B._%26_The_Blues_Shacks). Navnet peker både mot deres musikalske slektskap med B.B. King og trommeslagerens kallenavn «Boogie Bock» (Kilde: de.wikipedia.org). Gjennombruddet kom da bandet steppet inn for Sherman Robertson på Breminale-festivalen 20. mai 1994, noe som fanget interessen til Thomas Ritter i Stumble Records og førte til debutalbumet «Feelin'' Fine Today» samme år (Kilde: de.wikipedia.org). Siden har bandet gitt ut over tjue album — blant dem «Jive Talk, Slow Walk» (1995, med Chicago-bassisten Mike McCurdy), «Reality Show» (1997, spilt inn i California med produsent Richard Duran), «Midnite Diner» (2001, etter kontrakt med CrossCut Records), «Unique Taste» (2008, på Preis der deutschen Schallplattenkritiks kritikerliste), «London Days» (2010, bandets første vinyl-LP), «Businessmen» (2014), «Dirty Thirty» (2019) og «Breaking Point» (2021), fram til «Blues Is A Stew» (2026, Rhythm Bomb Records) (Kilde: de.wikipedia.org; bluesshacks.de). Dagens besetning er Michael Arlt (vokal, munnspill, siden 1989), Andreas Arlt (gitar, grunnlegger), Henning Hauerken (bass, siden 1996), Fabian Fritz (piano/orgel, siden 2015) og Andre Werkmeister (trommer, siden 2014) (Kilde: bluesshacks.de/de/14-deutsch/about/band.html). Med over 3000 konserter i Tyskland, Europa, USA, Dubai, Australia og Sør-Afrika har bandet delt scene med B.B. King, James Cotton, Elvis Costello, Kid Ramos og Bob Dylan (Kilde: de.wikipedia.org). De vant Trophée France Blues for beste europeiske bluesband i 2003, 2004 og 2005 (Andreas Arlt fikk samtidig prisen for beste europeiske bluesgitarist), fikk «DVD of the Year» for «Live at Vier Linden» av bluesnews og østerrikske Concerto i 2007, vant German Blues Award i 2010, 2011, 2013 og to priser i 2015 (beste band og beste innspilling for «Businessmen»), og ble kåret til «Artist Of The Year» av The Blues Lounge Radio Show i 2020 (Kilde: de.wikipedia.org). Gitarist Andreas Arlt har sagt: «Hvis gitaren er for høy, er du for svak!», mens bassist Henning Hauerken sier: «Når føttene begynner å trampe og ingen klarer å sitte stille, har jeg nådd målet mitt» (Kilde: bluesshacks.de/de/14-deutsch/about/band.html).', 'B.B. & The Blues Shacks were formed in August 1989 in Lamspringe near Hildesheim by guitarist Andreas Arlt, drummer Andreas Bock and bassist Martin Schlockwerder — all former members of the band Boogie Bock and die Beinharten. That same month Andreas''s brother Michael Arlt joined as vocalist and harmonica player (Source: de.wikipedia.org/wiki/B._B._%26_The_Blues_Shacks). The name nods both to the band''s musical kinship with B.B. King and to the drummer''s nickname "Boogie Bock" (Source: de.wikipedia.org). Their breakthrough came when the band stepped in for Sherman Robertson at the Breminale festival on 20 May 1994, catching the attention of Thomas Ritter of Stumble Records and leading to the debut album "Feelin'' Fine Today" the same year (Source: de.wikipedia.org). Since then the band has released more than twenty albums — among them "Jive Talk, Slow Walk" (1995, with Chicago bassist Mike McCurdy), "Reality Show" (1997, recorded in California with producer Richard Duran), "Midnite Diner" (2001, after signing to CrossCut Records), "Unique Taste" (2008, making the Preis der deutschen Schallplattenkritik critics'' list), "London Days" (2010, the band''s first vinyl LP), "Businessmen" (2014), "Dirty Thirty" (2019) and "Breaking Point" (2021), up to "Blues Is A Stew" (2026, Rhythm Bomb Records) (Source: de.wikipedia.org; bluesshacks.de). Today''s line-up is Michael Arlt (vocals, harmonica, since 1989), Andreas Arlt (guitar, founder), Henning Hauerken (bass, since 1996), Fabian Fritz (piano/organ, since 2015) and Andre Werkmeister (drums, since 2014) (Source: bluesshacks.de/de/14-deutsch/about/band.html). With more than 3,000 concerts across Germany, Europe, the USA, Dubai, Australia and South Africa, the band has shared the stage with B.B. King, James Cotton, Elvis Costello, Kid Ramos and Bob Dylan (Source: de.wikipedia.org). They won the Trophée France Blues for Best European Blues Band in 2003, 2004 and 2005 (with Andreas Arlt simultaneously winning Best European Blues Guitarist), had "Live at Vier Linden" named "DVD of the Year" by bluesnews and Austria''s Concerto in 2007, won the German Blues Award in 2010, 2011, 2013 and twice in 2015 (Best Band and Best Recording for "Businessmen"), and were named "Artist Of The Year" by The Blues Lounge Radio Show in 2020 (Source: de.wikipedia.org). Guitarist Andreas Arlt has said: "If the guitar is too loud, you are too weak!", while bassist Henning Hauerken says: "When feet start tapping and nobody can sit still, I''ve reached my goal!" (Source: bluesshacks.de/de/14-deutsch/about/band.html).', 'B.B. & The Blues Shacks bildades i augusti 1989 i Lamspringe utanför Hildesheim av gitarristen Andreas Arlt, trummisen Andreas Bock och basisten Martin Schlockwerder — alla tidigare medlemmar i bandet Boogie Bock and die Beinharten. Samma månad kom Andreas bror Michael Arlt in som sångare och munspelare (Källa: de.wikipedia.org/wiki/B._B._%26_The_Blues_Shacks). Namnet syftar både på bandets musikaliska släktskap med B.B. King och trummisens smeknamn "Boogie Bock" (Källa: de.wikipedia.org). Genombrottet kom när bandet hoppade in för Sherman Robertson på Breminale-festivalen den 20 maj 1994, vilket fångade intresset hos Thomas Ritter på Stumble Records och ledde till debutalbumet "Feelin'' Fine Today" samma år (Källa: de.wikipedia.org). Sedan dess har bandet gett ut mer än tjugo album — bland dem "Jive Talk, Slow Walk" (1995, med Chicagobasisten Mike McCurdy), "Reality Show" (1997, inspelat i Kalifornien med producenten Richard Duran), "Midnite Diner" (2001, efter kontrakt med CrossCut Records), "Unique Taste" (2008, på Preis der deutschen Schallplattenkritiks kritikerlista), "London Days" (2010, bandets första vinyl-LP), "Businessmen" (2014), "Dirty Thirty" (2019) och "Breaking Point" (2021), fram till "Blues Is A Stew" (2026, Rhythm Bomb Records) (Källa: de.wikipedia.org; bluesshacks.de). Dagens sättning är Michael Arlt (sång, munspel, sedan 1989), Andreas Arlt (gitarr, grundare), Henning Hauerken (bas, sedan 1996), Fabian Fritz (piano/orgel, sedan 2015) och Andre Werkmeister (trummor, sedan 2014) (Källa: bluesshacks.de/de/14-deutsch/about/band.html). Med över 3000 konserter i Tyskland, Europa, USA, Dubai, Australien och Sydafrika har bandet delat scen med B.B. King, James Cotton, Elvis Costello, Kid Ramos och Bob Dylan (Källa: de.wikipedia.org). De vann Trophée France Blues för bästa europeiska bluesband 2003, 2004 och 2005 (Andreas Arlt fick samtidigt priset för bästa europeiska bluesgitarrist), fick "DVD of the Year" för "Live at Vier Linden" av bluesnews och österrikiska Concerto 2007, vann German Blues Award 2010, 2011, 2013 och två priser 2015 (bästa band och bästa inspelning för "Businessmen"), och utsågs till "Artist Of The Year" av The Blues Lounge Radio Show 2020 (Källa: de.wikipedia.org). Gitarristen Andreas Arlt har sagt: "Om gitarren är för hög är du för svag!", medan basisten Henning Hauerken säger: "När fötterna börjar trampa och ingen kan sitta still har jag nått mitt mål!" (Källa: bluesshacks.de/de/14-deutsch/about/band.html).', 'B.B. & The Blues Shacks wurden im August 1989 in Lamspringe bei Hildesheim gegründet, von Gitarrist Andreas Arlt, Schlagzeuger Andreas Bock und Bassist Martin Schlockwerder — allesamt ehemalige Mitglieder der Band Boogie Bock and die Beinharten. Im selben Monat stieß Andreas'' Bruder Michael Arlt als Sänger und Mundharmonikaspieler dazu (Quelle: de.wikipedia.org/wiki/B._B._%26_The_Blues_Shacks). Der Name verweist sowohl auf die musikalische Verwandtschaft der Band mit B.B. King als auch auf den Spitznamen des Schlagzeugers, "Boogie Bock" (Quelle: de.wikipedia.org). Der Durchbruch gelang, als die Band am 20. Mai 1994 beim Breminale-Festival für Sherman Robertson einsprang und damit die Aufmerksamkeit von Thomas Ritter von Stumble Records auf sich zog, was zum Debütalbum "Feelin'' Fine Today" im selben Jahr führte (Quelle: de.wikipedia.org). Seither hat die Band mehr als zwanzig Alben veröffentlicht — darunter "Jive Talk, Slow Walk" (1995, mit dem Chicagoer Bassisten Mike McCurdy), "Reality Show" (1997, aufgenommen in Kalifornien mit Produzent Richard Duran), "Midnite Diner" (2001, nach Vertragsabschluss mit CrossCut Records), "Unique Taste" (2008, auf der Kritikerliste des Preises der deutschen Schallplattenkritik), "London Days" (2010, die erste Vinyl-LP der Band), "Businessmen" (2014), "Dirty Thirty" (2019) und "Breaking Point" (2021), bis hin zu "Blues Is A Stew" (2026, Rhythm Bomb Records) (Quelle: de.wikipedia.org; bluesshacks.de). Die heutige Besetzung ist Michael Arlt (Gesang, Mundharmonika, seit 1989), Andreas Arlt (Gitarre, Gründer), Henning Hauerken (Bass, seit 1996), Fabian Fritz (Klavier/Orgel, seit 2015) und Andre Werkmeister (Schlagzeug, seit 2014) (Quelle: bluesshacks.de/de/14-deutsch/about/band.html). Mit über 3000 Konzerten in Deutschland, Europa, den USA, Dubai, Australien und Südafrika stand die Band gemeinsam mit B.B. King, James Cotton, Elvis Costello, Kid Ramos und Bob Dylan auf der Bühne (Quelle: de.wikipedia.org). Sie gewannen die Trophée France Blues als beste europäische Bluesband 2003, 2004 und 2005 (Andreas Arlt gewann gleichzeitig den Preis als bester europäischer Bluesgitarrist), erhielten 2007 "DVD of the Year" für "Live at Vier Linden" von bluesnews und dem österreichischen Concerto, gewannen den German Blues Award 2010, 2011, 2013 und gleich zweimal 2015 (Beste Band und Beste Aufnahme für "Businessmen"), und wurden 2020 von The Blues Lounge Radio Show zum "Artist Of The Year" gekürt (Quelle: de.wikipedia.org). Gitarrist Andreas Arlt sagte einmal: "Wenn die Gitarre zu laut ist, bist du zu schwach!", während Bassist Henning Hauerken sagt: "Wenn die Füße zu wippen anfangen und niemand still sitzen kann, habe ich mein Ziel erreicht!" (Quelle: bluesshacks.de/de/14-deutsch/about/band.html).', 'B.B. & The Blues Shacks powstali w sierpniu 1989 roku w Lamspringe pod Hildesheim, założeni przez gitarzystę Andreasa Arlta, perkusistę Andreasa Bocka i basistę Martina Schlockwerdera — wszyscy byli wcześniej członkami zespołu Boogie Bock and die Beinharten. W tym samym miesiącu dołączył brat Andreasa, Michael Arlt, jako wokalista i harmonijkarz (Źródło: de.wikipedia.org/wiki/B._B._%26_The_Blues_Shacks). Nazwa nawiązuje zarówno do muzycznego pokrewieństwa zespołu z B.B. Kingiem, jak i do przezwiska perkusisty "Boogie Bock" (Źródło: de.wikipedia.org). Przełom nastąpił, gdy zespół zastąpił Shermana Robertsona na festiwalu Breminale 20 maja 1994 roku, co zwróciło uwagę Thomasa Rittera z Stumble Records i doprowadziło do wydania debiutanckiego albumu "Feelin'' Fine Today" w tym samym roku (Źródło: de.wikipedia.org). Od tego czasu zespół wydał ponad dwadzieścia albumów — wśród nich "Jive Talk, Slow Walk" (1995, z chicagowskim basistą Mikiem McCurdym), "Reality Show" (1997, nagrany w Kalifornii z producentem Richardem Duranem), "Midnite Diner" (2001, po podpisaniu kontraktu z CrossCut Records), "Unique Taste" (2008, na liście krytyków Preis der deutschen Schallplattenkritik), "London Days" (2010, pierwsza płyta winylowa zespołu), "Businessmen" (2014), "Dirty Thirty" (2019) i "Breaking Point" (2021), aż po "Blues Is A Stew" (2026, Rhythm Bomb Records) (Źródło: de.wikipedia.org; bluesshacks.de). Obecny skład to Michael Arlt (wokal, harmonijka, od 1989), Andreas Arlt (gitara, założyciel), Henning Hauerken (bas, od 1996), Fabian Fritz (fortepian/organy, od 2015) i Andre Werkmeister (perkusja, od 2014) (Źródło: bluesshacks.de/de/14-deutsch/about/band.html). Z ponad 3000 koncertów w Niemczech, Europie, USA, Dubaju, Australii i Republice Południowej Afryki zespół dzielił scenę z B.B. Kingiem, Jamesem Cottonem, Elvisem Costello, Kid Ramosem i Bobem Dylanem (Źródło: de.wikipedia.org). Zdobyli Trophée France Blues dla najlepszego europejskiego zespołu bluesowego w 2003, 2004 i 2005 roku (Andreas Arlt jednocześnie zdobył nagrodę dla najlepszego europejskiego gitarzysty bluesowego), otrzymali tytuł "DVD roku" za "Live at Vier Linden" od bluesnews i austriackiego Concerto w 2007 roku, zdobyli German Blues Award w 2010, 2011, 2013 roku i dwukrotnie w 2015 roku (najlepszy zespół i najlepsze nagranie za "Businessmen"), a w 2020 roku zostali uznani za "Artystę Roku" przez The Blues Lounge Radio Show (Źródło: de.wikipedia.org). Gitarzysta Andreas Arlt powiedział kiedyś: "Jeśli gitara jest za głośna, jesteś za słaby!", a basista Henning Hauerken mówi: "Kiedy stopy zaczynają tupać i nikt nie może usiedzieć spokojnie, osiągnąłem swój cel!" (Źródło: bluesshacks.de/de/14-deutsch/about/band.html).', NULL, NULL, NULL, NULL, 'Hildesheim, Niedersachsen, Germany', '1989–present', 'Med over tre tiår og mer enn 3000 konserter på fem kontinenter er B.B. & The Blues Shacks blant de mest turnerte og internasjonalt anerkjente bluesbandene Tyskland har produsert, med tre strake Trophée France Blues-seire (2003–2005) og status som fast innslag på blueskalenderen fra Notodden til Byron Bay (Kilde: de.wikipedia.org). At de har delt scene med selveste B.B. King, James Cotton og Bob Dylan, plasserer dem i en unik posisjon som brobyggere mellom den klassiske amerikanske Chicago-/R&B-tradisjonen og et europeisk bluespublikum (Kilde: de.wikipedia.org). Deres eget Blues Shacks Festival i Hildesheim, startet i 1999, har blitt et fast holdepunkt i den internasjonale bluesterminen og viser hvordan bandet aktivt har bygget infrastruktur for sjangeren i hjemlandet, ikke bare turnert i den (Kilde: de.wikipedia.org).', 'With over three decades and more than 3,000 concerts across five continents, B.B. & The Blues Shacks are among the most-touring and internationally recognised blues bands Germany has produced, with three straight Trophée France Blues wins (2003–2005) and a fixture status on the blues calendar from Notodden to Byron Bay (Source: de.wikipedia.org). Having shared stages with B.B. King himself, James Cotton and Bob Dylan places them in a unique position as bridge-builders between the classic American Chicago/R&B tradition and a European blues audience (Source: de.wikipedia.org). Their own Blues Shacks Festival in Hildesheim, launched in 1999, has become a fixture on the international blues calendar and shows how the band has actively built infrastructure for the genre at home, not just toured through it (Source: de.wikipedia.org).', 'Med över tre decennier och mer än 3000 konserter på fem kontinenter är B.B. & The Blues Shacks bland de mest turnerande och internationellt erkända bluesbanden Tyskland har producerat, med tre raka Trophée France Blues-segrar (2003–2005) och status som ett fast inslag på bluesagendan från Notodden till Byron Bay (Källa: de.wikipedia.org). Att de delat scen med B.B. King själv, James Cotton och Bob Dylan placerar dem i en unik position som brobyggare mellan den klassiska amerikanska Chicago-/R&B-traditionen och en europeisk bluespublik (Källa: de.wikipedia.org). Deras egen Blues Shacks Festival i Hildesheim, som startade 1999, har blivit ett fast inslag i den internationella blueskalendern och visar hur bandet aktivt byggt infrastruktur för genren hemma, inte bara turnerat i den (Källa: de.wikipedia.org).', 'Mit über drei Jahrzehnten und mehr als 3000 Konzerten auf fünf Kontinenten gehören B.B. & The Blues Shacks zu den meistgetourten und international bekanntesten Bluesbands, die Deutschland hervorgebracht hat, mit drei aufeinanderfolgenden Trophée-France-Blues-Siegen (2003–2005) und einem festen Platz im Blueskalender von Notodden bis Byron Bay (Quelle: de.wikipedia.org). Dass sie mit B.B. King persönlich, James Cotton und Bob Dylan auf der Bühne standen, verschafft ihnen eine einzigartige Position als Brückenbauer zwischen der klassischen amerikanischen Chicago-/R&B-Tradition und einem europäischen Bluespublikum (Quelle: de.wikipedia.org). Ihr eigenes Blues Shacks Festival in Hildesheim, 1999 gegründet, ist zu einem festen Bestandteil des internationalen Bluesterminkalenders geworden und zeigt, wie die Band aktiv Infrastruktur für das Genre zu Hause aufgebaut hat, statt nur hindurchzutouren (Quelle: de.wikipedia.org).', 'Z ponad trzema dekadami i ponad 3000 koncertów na pięciu kontynentach B.B. & The Blues Shacks należą do najbardziej koncertujących i uznanych na arenie międzynarodowej zespołów bluesowych, jakie wydały Niemcy, z trzema kolejnymi zwycięstwami w Trophée France Blues (2003–2005) i stałym miejscem w kalendarzu bluesowym od Notodden po Byron Bay (Źródło: de.wikipedia.org). Fakt, że dzielili scenę z samym B.B. Kingiem, Jamesem Cottonem i Bobem Dylanem, stawia ich w wyjątkowej pozycji budowniczych mostów między klasyczną amerykańską tradycją Chicago/R&B a europejską publicznością bluesową (Źródło: de.wikipedia.org). Ich własny Blues Shacks Festival w Hildesheim, zapoczątkowany w 1999 roku, stał się stałym punktem międzynarodowego kalendarza bluesowego i pokazuje, jak zespół aktywnie budował infrastrukturę dla gatunku we własnym kraju, a nie tylko go objeżdżał (Źródło: de.wikipedia.org).', '{"no":["Blues Is A Stew (Kilde: YouTube offisiell video)","Whatever You Do (feat. Bonita) (Kilde: YouTube offisiell video)","The Last Time (Kilde: YouTube offisiell video)"],"en":["Blues Is A Stew (Source: YouTube official video)","Whatever You Do (feat. Bonita) (Source: YouTube official video)","The Last Time (Source: YouTube official video)"],"sv":["Blues Is A Stew (Källa: YouTube officiell video)","Whatever You Do (feat. Bonita) (Källa: YouTube officiell video)","The Last Time (Källa: YouTube officiell video)"],"de":["Blues Is A Stew (Quelle: offizielles YouTube-Video)","Whatever You Do (feat. Bonita) (Quelle: offizielles YouTube-Video)","The Last Time (Quelle: offizielles YouTube-Video)"],"pl":["Blues Is A Stew (Źródło: oficjalny film YouTube)","Whatever You Do (feat. Bonita) (Źródło: oficjalny film YouTube)","The Last Time (Źródło: oficjalny film YouTube)"]}', '["Rhythm Bomb Records","CrossCut Records","Stumble Records"]', '["Vocals","Harmonica","Guitar","Bass","Piano","Organ","Drums"]', '["Chicago Blues","R&B","Jump Blues","Swing"]', '["Classic","Germany"]', '["B.B. & The Blues Shacks","Blues Shacks","Hildesheim blues","German blues"]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":["August 1989: Bandet dannes i Lamspringe ved Hildesheim (Kilde: de.wikipedia.org).","20. mai 1994: Steppet inn for Sherman Robertson på Breminale-festivalen — gjennombruddskonserten som førte til platekontrakt (Kilde: de.wikipedia.org).","1999: Etablerer sitt eget Blues Shacks Festival i Hildesheim (Kilde: de.wikipedia.org)."],"en":["August 1989: The band forms in Lamspringe near Hildesheim (Source: de.wikipedia.org).","20 May 1994: Steps in for Sherman Robertson at the Breminale festival — the breakthrough gig that led to a record deal (Source: de.wikipedia.org).","1999: Establishes their own Blues Shacks Festival in Hildesheim (Source: de.wikipedia.org)."],"sv":["Augusti 1989: Bandet bildas i Lamspringe utanför Hildesheim (Källa: de.wikipedia.org).","20 maj 1994: Hoppar in för Sherman Robertson på Breminale-festivalen — genombrottsspelningen som ledde till skivkontrakt (Källa: de.wikipedia.org).","1999: Grundar sin egen Blues Shacks Festival i Hildesheim (Källa: de.wikipedia.org)."],"de":["August 1989: Die Band gründet sich in Lamspringe bei Hildesheim (Quelle: de.wikipedia.org).","20. Mai 1994: Springt beim Breminale-Festival für Sherman Robertson ein — der Durchbruchsauftritt, der zum Plattenvertrag führte (Quelle: de.wikipedia.org).","1999: Gründet das eigene Blues Shacks Festival in Hildesheim (Quelle: de.wikipedia.org)."],"pl":["Sierpień 1989: Zespół powstaje w Lamspringe pod Hildesheim (Źródło: de.wikipedia.org).","20 maja 1994: Zastępuje Shermana Robertsona na festiwalu Breminale — przełomowy koncert, który doprowadził do kontraktu płytowego (Źródło: de.wikipedia.org).","1999: Zakłada własny Blues Shacks Festival w Hildesheim (Źródło: de.wikipedia.org)."]}', '{"no":[{"category":"Gitar","name":"Elektrisk gitar (Andreas Arlt)","note":"Grunnlegger og komponist av bandets originallåter; kalt en «vandrende blues-encyklopedi» (Kilde: bluesshacks.de/de/14-deutsch/about/band.html).","years":"1989–i dag"},{"category":"Annet","name":"Kontrabass/elbass (Henning Hauerken)","note":"Kjent for sjelden bruk av kontrabass som signaturlyd, i senere år også elbass med referanser til 60-talls soul/R&B (Kilde: de.wikipedia.org).","years":"1996–i dag"}],"en":[{"category":"Gitar","name":"Electric guitar (Andreas Arlt)","note":"Founder and composer of the band''s original songs; called a \"walking blues encyclopedia\" (Source: bluesshacks.de/de/14-deutsch/about/band.html).","years":"1989–present"},{"category":"Annet","name":"Upright bass/electric bass (Henning Hauerken)","note":"Known for the rare use of upright bass as a signature sound, in later years also electric bass referencing 1960s soul/R&B (Source: de.wikipedia.org).","years":"1996–present"}],"sv":[{"category":"Gitar","name":"Elgitarr (Andreas Arlt)","note":"Grundare och kompositör av bandets originallåtar; kallad en \"vandrande blues-encyklopedi\" (Källa: bluesshacks.de/de/14-deutsch/about/band.html).","years":"1989–idag"},{"category":"Annet","name":"Kontrabas/elbas (Henning Hauerken)","note":"Känd för ovanlig användning av kontrabas som signaturljud, senare år även elbas med referenser till 60-talets soul/R&B (Källa: de.wikipedia.org).","years":"1996–idag"}],"de":[{"category":"Gitar","name":"E-Gitarre (Andreas Arlt)","note":"Gründer und Komponist der Originalsongs der Band; als \"wandelndes Blues-Lexikon\" bezeichnet (Quelle: bluesshacks.de/de/14-deutsch/about/band.html).","years":"1989–heute"},{"category":"Annet","name":"Kontrabass/E-Bass (Henning Hauerken)","note":"Bekannt für den seltenen Einsatz des Kontrabasses als Markenzeichen, in späteren Jahren auch E-Bass mit Anklängen an Soul/R&B der 1960er (Quelle: de.wikipedia.org).","years":"1996–heute"}],"pl":[{"category":"Gitar","name":"Gitara elektryczna (Andreas Arlt)","note":"Założyciel i kompozytor oryginalnych utworów zespołu; nazywany \"chodzącą encyklopedią bluesa\" (Źródło: bluesshacks.de/de/14-deutsch/about/band.html).","years":"1989–obecnie"},{"category":"Annet","name":"Kontrabas/gitara basowa (Henning Hauerken)","note":"Znany z rzadkiego stosowania kontrabasu jako charakterystycznego brzmienia, w późniejszych latach także gitara basowa nawiązująca do soulu/R&B lat 60. (Źródło: de.wikipedia.org).","years":"1996–obecnie"}]}', '{"no":["Bandets gjennombrudd kom nærmest tilfeldig: da Sherman Robertson måtte melde avbud på Breminale-festivalen 20. mai 1994, steppet B.B. & The Blues Shacks inn — og fanget dermed oppmerksomheten til Thomas Ritter i Stumble Records (Kilde: de.wikipedia.org).","I 2011 opptrådte bandet på tre kontinenter i løpet av fire måneder: Dubai Jazz Festival i januar, Byron Bay Bluesfest i Australia i april, og Doheny Blues Festival i California i mai (Kilde: de.wikipedia.org)."],"en":["The band''s breakthrough came almost by chance: when Sherman Robertson had to cancel at the Breminale festival on 20 May 1994, B.B. & The Blues Shacks stepped in — catching the attention of Thomas Ritter of Stumble Records (Source: de.wikipedia.org).","In 2011 the band performed on three continents within four months: Dubai Jazz Festival in January, Byron Bay Bluesfest in Australia in April, and Doheny Blues Festival in California in May (Source: de.wikipedia.org)."],"sv":["Bandets genombrott kom nästan av en slump: när Sherman Robertson fick ställa in på Breminale-festivalen den 20 maj 1994 hoppade B.B. & The Blues Shacks in — vilket fångade uppmärksamheten hos Thomas Ritter på Stumble Records (Källa: de.wikipedia.org).","2011 uppträdde bandet på tre kontinenter inom fyra månader: Dubai Jazz Festival i januari, Byron Bay Bluesfest i Australien i april och Doheny Blues Festival i Kalifornien i maj (Källa: de.wikipedia.org)."],"de":["Der Durchbruch der Band kam beinahe zufällig: Als Sherman Robertson beim Breminale-Festival am 20. Mai 1994 absagen musste, sprang B.B. & The Blues Shacks ein — und weckte damit das Interesse von Thomas Ritter von Stumble Records (Quelle: de.wikipedia.org).","2011 trat die Band innerhalb von vier Monaten auf drei Kontinenten auf: Dubai Jazz Festival im Januar, Byron Bay Bluesfest in Australien im April und Doheny Blues Festival in Kalifornien im Mai (Quelle: de.wikipedia.org)."],"pl":["Przełom zespołu nastąpił niemal przypadkiem: gdy Sherman Robertson musiał odwołać występ na festiwalu Breminale 20 maja 1994 roku, B.B. & The Blues Shacks zastąpili go na scenie — co zwróciło uwagę Thomasa Rittera z Stumble Records (Źródło: de.wikipedia.org).","W 2011 roku zespół wystąpił na trzech kontynentach w ciągu czterech miesięcy: Dubai Jazz Festival w styczniu, Byron Bay Bluesfest w Australii w kwietniu i Doheny Blues Festival w Kalifornii w maju (Źródło: de.wikipedia.org)."]}', '{"no":[{"name":"B.B. King, James Cotton, Elvis Costello, Kid Ramos, Bob Dylan","note":"Artister B.B. & The Blues Shacks har delt scene med (Kilde: de.wikipedia.org)."},{"name":"Mike McCurdy","note":"Chicago-bassist som medvirket på albumet «Jive Talk, Slow Walk» (1995) (Kilde: de.wikipedia.org)."},{"name":"Tad Robinson","note":"Amerikansk blues-/soulvokalist bandet turnerte med og spilte inn liveplate sammen med i 1998 (Kilde: de.wikipedia.org)."}],"en":[{"name":"B.B. King, James Cotton, Elvis Costello, Kid Ramos, Bob Dylan","note":"Artists B.B. & The Blues Shacks have shared the stage with (Source: de.wikipedia.org)."},{"name":"Mike McCurdy","note":"Chicago bassist who featured on the album \"Jive Talk, Slow Walk\" (1995) (Source: de.wikipedia.org)."},{"name":"Tad Robinson","note":"American blues/soul vocalist the band toured with and recorded a live album alongside in 1998 (Source: de.wikipedia.org)."}],"sv":[{"name":"B.B. King, James Cotton, Elvis Costello, Kid Ramos, Bob Dylan","note":"Artister B.B. & The Blues Shacks delat scen med (Källa: de.wikipedia.org)."},{"name":"Mike McCurdy","note":"Chicagobasist som medverkade på albumet \"Jive Talk, Slow Walk\" (1995) (Källa: de.wikipedia.org)."},{"name":"Tad Robinson","note":"Amerikansk blues-/soulsångare bandet turnerade med och spelade in liveskiva tillsammans med 1998 (Källa: de.wikipedia.org)."}],"de":[{"name":"B.B. King, James Cotton, Elvis Costello, Kid Ramos, Bob Dylan","note":"Künstler, mit denen B.B. & The Blues Shacks gemeinsam auf der Bühne standen (Quelle: de.wikipedia.org)."},{"name":"Mike McCurdy","note":"Chicagoer Bassist, der auf dem Album \"Jive Talk, Slow Walk\" (1995) mitwirkte (Quelle: de.wikipedia.org)."},{"name":"Tad Robinson","note":"Amerikanischer Blues-/Soulsänger, mit dem die Band tourte und 1998 ein Livealbum aufnahm (Quelle: de.wikipedia.org)."}],"pl":[{"name":"B.B. King, James Cotton, Elvis Costello, Kid Ramos, Bob Dylan","note":"Artyści, z którymi B.B. & The Blues Shacks dzielili scenę (Źródło: de.wikipedia.org)."},{"name":"Mike McCurdy","note":"Chicagowski basista, który wystąpił na albumie \"Jive Talk, Slow Walk\" (1995) (Źródło: de.wikipedia.org)."},{"name":"Tad Robinson","note":"Amerykański wokalista blues/soul, z którym zespół koncertował i nagrał album koncertowy w 1998 roku (Źródło: de.wikipedia.org)."}]}', '[{"kind":"featured","title":"B.B. & THE BLUES SHACKS - Blues Is A Stew","youtube_id":"9oIdnNORPF4","channel":"B.B. & The Blues Shacks"},{"kind":"more","title":"BB & The Blues Shacks feat. BONITA - Whatever You Do - Official Video","youtube_id":"d5lymr-lvw8","channel":"B.B. & The Blues Shacks"},{"kind":"more","title":"B.B. & THE BLUES SHACKS - The Last Time","youtube_id":"KMo-mRNvMk0","channel":"B.B. & The Blues Shacks"},{"kind":"more","title":"B.B. & The Blues Shacks - Jazztime Hildesheim 2024","youtube_id":"OA97TDmpLG