{"year":2007,"title":"Tacy sami","label":"Independent","notes":"Källa: pl.wikipedia.org."},{"year":2010,"title":"15 Cree","label":"Independent","notes":"Jubileumsalbum. Källa: pl.wikipedia.org."},{"year":2012,"title":"Diabli nadali","label":"Independent","notes":"Källa: pl.wikipedia.org."},{"year":2013,"title":"Wyjdź...","label":"Independent","notes":"Källa: pl.wikipedia.org."},{"year":2015,"title":"Heartbreaker","label":"Independent","notes":"Källa: pl.wikipedia.org."},{"year":2024,"title":"Zawsze z wami","label":"Independent","notes":"Senaste albumet. Källa: pl.wikipedia.org."}],"de":[{"year":1998,"title":"Cree","label":"Independent","notes":"Debütalbum. Quelle: pl.wikipedia.org."},{"year":2002,"title":"Za tych...","label":"Independent","notes":"Blues-Album des Jahres, Twój Blues. Quelle: agencjaluxart.com."},{"year":2004,"title":"Parę lat","label":"Independent","notes":"Quelle: pl.wikipedia.org."},{"year":2007,"title":"Tacy sami","label":"Independent","notes":"Quelle: pl.wikipedia.org."},{"year":2010,"title":"15 Cree","label":"Independent","notes":"Jubiläumsalbum. Quelle: pl.wikipedia.org."},{"year":2012,"title":"Diabli nadali","label":"Independent","notes":"Quelle: pl.wikipedia.org."},{"year":2013,"title":"Wyjdź...","label":"Independent","notes":"Quelle: pl.wikipedia.org."},{"year":2015,"title":"Heartbreaker","label":"Independent","notes":"Quelle: pl.wikipedia.org."},{"year":2024,"title":"Zawsze z wami","label":"Independent","notes":"Jüngstes Album. Quelle: pl.wikipedia.org."}],"pl":[{"year":1998,"title":"Cree","label":"Independent","notes":"Album debiutancki. Źródło: pl.wikipedia.org."},{"year":2002,"title":"Za tych...","label":"Independent","notes":"Album Bluesowy Roku, Twój Blues. Źródło: agencjaluxart.com."},{"year":2004,"title":"Parę lat","label":"Independent","notes":"Źródło: pl.wikipedia.org."},{"year":2007,"title":"Tacy sami","label":"Independent","notes":"Źródło: pl.wikipedia.org."},{"year":2010,"title":"15 Cree","label":"Independent","notes":"Album jub