'{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":[{"year":1990,"title":"UK Blues Band of the Year","category":"Første av tre år på rad (1990, 1991, 1992)"},{"year":1992,"title":"Instrumentalist of the Year","category":"Første av fem påfølgende år på 1990-tallet"},{"year":2013,"title":"British Blues Harmonica Player of the Year","category":null},{"year":null,"title":"British Blues Awards Hall of Fame","category":"Innlemmet sammen med bl.a. Peter Green og John Mayall"}],"en":[{"year":1990,"title":"UK Blues Band of the Year","category":"First of three consecutive years (1990, 1991, 1992)"},{"year":1992,"title":"Instrumentalist of the Year","category":"First of five consecutive years through the 1990s"},{"year":2013,"title":"British Blues Harmonica Player of the Year","category":null},{"year":null,"title":"British Blues Awards Hall of Fame","category":"Inducted alongside Peter Green and John Mayall, among others"}],"sv":[{"year":1990,"title":"UK Blues Band of the Year","category":"Första av tre år i rad (1990, 1991, 1992)"},{"year":1992,"title":"Instrumentalist of the Year","category":"Första av fem följande år under 1990-talet"},{"year":2013,"title":"British Blues Harmonica Player of the Year","category":null},{"year":null,"title":"British Blues Awards Hall of Fame","category":"Invald tillsammans med bland andra Peter Green och John Mayall"}],"de":[{"year":1990,"title":"UK Blues Band of the Year","category":"Erstes von drei aufeinanderfolgenden Jahren (1990, 1991, 1992)"},{"year":1992,"title":"Instrumentalist of the Year","category":"Erstes von fünf aufeinanderfolgenden Jahren in den 1990ern"},{"year":2013,"title":"British Blues Harmonica Player of the Year","category":null},{"year":null,"title":"British Blues Awards Hall of Fame","category":"Aufgenommen u. a. gemeinsam mit Peter Green und John Mayall"}],"pl":[{"year":1990,"title":"UK Blues Band of the Year","category":"Pierwsza z trzech kolejnych nagród (1990, 1991, 1992)"},{"year":1992,"title":"Instrumentalist of the Year","category":"Pierwsza z pięciu kolejnych nagród w latach 90."},{"year":2013,"title":"British Blues Harmonica Player of the Year","category":null},{"year":null,"title":"British Blues Awards Hall of Fame","category":"Wprowadzony m.in. razem z Peterem Greenem i Johnem Mayallem"}]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', 'Paul Lamb & The King Snakes – British Blues Harmonica Legend | SlowBlues', 'Paul Lamb & The King Snakes – Britisk bluesmunnspill-legende | SlowBlues', 'Paul Lamb & The King Snakes – Brittisk bluesmunspels-legend | SlowBlues', 'Paul Lamb & The King Snakes – Britische Blues-Mundharmonika-Legende | SlowBlues', 'Paul Lamb & The King Snakes – Brytyjska legenda harmonijki bluesowej | SlowBlues', 'Paul Lamb & The King Snakes play Chicago-rooted electric blues from England. Career, awards, current lineup and booking on SlowBlues.', 'Paul Lamb & The King Snakes spiller Chicago-forankret elektrisk blues fra England. Karriere, priser, dagens besetning og booking hos SlowBlues.', 'Paul Lamb & The King Snakes spelar Chicago-förankrad elektrisk blues från England. Karriär, priser, dagens besättning och bokning hos SlowBlues.', 'Paul Lamb & The King Snakes spielen in Chicago verwurzelten Electric Blues aus England. Karriere, Auszeichnungen, aktuelle Besetzung und Booking bei SlowBlues.', 'Paul Lamb & The King Snakes grają electric blues zakorzeniony w Chicago, pochodzący z Anglii. Kariera, nagrody, obecny skład i booking na SlowBlues.', '{"facebook":"https://www.facebook.com/paullambmusic/","youtube":"https://www.youtube.com/channel/UC9Z3qUyaZV9ss2qJYKhdjQQ"}', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_Lamb_(musician)"},{"label":"Hohner — Paul Lamb","url":"https://hohner.de/en/paul-lamb"}]', '[{"title":"Wikipedia — Paul Lamb (musician)","url":"https://en.wikipedia.org/wiki/Paul_Lamb_(musician)"},{"title":"Hohner — Paul Lamb artist profile","url":"https://hohner.de/en/paul-lamb"},{"title":"allaboutbluesmusic.com — Paul Lamb","url":"https://www.allaboutbluesmusic.com/paul-lamb/"}]', 'http://www.paullamb.com/', 'https://www.facebook.com/paullambmusic/', '{"booking_agency":null,"agent_name":null,"booking_email":null,"booking_phone":null,"booking_url":"http://www.paullamb.com/","source_url":"http://www.paullamb.com/","note":"No direct public booking email/phone found; use the official website''s contact/press pages."}', '[]');

INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, region, country, base_path, img, image_credit, gallery_images, youtube_video_ids, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs_i18n, labels, instruments_simple, styles, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, key_recordings, awards_i18n, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, booking_info, related_slugs) VALUES ('ed1d3053-2964-404c-94a0-163c3c407b22', 'joanne-shaw-taylor', 'Joanne Shaw Taylor', NULL, 'Modern', 'Modern Era', 'United Kingdom', 'United Kingdom', '/artists', 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Joanne_Shaw_Taylor_live_in_Bury_St_Edmunds_28_11_22_%2852532046933%29.jpg', 'Foto: Steve Knight / Wikimedia Commons (CC BY 2.0)', '[]', '[]', 'A Black Country blues-rock guitarist discovered as a teenager by Dave Stewart, now a fixture of the UK Blues Chart and Joe Bonamassa''s Keeping the Blues Alive roster.', 'En bluesrock-gitarist fra Black Country som ble oppdaget som tenåring av Dave Stewart, nå en fast del av UK Blues Chart og Joe Bonamassas Keeping the Blues Alive-liste.', 'En bluesrock-gitarrist från Black Country som upptäcktes som tonåring av Dave Stewart, nu en fast del av UK Blues Chart och Joe Bonamassas Keeping the Blues Alive-lista.', 'Eine Blues-Rock-Gitarristin aus der Black Country, als Teenager von Dave Stewart entdeckt, heute fester Bestandteil der UK Blues Chart und von Joe Bonamassas Keeping the Blues Alive.', 'Gitarzystka blues-rockowa z regionu Black Country, odkryta jako nastolatka przez Dave''a Stewarta, dziś stały punkt UK Blues Chart i wytwórni Joe Bonamassy Keeping the Blues Alive.', 'Joanne Shaw Taylor was born in February 1985 in Wednesbury, in England''s Black Country near Birmingham, and was already a working guitarist by fourteen, drawn to the electric blues of Jimi Hendrix, Albert Collins and Stevie Ray Vaughan as much as to soul (Source: Wikipedia). At sixteen she was spotted by Eurythmics'' Dave Stewart, who put her on lead guitar in his project D.U.P. — an early break that put her in front of international audiences years before her solo career began (Source: Wikipedia; AllMusic).\n\nHer 2009 solo debut \"White Sugar\" and its 2010 follow-up \"Diamonds in the Dirt\" both reached the Top Ten of the American Blues chart, establishing her reputation on both sides of the Atlantic. In 2012 she played lead guitar alongside Annie Lennox at the Queen''s Diamond Jubilee concert (Source: Wikipedia). She released \"Dirty Truth\" (2014) and \"Wild\" (2016) on her own Axe House Music label, then relocated to Detroit, recording 2019''s \"Reckless Heart\" in her adopted hometown (Source: AllMusic).\n\nAfter signing to Joe Bonamassa''s label Keeping the Blues Alive, Taylor released \"The Blues Album\" (2021), which reached number 56 on the UK charts, followed by the live album \"Blues from the Heart Live\" (2022), which topped the UK Jazz & Blues Albums Chart. Her most recent record, \"Black & Gold\" (July 2025), was produced by Kevin Shirley and recorded in Nashville, marking her most polished studio work to date (Source: AllMusic; Wikipedia). Across ten studio albums, two live albums and 30 singles, she has become one of the most consistently touring British blues-rock guitarists of her generation.', 'Joanne Shaw Taylor ble født i februar 1985 i Wednesbury, i Englands Black Country nær Birmingham, og var allerede en arbeidende gitarist som fjortenåring, tiltrukket av den elektriske bluesen til Jimi Hendrix, Albert Collins og Stevie Ray Vaughan like mye som av soul (Kilde: Wikipedia). Som seksten år ble hun oppdaget av Eurythmics-medlem Dave Stewart, som satte henne på sologitar i prosjektet sitt D.U.P. — et tidlig gjennombrudd som ga henne internasjonalt publikum flere år før soloartistkarrieren begynte (Kilde: Wikipedia; AllMusic).\n\nSolodebuten hennes «White Sugar» fra 2009 og oppfølgeren «Diamonds in the Dirt» fra 2010 nådde begge topp ti på den amerikanske blueslisten, og etablerte ryktet hennes på begge sider av Atlanteren. I 2012 spilte hun sologitar sammen med Annie Lennox på Dronningens diamantjubileumskonsert (Kilde: Wikipedia). Hun ga ut «Dirty Truth» (2014) og «Wild» (2016) på sitt eget plateselskap Axe House Music, og flyttet deretter til Detroit, der «Reckless Heart» (2019) ble spilt inn i den nye hjembyen hennes (Kilde: AllMusic).\n\nEtter å ha signert med Joe Bonamassas selskap Keeping the Blues Alive, ga Taylor ut «The Blues Album» (2021), som nådde 56. plass på de britiske listene, etterfulgt av livealbumet «Blues from the Heart Live» (2022), som toppet UK Jazz & Blues Albums Chart. Den nyeste platen hennes, «Black & Gold» (juli 2025), ble produsert av Kevin Shirley og spilt inn i Nashville, og markerer det mest polerte studioarbeidet hennes til nå (Kilde: AllMusic; Wikipedia). Med ti studioalbum, to livealbum og 30 singler er hun blitt en av de mest konsekvent turnerende britiske bluesrock-gitaristene i sin generasjon.', 'Joanne Shaw Taylor föddes i februari 1985 i Wednesbury, i Englands Black Country nära Birmingham, och var redan en arbetande gitarrist som fjortonåring, dragen till den elektriska bluesen hos Jimi Hendrix, Albert Collins och Stevie Ray Vaughan lika mycket som till soul (Källa: Wikipedia). Som sextonåring upptäcktes hon av Eurythmics-medlemmen Dave Stewart, som satte henne på sologitarr i sitt projekt D.U.P. — ett tidigt genombrott som gav henne internationell publik flera år innan soloartistkarriären inleddes (Källa: Wikipedia; AllMusic).\n\nHennes solodebut \"White Sugar\" från 2009 och uppföljaren \"Diamonds in the Dirt\" från 2010 nådde båda topp tio på den amerikanska blueslistan, vilket etablerade hennes rykte på båda sidor av Atlanten. 2012 spelade hon sologitarr tillsammans med Annie Lennox på drottningens diamantjubileumskonsert (Källa: Wikipedia). Hon släppte \"Dirty Truth\" (2014) och \"Wild\" (2016) på sitt eget bolag Axe House Music, och flyttade sedan till Detroit, där \"Reckless Heart\" (2019) spelades in i hennes nya hemstad (Källa: AllMusic).\n\nEfter att ha skrivit kontrakt med Joe Bonamassas bolag Keeping the Blues Alive släppte Taylor \"The Blues Album\" (2021), som nådde 56:e plats på de brittiska listorna, följt av livealbumet \"Blues from the Heart Live\" (2022), som toppade UK Jazz & Blues Albums Chart. Hennes senaste skiva, \"Black & Gold\" (juli 2025), producerades av Kevin Shirley och spelades in i Nashville, och markerar hennes mest polerade studioarbete hittills (Källa: AllMusic; Wikipedia). Med tio studioalbum, två livealbum och 30 singlar har hon blivit en av de mest konsekvent turnerande brittiska bluesrock-gitarristerna i sin generation.', 'Joanne Shaw Taylor wurde im Februar 1985 in Wednesbury geboren, in Englands Black Country nahe Birmingham, und war bereits mit vierzehn Jahren eine arbeitende Gitarristin, angezogen vom Electric Blues eines Jimi Hendrix, Albert Collins und Stevie Ray Vaughan ebenso wie vom Soul (Quelle: Wikipedia). Mit sechzehn wurde sie von Eurythmics-Mitglied Dave Stewart entdeckt, der sie als Leadgitarristin in sein Projekt D.U.P. holte — ein früher Durchbruch, der ihr Jahre vor ihrer Solokarriere internationales Publikum verschaffte (Quelle: Wikipedia; AllMusic).\n\nIhr Solodebüt „White Sugar" (2009) und das Nachfolgealbum „Diamonds in the Dirt" (2010) erreichten beide die Top Ten der amerikanischen Blues-Charts und etablierten ihren Ruf auf beiden Seiten des Atlantiks. 2012 spielte sie gemeinsam mit Annie Lennox Leadgitarre beim Diamantenen Thronjubiläumskonzert der Königin (Quelle: Wikipedia). Sie veröffentlichte „Dirty Truth" (2014) und „Wild" (2016) auf ihrem eigenen Label Axe House Music und zog anschließend nach Detroit, wo „Reckless Heart" (2019) in ihrer neuen Heimatstadt aufgenommen wurde (Quelle: AllMusic).\n\nNach der Unterzeichnung bei Joe Bonamassas Label Keeping the Blues Alive veröffentlichte Taylor „The Blues Album" (2021), das Platz 56 der britischen Charts erreichte, gefolgt vom Livealbum „Blues from the Heart Live" (2022), das die UK Jazz & Blues Albums Chart anführte. Ihr jüngstes Album, „Black & Gold" (Juli 2025), wurde von Kevin Shirley produziert und in Nashville aufgenommen — ihr bisher poliertestes Studiowerk (Quelle: AllMusic; Wikipedia). Mit zehn Studioalben, zwei Livealben und 30 Singles ist sie zu einer der beständigsten tourenden britischen Blues-Rock-Gitarristinnen ihrer Generation geworden.', 'Joanne Shaw Taylor urodziła się w lutym 1985 roku w Wednesbury, w angielskim regionie Black Country niedaleko Birmingham, i już jako czternastolatka była pracującą gitarzystką, pociągniętą zarówno przez electric blues Jimiego Hendrixa, Alberta Collinsa i Stevie''ego Raya Vaughana, jak i przez soul (Źródło: Wikipedia). W wieku szesnastu lat została odkryta przez członka Eurythmics, Dave''a Stewarta, który powierzył jej gitarę prowadzącą w swoim projekcie D.U.P. — wczesny przełom, który dał jej międzynarodową publiczność na wiele lat przed rozpoczęciem kariery solowej (Źródło: Wikipedia; AllMusic).\n\nJej solowy debiut „White Sugar" (2009) i kontynuacja „Diamonds in the Dirt" (2010) trafiły do pierwszej dziesiątki amerykańskiej listy bluesowej, ugruntowując jej reputację po obu stronach Atlantyku. W 2012 roku zagrała na gitarze prowadzącej u boku Annie Lennox na koncercie z okazji Diamentowego Jubileuszu Królowej (Źródło: Wikipedia). Wydała „Dirty Truth" (2014) i „Wild" (2016) we własnej wytwórni Axe House Music, a następnie przeniosła się do Detroit, gdzie nagrała „Reckless Heart" (2019) w swoim nowym rodzinnym mieście (Źródło: AllMusic).\n\nPo podpisaniu kontraktu z wytwórnią Joe Bonamassy Keeping the Blues Alive, Taylor wydała „The Blues Album" (2021), który dotarł na 56. miejsce brytyjskich list, a następnie album koncertowy „Blues from the Heart Live" (2022), który znalazł się na szczycie UK Jazz & Blues Albums Chart. Jej najnowsza płyta, „Black & Gold" (lipiec 2025), została wyprodukowana przez Kevina Shirleya i nagrana w Nashville, oznaczając jej najbardziej dopracowany materiał studyjny do tej pory (Źródło: AllMusic; Wikipedia). Mając na koncie dziesięć albumów studyjnych, dwa koncertowe i 30 singli, stała się jedną z najbardziej konsekwentnie koncertujących brytyjskich gitarzystek blues-rockowych swojego pokolenia.', NULL, NULL, NULL, NULL, 'Wednesbury, Black Country, England', '1999–', 'Discovered as a teenager and mentored by Dave Stewart, Joanne Shaw Taylor represents a generation of British blues-rock guitarists who came up outside the traditional club circuit and built careers through relentless recording and international touring rather than a single breakout hit (Source: Wikipedia). Her decision to sign with Joe Bonamassa''s Keeping the Blues Alive label placed her at the centre of the current transatlantic blues-rock revival, and her chart placements on both the UK Jazz & Blues chart and the American Blues chart make her one of the few British artists with a genuinely dual audience.', 'Oppdaget som tenåring og veiledet av Dave Stewart, representerer Joanne Shaw Taylor en generasjon britiske bluesrock-gitarister som vokste opp utenfor den tradisjonelle klubbscenen og bygde karrierer gjennom ustanselig plateinnspilling og internasjonal turnering fremfor én enkelt gjennombruddshit (Kilde: Wikipedia). Beslutningen om å signere med Joe Bonamassas selskap Keeping the Blues Alive plasserte henne midt i den pågående transatlantiske bluesrock-vekkelsen, og listeplasseringene hennes på både UK Jazz & Blues-listen og den amerikanske blueslisten gjør henne til en av få britiske artister med et genuint dobbelt publikum.', 'Upptäckt som tonåring och mentorerad av Dave Stewart representerar Joanne Shaw Taylor en generation brittiska bluesrock-gitarrister som växte upp utanför den traditionella klubbscenen och byggde karriärer genom ihärdig inspelning och internationell turnering snarare än en enda genombrottshit (Källa: Wikipedia). Beslutet att skriva kontrakt med Joe Bonamassas bolag Keeping the Blues Alive placerade henne mitt i den pågående transatlantiska bluesrock-väckelsen, och hennes listplaceringar på både UK Jazz & Blues-listan och den amerikanska blueslistan gör henne till en av få brittiska artister med en genuint dubbel publik.', 'Als Teenager entdeckt und von Dave Stewart gefördert, verkörpert Joanne Shaw Taylor eine Generation britischer Blues-Rock-Gitarristinnen, die außerhalb der traditionellen Club-Szene aufwuchsen und ihre Karriere durch unermüdliches Aufnehmen und internationales Touren statt durch einen einzelnen Durchbruchshit aufbauten (Quelle: Wikipedia). Ihre Entscheidung, bei Joe Bonamassas Label Keeping the Blues Alive zu unterschreiben, rückte sie ins Zentrum der aktuellen transatlantischen Blues-Rock-Wiederbelebung, und ihre Chartplatzierungen sowohl in der UK Jazz & Blues Chart als auch in der amerikanischen Blues-Chart machen sie zu einer der wenigen britischen Künstlerinnen mit einem wirklich doppelten Publikum.', 'Odkryta jako nastolatka i pod skrzydłami Dave''a Stewarta, Joanne Shaw Taylor reprezentuje pokolenie brytyjskich gitarzystek blues-rockowych, które wyrosły poza tradycyjną sceną klubową i budowały kariery poprzez nieustanne nagrywanie i międzynarodowe koncertowanie, a nie pojedynczy przebojowy hit (Źródło: Wikipedia). Decyzja o podpisaniu kontraktu z wytwórnią Joe Bonamassy Keeping the Blues Alive umieściła ją w centrum obecnego transatlantyckiego odrodzenia blues-rocka, a jej pozycje na listach zarówno UK Jazz & Blues, jak i amerykańskiej liście bluesowej czynią ją jedną z niewielu brytyjskich artystek z prawdziwie podwójną publicznością.', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '["Guitar","Vocals"]', '["Blues Rock","Electric Blues","Soul"]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":["1985: Joanne Shaw Taylor født i Wednesbury, Black Country (Kilde: Wikipedia).","c. 1999: Startet som arbeidende gitarist, 14 år gammel.","c. 2001: Oppdaget av Dave Stewart (Eurythmics), sologitarist i hans prosjekt D.U.P.","2009: Solodebuten «White Sugar», topp ti på amerikansk blues-liste.","2012: Sologitar sammen med Annie Lennox på Dronningens diamantjubileumskonsert.","2019: Flyttet til Detroit; spilte inn «Reckless Heart» der.","2021: Signerte med Joe Bonamassas Keeping the Blues Alive; «The Blues Album» utgitt.","2022: «Blues from the Heart Live» topper UK Jazz & Blues Albums Chart.","Juli 2025: «Black & Gold» utgitt, produsert av Kevin Shirley i Nashville."],"en":["1985: Joanne Shaw Taylor born in Wednesbury, Black Country (Source: Wikipedia).","c. 1999: Began working as a guitarist aged 14.","c. 2001: Discovered by Dave Stewart (Eurythmics), lead guitarist in his D.U.P. project.","2009: Solo debut \"White Sugar,\" Top Ten on the American Blues chart.","2012: Lead guitar alongside Annie Lennox at the Queen''s Diamond Jubilee concert.","2019: Relocated to Detroit; recorded \"Reckless Heart\" there.","2021: Signed to Joe Bonamassa''s Keeping the Blues Alive; \"The Blues Album\" released.","2022: \"Blues from the Heart Live\" tops the UK Jazz & Blues Albums Chart.","July 2025: \"Black & Gold\" released, produced by Kevin Shirley in Nashville."],"sv":["1985: Joanne Shaw Taylor föds i Wednesbury, Black Country (Källa: Wikipedia).","c. 1999: Börjar arbeta som gitarrist, 14 år gammal.","c. 2001: Upptäcks av Dave Stewart (Eurythmics), sologitarrist i hans projekt D.U.P.","2009: Solodebuten \"White Sugar\", topp tio på amerikanska blueslistan.","2012: Sologitarr tillsammans med Annie Lennox på drottningens diamantjubileumskonsert.","2019: Flyttar till Detroit; spelar in \"Reckless Heart\" där.","2021: Skriver kontrakt med Joe Bonamassas Keeping the Blues Alive; \"The Blues Album\" släpps.","2022: \"Blues from the Heart Live\" toppar UK Jazz & Blues Albums Chart.","Juli 2025: \"Black & Gold\" släpps, producerad av Kevin Shirley i Nashville."],"de":["1985: Joanne Shaw Taylor wird in Wednesbury, Black Country, geboren (Quelle: Wikipedia).","um 1999: Beginnt im Alter von 14 Jahren als arbeitende Gitarristin.","um 2001: Wird von Dave Stewart (Eurythmics) entdeckt, Leadgitarristin in seinem Projekt D.U.P.","2009: Solodebüt „White Sugar\", Top Ten der amerikanischen Blues-Charts.","2012: Leadgitarre gemeinsam mit Annie Lennox beim Diamantenen Thronjubiläumskonzert der Königin.","2019: Zieht nach Detroit; nimmt dort „Reckless Heart\" auf.","2021: Unterschreibt bei Joe Bonamassas Keeping the Blues Alive; „The Blues Album\" erscheint.","2022: „Blues from the Heart Live\" erreicht Platz 1 der UK Jazz & Blues Albums Chart.","Juli 2025: „Black & Gold\" erscheint, produziert von Kevin Shirley in Nashville."],"pl":["1985: Joanne Shaw Taylor rodzi się w Wednesbury w regionie Black Country (Źródło: Wikipedia).","ok. 1999: Zaczyna pracować jako gitarzystka w wieku 14 lat.","ok. 2001: Zostaje odkryta przez Dave''a Stewarta (Eurythmics), gitarzystka prowadząca w jego projekcie D.U.P.","2009: Solowy debiut „White Sugar\", pierwsza dziesiątka amerykańskiej listy bluesowej.","2012: Gitara prowadząca u boku Annie Lennox na koncercie z okazji Diamentowego Jubileuszu Królowej.","2019: Przenosi się do Detroit; nagrywa tam „Reckless Heart\".","2021: Podpisuje kontrakt z wytwórnią Joe Bonamassy Keeping the Blues Alive; ukazuje się „The Blues Album\".","2022: „Blues from the Heart Live\" na szczycie UK Jazz & Blues Albums Chart.","Lipiec 2025: Ukazuje się „Black & Gold\", wyprodukowany przez Kevina Shirleya w Nashville."]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[{"kind":"featured","title":"Joanne Shaw Taylor - \"Black & Gold\" Official Music Video","youtube_id":"bV3tPGoBgAQ","channel":"Joanne Shaw Taylor","note":null}]', '{"no":[{"year":2009,"title":"White Sugar","label":"Ruf Records","notes":"Solodebut; topp ti på amerikansk blues-liste (Kilde: Wikipedia)."},{"year":2010,"title":"Diamonds in the Dirt","label":"Ruf Records","notes":"Kilde: Wikipedia."},{"year":2014,"title":"Dirty Truth","label":"Axe House Music","notes":"Kilde: AllMusic."},{"year":2016,"title":"Wild","label":"Axe House Music","notes":"Kilde: AllMusic."},{"year":2019,"title":"Reckless Heart","label":"Axe House Music","notes":"Spilt inn i Detroit (Kilde: AllMusic)."},{"year":2021,"title":"The Blues Album","label":"Keeping the Blues Alive","notes":"Nr. 56 på UK-listen (Kilde: Wikipedia)."},{"year":2022,"title":"Blues from the Heart Live","label":"Keeping the Blues Alive","notes":"Toppet UK Jazz & Blues Albums Chart (Kilde: AllMusic)."},{"year":2025,"title":"Black & Gold","label":"Keeping the Blues Alive","producer":"Kevin Shirley","notes":"Spilt inn i Nashville (Kilde: AllMusic; Wikipedia)."}],"en":[{"year":2009,"title":"White Sugar","label":"Ruf Records","notes":"Solo debut; Top Ten on the American Blues chart (Source: Wikipedia)."},{"year":2010,"title":"Diamonds in the Dirt","label":"Ruf Records","notes":"Source: Wikipedia."},{"year":2014,"title":"Dirty Truth","label":"Axe House Music","notes":"Source: AllMusic."},{"year":2016,"title":"Wild","label":"Axe House Music","notes":"Source: AllMusic."},{"year":2019,"title":"Reckless Heart","label":"Axe House Music","notes":"Recorded in Detroit (Source: AllMusic)."},{"year":2021,"title":"The Blues Album","label":"Keeping the Blues Alive","notes":"No. 56 on the UK chart (Source: Wikipedia)."},{"year":2022,"title":"Blues from the Heart Live","label":"Keeping the Blues Alive","notes":"Topped the UK Jazz & Blues Albums Chart (Source: AllMusic)."},{"year":2025,"title":"Black & Gold","label":"Keeping the Blues Alive","producer":"Kevin Shirley","notes":"Recorded in Nashville (Source: AllMusic; Wikipedia)."}],"sv":[{"year":2009,"title":"White Sugar","label":"Ruf Records","notes":"Solodebut; topp tio på amerikanska blueslistan (Källa: Wikipedia)."},{"year":2010,"title":"Diamonds in the Dirt","label":"Ruf Records","notes":"Källa: Wikipedia."},{"year":2014,"title":"Dirty Truth","label":"Axe House Music","notes":"Källa: AllMusic."},{"year":2016,"title":"Wild","label":"Axe House Music","notes":"Källa: AllMusic."},{"year":2019,"title":"Reckless Heart","label":"Axe House Music","notes":"Inspelad i Detroit (Källa: AllMusic)."},{"year":2021,"title":"The Blues Album","label":"Keeping the Blues Alive","notes":"Nr. 56 på brittiska listan (Källa: Wikipedia)."},{"year":2022,"title":"Blues from the Heart Live","label":"Keeping the Blues Alive","notes":"Toppade UK Jazz & Blues Albums Chart (Källa: AllMusic)."},{"year":2025,"title":"Black & Gold","label":"Keeping the Blues Alive","producer":"Kevin Shirley","notes":"Inspelad i Nashville (Källa: AllMusic; Wikipedia)."}],"de":[{"year":2009,"title":"White Sugar","label":"Ruf Records","notes":"Solodebüt; Top Ten der amerikanischen Blues-Charts (Quelle: Wikipedia)."},{"year":2010,"title":"Diamonds in the Dirt","label":"Ruf Records","notes":"Quelle: Wikipedia."},{"year":2014,"title":"Dirty Truth","label":"Axe House Music","notes":"Quelle: AllMusic."},{"year":2016,"title":"Wild","label":"Axe House Music","notes":"Quelle: AllMusic."},{"year":2019,"title":"Reckless Heart","label":"Axe House Music","notes":"Aufgenommen in Detroit (Quelle: AllMusic)."},{"year":2021,"title":"The Blues Album","label":"Keeping the Blues Alive","notes":"Platz 56 der UK-Charts (Quelle: Wikipedia)."},{"year":2022,"title":"Blues from the Heart Live","label":"Keeping the Blues Alive","notes":"Erreichte Platz 1 der UK Jazz & Blues Albums Chart (Quelle: AllMusic)."},{"year":2025,"title":"Black & Gold","label":"Keeping the Blues Alive","producer":"Kevin Shirley","notes":"Aufgenommen in Nashville (Quelle: AllMusic; Wikipedia)."}],"pl":[{"year":2009,"title":"White Sugar","label":"Ruf Records","notes":"Debiut solowy; pierwsza dziesiątka amerykańskiej listy bluesowej (Źródło: Wikipedia)."},{"year":2010,"title":"Diamonds in the Dirt","label":"Ruf Records","notes":"Źródło: Wikipedia."},{"year":2014,"title":"Dirty Truth","label":"Axe House Music","notes":"Źródło: AllMusic."},{"year":2016,"title":"Wild","label":"Axe House Music","notes":"Źródło: AllMusic."},{"year":2019,"title":"Reckless Heart","label":"Axe House Music","notes":"Nagrany w Detroit (Źródło: AllMusic)."},{"year":2021,"title":"The Blues Album","label":"Keeping the Blues Alive","notes":"56. miejsce na liście UK (Źródło: Wikipedia)."},{"year":2022,"title":"Blues from the Heart Live","label":"Keeping the Blues Alive","notes":"Na szczycie UK Jazz & Blues Albums Chart (Źródło: AllMusic)."},{"year":2025,"title":"Black & Gold","label":"Keeping the Blues Alive","producer":"Kevin Shirley","notes":"Nagrany w Nashville (Źródło: AllMusic; Wikipedia)."}]}', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', 'Joanne Shaw Taylor – British Blues-Rock Guitarist | SlowBlues', 'Joanne Shaw Taylor – Britisk bluesrock-gitarist | SlowBlues', 'Joanne Shaw Taylor – Brittisk bluesrock-gitarrist | SlowBlues', 'Joanne Shaw Taylor – Britische Blues-Rock-Gitarristin | SlowBlues', 'Joanne Shaw Taylor – Brytyjska gitarzystka blues-rockowa | SlowBlues', 'Joanne Shaw Taylor is a Black Country blues-rock guitarist and Keeping the Blues Alive artist. Biography, discography and booking on SlowBlues.', 'Joanne Shaw Taylor er en bluesrock-gitarist fra Black Country og Keeping the Blues Alive-artist. Biografi, diskografi og booking hos SlowBlues.', 'Joanne Shaw Taylor är en bluesrock-gitarrist från Black Country och Keeping the Blues Alive-artist. Biografi, diskografi och bokning hos SlowBlues.', 'Joanne Shaw Taylor ist eine Blues-Rock-Gitarristin aus der Black Country und Keeping-the-Blues-Alive-Künstlerin. Biografie, Diskografie und Booking bei SlowBlues.', 'Joanne Shaw Taylor to gitarzystka blues-rockowa z regionu Black Country i artystka Keeping the Blues Alive. Biografia, dyskografia i booking na SlowBlues.', '{}', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joanne_Shaw_Taylor"}]', '[{"title":"Wikipedia — Joanne Shaw Taylor","url":"https://en.wikipedia.org/wiki/Joanne_Shaw_Taylor"},{"title":"AllMusic — Joanne Shaw Taylor","url":"https://www.allmusic.com/artist/joanne-shaw-taylor-mn0001059252"}]', 'https://www.joanneshawtaylor.com', NULL, '{}', '[]');

INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, region, country, base_path, img, image_credit, gallery_images, youtube_video_ids, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs_i18n, labels, instruments_simple, styles, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, key_recordings, awards_i18n, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, booking_info, related_slugs) VALUES ('9a386e3f-4e22-4a26-98b3-4c1d4a081443', 'cinelli-brothers', 'The Cinelli Brothers', NULL, 'Modern', 'Modern Era', 'United Kingdom', 'United Kingdom', '/artists', 'https://images.squarespace-cdn.com/content/v1/57beaad08419c213749f5aae/8fe702e7-ded1-448d-aa66-5846bbf70ab0/CINELLI+BROTHERS+SOHO+JUNE+25+BLACKHAM+IMAGES-154.jpg', 'Foto: Blackham Images (offisielt pressebilde, cinellibrothers.com)', '[]', '[]', 'A London-based blues and soul four-piece led by Italian-born brothers Marco and Alessandro Cinelli, crowned 2024 UK Blues Band of the Year.', 'Et London-basert blues- og soul-firemannsband ledet av de italienskfødte brødrene Marco og Alessandro Cinelli, kåret til UK Blues Band of the Year 2024.', 'Ett Londonbaserat blues- och soul-fyrmannaband lett av de italienskfödda bröderna Marco och Alessandro Cinelli, utsett till UK Blues Band of the Year 2024.', 'Ein in London ansässiges vierköpfiges Blues- und Soul-Ensemble unter Leitung der in Italien geborenen Brüder Marco und Alessandro Cinelli, gekrönt als UK Blues Band of the Year 2024.', 'Londyński czteroosobowy zespół bluesowo-soulowy prowadzony przez urodzonych we Włoszech braci Marco i Alessandro Cinelli, okrzyknięty UK Blues Band of the Year 2024.', 'The Cinelli Brothers were formed in London in 2017 by Italian-born brothers Marco Cinelli (guitar, lead vocals) and Alessandro Cinelli (drums), who built the band into a four-piece with Tom Julian-Jones (harmonica, guitar, vocals), a London native, and Stephen Giry (bass, guitar, vocals) from France (Source: onstage-group.de; blues.gr). Their sound is rooted in the electric blues of 1960s and ''70s Chicago and Texas, filtered through the songwriting craft of influences including The Beatles, The Band, Little Feat, Stevie Wonder, Ray Charles and Steve Winwood — a soul-and-blues hybrid rather than a straight blues covers act (Source: blues.gr).\n\nTheir 2018 debut album \"Babe Please Set Your Alarm\" drew critical acclaim and award nominations, the first of four studio albums to date, most recently \"Almost Exactly...The Cinelli Brothers,\" recorded in Woodstock, New York, and released in 2024 (Source: jsjbf.org; onstage-group.de). The band has built its reputation on the road, playing well over a thousand shows across the UK, Europe, the USA and South America (Source: onstage-group.de).\n\nThe Cinelli Brothers won the UK Blues Challenge in 2022, followed by second place at the International Blues Challenge in Memphis in January 2023, and were named 2024 UK Blues Band of the Year at the UK Blues Awards (Source: blues.gr; onstage-group.de).', 'The Cinelli Brothers ble dannet i London i 2017 av de italienskfødte brødrene Marco Cinelli (gitar, hovedvokal) og Alessandro Cinelli (trommer), som bygde bandet til et firemannsensemble med Tom Julian-Jones (munnspill, gitar, vokal), født og oppvokst i London, og Stephen Giry (bass, gitar, vokal) fra Frankrike (Kilde: onstage-group.de; blues.gr). Lyden deres er forankret i 1960- og 70-tallets elektriske blues fra Chicago og Texas, filtrert gjennom låtskriverhåndverket til påvirkninger som The Beatles, The Band, Little Feat, Stevie Wonder, Ray Charles og Steve Winwood — en soul-og-blues-hybrid fremfor et rent coverband (Kilde: blues.gr).\n\nDebutalbumet «Babe Please Set Your Alarm» fra 2018 fikk godt kritikermottak og prisnominasjoner, det første av fire studioalbum til nå, sist «Almost Exactly...The Cinelli Brothers», spilt inn i Woodstock, New York, og utgitt i 2024 (Kilde: jsjbf.org; onstage-group.de). Bandet har bygget ryktet sitt på veien, med over tusen konserter i Storbritannia, Europa, USA og Sør-Amerika (Kilde: onstage-group.de).\n\nThe Cinelli Brothers vant UK Blues Challenge i 2022, fulgt av andreplass i International Blues Challenge i Memphis i januar 2023, og ble kåret til UK Blues Band of the Year 2024 på UK Blues Awards (Kilde: blues.gr; onstage-group.de).', 'The Cinelli Brothers bildades i London 2017 av de italienskfödda bröderna Marco Cinelli (gitarr, huvudsång) och Alessandro Cinelli (trummor), som byggde bandet till en fyrmannaensemble med Tom Julian-Jones (munspel, gitarr, sång), född och uppvuxen i London, och Stephen Giry (bas, gitarr, sång) från Frankrike (Källa: onstage-group.de; blues.gr). Deras sound är förankrat i 1960- och 70-talets elektriska blues från Chicago och Texas, filtrerat genom låtskrivarhantverket hos influenser som The Beatles, The Band, Little Feat, Stevie Wonder, Ray Charles och Steve Winwood — en soul-och-blues-hybrid snarare än ett rent coverband (Källa: blues.gr).\n\nDebutalbumet \"Babe Please Set Your Alarm\" från 2018 fick starkt kritikermottagande och prisnomineringar, det första av fyra studioalbum hittills, senast \"Almost Exactly...The Cinelli Brothers\", inspelat i Woodstock, New York, och utgivet 2024 (Källa: jsjbf.org; onstage-group.de). Bandet har byggt sitt rykte på vägen, med över tusen spelningar i Storbritannien, Europa, USA och Sydamerika (Källa: onstage-group.de).\n\nThe Cinelli Brothers vann UK Blues Challenge 2022, följt av en andraplats i International Blues Challenge i Memphis i januari 2023, och utsågs till UK Blues Band of the Year 2024 vid UK Blues Awards (Källa: blues.gr; onstage-group.de).', 'The Cinelli Brothers wurden 2017 in London von den in Italien geborenen Brüdern Marco Cinelli (Gitarre, Leadgesang) und Alessandro Cinelli (Schlagzeug) gegründet, die die Band zu einem Quartett mit Tom Julian-Jones (Mundharmonika, Gitarre, Gesang), einem gebürtigen Londoner, und Stephen Giry (Bass, Gitarre, Gesang) aus Frankreich ausbauten (Quelle: onstage-group.de; blues.gr). Ihr Sound wurzelt im Electric Blues der 1960er und 70er aus Chicago und Texas, gefiltert durch das Songwriting-Handwerk von Einflüssen wie The Beatles, The Band, Little Feat, Stevie Wonder, Ray Charles und Steve Winwood — ein Soul-Blues-Hybrid statt einer reinen Coverband (Quelle: blues.gr).\n\nIhr Debütalbum „Babe Please Set Your Alarm" von 2018 erhielt große Anerkennung der Kritik und Preisnominierungen, das erste von bislang vier Studioalben, zuletzt „Almost Exactly...The Cinelli Brothers", aufgenommen in Woodstock, New York, und 2024 veröffentlicht (Quelle: jsjbf.org; onstage-group.de). Die Band hat sich ihren Ruf unterwegs erspielt, mit weit über tausend Konzerten in Großbritannien, Europa, den USA und Südamerika (Quelle: onstage-group.de).\n\nThe Cinelli Brothers gewannen 2022 die UK Blues Challenge, gefolgt von einem zweiten Platz bei der International Blues Challenge in Memphis im Januar 2023, und wurden bei den UK Blues Awards zur UK Blues Band of the Year 2024 gekürt (Quelle: blues.gr; onstage-group.de).', 'The Cinelli Brothers powstali w Londynie w 2017 roku, założeni przez urodzonych we Włoszech braci Marco Cinelli (gitara, wokal prowadzący) i Alessandro Cinelli (perkusja), którzy rozbudowali zespół do czteroosobowego składu z Tomem Julianem-Jonesem (harmonijka, gitara, wokal), rodowitym londyńczykiem, i Stephenem Girym (bas, gitara, wokal) z Francji (Źródło: onstage-group.de; blues.gr). Ich brzmienie zakorzenione jest w electric blues Chicago i Teksasu z lat 60. i 70., przefiltrowanym przez warsztat kompozytorski takich inspiracji jak The Beatles, The Band, Little Feat, Stevie Wonder, Ray Charles i Steve Winwood — hybryda soul i bluesa, a nie zwykły zespół coverowy (Źródło: blues.gr).\n\nDebiutancki album „Babe Please Set Your Alarm" z 2018 roku spotkał się z uznaniem krytyków i nominacjami do nagród, pierwszy z czterech dotychczasowych albumów studyjnych, ostatnio „Almost Exactly...The Cinelli Brothers", nagrany w Woodstock w stanie Nowy Jork i wydany w 2024 roku (Źródło: jsjbf.org; onstage-group.de). Zespół zbudował swoją reputację na trasie, grając ponad tysiąc koncertów w Wielkiej Brytanii, Europie, USA i Ameryce Południowej (Źródło: onstage-group.de).\n\nThe Cinelli Brothers wygrali UK Blues Challenge w 2022 roku, a następnie zdobyli drugie miejsce na International Blues Challenge w Memphis w styczniu 2023 roku, i zostali okrzyknięci UK Blues Band of the Year 2024 podczas UK Blues Awards (Źródło: blues.gr; onstage-group.de).', NULL, NULL, NULL, NULL, 'London, England', '2017–', 'By fusing British and European musicianship (Italian-born founders, a French bassist, a London-born harmonica player) into a sound built on classic American soul-blues songwriting rather than pure blues-rock, The Cinelli Brothers represent the increasingly international character of the UK blues scene. Their rapid climb from a 2018 debut album to UK Blues Band of the Year in 2024, via a strong showing at the International Blues Challenge in Memphis, marks them as one of the most decorated younger bands on the current circuit.', 'Ved å smelte sammen britisk og europeisk musikalitet (italienskfødte grunnleggere, en fransk bassist, en Londonfødt munnspiller) til en lyd bygget på klassisk amerikansk soul-blues-låtskriving fremfor ren bluesrock, representerer The Cinelli Brothers den stadig mer internasjonale karakteren til den britiske bluesscenen. Den raske reisen fra et debutalbum i 2018 til UK Blues Band of the Year i 2024, via en sterk plassering i International Blues Challenge i Memphis, gjør dem til et av de mest premierte yngre bandene på dagens scene.', 'Genom att smälta samman brittisk och europeisk musikalitet (italienskfödda grundare, en fransk basist, en Londonfödd munspelare) till ett sound byggt på klassiskt amerikanskt soul-blues-låtskrivande snarare än ren bluesrock, representerar The Cinelli Brothers den alltmer internationella karaktären hos den brittiska bluesscenen. Den snabba resan från ett debutalbum 2018 till UK Blues Band of the Year 2024, via en stark placering i International Blues Challenge i Memphis, gör dem till ett av de mest prisbelönta yngre banden på dagens scen.', 'Durch die Verschmelzung britischer und europäischer Musikalität (in Italien geborene Gründer, ein französischer Bassist, ein in London geborener Mundharmonikaspieler) zu einem Sound, der auf klassischem amerikanischem Soul-Blues-Songwriting statt purem Blues-Rock basiert, verkörpern The Cinelli Brothers den zunehmend internationalen Charakter der britischen Blues-Szene. Ihr rascher Aufstieg von einem Debütalbum 2018 zur UK Blues Band of the Year 2024, über eine starke Platzierung bei der International Blues Challenge in Memphis, macht sie zu einer der am meisten ausgezeichneten jüngeren Bands der aktuellen Szene.', 'Łącząc brytyjską i europejską muzykalność (urodzeni we Włoszech założyciele, francuski basista, urodzony w Londynie harmonijkarz) w brzmienie oparte na klasycznym amerykańskim pisaniu piosenek soul-blues, a nie czystym blues-rocku, The Cinelli Brothers reprezentują coraz bardziej międzynarodowy charakter brytyjskiej sceny bluesowej. Ich szybka droga od debiutanckiego albumu w 2018 roku do tytułu UK Blues Band of the Year w 2024 roku, poprzez mocny występ na International Blues Challenge w Memphis, czyni ich jednym z najbardziej nagradzanych młodszych zespołów na obecnej scenie.', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '["Guitar","Drums","Harmonica","Bass","Vocals"]', '["Electric Blues","Soul Blues","Chicago Blues","Texas Blues"]', '{"no":[{"relation":"Bror","name":"Alessandro Cinelli","note":"Trommeslager; sammen med Marco en av bandets to grunnleggere og navnebrødre.","source":"onstage-group.de"}],"en":[{"relation":"Brother","name":"Alessandro Cinelli","note":"Drummer; together with Marco one of the band''s two founding, name-giving brothers.","source":"onstage-group.de"}],"sv":[{"relation":"Bror","name":"Alessandro Cinelli","note":"Trummis; tillsammans med Marco en av bandets två grundande, namngivande bröder.","source":"onstage-group.de"}],"de":[{"relation":"Bruder","name":"Alessandro Cinelli","note":"Schlagzeuger; zusammen mit Marco einer der beiden namensgebenden Gründerbrüder der Band.","source":"onstage-group.de"}],"pl":[{"relation":"Brat","name":"Alessandro Cinelli","note":"Perkusista; wraz z Marco jeden z dwóch braci założycieli i patronów nazwy zespołu.","source":"onstage-group.de"}]}', '{"no":["2017: Bandet dannet i London av brødrene Marco og Alessandro Cinelli (Kilde: onstage-group.de).","2018: Debutalbumet «Babe Please Set Your Alarm» utgitt, fikk kritikerros og prisnominasjoner.","2022: Vant UK Blues Challenge.","Januar 2023: Andreplass i International Blues Challenge, Memphis.","2024: «Almost Exactly...The Cinelli Brothers» spilt inn i Woodstock, New York.","2024: Kåret til UK Blues Band of the Year (Kilde: blues.gr)."],"en":["2017: Band formed in London by brothers Marco and Alessandro Cinelli (Source: onstage-group.de).","2018: Debut album \"Babe Please Set Your Alarm\" released, earning critical acclaim and award nominations.","2022: Won the UK Blues Challenge.","January 2023: Second place at the International Blues Challenge, Memphis.","2024: \"Almost Exactly...The Cinelli Brothers\" recorded in Woodstock, New York.","2024: Named UK Blues Band of the Year (Source: blues.gr)."],"sv":["2017: Bandet bildas i London av bröderna Marco och Alessandro Cinelli (Källa: onstage-group.de).","2018: Debutalbumet \"Babe Please Set Your Alarm\" släpps, får kritikerros och prisnomineringar.","2022: Vinner UK Blues Challenge.","Januari 2023: Andraplats i International Blues Challenge, Memphis.","2024: \"Almost Exactly...The Cinelli Brothers\" spelas in i Woodstock, New York.","2024: Utses till UK Blues Band of the Year (Källa: blues.gr)."],"de":["2017: Band von den Brüdern Marco und Alessandro Cinelli in London gegründet (Quelle: onstage-group.de).","2018: Debütalbum „Babe Please Set Your Alarm\" erscheint, erhält Kritikerlob und Preisnominierungen.","2022: Gewinn der UK Blues Challenge.","Januar 2023: Zweiter Platz bei der International Blues Challenge, Memphis.","2024: „Almost Exactly...The Cinelli Brothers\" wird in Woodstock, New York, aufgenommen.","2024: Auszeichnung als UK Blues Band of the Year (Quelle: blues.gr)."],"pl":["2017: Zespół zostaje założony w Londynie przez braci Marco i Alessandro Cinelli (Źródło: onstage-group.de).","2018: Ukazuje się debiutancki album „Babe Please Set Your Alarm\", zdobywając uznanie krytyków i nominacje do nagród.","2022: Zwycięstwo w UK Blues Challenge.","Styczeń 2023: Drugie miejsce na International Blues Challenge w Memphis.","2024: „Almost Exactly...The Cinelli Brothers\" nagrywany w Woodstock w stanie Nowy Jork.","2024: Tytuł UK Blues Band of the Year (Źródło: blues.gr)."]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":[{"year":2018,"title":"Babe Please Set Your Alarm","notes":"Debutalbum; kritikerros og prisnominasjoner (Kilde: jsjbf.org)."},{"year":2024,"title":"Almost Exactly...The Cinelli Brothers","notes":"Spilt inn i Woodstock, New York (Kilde: onstage-group.de)."}],"en":[{"year":2018,"title":"Babe Please Set Your Alarm","notes":"Debut album; critical acclaim and award nominations (Source: jsjbf.org)."},{"year":2024,"title":"Almost Exactly...The Cinelli Brothers","notes":"Recorded in Woodstock, New York (Source: onstage-group.de)."}],"sv":[{"year":2018,"title":"Babe Please Set Your Alarm","notes":"Debutalbum; kritikerros och prisnomineringar (Källa: jsjbf.org)."},{"year":2024,"title":"Almost Exactly...The Cinelli Brothers","notes":"Inspelat i Woodstock, New York (Källa: onstage-group.de)."}],"de":[{"year":2018,"title":"Babe Please Set Your Alarm","notes":"Debütalbum; Kritikerlob und Preisnominierungen (Quelle: jsjbf.org)."},{"year":2024,"title":"Almost Exactly...The Cinelli Brothers","notes":"Aufgenommen in Woodstock, New York (Quelle: onstage-group.de)."}],"pl":[{"year":2018,"title":"Babe Please Set Your Alarm","notes":"Debiutancki album; uznanie krytyków i nominacje do nagród (Źródło: jsjbf.org)."},{"year":2024,"title":"Almost Exactly...The Cinelli Brothers","notes":"Nagrany w Woodstock w stanie Nowy Jork (Źródło: onstage-group.de)."}]}', '[]', '{"no":[{"year":2022,"title":"UK Blues Challenge — Vinner"},{"year":2023,"title":"International Blues Challenge, Memphis — 2. plass"},{"year":2024,"title":"UK Blues Band of the Year"}],"en":[{"year":2022,"title":"UK Blues Challenge — Winner"},{"year":2023,"title":"International Blues Challenge, Memphis — 2nd place"},{"year":2024,"title":"UK Blues Band of the Year"}],"sv":[{"year":2022,"title":"UK Blues Challenge — Vinnare"},{"year":2023,"title":"International Blues Challenge, Memphis — 2:a plats"},{"year":2024,"title":"UK Blues Band of the Year"}],"de":[{"year":2022,"title":"UK Blues Challenge — Gewinner"},{"year":2023,"title":"International Blues Challenge, Memphis — 2. Platz"},{"year":2024,"title":"UK Blues Band of the Year"}],"pl":[{"year":2022,"title":"UK Blues Challenge — Zwycięzca"},{"year":2023,"title":"International Blues Challenge, Memphis — 2. miejsce"},{"year":2024,"title":"UK Blues Band of the Year"}]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', 'The Cinelli Brothers – London Blues & Soul Band | SlowBlues', 'The Cinelli Brothers – Blues- og soulband fra London | SlowBlues', 'The Cinelli Brothers – Blues- och soulband från London | SlowBlues', 'The Cinelli Brothers – Blues- und Soul-Band aus London | SlowBlues', 'The Cinelli Brothers – Londyński zespół blues i soul | SlowBlues', 'The Cinelli Brothers are a London blues and soul band, 2024 UK Blues Band of the Year. Biography, discography and booking on SlowBlues.', 'The Cinelli Brothers er et blues- og soulband fra London, UK Blues Band of the Year 2024. Biografi, diskografi og booking hos SlowBlues.', 'The Cinelli Brothers är ett blues- och soulband från London, UK Blues Band of the Year 2024. Biografi, diskografi och bokning hos SlowBlues.', 'The Cinelli Brothers sind eine Blues- und Soul-Band aus London, UK Blues Band of the Year 2024. Biografie, Diskografie und Booking bei SlowBlues.', 'The Cinelli Brothers to londyński zespół blues i soul, UK Blues Band of the Year 2024. Biografia, dyskografia i booking na SlowBlues.', '{"facebook":"https://www.facebook.com/thecinellibros/"}', '[]', '[{"title":"onstage-group.de — The Cinelli Brothers","url":"https://onstage-group.de/en/blogs/news/the-cinelli-brothers"},{"title":"blues.gr — Q&A with The Cinelli Brothers","url":"https://blues.gr/profiles/blogs/q-a-with-uk-band-of-the-cinelli-brothers-a-rising-force-on-the-mu"}]', 'http://www.cinellibrothers.com/', 'https://www.facebook.com/thecinellibros/', '{}', '[]');

INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, region, country, base_path, img, image_credit, gallery_images, youtube_video_ids, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs_i18n, labels, instruments_simple, styles, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, key_recordings, awards_i18n, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, booking_info, related_slugs) VALUES ('bf5e361e-07bf-4a03-bb75-1f4005fe29fd', 'alice-armstrong', 'Alice Armstrong', NULL, 'Modern', 'Modern Era', 'United Kingdom', 'United Kingdom', '/artists', 'https://images.squarespace-cdn.com/content/v1/60132f983dcc51351d610258/fb5bb8ae-d74b-4b34-8c9b-f32cbe5ec36c/Alice+Benicassim+by+Ana+Torregrosa23.jpg', 'Foto: Ana Torregrosa (Benicàssim, offisiell EPK, alicearmstrongmusic.co.uk)', '[]', '[]', 'A Surrey-born rhythm & blues singer-songwriter and two-time UK Blues Awards Contemporary Artist of the Year, winner of the 2025 European Blues Challenge.', 'En rhythm & blues-vokalist og låtskriver fra Surrey, to ganger kåret til UK Blues Awards Contemporary Artist of the Year, vinner av European Blues Challenge 2025.', 'En rhythm & blues-sångerska och låtskrivare från Surrey, tvåfaldig UK Blues Awards Contemporary Artist of the Year, vinnare av European Blues Challenge 2025.', 'Eine Rhythm-&-Blues-Sängerin und Songwriterin aus Surrey, zweifache UK Blues Awards Contemporary Artist of the Year, Siegerin der European Blues Challenge 2025.', 'Wokalistka i autorka piosenek rhythm & blues z Surrey, dwukrotna laureatka UK Blues Awards Contemporary Artist of the Year, zwyciężczyni European Blues Challenge 2025.', 'Alice Armstrong is a singer-songwriter from Surrey, England, who reshapes classic rhythm & blues grooves through a contemporary lens, blending modern blues, funk, soul and rock ''n'' roll (Source: alicearmstrongmusic.co.uk). She first built a following fronting and writing for the Crossfire Blues Band alongside guitarist Marcus Praestgaard-Stevens, before establishing her own band and name across the UK''s biggest rhythm & blues festivals (Source: bluesfestival.co.uk).\n\nArmstrong was a finalist at the UK Blues Awards in 2020, 2021 and 2022, and has since completed a European tour and performed to sold-out venues in more than 20 countries. In 2025 she and her band won first place at the European Blues Challenge, competing against acts from 22 other countries, and she was voted UK Blues Awards Contemporary Artist of the Year for the second year running (Source: bluesfestival.co.uk; ffarcottonpromotions.co.uk). She has also featured on Joe Bonamassa''s Spotify playlists. Her main musical influences are Ella Fitzgerald, Etta James, Aretha Franklin, Donny Hathaway, Amy Winehouse, Peggy Lee and Dinah Washington (Source: alicearmstrongmusic.co.uk).', 'Alice Armstrong er en låtskriver og vokalist fra Surrey i England som gjenskaper klassiske rhythm & blues-grooves gjennom et samtidig blikk, og blander moderne blues, funk, soul og rock ''n'' roll (Kilde: alicearmstrongmusic.co.uk). Hun bygde først en fanskare som frontfigur og låtskriver for Crossfire Blues Band sammen med gitarist Marcus Praestgaard-Stevens, før hun etablerte sitt eget band og navn på Storbritannias største rhythm & blues-festivaler (Kilde: bluesfestival.co.uk).\n\nArmstrong var finalist i UK Blues Awards i 2020, 2021 og 2022, og har siden fullført en Europa-turné og spilt for utsolgte saler i over 20 land. I 2025 vant hun og bandet førsteplass i European Blues Challenge, mot artister fra 22 andre land, og hun ble kåret til UK Blues Awards Contemporary Artist of the Year for andre år på rad (Kilde: bluesfestival.co.uk; ffarcottonpromotions.co.uk). Hun har også vært med på Joe Bonamassas Spotify-spillelister. Hovedinspirasjonene hennes er Ella Fitzgerald, Etta James, Aretha Franklin, Donny Hathaway, Amy Winehouse, Peggy Lee og Dinah Washington (Kilde: alicearmstrongmusic.co.uk).', 'Alice Armstrong är en låtskrivare och sångerska från Surrey i England som återskapar klassiska rhythm & blues-grooves genom ett samtida perspektiv, och blandar modern blues, funk, soul och rock ''n'' roll (Källa: alicearmstrongmusic.co.uk). Hon byggde först en fanskara som frontfigur och låtskrivare för Crossfire Blues Band tillsammans med gitarristen Marcus Praestgaard-Stevens, innan hon etablerade sitt eget band och namn på Storbritanniens största rhythm & blues-festivaler (Källa: bluesfestival.co.uk).\n\nArmstrong var finalist i UK Blues Awards 2020, 2021 och 2022, och har sedan dess fullföljt en Europaturné och spelat för utsålda salonger i över 20 länder. 2025 vann hon och bandet förstaplatsen i European Blues Challenge, mot artister från 22 andra länder, och hon utsågs till UK Blues Awards Contemporary Artist of the Year för andra året i rad (Källa: bluesfestival.co.uk; ffarcottonpromotions.co.uk). Hon har också funnits med på Joe Bonamassas Spotify-spellistor. Hennes huvudsakliga influenser är Ella Fitzgerald, Etta James, Aretha Franklin, Donny Hathaway, Amy Winehouse, Peggy Lee och Dinah Washington (Källa: alicearmstrongmusic.co.uk).', 'Alice Armstrong ist eine Songwriterin und Sängerin aus Surrey, England, die klassische Rhythm-&-Blues-Grooves durch eine zeitgenössische Linse neu gestaltet und dabei modernen Blues, Funk, Soul und Rock ''n'' Roll mischt (Quelle: alicearmstrongmusic.co.uk). Sie baute sich zunächst als Frontfrau und Songwriterin der Crossfire Blues Band gemeinsam mit Gitarrist Marcus Praestgaard-Stevens eine Fangemeinde auf, bevor sie ihre eigene Band und ihren eigenen Namen bei Großbritanniens größten Rhythm-&-Blues-Festivals etablierte (Quelle: bluesfestival.co.uk).\n\nArmstrong war 2020, 2021 und 2022 Finalistin bei den UK Blues Awards und hat seitdem eine Europatournee absolviert und vor ausverkauften Häusern in über 20 Ländern gespielt. 2025 gewannen sie und ihre Band den ersten Platz bei der European Blues Challenge gegen Acts aus 22 anderen Ländern, und sie wurde zum zweiten Mal in Folge zur UK Blues Awards Contemporary Artist of the Year gewählt (Quelle: bluesfestival.co.uk; ffarcottonpromotions.co.uk). Sie war zudem auf Joe Bonamassas Spotify-Playlists vertreten. Ihre wichtigsten musikalischen Einflüsse sind Ella Fitzgerald, Etta James, Aretha Franklin, Donny Hathaway, Amy Winehouse, Peggy Lee und Dinah Washington (Quelle: alicearmstrongmusic.co.uk).', 'Alice Armstrong to autorka piosenek i wokalistka z Surrey w Anglii, która na nowo kształtuje klasyczne brzmienia rhythm & blues przez współczesny pryzmat, łącząc nowoczesny blues, funk, soul i rock ''n'' roll (Źródło: alicearmstrongmusic.co.uk). Najpierw zbudowała swoją publiczność jako liderka i autorka tekstów Crossfire Blues Band u boku gitarzysty Marcusa Praestgaarda-Stevensa, zanim ustanowiła własny zespół i markę na największych brytyjskich festiwalach rhythm & blues (Źródło: bluesfestival.co.uk).\n\nArmstrong była finalistką UK Blues Awards w latach 2020, 2021 i 2022, a od tego czasu odbyła trasę koncertową po Europie i grała przed wyprzedanymi salami w ponad 20 krajach. W 2025 roku ona i jej zespół zdobyli pierwsze miejsce na European Blues Challenge, rywalizując z wykonawcami z 22 innych krajów, a ona sama została wybrana UK Blues Awards Contemporary Artist of the Year po raz drugi z rzędu (Źródło: bluesfestival.co.uk; ffarcottonpromotions.co.uk). Pojawiła się także na playlistach Spotify Joego Bonamassy. Jej głównymi inspiracjami muzycznymi są Ella Fitzgerald, Etta James, Aretha Franklin, Donny Hathaway, Amy Winehouse, Peggy Lee i Dinah Washington (Źródło: alicearmstrongmusic.co.uk).', NULL, NULL, NULL, NULL, 'Surrey, England', '2016–', 'Armstrong''s back-to-back Contemporary Artist of the Year wins and her band''s 2025 European Blues Challenge victory against 22 competing countries mark her as one of the fastest-rising vocalists on the UK circuit, carrying classic rhythm & blues vocal phrasing into a modern funk-and-soul-inflected band sound.', 'Armstrongs to strake seire som Contemporary Artist of the Year, og bandets seier i European Blues Challenge 2025 mot 22 konkurrerende land, gjør henne til en av de raskest voksende vokalistene på den britiske scenen, som fører klassisk rhythm & blues-frasering inn i en moderne funk- og soul-preget bandlyd.', 'Armstrongs två raka segrar som Contemporary Artist of the Year, och bandets seger i European Blues Challenge 2025 mot 22 tävlande länder, gör henne till en av de snabbast växande sångerskorna på den brittiska scenen, som för in klassisk rhythm & blues-frasering i ett modernt funk- och soulpräglat bandsound.', 'Armstrongs zwei aufeinanderfolgende Siege als Contemporary Artist of the Year und der Sieg ihrer Band bei der European Blues Challenge 2025 gegen 22 konkurrierende Länder machen sie zu einer der am schnellsten aufsteigenden Sängerinnen der britischen Szene, die klassisches Rhythm-&-Blues-Phrasing in einen modernen, funk- und soulgeprägten Bandsound trägt.', 'Dwa kolejne zwycięstwa Armstrong jako Contemporary Artist of the Year oraz triumf jej zespołu na European Blues Challenge 2025 wśród 22 rywalizujących krajów czynią ją jedną z najszybciej rosnących wokalistek na brytyjskiej scenie, przenoszącą klasyczne frazowanie rhythm & blues do nowoczesnego, funkowo-soulowego brzmienia zespołu.', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '["Vocals"]', '["Rhythm & Blues","Soul Blues","Funk Blues"]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":["c. 2016: Startet karrieren som frontfigur og låtskriver for Crossfire Blues Band.","2020-2022: Finalist i UK Blues Awards tre år på rad.","2024: Kåret til UK Blues Awards Contemporary Artist of the Year.","2025: Vant European Blues Challenge med bandet sitt, mot artister fra 22 land.","2025: Kåret til Contemporary Artist of the Year for andre år på rad (Kilde: bluesfestival.co.uk)."],"en":["c. 2016: Began her career fronting and writing for the Crossfire Blues Band.","2020-2022: UK Blues Awards finalist three years running.","2024: Named UK Blues Awards Contemporary Artist of the Year.","2025: Won the European Blues Challenge with her band, against acts from 22 countries.","2025: Named Contemporary Artist of the Year for the second year running (Source: bluesfestival.co.uk)."],"sv":["c. 2016: Inledde sin karriär som frontfigur och låtskrivare för Crossfire Blues Band.","2020-2022: Finalist i UK Blues Awards tre år i rad.","2024: Utsedd till UK Blues Awards Contemporary Artist of the Year.","2025: Vann European Blues Challenge med sitt band, mot artister från 22 länder.","2025: Utsedd till Contemporary Artist of the Year för andra året i rad (Källa: bluesfestival.co.uk)."],"de":["um 2016: Beginnt ihre Karriere als Frontfrau und Songwriterin der Crossfire Blues Band.","2020-2022: Drei Jahre in Folge Finalistin bei den UK Blues Awards.","2024: Wird UK Blues Awards Contemporary Artist of the Year.","2025: Gewinnt mit ihrer Band die European Blues Challenge gegen Acts aus 22 Ländern.","2025: Wird zum zweiten Mal in Folge Contemporary Artist of the Year (Quelle: bluesfestival.co.uk)."],"pl":["ok. 2016: Rozpoczyna karierę jako liderka i autorka tekstów Crossfire Blues Band.","2020-2022: Finalistka UK Blues Awards trzy lata z rzędu.","2024: Zostaje UK Blues Awards Contemporary Artist of the Year.","2025: Wygrywa European Blues Challenge ze swoim zespołem, pokonując wykonawców z 22 krajów.","2025: Zostaje Contemporary Artist of the Year po raz drugi z rzędu (Źródło: bluesfestival.co.uk)."]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[{"name":"Marcus Praestgaard-Stevens","note":"Gitarist; sammen med Armstrong i Crossfire Blues Band før hennes solokarriere.","source":"bluesfestival.co.uk"}],"en":[{"name":"Marcus Praestgaard-Stevens","note":"Guitarist; alongside Armstrong in the Crossfire Blues Band before her solo career.","source":"bluesfestival.co.uk"}],"sv":[{"name":"Marcus Praestgaard-Stevens","note":"Gitarrist; tillsammans med Armstrong i Crossfire Blues Band före hennes solokarriär.","source":"bluesfestival.co.uk"}],"de":[{"name":"Marcus Praestgaard-Stevens","note":"Gitarrist; gemeinsam mit Armstrong in der Crossfire Blues Band vor ihrer Solokarriere.","source":"bluesfestival.co.uk"}],"pl":[{"name":"Marcus Praestgaard-Stevens","note":"Gitarzysta; wraz z Armstrong w Crossfire Blues Band przed jej karierą solową.","source":"bluesfestival.co.uk"}]}', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":[{"year":2024,"title":"UK Blues Awards Contemporary Artist of the Year"},{"year":2025,"title":"UK Blues Awards Contemporary Artist of the Year","category":"Andre år på rad"},{"year":2025,"title":"European Blues Challenge","category":"1. plass, mot 22 land"}],"en":[{"year":2024,"title":"UK Blues Awards Contemporary Artist of the Year"},{"year":2025,"title":"UK Blues Awards Contemporary Artist of the Year","category":"Second year running"},{"year":2025,"title":"European Blues Challenge","category":"1st place, against 22 countries"}],"sv":[{"year":2024,"title":"UK Blues Awards Contemporary Artist of the Year"},{"year":2025,"title":"UK Blues Awards Contemporary Artist of the Year","category":"Andra året i rad"},{"year":2025,"title":"European Blues Challenge","category":"1:a plats, mot 22 länder"}],"de":[{"year":2024,"title":"UK Blues Awards Contemporary Artist of the Year"},{"year":2025,"title":"UK Blues Awards Contemporary Artist of the Year","category":"Zweites Jahr in Folge"},{"year":2025,"title":"European Blues Challenge","category":"1. Platz, gegen 22 Länder"}],"pl":[{"year":2024,"title":"UK Blues Awards Contemporary Artist of the Year"},{"year":2025,"title":"UK Blues Awards Contemporary Artist of the Year","category":"Drugi rok z rzędu"},{"year":2025,"title":"European Blues Challenge","category":"1. miejsce, wśród 22 krajów"}]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', 'Alice Armstrong – UK Rhythm & Blues Singer-Songwriter | SlowBlues', 'Alice Armstrong – Britisk rhythm & blues-vokalist | SlowBlues', 'Alice Armstrong – Brittisk rhythm & blues-sångerska | SlowBlues', 'Alice Armstrong – Britische Rhythm-&-Blues-Sängerin | SlowBlues', 'Alice Armstrong – Brytyjska wokalistka rhythm & blues | SlowBlues', 'Alice Armstrong is a Surrey-born UK rhythm & blues singer-songwriter, European Blues Challenge 2025 winner. Biography and booking on SlowBlues.', 'Alice Armstrong er en rhythm & blues-vokalist fra Surrey, vinner av European Blues Challenge 2025. Biografi og booking hos SlowBlues.', 'Alice Armstrong är en rhythm & blues-sångerska från Surrey, vinnare av European Blues Challenge 2025. Biografi och bokning hos SlowBlues.', 'Alice Armstrong ist eine Rhythm-&-Blues-Sängerin aus Surrey, Siegerin der European Blues Challenge 2025. Biografie und Booking bei SlowBlues.', 'Alice Armstrong to wokalistka rhythm & blues z Surrey, zwyciężczyni European Blues Challenge 2025. Biografia i booking na SlowBlues.', '{}', '[]', '[{"title":"alicearmstrongmusic.co.uk — About","url":"https://www.alicearmstrongmusic.co.uk/about"},{"title":"bluesfestival.co.uk — Alice Armstrong","url":"https://www.bluesfestival.co.uk/2025-line-up/alice-armstrong/"}]', 'https://www.alicearmstrongmusic.co.uk', NULL, '{}', '[]');

INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, region, country, base_path, img, image_credit, gallery_images, youtube_video_ids, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs_i18n, labels, instruments_simple, styles, family_i18n, formative_i18n, instruments_i18n, anecdotes_i18n, collaborators_i18n, videos, discography_i18n, key_recordings, awards_i18n, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, booking_info, related_slugs) VALUES ('af05a881-6a0b-4d43-9c06-5054c98e0140', 'connor-selby', 'Connor Selby', NULL, 'Modern', 'Modern Era', 'United Kingdom', 'United Kingdom', '/artists', 'https://www.fabricationshq.com/uploads/8/3/3/8/833898/published/connor-selby-blackham-images-285.jpg?1756218602', 'Foto: Rob Blackham / Blackham Images', '[]', '[]', 'A young voice of traditional British blues from Ashford, Kent, whose self-titled 2023 debut was named MOJO Magazine Blues Album of the Year.', 'En ung stemme i tradisjonell britisk blues fra Ashford, Kent, hvis selvtitulerte debut fra 2023 ble kåret til MOJO Magazines bluesalbum året.', 'En ung röst i traditionell brittisk blues från Ashford, Kent, vars självbetitlade debut från 2023 utsågs till MOJO Magazines bluesalbum året.', 'Eine junge Stimme des traditionellen britischen Blues aus Ashford, Kent, dessen selbstbetiteltes Debüt 2023 zum MOJO Magazine Blues Album of the Year gekürt wurde.', 'Młody głos tradycyjnego brytyjskiego bluesa z Ashford w hrabstwie Kent, którego debiutancki album z 2023 roku został okrzyknięty Blues Album of the Year magazynu MOJO.', 'Connor Selby, from Ashford, Kent, is regarded as one of the most distinctive voices in contemporary British blues, combining a soulful, emotionally direct vocal style with expressive, tradition-rooted guitar playing (Source: connorselby.com). He was a three-time winner of the UK Blues Awards'' "Young Artist of the Year" title from 2020 to 2022, before winning the 2025 "Traditional Blues Artist of the Year" award as an established adult artist (Source: australianmusician.com.au).\n\nHis self-titled 2023 debut album was named MOJO Magazine''s Blues Album of the Year, a breakthrough that brought widespread critical acclaim, radio support and millions of streams. He has followed it with further releases including "The Truth Comes Out Eventually" (Source: connorselby.com; australianmusician.com.au). In 2024 he featured on Mark Knopfler''s charity single "Going Home (Theme from Local Hero)" alongside a roster of major artists, has shared a stage with The Who at Wembley Stadium, appeared at London''s Hyde Park Festival alongside Pearl Jam and Stereophonics, and has toured with Beth Hart, Robert Cray and Joanne Shaw Taylor (Source: australianmusician.com.au).', 'Connor Selby, fra Ashford i Kent, regnes som en av de mest særpregede stemmene i samtidig britisk blues, og kombinerer en sjelfull, følelsesmessig direkte vokalstil med uttrykksfullt, tradisjonsforankret gitarspill (Kilde: connorselby.com). Han vant UK Blues Awards'' tittel «Young Artist of the Year» tre ganger på rad, fra 2020 til 2022, før han vant prisen «Traditional Blues Artist of the Year» i 2025 som etablert voksen artist (Kilde: australianmusician.com.au).\n\nHans selvtitulerte debutalbum fra 2023 ble kåret til MOJO Magazines bluesalbum året, et gjennombrudd som ga bred kritikerros, radiospilling og millioner av avspillinger. Han har fulgt opp med flere utgivelser, deriblant «The Truth Comes Out Eventually» (Kilde: connorselby.com; australianmusician.com.au). I 2024 medvirket han på Mark Knopflers veldedighetssingel «Going Home (Theme from Local Hero)» sammen med en rekke store artister, har delt scene med The Who på Wembley Stadium, opptrådte på Londons Hyde Park Festival sammen med Pearl Jam og Stereophonics, og har turnert med Beth Hart, Robert Cray og Joanne Shaw Taylor (Kilde: australianmusician.com.au).', 'Connor Selby, från Ashford i Kent, betraktas som en av de mest särpräglade rösterna i samtida brittisk blues, och kombinerar en själfull, känslomässigt direkt sångstil med uttrycksfullt, traditionsförankrat gitarrspel (Källa: connorselby.com). Han vann UK Blues Awards titel \"Young Artist of the Year\" tre gånger i rad, från 2020 till 2022, innan han vann priset \"Traditional Blues Artist of the Year\" 2025 som etablerad vuxen artist (Källa: australianmusician.com.au).\n\nHans självbetitlade debutalbum från 2023 utsågs till MOJO Magazines bluesalbum året, ett genombrott som gav brett kritikerbemötande, radiospelning och miljontals lyssningar. Han har följt upp med fler utgivningar, bland annat \"The Truth Comes Out Eventually\" (Källa: connorselby.com; australianmusician.com.au). 2024 medverkade han på Mark Knopflers välgörenhetssingel \"Going Home (Theme from Local Hero)\" tillsammans med en rad stora artister, har delat scen med The Who på Wembley Stadium, uppträdde på Londons Hyde Park Festival tillsammans med Pearl Jam och Stereophonics, och har turnerat med Beth Hart, Robert Cray och Joanne Shaw Taylor (Källa: australianmusician.com.au).', 'Connor Selby aus Ashford, Kent, gilt als eine der markantesten Stimmen des zeitgenössischen britischen Blues und verbindet einen seelenvollen, emotional direkten Gesangsstil mit ausdrucksstarkem, traditionsverwurzeltem Gitarrenspiel (Quelle: connorselby.com). Er gewann von 2020 bis 2022 dreimal in Folge den Titel „Young Artist of the Year" bei den UK Blues Awards, bevor er 2025 als etablierter erwachsener Künstler den Preis „Traditional Blues Artist of the Year" gewann (Quelle: australianmusician.com.au).\n\nSein selbstbetiteltes Debütalbum von 2023 wurde vom MOJO Magazine zum Blues Album of the Year gekürt — ein Durchbruch, der ihm breite Kritikeranerkennung, Radio-Airplay und Millionen von Streams einbrachte. Es folgten weitere Veröffentlichungen, darunter „The Truth Comes Out Eventually" (Quelle: connorselby.com; australianmusician.com.au). 2024 war er auf Mark Knopflers Wohltätigkeitssingle „Going Home (Theme from Local Hero)" neben einer Reihe großer Künstler vertreten, teilte sich mit The Who die Bühne im Wembley-Stadion, trat beim Hyde-Park-Festival in London neben Pearl Jam und Stereophonics auf und tourte mit Beth Hart, Robert Cray und Joanne Shaw Taylor (Quelle: australianmusician.com.au).', 'Connor Selby z Ashford w hrabstwie Kent uważany jest za jeden z najbardziej charakterystycznych głosów współczesnego brytyjskiego bluesa, łączący pełen duszy, emocjonalnie bezpośredni styl wokalny z ekspresyjną, zakorzenioną w tradycji grą na gitarze (Źródło: connorselby.com). Trzykrotnie zdobył tytuł „Young Artist of the Year" na UK Blues Awards, od 2020 do 2022 roku, zanim w 2025 roku, jako uznany dorosły artysta, zdobył nagrodę „Traditional Blues Artist of the Year" (Źródło: australianmusician.com.au).\n\nJego debiutancki, samotytułowy album z 2023 roku został okrzyknięty przez magazyn MOJO Blues Album of the Year — przełom, który przyniósł szerokie uznanie krytyków, wsparcie radiowe i miliony odtworzeń. Kontynuował tę passę kolejnymi wydawnictwami, w tym „The Truth Comes Out Eventually" (Źródło: connorselby.com; australianmusician.com.au). W 2024 roku pojawił się na charytatywnym singlu Marka Knopflera „Going Home (Theme from Local Hero)" obok grona wybitnych artystów, dzielił scenę z The Who na stadionie Wembley, wystąpił na londyńskim Hyde Park Festival obok Pearl Jam i Stereophonics oraz koncertował z Beth Hart, Robertem Crayem i Joanne Shaw Taylor (Źródło: australianmusician.com.au).', NULL, NULL, NULL, NULL, 'Ashford, Kent, England', '2017–', 'Selby''s progression from three-time "Young Artist of the Year" to MOJO''s Blues Album of the Year and a place on Mark Knopfler''s own charity single marks a rare, fully-formed transition from prodigy status to a genuinely traditional-blues-rooted adult career, at a moment when the UK Blues Awards themselves have begun recognising him under a "Traditional" rather than "Young" category.', 'Selbys utvikling fra tre ganger «Young Artist of the Year» til MOJOs bluesalbum året og en plass på Mark Knopflers egen veldedighetssingel, markerer en sjelden, fullt utviklet overgang fra vidunderbarn-status til en genuint tradisjonsforankret voksenkarriere, i en tid der selve UK Blues Awards har begynt å hedre ham under en «tradisjonell» heller enn «ung»-kategori.', 'Selbys utveckling från trefaldig \"Young Artist of the Year\" till MOJOs bluesalbum året och en plats på Mark Knopflers egen välgörenhetssingel markerar en sällsynt, fullt utvecklad övergång från underbarnsstatus till en genuint traditionsförankrad vuxenkarriär, i en tid då själva UK Blues Awards har börjat hedra honom under en \"traditionell\" snarare än \"ung\"-kategori.', 'Selbys Entwicklung vom dreifachen „Young Artist of the Year" zum MOJO-Blues-Album des Jahres und einem Platz auf Mark Knopflers eigener Wohltätigkeitssingle markiert einen seltenen, vollständig ausgereiften Übergang vom Wunderkind-Status zu einer echten, traditionsverwurzelten Erwachsenenkarriere — zu einer Zeit, in der die UK Blues Awards selbst begonnen haben, ihn in einer „traditionellen" statt einer „jungen" Kategorie zu würdigen.', 'Ewolucja Selby''ego od trzykrotnego „Young Artist of the Year" do Blues Album of the Year magazynu MOJO i miejsca na charytatywnym singlu samego Marka Knopflera to rzadkie, w pełni ukształtowane przejście od statusu cudownego dziecka do prawdziwie zakorzenionej w tradycji kariery dorosłego artysty — w momencie, gdy same UK Blues Awards zaczęły honorować go w kategorii „tradycyjnej", a nie „młodzieżowej".', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '["Guitar","Vocals"]', '["Traditional Blues","Electric Blues"]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":["2020-2022: Vant UK Blues Awards «Young Artist of the Year» tre år på rad.","2023: Det selvtitulerte debutalbumet utgitt, kåret til MOJO Magazines bluesalbum året.","2024: Medvirket på Mark Knopflers veldedighetssingel «Going Home (Theme from Local Hero)».","2024: Delte scene med The Who på Wembley Stadium; opptrådte på Hyde Park Festival med Pearl Jam og Stereophonics.","2025: Vant UK Blues Awards «Traditional Blues Artist of the Year» (Kilde: australianmusician.com.au)."],"en":["2020-2022: Won the UK Blues Awards \"Young Artist of the Year\" three years running.","2023: Self-titled debut album released, named MOJO Magazine''s Blues Album of the Year.","2024: Featured on Mark Knopfler''s charity single \"Going Home (Theme from Local Hero).\"","2024: Shared a stage with The Who at Wembley Stadium; appeared at Hyde Park Festival with Pearl Jam and Stereophonics.","2025: Won the UK Blues Awards \"Traditional Blues Artist of the Year\" (Source: australianmusician.com.au)."],"sv":["2020-2022: Vann UK Blues Awards \"Young Artist of the Year\" tre år i rad.","2023: Det självbetitlade debutalbumet släpps, utses till MOJO Magazines bluesalbum året.","2024: Medverkade på Mark Knopflers välgörenhetssingel \"Going Home (Theme from Local Hero)\".","2024: Delade scen med The Who på Wembley Stadium; uppträdde på Hyde Park Festival med Pearl Jam och Stereophonics.","2025: Vann UK Blues Awards \"Traditional Blues Artist of the Year\" (Källa: australianmusician.com.au)."],"de":["2020-2022: Gewinnt drei Jahre in Folge den UK Blues Awards „Young Artist of the Year\".","2023: Selbstbetiteltes Debütalbum erscheint, wird MOJO Magazine Blues Album of the Year.","2024: Vertreten auf Mark Knopflers Wohltätigkeitssingle „Going Home (Theme from Local Hero)\".","2024: Teilt sich mit The Who die Bühne im Wembley-Stadion; Auftritt beim Hyde Park Festival mit Pearl Jam und Stereophonics.","2025: Gewinnt den UK Blues Awards „Traditional Blues Artist of the Year\" (Quelle: australianmusician.com.au)."],"pl":["2020-2022: Zdobywa tytuł UK Blues Awards „Young Artist of the Year\" trzy lata z rzędu.","2023: Ukazuje się debiutancki, samotytułowy album, okrzyknięty Blues Album of the Year magazynu MOJO.","2024: Pojawia się na charytatywnym singlu Marka Knopflera „Going Home (Theme from Local Hero)\".","2024: Dzieli scenę z The Who na stadionie Wembley; występuje na Hyde Park Festival z Pearl Jam i Stereophonics.","2025: Zdobywa nagrodę UK Blues Awards „Traditional Blues Artist of the Year\" (Źródło: australianmusician.com.au)."]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '{"no":[{"name":"Mark Knopfler","note":"Medvirket på Knopflers veldedighetssingel «Going Home (Theme from Local Hero)», 2024.","source":"australianmusician.com.au"},{"name":"Beth Hart","note":"Turnerte sammen med Hart.","source":"australianmusician.com.au"},{"name":"Robert Cray","note":"Turnerte sammen med Cray.","source":"australianmusician.com.au"},{"name":"Joanne Shaw Taylor","note":"Turnerte sammen med Taylor.","source":"australianmusician.com.au"}],"en":[{"name":"Mark Knopfler","note":"Featured on Knopfler''s charity single \"Going Home (Theme from Local Hero),\" 2024.","source":"australianmusician.com.au"},{"name":"Beth Hart","note":"Toured alongside Hart.","source":"australianmusician.com.au"},{"name":"Robert Cray","note":"Toured alongside Cray.","source":"australianmusician.com.au"},{"name":"Joanne Shaw Taylor","note":"Toured alongside Taylor.","source":"australianmusician.com.au"}],"sv":[{"name":"Mark Knopfler","note":"Medverkade på Knopflers välgörenhetssingel \"Going Home (Theme from Local Hero)\", 2024.","source":"australianmusician.com.au"},{"name":"Beth Hart","note":"Turnerade tillsammans med Hart.","source":"australianmusician.com.au"},{"name":"Robert Cray","note":"Turnerade tillsammans med Cray.","source":"australianmusician.com.au"},{"name":"Joanne Shaw Taylor","note":"Turnerade tillsammans med Taylor.","source":"australianmusician.com.au"}],"de":[{"name":"Mark Knopfler","note":"Vertreten auf Knopflers Wohltätigkeitssingle „Going Home (Theme from Local Hero)\", 2024.","source":"australianmusician.com.au"},{"name":"Beth Hart","note":"Tour gemeinsam mit Hart.","source":"australianmusician.com.au"},{"name":"Robert Cray","note":"Tour gemeinsam mit Cray.","source":"australianmusician.com.au"},{"name":"Joanne Shaw Taylor","note":"Tour gemeinsam mit Taylor.","source":"australianmusician.com.au"}],"pl":[{"name":"Mark Knopfler","note":"Wystąpił na charytatywnym singlu Knopflera „Going Home (Theme from Local Hero)\", 2024.","source":"australianmusician.com.au"},{"name":"Beth Hart","note":"Koncertował z Hart.","source":"australianmusician.com.au"},{"name":"Robert Cray","note":"Koncertował z Crayem.","source":"australianmusician.com.au"},{"name":"Joanne Shaw Taylor","note":"Koncertował z Taylor.","source":"australianmusician.com.au"}]}', '[]', '{"no":[{"year":2023,"title":"Connor Selby","notes":"Selvtitulert debutalbum; kåret til MOJO Magazines bluesalbum året (Kilde: connorselby.com)."},{"year":null,"title":"The Truth Comes Out Eventually","notes":"Kilde: connorselby.com."}],"en":[{"year":2023,"title":"Connor Selby","notes":"Self-titled debut album; named MOJO Magazine''s Blues Album of the Year (Source: connorselby.com)."},{"year":null,"title":"The Truth Comes Out Eventually","notes":"Source: connorselby.com."}],"sv":[{"year":2023,"title":"Connor Selby","notes":"Självbetitlat debutalbum; utsett till MOJO Magazines bluesalbum året (Källa: connorselby.com)."},{"year":null,"title":"The Truth Comes Out Eventually","notes":"Källa: connorselby.com."}],"de":[{"year":2023,"title":"Connor Selby","notes":"Selbstbetiteltes Debütalbum; MOJO Magazine Blues Album of the Year (Quelle: connorselby.com)."},{"year":null,"title":"The Truth Comes Out Eventually","notes":"Quelle: connorselby.c