INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, era_label_en, era_label_no, era_label_sv, era_label_de, era_label_pl, region, country, base_path, route_path, source_file, source_region, img, og_image, image_credit, gallery_images, youtube_video_ids, video_search_query, short, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_note, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs, signature_songs_i18n, influences, influences_i18n, labels, instruments_simple, styles, categories, search_terms, legacy, family, family_i18n, formative, formative_i18n, instruments, instruments_i18n, anecdotes, anecdotes_i18n, collaborators, collaborators_i18n, videos, discography, discography_i18n, key_recordings, awards, awards_i18n, press_quotes, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, link_check, related_slugs, sort_order, created_at, updated_at, sync_ids, sync_data, booking_info) VALUES ('e7c9a2b1-4f3d-4a6e-9c8b-2d1e5f7a9b3c', 'jolly-jumper-and-big-moe', 'Jolly Jumper & Big Moe', 'Jolly Jumper & Big Moe m/ The Jimbo Jambo Band', 'Modern', 'Modern Era', NULL, NULL, NULL, NULL, NULL, 'Nordic', 'Norway', '/artists', NULL, NULL, NULL, 'https://bluesinhell.no/wp-content/uploads/2025/06/jolly-jumper-big-moe.jpg', NULL, 'Foto: Per Ole Hagen / Blues in Hell', '[]', '[]', NULL, NULL, 'One of Norway''s most beloved acoustic blues duos, pairing harmonica singer Jolly Jumper with veteran guitarist Big Moe.', 'En av Norges mest folkekjære akustiske bluesduoer, med munnspillsanger Jolly Jumper og gitarveteranen Big Moe.', 'En av Norges mest folkkära akustiska bluesduor, med munspelssångaren Jolly Jumper och gitarrveteranen Big Moe.', 'Eines von Norwegens beliebtesten akustischen Blues-Duos, mit dem Mundharmonika-Sänger Jolly Jumper und Gitarrenveteran Big Moe.', 'Jeden z najbardziej lubianych akustycznych duetów bluesowych w Norwegii, z wokalistą-harmonijkarzem Jolly Jumper i gitarowym weteranem Big Moe.', 'Many point to Jolly Jumper & Big Moe as the act that started Norway''s wave of acoustic blues duos in the 1990s (Source: Blues in Hell). The duo consists of Kjell Inge Fischer Brovoll, performing as "Jolly Jumper," and guitarist Jan Erik "Big" Moe (Source: Blues in Hell; Trondheim Bluesklubb). Brovoll handles the vocals and a harmonica style many consider among the most distinctive in Norwegian blues, while Moe has built his reputation as a guitarist ever since forming his very first blues band in 1965 (Source: Trondheim Bluesklubb). The two found each other at the Hell Bluesfestival in 1992, and their partnership has continued unbroken ever since -- well over thirty years as stage partners (Source: Blues in Hell). In 2018 Moe received the Blues in Hell Award, a recognition that came after a musical life spanning more than five decades (Source: Trondheim Bluesklubb). Since retiring from his day job a few years ago, he has made clear that blues now has his full attention (Source: Trondheim Bluesklubb). Audiences know the duo for a stage presence full of warmth, humor and top-tier musical craft, which has made them some of the most sought-after names on club and festival stages both in Norway and abroad (Source: Blues in Hell). With a full band, they perform as "Jolly Jumper & Big Moe m/ The Jimbo Jambo Band," joined by Daniel Trustrup Røssing on piano and vocals and Arne "King Kong" Skognes on drums (Source: Trondheim Bluesklubb). They are regulars at the Blues in Hell festival, where their shows are consistently sold out (Source: Blues in Hell), and have also performed for Trondheim Bluesklubb at Krambua (Source: Trondheim Bluesklubb).', 'Mange peker på Jolly Jumper & Big Moe som opphavet til den norske bølgen av akustiske bluesduoer på 1990-tallet (Kilde: Blues in Hell). Duoen består av Kjell Inge Fischer Brovoll, kjent under artistnavnet «Jolly Jumper», og gitarist Jan Erik «Big» Moe (Kilde: Blues in Hell; Trondheim Bluesklubb). Brovoll står bak vokalen og et munnspillspill mange regner blant det mest særpregede i norsk blues, mens Moe har bygget seg opp som gitarist siden han dannet sitt aller første bluesband i 1965 (Kilde: Trondheim Bluesklubb). De to fant hverandre på Hell Bluesfestival i 1992, og siden den gang har samarbeidet vart uavbrutt -- godt over tretti år som scenepartnere (Kilde: Blues in Hell). I 2018 mottok Moe Blues in Hell Award, en anerkjennelse som kom etter et langt musikerliv med mer enn fem tiår bak seg (Kilde: Trondheim Bluesklubb). Etter at han for noen år siden trakk seg tilbake fra fast jobb, har han vært tydelig på at bluesen nå har hans fulle oppmerksomhet (Kilde: Trondheim Bluesklubb). Publikum kjenner duoen for et scenevesen preget av overskudd, humor og et musikalsk håndverk av høy klasse, noe som har gjort dem til noen av de mest etterspurte navnene på både norske og utenlandske klubb- og festivalscener (Kilde: Blues in Hell). Med full besetning opptrer de under navnet «Jolly Jumper & Big Moe m/ The Jimbo Jambo Band», forsterket av Daniel Trustrup Røssing på piano og vokal og Arne «King Kong» Skognes bak trommene (Kilde: Trondheim Bluesklubb). De er faste innslag på Blues in Hell-festivalen, der konsertene deres jevnlig er fullsatt (Kilde: Blues in Hell), og de har blant annet også spilt for Trondheim Bluesklubb på Krambua (Kilde: Trondheim Bluesklubb).', 'Många pekar ut Jolly Jumper & Big Moe som de som satte igång den norska vågen av akustiska bluesduor på 1990-talet (Källa: Blues in Hell). Duon består av Kjell Inge Fischer Brovoll, som uppträder som «Jolly Jumper», och gitarristen Jan Erik «Big» Moe (Källa: Blues in Hell; Trondheim Bluesklubb). Brovoll står för sången och ett munspelsspel som många räknar bland det mest särpräglade inom norsk blues, medan Moe har byggt upp sitt rykte som gitarrist alltsedan han bildade sitt allra första bluesband 1965 (Källa: Trondheim Bluesklubb). De två fann varandra på Hell Bluesfestival 1992, och sedan dess har samarbetet fortsatt oavbrutet -- gott och väl trettio år som scenpartners (Källa: Blues in Hell). År 2018 mottog Moe Blues in Hell Award, ett erkännande som kom efter ett musikerliv på över fem decennier (Källa: Trondheim Bluesklubb). Sedan han för några år sedan gick i pension från sitt ordinarie jobb har han varit tydlig med att bluesen nu har hans fulla uppmärksamhet (Källa: Trondheim Bluesklubb). Publiken känner duon för ett scenframträdande fyllt av värme, humor och musikaliskt hantverk av hög klass, vilket gjort dem till några av de mest efterfrågade namnen på klubb- och festivalscener både hemma och utomlands (Källa: Blues in Hell). Med full bestättning uppträder de som «Jolly Jumper & Big Moe m/ The Jimbo Jambo Band», förstärkta av Daniel Trustrup Røssing på piano och sång och Arne «King Kong» Skognes bakom trummorna (Källa: Trondheim Bluesklubb). De är fasta inslag på Blues in Hell-festivalen, där deras konserter regelbundet är slutsålda (Källa: Blues in Hell), och de har bland annat även spelat för Trondheim Bluesklubb på Krambua (Källa: Trondheim Bluesklubb).', 'Viele sehen in Jolly Jumper & Big Moe die Band, die in den 1990er-Jahren die norwegische Welle akustischer Blues-Duos auslöste (Quelle: Blues in Hell). Das Duo besteht aus Kjell Inge Fischer Brovoll, der als „Jolly Jumper" auftritt, und Gitarrist Jan Erik „Big" Moe (Quelle: Blues in Hell; Trondheim Bluesklubb). Brovoll übernimmt den Gesang und ein Mundharmonikaspiel, das viele zu den markantesten im norwegischen Blues zählen, während Moe sich seinen Ruf als Gitarrist erarbeitete, seit er 1965 seine allererste Bluesband gründete (Quelle: Trondheim Bluesklubb). Die beiden fanden 1992 beim Hell Bluesfestival zueinander, und ihre Zusammenarbeit hält seitdem ununterbrochen an -- weit über dreißig Jahre als Bühnenpartner (Quelle: Blues in Hell). 2018 erhielt Moe den Blues in Hell Award, eine Anerkennung nach einem Musikerleben von mehr als fünf Jahrzehnten (Quelle: Trondheim Bluesklubb). Seit er vor einigen Jahren aus seinem festen Job ausschied, hat er deutlich gemacht, dass der Blues nun seine volle Aufmerksamkeit hat (Quelle: Trondheim Bluesklubb). Das Publikum kennt das Duo für einen Bühnenauftritt voller Wärme, Humor und musikalischem Können auf hohem Niveau, was die beiden zu einem der gefragtesten Namen auf Club- und Festivalbühnen im In- und Ausland gemacht hat (Quelle: Blues in Hell). Mit voller Besetzung treten sie als „Jolly Jumper & Big Moe m/ The Jimbo Jambo Band" auf, verstärkt durch Daniel Trustrup Røssing an Klavier und Gesang sowie Arne „King Kong" Skognes am Schlagzeug (Quelle: Trondheim Bluesklubb). Sie sind feste Größen beim Blues-in-Hell-Festival, wo ihre Konzerte regelmäßig ausverkauft sind (Quelle: Blues in Hell), und traten unter anderem auch beim Trondheim Bluesklubb im Krambua auf (Quelle: Trondheim Bluesklubb).', 'Wielu wskazuje Jolly Jumper & Big Moe jako duet, który zapoczątkował norweską falę akustycznych duetów bluesowych w latach 90. (Źródło: Blues in Hell). Duet tworzą Kjell Inge Fischer Brovoll, występujący jako „Jolly Jumper", oraz gitarzysta Jan Erik „Big" Moe (Źródło: Blues in Hell; Trondheim Bluesklubb). Brovoll odpowiada za śpiew i grę na harmonijce ustnej, uznawaną przez wielu za jedną z najbardziej charakterystycznych w norweskim bluesie, podczas gdy Moe budował swoją markę jako gitarzysta od czasu założenia swojego pierwszego zespołu bluesowego w 1965 roku (Źródło: Trondheim Bluesklubb). Obaj odnaleźli się na Hell Bluesfestival w 1992 roku, a ich współpraca trwa nieprzerwanie od tego czasu -- ponad trzydzieści lat jako partnerzy sceniczni (Źródło: Blues in Hell). W 2018 roku Moe otrzymał nagrodę Blues in Hell Award, wyróżnienie, które przyszło po ponad pięciu dekadach kariery muzycznej (Źródło: Trondheim Bluesklubb). Odkąd kilka lat temu przeszedł na emeryturę z pracy zawodowej, jasno podkreśla, że blues ma teraz jego pełną uwagę (Źródło: Trondheim Bluesklubb). Publiczność zna duet z występów pełnych ciepła, humoru i wysokiej klasy warsztatu muzycznego, co uczyniło ich jednymi z najbardziej poszukiwanych nazwisk na scenach klubowych i festiwalowych, zarówno w Norwegii, jak i za granicą (Źródło: Blues in Hell). W pełnym składzie występują jako „Jolly Jumper & Big Moe m/ The Jimbo Jambo Band", wzmocnieni przez Daniela Trustrupa Røssinga na fortepianie i wokalu oraz Arne „King Kong" Skognesa na perkusji (Źródło: Trondheim Bluesklubb). Są stałym punktem festiwalu Blues in Hell, gdzie ich koncerty regularnie są wyprzedane (Źródło: Blues in Hell), a także grali między innymi dla Trondheim Bluesklubb w Krambua (Źródło: Trondheim Bluesklubb).', NULL, NULL, NULL, NULL, 'Norge', '1992–', NULL, 'Jolly Jumper & Big Moe are widely credited with kickstarting the acoustic blues-duo format in Norway in the 1990s, opening the door for a whole generation of Norwegian duos that followed (Source: Blues in Hell).', 'Jolly Jumper & Big Moe krediteres av mange for å ha satt i gang den akustiske bluesduo-formen i Norge på 1990-tallet, og åpnet døren for en hel generasjon norske duoer som fulgte etter (Kilde: Blues in Hell).', 'Jolly Jumper & Big Moe krediteras av många för att ha satt igång den akustiska bluesduoformen i Norge under 1990-talet, och öppnade dörren för en hel generation norska duor som följde efter (Källa: Blues in Hell).', 'Jolly Jumper & Big Moe gelten vielen als Begründer des akustischen Blues-Duo-Formats in Norwegen in den 1990er-Jahren und öffneten die Tür für eine ganze Generation norwegischer Duos, die folgten (Quelle: Blues in Hell).', 'Jolly Jumper & Big Moe są przez wielu uznawani za pionierów akustycznej formuły duetu bluesowego w Norwegii w latach 90., otwierając drzwi dla całego pokolenia norweskich duetów, które poszły w ich ślady (Źródło: Blues in Hell).', '[]', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{}', '[]', '["Vocals","Harmonica","Guitar","Piano","Drums"]', '["Acoustic Blues","Traditional Blues","Contemporary Blues"]', '[]', '[]', NULL, '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":["1965: Big Moe startet sitt første bluesband (Kilde: Trondheim Bluesklubb).","1992: Jolly Jumper og Big Moe møttes under Hell Bluesfestival og begynte å spille sammen (Kilde: Blues in Hell).","2018: Jan Erik «Big» Moe ble tildelt Blues in Hell Award (Kilde: Trondheim Bluesklubb).","Moe gikk av med pensjon fra dagjobben og valgte å satse på blues på heltid (Kilde: Trondheim Bluesklubb)."],"en":["1965: Big Moe started his first blues band (Source: Trondheim Bluesklubb).","1992: Jolly Jumper and Big Moe met at the Hell Bluesfestival and began playing together (Source: Blues in Hell).","2018: Jan Erik \"Big\" Moe received the Blues in Hell Award (Source: Trondheim Bluesklubb).","Moe retired from his day job and chose to commit to playing blues full-time (Source: Trondheim Bluesklubb)."],"sv":["1965: Big Moe startade sitt första bluesband (Källa: Trondheim Bluesklubb).","1992: Jolly Jumper och Big Moe möttes under Hell Bluesfestival och började spela tillsammans (Källa: Blues in Hell).","2018: Jan Erik «Big» Moe tilldelades Blues in Hell Award (Källa: Trondheim Bluesklubb).","Moe gick i pension från sitt dagjobb och valde att satsa på blues på heltid (Källa: Trondheim Bluesklubb)."],"de":["1965: Big Moe gründete seine erste Bluesband (Quelle: Trondheim Bluesklubb).","1992: Jolly Jumper und Big Moe lernten sich beim Hell Bluesfestival kennen und begannen, zusammen zu spielen (Quelle: Blues in Hell).","2018: Jan Erik „Big" Moe erhielt den Blues in Hell Award (Quelle: Trondheim Bluesklubb).","Moe ging in den Ruhestand und entschied sich, sich fortan hauptberuflich dem Blues zu widmen (Quelle: Trondheim Bluesklubb)."],"pl":["1965: Big Moe założył swój pierwszy zespół bluesowy (Źródło: Trondheim Bluesklubb).","1992: Jolly Jumper i Big Moe poznali się podczas Hell Bluesfestival i zaczęli grać razem (Źródło: Blues in Hell).","2018: Jan Erik „Big" Moe otrzymał nagrodę Blues in Hell Award (Źródło: Trondheim Bluesklubb).","Moe przeszedł na emeryturę z pracy zawodowej i postanowił poświęcić się bluesowi na pełny etat (Źródło: Trondheim Bluesklubb)."]}', '[]', '{"no":[{"category":"Vokal","name":"Vokal og munnspill (Jolly Jumper / Kjell Inge Fischer Brovoll)","note":"Brovolls munnspillspill er duoens umiskjennelige signaturlyd.","years":null},{"category":"Gitar","name":"Gitar (Big Moe / Jan Erik Moe)","note":"Moes gitarspill er formet gjennom over 50 år på scenen siden 1965.","years":null}],"en":[{"category":"Gitar","name":"Vocals and harmonica (Jolly Jumper / Kjell Inge Fischer Brovoll)","note":"Brovoll''s harmonica playing is the duo''s unmistakable signature sound.","years":null},{"category":"Gitar","name":"Guitar (Big Moe / Jan Erik Moe)","note":"Moe''s guitar playing has been shaped by more than 50 years on stage since 1965.","years":null}],"sv":[{"category":"Gitar","name":"Sång och munspel (Jolly Jumper / Kjell Inge Fischer Brovoll)","note":"Brovolls munspelsspel är duons oefterhärmliga signaturljud.","years":null},{"category":"Gitar","name":"Gitarr (Big Moe / Jan Erik Moe)","note":"Moes gitarrspel har formats genom över 50 år på scenen sedan 1965.","years":null}],"de":[{"category":"Gitar","name":"Gesang und Mundharmonika (Jolly Jumper / Kjell Inge Fischer Brovoll)","note":"Brovolls Mundharmonikaspiel ist der unverwechselbare Signatursound des Duos.","years":null},{"category":"Gitar","name":"Gitarre (Big Moe / Jan Erik Moe)","note":"Moes Gitarrenspiel wurde durch über 50 Jahre Bühnenerfahrung seit 1965 geprägt.","years":null}],"pl":[{"category":"Gitar","name":"Śpiew i harmonijka ustna (Jolly Jumper / Kjell Inge Fischer Brovoll)","note":"Gra Brovolla na harmonijce to niepowtarzalne sygnaturowe brzmienie duetu.","years":null},{"category":"Gitar","name":"Gitara (Big Moe / Jan Erik Moe)","note":"Gra Moego na gitarze została ukształtowana przez ponad 50 lat na scenie od 1965 roku.","years":null}]}', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":[{"name":"Daniel Trustrup Røssing","note":"Piano og vokal i «The Jimbo Jambo Band», duoens faste fullbandbesetning.","source":"Trondheim Bluesklubb"},{"name":"Arne «King Kong» Skognes","note":"Trommer i «The Jimbo Jambo Band».","source":"Trondheim Bluesklubb"}],"en":[{"name":"Daniel Trustrup Røssing","note":"Piano and vocals in \"The Jimbo Jambo Band,\" the duo''s regular full-band lineup.","source":"Trondheim Bluesklubb"},{"name":"Arne \"King Kong\" Skognes","note":"Drums in \"The Jimbo Jambo Band.\"","source":"Trondheim Bluesklubb"}],"sv":[{"name":"Daniel Trustrup Røssing","note":"Piano och sång i «The Jimbo Jambo Band», duons fasta fullbandssättning.","source":"Trondheim Bluesklubb"},{"name":"Arne «King Kong» Skognes","note":"Trummor i «The Jimbo Jambo Band».","source":"Trondheim Bluesklubb"}],"de":[{"name":"Daniel Trustrup Røssing","note":"Klavier und Gesang in „The Jimbo Jambo Band", der festen Vollbesetzung des Duos.","source":"Trondheim Bluesklubb"},{"name":"Arne „King Kong" Skognes","note":"Schlagzeug in „The Jimbo Jambo Band".","source":"Trondheim Bluesklubb"}],"pl":[{"name":"Daniel Trustrup Røssing","note":"Fortepian i wokal w „The Jimbo Jambo Band", stałym pełnym składzie duetu.","source":"Trondheim Bluesklubb"},{"name":"Arne „King Kong" Skognes","note":"Perkusja w „The Jimbo Jambo Band".","source":"Trondheim Bluesklubb"}]}', '[{"kind":"featured","title":"Rooster Soup","youtube_id":"pW5beW4DgcQ","channel":"Provided to YouTube by The Orchard Enterprises"},{"kind":"more","title":"Death Don''t Have No Mercy","youtube_id":"OeuqxLBkDQE","channel":"Provided to YouTube by The Orchard Enterprises"},{"kind":"more","title":"James Alley Blues","youtube_id":"qsiGWjHmfRU","channel":"Provided to YouTube by The Orcha