INSERT OR REPLACE INTO artists (id, slug, name, alt_name, tag, era, era_label_en, era_label_no, era_label_sv, era_label_de, era_label_pl, region, country, base_path, route_path, source_file, source_region, img, og_image, image_credit, gallery_images, youtube_video_ids, video_search_query, short, short_en, short_no, short_sv, short_de, short_pl, biography_en, biography_no, biography_sv, biography_de, biography_pl, born, died, birth_name, birth_place, origin, active_years, influence_note, influence_en, influence_no, influence_sv, influence_de, influence_pl, bio, signature_songs, signature_songs_i18n, influences, influences_i18n, labels, instruments_simple, styles, categories, search_terms, legacy, family, family_i18n, formative, formative_i18n, instruments, instruments_i18n, anecdotes, anecdotes_i18n, collaborators, collaborators_i18n, videos, discography, discography_i18n, key_recordings, awards, awards_i18n, press_quotes, press_quotes_i18n, seo_title_en, seo_title_no, seo_title_sv, seo_title_de, seo_title_pl, seo_description_en, seo_description_no, seo_description_sv, seo_description_de, seo_description_pl, social_links, external_links, article_references, website_url, facebook_url, link_check, related_slugs, sort_order, created_at, updated_at, sync_ids, sync_data, booking_info) VALUES ('b1a1a1a1-0002-4001-8001-000000000002', 'lightnin-guy', 'Lightnin'' Guy', 'Guy Verlinde', 'Modern', 'Modern Era', NULL, NULL, NULL, NULL, NULL, 'Western Europe', 'Belgium', '/artists', NULL, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Lightnin%27_Guy_at_Zoetermeer_Blues_2011_%285828582821%29.jpg', NULL, 'Foto: FaceMePLS, Zoetermeer Blues 2011 (CC BY 2.0, Wikimedia Commons)', '[]', '[]', NULL, NULL, 'A Belgian blues guitarist, harmonica player and singer, the first Belgian blues artist signed to Dixiefrog Records, now leading Artisans of Solace.', 'En belgisk blues-gitarist, munnspiller og vokalist, den forste belgiske bluesartisten signert til Dixiefrog Records, na med bandet Artisans of Solace.', 'En belgisk bluesgitarrist, munspelare och sangare, den forsta belgiska bluesartisten som skrev pa Dixiefrog Records, nu med Artisans of Solace.', 'Ein belgischer Blues-Gitarrist, Mundharmonikaspieler und Saenger, der erste belgische Blueskuenstler bei Dixiefrog Records, heute mit Artisans of Solace.', 'Belgijski gitarzysta bluesowy, harmonijkarz i wokalista, pierwszy belgijski artysta bluesowy podpisany do Dixiefrog Records, obecnie z zespolem Artisans of Solace.', 'Lightnin'' Guy -- real name Guy Verlinde, born 22 March 1976 -- is one of the most travelled figures in Belgian blues, known both under that stage name and his own (Source: Discogs; nl.wikipedia.org). He formed his first band, Smokin'' Chillums, at just 17, and after it disbanded in 2000 played in Backbone and Mo'' Rice before founding Lightnin'' Guy & The Mighty Gators in 2008 (Source: nl.wikipedia.org). In 2015 he began performing more consistently as Guy Verlinde, while continuing to lead several parallel projects -- Guy Verlinde & The Mighty Gators, Guy Verlinde And The Houserockers, the Guy Verlinde Trio, and, since 2021, Guy Verlinde & The Artisans Of Solace, which blends blues with roots and Americana (Source: nl.wikipedia.org; Discogs). He won the Belgian Blues Challenge in 2011 and represented Belgium at the European Blues Challenge in Berlin in 2012, the same year he became the first Belgian blues artist signed to the French label Dixiefrog Records (Source: nl.wikipedia.org). He has since been honoured with Belgian Blues Awards for Best Solo/Duo (2024 and 2026) and, with Artisans of Solace, Best Band (2025) (Source: nl.wikipedia.org). Over more than twenty countries of touring he has shared stages with B.B. King, Tony Joe White, Canned Heat, Santana and John Fogerty, among others (Source: nl.wikipedia.org). Alongside performing, he develops educational blues programmes for schools across Flanders and Wallonia addressing history, poetry and social themes, and marked his 50th birthday in March 2026 with the retrospective boxset "50 Years / 50 Songs" (Source: nl.wikipedia.org; Discogs).', 'Lightnin'' Guy -- egentlig Guy Verlinde, fodt 22. mars 1976 -- er en av de mest reisende skikkelsene i belgisk blues, like kjent under artistnavnet som under sitt eget (Kilde: Discogs; nl.wikipedia.org). Han dannet sitt forste band, Smokin'' Chillums, allerede som 17-aring, og etter at det ble opplost i 2000 spilte han i Backbone og Mo'' Rice for han grunnla Lightnin'' Guy & The Mighty Gators i 2008 (Kilde: nl.wikipedia.org). Fra 2015 begynte han a opptre mer konsekvent som Guy Verlinde, samtidig som han fortsatte a lede flere parallelle prosjekter -- Guy Verlinde & The Mighty Gators, Guy Verlinde And The Houserockers, Guy Verlinde Trio, og fra 2021 Guy Verlinde & The Artisans Of Solace, som blander blues med roots og Americana (Kilde: nl.wikipedia.org; Discogs). Han vant Belgian Blues Challenge i 2011 og representerte Belgia i European Blues Challenge i Berlin i 2012, samme ar som han ble den forste belgiske bluesartisten som ble signert til det franske plateselskapet Dixiefrog Records (Kilde: nl.wikipedia.org). Han har siden blitt hedret med Belgian Blues Awards for Beste solo/duo (2024 og 2026) og, med Artisans of Solace, Beste band (2025) (Kilde: nl.wikipedia.org). Pa turne i over tjue land har han delt scene med B.B. King, Tony Joe White, Canned Heat, Santana og John Fogerty, blant andre (Kilde: nl.wikipedia.org). Ved siden av a opptre utvikler han pedagogiske blues-programmer for skoler i Flandern og Vallonia om historie, poesi og sosiale tema, og markerte sin 50-arsdag i mars 2026 med samleboksen «50 Years / 50 Songs» (Kilde: nl.wikipedia.org; Discogs).', 'Lightnin'' Guy -- egentligen Guy Verlinde, fodd 22 mars 1976 -- ar en av de mest resande gestalterna inom belgisk blues, lika kand under artistnamnet som under sitt eget (Kalla: Discogs; nl.wikipedia.org). Han bildade sitt forsta band, Smokin'' Chillums, redan som 17-aring, och efter att det upplostes ar 2000 spelade han i Backbone och Mo'' Rice innan han grundade Lightnin'' Guy & The Mighty Gators 2008 (Kalla: nl.wikipedia.org). Fran 2015 borjade han uppträda mer konsekvent som Guy Verlinde, samtidigt som han fortsatte leda flera parallella projekt -- Guy Verlinde & The Mighty Gators, Guy Verlinde And The Houserockers, Guy Verlinde Trio, och fran 2021 Guy Verlinde & The Artisans Of Solace, som blandar blues med roots och Americana (Kalla: nl.wikipedia.org; Discogs). Han vann Belgian Blues Challenge 2011 och representerade Belgien i European Blues Challenge i Berlin 2012, samma ar som han blev den forsta belgiska bluesartisten som skrev pa for det franska skivbolaget Dixiefrog Records (Kalla: nl.wikipedia.org). Han har sedan dess hedrats med Belgian Blues Awards for Basta solo/duo (2024 och 2026) och, med Artisans of Solace, Basta band (2025) (Kalla: nl.wikipedia.org). Pa turne i over tjugo lander har han delat scen med B.B. King, Tony Joe White, Canned Heat, Santana och John Fogerty, bland andra (Kalla: nl.wikipedia.org). Vid sidan av att uppträda utvecklar han pedagogiska blues-program for skolor i Flandern och Vallonien om historia, poesi och sociala teman, och firade sin 50-arsdag i mars 2026 med samlingsboxen «50 Years / 50 Songs» (Kalla: nl.wikipedia.org; Discogs).', 'Lightnin'' Guy -- buergerlich Guy Verlinde, geboren am 22. Maerz 1976 -- ist eine der meistgereisten Figuren des belgischen Blues, ebenso bekannt unter diesem Buehnennamen wie unter seinem eigenen (Quelle: Discogs; nl.wikipedia.org). Er gruendete seine erste Band, Smokin'' Chillums, bereits mit 17 Jahren, und spielte nach deren Aufloesung im Jahr 2000 in Backbone und Mo'' Rice, bevor er 2008 Lightnin'' Guy & The Mighty Gators gruendete (Quelle: nl.wikipedia.org). Ab 2015 trat er zunehmend als Guy Verlinde auf und leitete gleichzeitig mehrere parallele Projekte -- Guy Verlinde & The Mighty Gators, Guy Verlinde And The Houserockers, das Guy Verlinde Trio und ab 2021 Guy Verlinde & The Artisans Of Solace, die Blues mit Roots und Americana verbinden (Quelle: nl.wikipedia.org; Discogs). Er gewann 2011 die Belgian Blues Challenge und vertrat Belgien 2012 bei der European Blues Challenge in Berlin, im selben Jahr, in dem er als erster belgischer Blueskuenstler beim franzoesischen Label Dixiefrog Records unterschrieb (Quelle: nl.wikipedia.org). Seitdem wurde er mit Belgian Blues Awards als Bester Solo/Duo (2024 und 2026) sowie, mit Artisans of Solace, als Beste Band (2025) ausgezeichnet (Quelle: nl.wikipedia.org). Auf Tourneen durch mehr als zwanzig Laender teilte er die Buehne unter anderem mit B.B. King, Tony Joe White, Canned Heat, Santana und John Fogerty (Quelle: nl.wikipedia.org). Neben seinen Auftritten entwickelt er paedagogische Blues-Programme fuer Schulen in Flandern und der Wallonie zu Geschichte, Poesie und sozialen Themen, und feierte seinen 50. Geburtstag im Maerz 2026 mit der Retrospektiv-Box "50 Years / 50 Songs" (Quelle: nl.wikipedia.org; Discogs).', 'Lightnin'' Guy -- naprawde Guy Verlinde, urodzony 22 marca 1976 roku -- to jedna z najbardziej podroznych postaci belgijskiego bluesa, znany zarowno pod tym pseudonimem scenicznym, jak i pod wlasnym nazwiskiem (Zrodlo: Discogs; nl.wikipedia.org). Zalozyl swoj pierwszy zespol, Smokin'' Chillums, juz w wieku 17 lat, a po jego rozwiazaniu w 2000 roku gral w Backbone i Mo'' Rice, zanim w 2008 roku zalozyl Lightnin'' Guy & The Mighty Gators (Zrodlo: nl.wikipedia.org). Od 2015 roku zaczal wystepowac bardziej konsekwentnie jako Guy Verlinde, jednoczesnie prowadzac kilka rownoleglych projektow -- Guy Verlinde & The Mighty Gators, Guy Verlinde And The Houserockers, Guy Verlinde Trio, a od 2021 roku Guy Verlinde & The Artisans Of Solace, laczacy blues z rootsem i Americana (Zrodlo: nl.wikipedia.org; Discogs). Wygral Belgian Blues Challenge w 2011 roku i reprezentowal Belgie na European Blues Challenge w Berlinie w 2012 roku, w tym samym roku, w ktorym jako pierwszy belgijski artysta bluesowy podpisal kontrakt z francuska wytwornia Dixiefrog Records (Zrodlo: nl.wikipedia.org). Od tego czasu zostal uhonorowany nagrodami Belgian Blues Awards dla Najlepszego Solisty/Duetu (2024 i 2026) oraz, z Artisans of Solace, dla Najlepszego Zespolu (2025) (Zrodlo: nl.wikipedia.org). Podczas tras koncertowych w ponad dwudziestu krajach dzielil scene m.in. z B.B. Kingiem, Tony Joe White, Canned Heat, Santana i Johnem Fogertym (Zrodlo: nl.wikipedia.org). Oprocz wystepow tworzy edukacyjne programy bluesowe dla szkol we Flandrii i Walonii, poswiecone historii, poezji i tematom spolecznym, a swoje 50. urodziny w marcu 2026 roku uczcil retrospektywnym boxem "50 Years / 50 Songs" (Zrodlo: nl.wikipedia.org; Discogs).', '22 March 1976', NULL, NULL, 'Belgium', 'Belgia', '2000–', NULL, 'As the first Belgian blues artist signed to Dixiefrog Records and a two-time Belgian Blues Awards winner, Guy Verlinde has helped raise the international profile of Belgian blues while also passing the tradition on through his school programmes across Flanders and Wallonia (Source: nl.wikipedia.org).', 'Som den forste belgiske bluesartisten signert til Dixiefrog Records og to ganger vinner av Belgian Blues Awards, har Guy Verlinde bidratt til a lofte den internasjonale profilen til belgisk blues, samtidig som han forer tradisjonen videre gjennom skoleprogrammene sine i Flandern og Vallonia (Kilde: nl.wikipedia.org).', 'Som den forsta belgiska bluesartisten som skrev pa for Dixiefrog Records och tvafaldig vinnare av Belgian Blues Awards har Guy Verlinde bidragit till att lyfta den internationella profilen for belgisk blues, samtidigt som han for traditionen vidare genom sina skolprogram i Flandern och Vallonien (Kalla: nl.wikipedia.org).', 'Als erster belgischer Blueskuenstler bei Dixiefrog Records und zweifacher Gewinner der Belgian Blues Awards hat Guy Verlinde dazu beigetragen, das internationale Profil des belgischen Blues zu schaerfen, waehrend er die Tradition durch seine Schulprogramme in Flandern und der Wallonie weitergibt (Quelle: nl.wikipedia.org).', 'Jako pierwszy belgijski artysta bluesowy podpisany do Dixiefrog Records i dwukrotny zdobywca Belgian Blues Awards, Guy Verlinde przyczynil sie do podniesienia miedzynarodowej rangi belgijskiego bluesa, jednoczesnie przekazujac tradycje poprzez swoje programy szkolne we Flandrii i Walonii (Zrodlo: nl.wikipedia.org).', '[]', '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{}', '["Dixiefrog Records"]', '["Vocals","Guitar","Slide Guitar","Harmonica"]', '["Blues","Blues Rock","Roots Blues","Americana / Blues"]', '[]', '[]', NULL, '[]', '{"no":[],"en":[],"sv":[],"de":[],"pl":[]}', '[]', '{"no":["1993: Dannet sitt forste band, Smokin'' Chillums, som 17-aring (Kilde: nl.wikipedia.org).","2008: Grunnla Lightnin'' Guy & The Mighty Gators (Kilde: nl.wikipedia.org).","2011: Vant Belgian Blues Challenge (Kilde: nl.wikipedia.org).","2012: Representerte Belgia i European Blues Challenge i Berlin, og ble forste belgiske bluesartist signert til Dixiefrog Records (Kilde: nl.wikipedia.org).","2015: Begynte a opptre konsekvent under eget navn (Kilde: nl.wikipedia.org).","2021: Dannet Guy Verlinde & The Artisans Of Solace (Kilde: nl.wikipedia.org).","2026: Ga ut samleboksen «50 Years / 50 Songs» pa sin 50-arsdag (Kilde: Discogs)."],"en":["1993: Formed his first band, Smokin'' Chillums, at age 17 (Source: nl.wikipedia.org).","2008: Founded Lightnin'' Guy & The Mighty Gators (Source: nl.wikipedia.org).","2011: Won the Belgian Blues Challenge (Source: nl.wikipedia.org).","2012: Represented Belgium at the European Blues Challenge in Berlin, and became the first Belgian blues artist signed to Dixiefrog Records (Source: nl.wikipedia.org).","2015: Began performing consistently under his own name (Source: nl.wikipedia.org).","2021: Formed Guy Verlinde & The Artisans Of Solace (Source: nl.wikipedia.org).","2026: Released the retrospective boxset \"50 Years / 50 Songs\" on his 50th birthday (Source: Discogs)."],"sv":["1993: Bildade sitt forsta band, Smokin'' Chillums, vid 17 ars alder (Kalla: nl.wikipedia.org).","2008: Grundade Lightnin'' Guy & The Mighty Gators (Kalla: nl.wikipedia.org).","2011: Vann Belgian Blues Challenge (Kalla: nl.wikipedia.org).","2012: Representerade Belgien i European Blues Challenge i Berlin, och blev den forsta belgiska bluesartisten som skrev pa for Dixiefrog Records (Kalla: nl.wikipedia.org).","2015: Borjade uppträda konsekvent under sitt eget namn (Kalla: nl.wikipedia.org).","2021: Bildade Guy Verlinde & The Artisans Of Solace (Kalla: nl.wikipedia.org).","2026: Slappte samlingsboxen «50 Years / 50 Songs» pa sin 50-arsdag (Kalla: Discogs)."],"de":["1993: Gruendete seine erste Band, Smokin'' Chillums, im Alter von 17 Jahren (Quelle: nl.wikipedia.org).","2008: Gruendete Lightnin'' Guy & The Mighty Gators (Quelle: nl.wikipedia.org).","2011: Gewann die Belgian Blues Challenge (Quelle: nl.wikipedia.org).","2012: Vertrat Belgien bei der European Blues Challenge in Berlin und wurde erster belgischer Blueskuenstler bei Dixiefrog Records (Quelle: nl.wikipedia.org).","2015: Begann konsequent unter eigenem Namen aufzutreten (Quelle: nl.wikipedia.org).","2021: Gruendete Guy Verlinde & The Artisans Of Solace (Quelle: nl.wikipedia.org).","2026: Veroeffentlichte die Retrospektiv-Box \"50 Years / 50 Songs\" zu seinem 50. Geburtstag (Quelle: Discogs)."],"pl":["1993: Zalozyl swoj pierwszy zespol, Smokin'' Chillums, w wieku 17 lat (Zrodlo: nl.wikipedia.org).","2008: Zalozyl Lightnin'' Guy & The Mighty Gators (Zrodlo: nl.wikipedia.org).","2011: Wygral Belgian Blues Challenge (Zrodlo: nl.wikipedia.org).","2012: Reprezentowal Belgie na European Blues Challenge w Berlinie i zostal pierwszym belgijskim artysta bluesowym podpisanym do Dixiefrog Records (Zrodlo: nl.wikipedia.org).","2015: Zaczal wystepowac konsekwentnie pod wlasnym nazwiskiem (Zrodlo: nl.wikipedia.org).","2021: Zalozyl Guy Verlinde & The Artisans Of Solace (Zrodlo: nl.wikipedia.org).","2026: Wydal retros